_CONTROL_PLANE_START_LOCK = threading.Lock()

# Per-session /compact dedupe: nothing upstream (client-side `_compactInFlight`
# in app.js, or the control-plane idempotency_key) protects against two
# independent HTTP requests for the SAME session_id racing each other — e.g. a
# phone tab reloading mid-request and re-sending, or two open tabs/devices on
# the same session both pressing Compact. Each request otherwise gets its own
# idempotency_key (a fresh uuid4 when the client doesn't supply one — see
# _take_control_plane_action_id) and is processed independently, so a single
# accidental double-send can fire off several real /compact runs. Guard here
# collapses concurrent/rapid duplicate requests for one session_id.
_COMPACT_INFLIGHT_LOCK = threading.Lock()
_COMPACT_INFLIGHT_SESSIONS = {}  # sid -> monotonic timestamp compact started
_COMPACT_INFLIGHT_COOLDOWN_SECONDS = 20.0


def _set_control_plane_action_id(value):
    _CONTROL_PLANE_REQUEST_CONTEXT.idempotency_key = str(value or "").strip()


def _take_control_plane_action_id():
    value = str(
        getattr(_CONTROL_PLANE_REQUEST_CONTEXT, "idempotency_key", "") or ""
    ).strip()
    _CONTROL_PLANE_REQUEST_CONTEXT.idempotency_key = ""
    return value or None


def _control_plane_request(method, params=None, *, engine_timeout=False):
    """Call the persistent worker without making dashboard availability depend on it."""
    client = _CONTROL_PLANE_ENGINE_CLIENT if engine_timeout else _CONTROL_PLANE_CLIENT
    response = client.request(method, params)
    if not isinstance(response, dict):
        return {"ok": False, "available": False, "error": "invalid worker response"}
    return response


def _control_plane_routes_engines():
    return (
        os.environ.get("CCC_WORKER_PROCESS") != "1"
        and os.environ.get("CCC_CONTROL_PLANE_ENGINES", "1").lower()
        not in ("0", "false", "no")
    )


def _control_plane_engine_call(
    engine, operation, args, *, mutate=True, idempotency_key=None,
    parent_work_id=None, timeout_ms=None,
):
    """Return worker result, or None only when no worker accepted the request."""
    if not _control_plane_routes_engines():
        return None
    method = "engine.execute" if mutate else "engine.query"
    payload = {
        "engine": engine,
        "operation": operation,
        "args": args if isinstance(args, dict) else {},
    }
    if mutate:
        payload["idempotency_key"] = str(idempotency_key or uuid.uuid4())
        if parent_work_id:
            payload["parent_work_id"] = str(parent_work_id)
    # Engine reads may lazily initialize a native transport too, so they need
    # the same timeout budget as writes. The mutate flag controls durability,
    # not how quickly an engine can answer.
    if timeout_ms is not None:
        try:
            requested_timeout = max(
                _CONTROL_PLANE_ENGINE_CLIENT.timeout,
                float(timeout_ms) / 1000.0 + 5.0,
            )
        except (TypeError, ValueError):
            requested_timeout = _CONTROL_PLANE_ENGINE_CLIENT.timeout
        client = ControlPlaneClient(
            path=_CONTROL_PLANE_ENGINE_CLIENT.path,
            token_file=_CONTROL_PLANE_ENGINE_CLIENT.token_file,
            timeout=requested_timeout,
        )
        response = client.request(method, payload)
    else:
        response = _control_plane_request(method, payload, engine_timeout=True)
    if response.get("code") == "method_not_found":
        # Version skew during a rolling dashboard update: an older worker has
        # definitively rejected (and therefore did not execute) the request.
        # Falling back is safe until that idle worker is upgraded.
        return None
    # A connect failure proves the worker did not receive the request, so the
    # mature in-process path remains a compatibility fallback. A timeout after
    # send is ambiguous and MUST NOT fall back or it could duplicate effects.
    if not response.get("available") and not response.get("ambiguous"):
        return None
    return response


def _dashboard_owned_active_executions():
    """Describe live execution still owned by this restartable process."""
    active = []
    with _ACP_LOCK:
        for harness in _ACP_WORKER_HARNESSES:
            for sid, state in (_ACP_SESSION_STATE.get(harness) or {}).items():
                if str((state or {}).get("status") or "").lower() == "active":
                    active.append({"engine": harness, "session_id": sid})
    for entry in list(_spawned_sessions):
        try:
            running = _poll_spawn_entry(entry) is None
        except Exception:
            running = False
        if not running:
            continue
        active.append({
            "engine": str(entry.get("engine") or "claude"),
            "session_id": (
                entry.get("session_id")
                or entry.get("resumed_sid")
                or ""
            ),
            "pid": entry.get("pid"),
        })
    return active


def _retire_wedged_control_plane_worker():
    """Stop a worker that still owns the socket but cannot answer health.

    A worker that has exhausted its file descriptors keeps the socket bound and
    closes every connection unread. A fresh worker then refuses to boot ("already
    running") and Maintenance reports "did not become ready" forever, so the only
    recovery is to retire the recorded PID and clear the stale socket. Engine
    children run in their own sessions and are re-adopted by the next worker.
    """
    try:
        pid = int(worker_pid_path().read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        pid = 0
    stopped = False
    if pid > 1 and pid != os.getpid():
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            # Already gone; the socket it left behind is what blocks the restart.
            stopped = True
        except OSError:
            pid = 0
        else:
            deadline = time.time() + 5
            while time.time() < deadline:
                try:
                    os.kill(pid, 0)
                except OSError:
                    stopped = True
                    break
                time.sleep(0.1)
            if not stopped:
                try:
                    os.kill(pid, signal.SIGKILL)
                    stopped = True
                except OSError:
                    pass
    try:
        socket_path().unlink()
    except OSError:
        pass
    return {"retired_pid": pid if stopped else 0}


def _start_control_plane_worker():
    """Start the persistent worker when Maintenance finds it unavailable."""
    with _CONTROL_PLANE_START_LOCK:
        current = _control_plane_request("health")
        if current.get("ok"):
            return current
        # `available` here means the socket answered at all. A worker that is
        # reachable but not ok is wedged, and a new one cannot bind over it.
        retired = (
            _retire_wedged_control_plane_worker()
            if current.get("available") or current.get("ambiguous")
            else {}
        )
        logs_dir = COMMAND_CENTER_STATE_DIR / "logs"
        logs_dir.mkdir(parents=True, exist_ok=True)
        try:
            with (
                (logs_dir / "worker.out.log").open("a", encoding="utf-8") as out,
                (logs_dir / "worker.err.log").open("a", encoding="utf-8") as err,
            ):
                process = subprocess.Popen(
                    [sys.executable, str(CCC_ROOT / "ccc_worker.py")],
                    stdin=subprocess.DEVNULL,
                    stdout=out,
                    stderr=err,
                    start_new_session=True,
                    cwd=str(CCC_ROOT),
                )
        except OSError as exc:
            return {"ok": False, "available": False, "error": str(exc)}
        deadline = time.time() + 8
        while time.time() < deadline:
            health = _control_plane_request("health")
            if health.get("ok"):
                health["started"] = True
                health["started_pid"] = process.pid
                if retired.get("retired_pid"):
                    health["retired_pid"] = retired["retired_pid"]
                return health
            if process.poll() is not None:
                break
            time.sleep(0.1)
        detail = "persistent worker did not become ready"
        if process.poll() is not None:
            detail += f" (exited {process.poll()}; see logs/worker.err.log)"
        return {
            "ok": False,
            "available": False,
            "error": detail,
            "retired_pid": retired.get("retired_pid") or 0,
        }


def _install_python_stack_dump_handler(log_path=None):
    """Append all-thread Python tracebacks to a log when SIGUSR2 arrives."""
    global _PYTHON_STACK_DUMP_FILE
    if _PYTHON_STACK_DUMP_FILE is not None:
        return True
    sigusr2 = getattr(signal, "SIGUSR2", None)
    if sigusr2 is None:
        return False
    path = Path(log_path) if log_path is not None else PYTHON_STACK_DUMP_LOG
    dump_file = None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        dump_file = open(path, "a", buffering=1)
        dump_file.write(
            f"\n=== CCC Python stack handler started "
            f"{datetime.now(tz=timezone.utc).isoformat()} pid={os.getpid()} ===\n"
        )
        dump_file.flush()
        faulthandler.register(sigusr2, file=dump_file, all_threads=True, chain=False)
    except (OSError, RuntimeError, ValueError) as exc:
        if dump_file is not None:
            try:
                dump_file.close()
            except OSError:
                pass
        print(f"⚠️  Could not install Python stack diagnostics: {exc}", file=sys.stderr)
        return False
    _PYTHON_STACK_DUMP_FILE = dump_file
    return True


# AskUserQuestion relay: headless `claude -p` auto-declines AskUserQuestion
# (no TUI picker), so for CCC-spawned sessions the PreToolUse hook blocks and
# waits here for the dashboard to drop an answer file. Kept in sync with
# QUESTION_RELAY_DIR in hooks/pre-tool-use.py. CCC marks the sessions it wants
# intercepted by setting QUESTION_RELAY_ENV on the spawned process.
QUESTION_RELAY_DIR = COMMAND_CENTER_STATE_DIR / "questions"
QUESTION_RELAY_ENV = "CCC_QUESTION_RELAY"
# Claude Code kills a hook that runs past its registered timeout. The
# PreToolUse hook blocks here while a relayed AskUserQuestion waits for an
# answer, so it needs a generous ceiling — kept above the hook's own
# CCC_QUESTION_TIMEOUT (default 1740s) so the hook returns its own clean
# message before Claude Code force-kills it.
PRETOOLUSE_HOOK_TIMEOUT = 1800


def _question_relay_env():
    """Child env that opts a spawned session into AskUserQuestion relay."""
    return dict(os.environ, **{QUESTION_RELAY_ENV: "1"})


def _read_question_request(session_id):
    """Return the pending AskUserQuestion relay request for a session, or None.

    The PreToolUse hook writes this {nonce, questions, ...} file while it
    blocks waiting for an answer; the dashboard reads it to render the modal.
    """
    if not session_id:
        return None
    path = QUESTION_RELAY_DIR / f"{session_id}.request.json"
    try:
        with open(path) as f:
            data = json.load(f)
    except (OSError, ValueError):
        return None
    if not isinstance(data, dict) or not data.get("nonce"):
        return None
    return data


def _write_question_answer(session_id, answers):
    """Drop the user's AskUserQuestion picks for the blocking hook to consume.

    `answers` is aligned to the request's questions; each entry is
    {"index": int, "text": str} — a non-negative index selects that option,
    otherwise `text` is used as a free-text answer. The nonce from the live
    request is stamped in so a stale hook never consumes a fresh answer.
    """
    req = _read_question_request(session_id)
    if not req:
        return {"ok": False, "error": "no pending question for this session"}
    if not isinstance(answers, list) or not answers:
        return {"ok": False, "error": "answers must be a non-empty list"}
    # CCC-46: the blocking PreToolUse hook (in the headless `claude -p` process)
    # is the ONLY consumer of the answer file. If that process is gone, writing
    # the answer succeeds silently but nothing ever reads it — the classic
    # "I answered and nothing happened" symptom. Verify the hook's pid is alive
    # before pretending the answer was delivered.
    hook_pid = req.get("pid")
    if hook_pid and not _pid_alive(hook_pid):
        # Stale request from a dead process — clear it so the waiting indicator
        # doesn't keep prompting for an answer that can never land.
        try:
            (QUESTION_RELAY_DIR / f"{session_id}.request.json").unlink()
        except OSError:
            pass
        try:
            marker = SIDECAR_STATE_DIR / f"{session_id}_in_flight.json"
            if marker.exists():
                marker.unlink()
        except (OSError, ValueError):
            pass
        return {
            "ok": False,
            "dead": True,
            "error": "this session's process is no longer running - "
                     "the answer can't reach it. Resume the session to continue.",
        }
    norm = []
    for a in answers:
        if isinstance(a, dict):
            idx = a.get("index")
            norm.append({
                "index": idx if isinstance(idx, int) else -1,
                "text": str(a.get("text") or ""),
            })
        else:
            norm.append({"index": -1, "text": str(a or "")})
    try:
        QUESTION_RELAY_DIR.mkdir(parents=True, exist_ok=True)
        path = QUESTION_RELAY_DIR / f"{session_id}.answer.json"
        tmp = str(path) + ".tmp"
        with open(tmp, "w") as f:
            json.dump({"nonce": req["nonce"], "answers": norm, "ts": time.time()}, f)
        os.replace(tmp, path)
    except OSError as e:
        return {"ok": False, "error": f"could not write answer: {e}"}
    # The user just answered — proactively drop the AskUserQuestion in-flight
    # marker so the "Question waiting for answer" indicator clears on the very
    # next status poll, instead of lingering (with stale preamble text) until
    # the tool_result round-trips back into the transcript. That lag is the
    # "question synchronization isn't working" symptom: the prompt is already
    # answered but the live indicator keeps showing it as waiting.
    try:
        marker = SIDECAR_STATE_DIR / f"{session_id}_in_flight.json"
        if marker.exists():
            data = json.loads(marker.read_text())
            if isinstance(data, dict) and data.get("tool") == "AskUserQuestion":
                marker.unlink()
    except (OSError, ValueError):
        pass
    return {"ok": True, "questions": len(req.get("questions") or [])}
