def _load_custom_repos():
    """Return the list of user-picked repo paths (absolute, deduped, existing dirs)."""
    try:
        raw = _CUSTOM_REPOS_FILE.read_text()
    except OSError:
        return []
    out = []
    seen = set()
    for line in raw.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            p = Path(line).expanduser().resolve()
        except (OSError, ValueError):
            continue
        s = str(p)
        if s in seen or not p.is_dir():
            continue
        seen.add(s)
        out.append(s)
    return out


def _load_recent_repos():
    """Return recently-used repo paths, most-recent first (deduped, existing dirs only)."""
    try:
        raw = _RECENT_REPOS_FILE.read_text()
    except OSError:
        return []
    out = []
    seen = set()
    for line in raw.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            p = Path(line).expanduser().resolve()
        except (OSError, ValueError):
            continue
        s = str(p)
        if s in seen or not p.is_dir():
            continue
        seen.add(s)
        out.append(s)
        if len(out) >= _RECENT_REPOS_CAP:
            break
    return out


def _spawn_cwd_outside_home_allowed(candidate):
    """A spawn cwd outside $HOME is allowed if it's an existing directory.
    The $HOME clamp is a typo-guard, not a hard security boundary (loopback
    already grants full command access — see SECURITY.md), and the caller has
    already verified the path exists and is a directory before reaching here,
    so a typo'd/nonexistent path can never get this far. Any real external
    volume the user typed/pasted/picked (e.g. /Volumes/Drive/proj) is honored
    and auto-registered as a recent repo so it surfaces in the picker next
    time. `candidate` must be an already-resolved Path."""
    try:
        cand = str(candidate)
    except Exception:
        return False
    try:
        if not Path(candidate).is_dir():
            return False
    except OSError:
        return False
    # Already an existing directory — auto-register so future spawns/pickers
    # see it without a separate "Add repo" step. Best-effort; never blocks.
    try:
        _record_recent_repo(cand)
    except Exception:
        pass
    return True


def _record_recent_repo(path_str):
    """Prepend a switch event to the recent list. Silent on I/O error — the
    recency ordering is a UX nicety, not load-bearing."""
    try:
        p = Path(path_str).expanduser().resolve()
    except (OSError, ValueError):
        return
    if not p.is_dir():
        return
    existing = _load_recent_repos()
    new_list = [str(p)] + [x for x in existing if x != str(p)]
    new_list = new_list[:_RECENT_REPOS_CAP]
    try:
        _RECENT_REPOS_FILE.parent.mkdir(parents=True, exist_ok=True)
        _RECENT_REPOS_FILE.write_text("\n".join(new_list) + "\n")
    except OSError:
        pass
    _invalidate_known_repo_paths()


def _append_custom_repo(path_str):
    """Persist a user-picked repo path. Returns the absolute resolved path.
    Raises ValueError if the path isn't an existing directory."""
    p = Path(path_str).expanduser().resolve()
    if not p.is_dir():
        raise ValueError(f"not a directory: {p}")
    existing = set(_load_custom_repos())
    if str(p) in existing:
        return str(p)
    _CUSTOM_REPOS_FILE.parent.mkdir(parents=True, exist_ok=True)
    with _CUSTOM_REPOS_FILE.open("a") as f:
        f.write(str(p) + "\n")
    _invalidate_known_repo_paths()
    return str(p)


# Visual-only override of which repo a session appears under in the all-repos
# archive view. {session_id: repo_path}. Does not touch the JSONL transcript —
# the session's recorded cwd is unchanged, only the row's grouping is moved.
# Used when a session was launched in repo A but the work logically belongs
# under repo B and the user wants the row to appear there for scanning.
_REPO_PINS_FILE = Path.home() / ".claude" / "command-center" / "repo-pins.json"
_SESSION_LANE_VALUES = {"coding", "workers", "messages"}


def _load_repo_pins():
    try:
        with open(_REPO_PINS_FILE) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    return {str(k): str(v) for k, v in data.items() if k and v}


def _save_repo_pins(pins):
    _REPO_PINS_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = _REPO_PINS_FILE.with_suffix(".json.tmp")
    with open(tmp, "w") as f:
        json.dump(pins, f, indent=2, sort_keys=True)
    tmp.replace(_REPO_PINS_FILE)


def _normalize_session_lane(lane):
    lane = str(lane or "").strip().lower()
    return lane if lane in _SESSION_LANE_VALUES else ""


def _load_session_lane_overrides():
    """Return {session_id: all-tab lane override}."""
    try:
        with open(SESSION_LANE_OVERRIDES_FILE) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    out = {}
    for sid, lane in data.items():
        clean = _normalize_session_lane(lane)
        if isinstance(sid, str) and sid and clean:
            out[sid] = clean
    return out


def _save_session_lane_overrides(overrides):
    SESSION_LANE_OVERRIDES_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = SESSION_LANE_OVERRIDES_FILE.with_suffix(".json.tmp")
    clean = {}
    for sid, lane in (overrides or {}).items():
        clean_lane = _normalize_session_lane(lane)
        if sid and clean_lane:
            clean[str(sid)] = clean_lane
    with open(tmp, "w") as f:
        json.dump(clean, f, indent=2, sort_keys=True)
    tmp.replace(SESSION_LANE_OVERRIDES_FILE)
    return clean


def _get_session_lane_override(session_id):
    sid = str(session_id or "").strip()
    if not sid:
        return ""
    return _load_session_lane_overrides().get(sid, "")


def _set_session_lane_override(session_id, lane):
    """Persist an All-tab lane override. Empty/invalid lane clears it."""
    sid = str(session_id or "").strip()
    if not sid:
        raise ValueError("missing session_id")
    clean = _normalize_session_lane(lane)
    overrides = _load_session_lane_overrides()
    if clean:
        overrides[sid] = clean
    else:
        overrides.pop(sid, None)
    _save_session_lane_overrides(overrides)
    return clean


def _set_session_lane_overrides(session_ids, lane):
    """Persist an All-tab lane override for every known alias of a row."""
    ids = []
    seen = set()
    for raw in session_ids or []:
        sid = str(raw or "").strip()
        if not sid or sid in seen:
            continue
        seen.add(sid)
        ids.append(sid)
    if not ids:
        raise ValueError("missing session_id")
    clean = _normalize_session_lane(lane)
    overrides = _load_session_lane_overrides()
    for sid in ids:
        if clean:
            overrides[sid] = clean
        else:
            overrides.pop(sid, None)
    _save_session_lane_overrides(overrides)
    return clean, ids


def _apply_session_lane_overrides(rows, overrides=None):
    """Stamp per-session All-tab lane overrides onto any row shape."""
    if overrides is None:
        try:
            overrides = _load_session_lane_overrides()
        except Exception:
            overrides = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        sid = row.get("session_id") or row.get("id")
        if sid:
            row["all_lane_override"] = overrides.get(str(sid), "")
    return rows


# CCC-893: external tools that spawn a Claude Code session (e.g. the
# reddit-writer skill, which lives outside this repo) currently land on the
# All tab's "Coding" lane by default, same as any interactively-typed
# session. There's no way for the spawning tool to say "this one's a worker,
# not a person typing" short of the user manually dragging it to Workers
# every time.
#
# Marker contract: the spawning tool drops one small JSON file per session at
# SPAWN_MARKERS_DIR/<session_id>.json. New writers specify a display lane, for
# example {"kind": "assistant", "lane": "other", "spawned_via": "ccc-ask"}.
# This is a plain filesystem write — no CCC API call or auth — matching how an
# external tool has filesystem access but not a running CCC to talk to at spawn
# time. Old {"spawned_via": "<tool>"} markers remain valid and mean Workers.
# CCC intentionally has no source allowlist: a new external tool can classify
# its own session without a CCC release.
SPAWN_MARKERS_DIR = COMMAND_CENTER_STATE_DIR / "spawn-markers"  # <session_id>.json -> {"spawned_via": "<tool>"}
_SPAWN_MARKER_VALUE_MAX_CHARS = 64
_SPAWN_MARKER_LANES = frozenset({"workers", "other"})


def _load_spawn_markers():
    """Return typed metadata from SPAWN_MARKERS_DIR/<sid>.json files."""
    out = {}
    try:
        files = list(SPAWN_MARKERS_DIR.iterdir())
    except OSError:
        return out
    for f in files:
        if not f.name.endswith(".json") or not f.is_file():
            continue
        sid = f.name[: -len(".json")].strip()
        if not sid:
            continue
        try:
            data = json.loads(f.read_text())
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        via = str(data.get("spawned_via") or "").strip()[:_SPAWN_MARKER_VALUE_MAX_CHARS]
        lane = str(data.get("lane") or "").strip().lower()
        if lane not in _SPAWN_MARKER_LANES:
            lane = "workers" if via else ""
        if not lane:
            continue
        marker = {"lane": lane}
        kind = str(data.get("kind") or "").strip()[:_SPAWN_MARKER_VALUE_MAX_CHARS]
        if kind:
            marker["kind"] = kind
        if via:
            marker["spawned_via"] = via
        out[sid] = marker
    return out


def _apply_spawn_markers(rows, markers=None):
    """Stamp external spawn metadata onto any row shape."""
    if markers is None:
        try:
            markers = _load_spawn_markers()
        except Exception:
            markers = {}
    if not markers:
        return rows
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        sid = row.get("session_id") or row.get("id")
        if sid:
            marker = markers.get(str(sid)) or {}
            lane = marker.get("lane")
            if lane:
                row["spawned_lane"] = lane
            kind = marker.get("kind")
            if kind:
                row["spawned_kind"] = kind
            via = marker.get("spawned_via")
            if via:
                row["spawned_via"] = via
    return rows


def _write_spawn_marker(session_id, *, lane, kind="", spawned_via=""):
    """Atomically persist typed launch metadata for one known session."""
    sid = str(session_id or "").strip()
    clean_lane = str(lane or "").strip().lower()
    if not sid or Path(sid).name != sid:
        raise ValueError("invalid session_id")
    if clean_lane not in _SPAWN_MARKER_LANES:
        raise ValueError("invalid spawn marker lane")
    payload = {"lane": clean_lane}
    clean_kind = str(kind or "").strip()[:_SPAWN_MARKER_VALUE_MAX_CHARS]
    clean_via = str(spawned_via or "").strip()[:_SPAWN_MARKER_VALUE_MAX_CHARS]
    if clean_kind:
        payload["kind"] = clean_kind
    if clean_via:
        payload["spawned_via"] = clean_via
    SPAWN_MARKERS_DIR.mkdir(parents=True, exist_ok=True)
    marker_path = SPAWN_MARKERS_DIR / f"{sid}.json"
    tmp_path = marker_path.with_suffix(f".json.{uuid.uuid4().hex}.tmp")
    try:
        tmp_path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")
        tmp_path.replace(marker_path)
    finally:
        try:
            tmp_path.unlink(missing_ok=True)
        except OSError:
            pass


def _infer_session_spawned_via(row_or_entry, sid=None, markers=None, spawn_registry_by_sid=None):
    """Guarantees a concrete, non-empty spawned_via attribution for any session.

    Never returns null, empty, or 'not available'. Priority:
    1. Explicit spawned_via already present and valid on the row/entry.
    2. Explicit spawned_via in spawn registry.
    3. Explicit spawned_via in spawn markers (~/.claude/command-center/spawn-markers/<sid>.json).
    4. Subagent if parent_session_id is present.
    5. WatchTower if lane-w*, lane-e*, [watchtower], or [wt].
    6. Resumed if continued_from_session_id or resume- prefix.
    7. UI if recorded in spawn registry but missing via.
    8. Terminal for all sessions started outside CCC (interactive CLI in terminal).
    """
    if not isinstance(row_or_entry, dict):
        return "terminal"
    via = str(row_or_entry.get("spawned_via") or "").strip().lower()
    if via and via not in ("none", "null", "-", "not-available", "not available", "unknown"):
        return via
    sid_clean = str(sid or row_or_entry.get("session_id") or row_or_entry.get("id") or "").strip()
    if spawn_registry_by_sid is not None and sid_clean and sid_clean in spawn_registry_by_sid:
        reg_entry = spawn_registry_by_sid[sid_clean]
        if isinstance(reg_entry, dict):
            reg_via = str(reg_entry.get("spawned_via") or "").strip().lower()
            if reg_via and reg_via not in ("none", "null", "-", "not-available", "not available", "unknown"):
                return reg_via
    if markers is None:
        try:
            markers = _load_spawn_markers()
        except Exception:
            markers = {}
    if sid_clean and sid_clean in markers:
        marker_via = str(markers[sid_clean].get("spawned_via") or "").strip().lower()
        if marker_via:
            return marker_via
    parent = row_or_entry.get("parent_session_id")
    if parent and str(parent).strip():
        return "subagent"
    name = str(row_or_entry.get("name") or row_or_entry.get("display_name") or row_or_entry.get("first_message") or "").strip().lower()
    if (
        name.startswith("lane-w")
        or name.startswith("lane-e")
        or "[watchtower]" in name
        or "[wt]" in name
        or name.startswith("wt-")
        or bool(row_or_entry.get("_worker_id"))
    ):
        return "watchtower"
    if row_or_entry.get("continued_from_session_id") or name.startswith("resume-"):
        return "resumed"
    if spawn_registry_by_sid is not None and sid_clean and sid_clean in spawn_registry_by_sid:
        return "ui"
    return "terminal"


def _tag_spawned_via_in_registry(pid=None, session_id=None, via=""):
    """Persist spawned_via onto the spawn registry entry by PID and/or session_id."""
    clean_via = str(via or "").strip()
    if not clean_via or (pid is None and not session_id):
        return
    def _mutator(entries):
        changed = False
        for entry in entries:
            pid_match = pid is not None and entry.get("pid") == pid
            sid_match = session_id and entry.get("session_id") == session_id
            if (pid_match or sid_match) and entry.get("spawned_via") != clean_via:
                entry["spawned_via"] = clean_via
                changed = True
        return changed
    _mutate_spawn_registry(_mutator)


def _load_session_overrides():
    """Return {session_id: {model, context_1m, engine, set_at}} or {}."""
    try:
        with open(SESSION_OVERRIDES_FILE) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def _save_session_overrides(overrides):
    SESSION_OVERRIDES_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = SESSION_OVERRIDES_FILE.with_suffix(".json.tmp")
    with open(tmp, "w") as f:
        json.dump(overrides, f, indent=2, sort_keys=True)
    tmp.replace(SESSION_OVERRIDES_FILE)


def _load_auto_handover_flags():
    """Return {session_id: {enabled, set_at, last_fired_mtime, last_fired_at}} or {}."""
    try:
        with open(AUTO_HANDOVER_FILE) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def _save_auto_handover_flags(flags):
    AUTO_HANDOVER_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = AUTO_HANDOVER_FILE.with_suffix(".json.tmp")
    with open(tmp, "w") as f:
        json.dump(flags, f, indent=2, sort_keys=True)
    tmp.replace(AUTO_HANDOVER_FILE)


_AUTO_HANDOVER_MODES = ("mdfile", "compact", "both")


def _auto_handover_mode(session_id):
    """The armed mode for a session, or the 'mdfile' default for legacy
    flags saved before mode existed."""
    entry = _load_auto_handover_flags().get(session_id or "")
    mode = isinstance(entry, dict) and entry.get("mode")
    return mode if mode in _AUTO_HANDOVER_MODES else "mdfile"


def _set_auto_handover(session_id, enabled, mode="mdfile"):
    sid = (session_id or "").strip()
    if not sid:
        return {"ok": False, "error": "missing session_id"}
    if mode not in _AUTO_HANDOVER_MODES:
        return {"ok": False, "error": f"mode must be one of {', '.join(_AUTO_HANDOVER_MODES)}"}
    flags = _load_auto_handover_flags()
    if enabled:
        flags[sid] = {
            "enabled": True,
            "mode": mode,
            "set_at": datetime.now().isoformat(),
            "last_fired_mtime": None,
            "last_fired_at": None,
        }
    else:
        flags.pop(sid, None)
    _save_auto_handover_flags(flags)
    return {"ok": True, "session_id": sid, "enabled": bool(enabled), "mode": mode}


def _mark_auto_handover_fired(session_id, transcript_mtime):
    """Record the fire and disable the flag -- one-shot per enable.

    The injected prompt (and the model's own `wt add` response to it) rewrites
    the transcript, which bumps its mtime. If we stayed enabled and kept
    comparing against that mtime, the watchdog would see a "fresh" idle streak
    starting from the fire's own footprint and re-fire again 55 minutes later,
    forever, with no real user activity involved (observed 2026-08-06: fired
    10x overnight for one session). Disabling after the first fire sidesteps
    that self-sustaining loop entirely; re-enable manually for another round.
    """
    flags = _load_auto_handover_flags()
    entry = flags.get(session_id)
    if not entry:
        return  # toggled off since the watchdog last checked — nothing to mark
    entry["last_fired_mtime"] = float(transcript_mtime)
    entry["last_fired_at"] = datetime.now().isoformat()
    entry["enabled"] = False
    _save_auto_handover_flags(flags)


_AUTO_HANDOVER_IDLE_MINUTES = 55  # 5 min before F2_STALE_MINUTES's claude cliff (60, static/app.js)
_AUTO_HANDOVER_CHECK_INTERVAL_S = 60  # stat()-ing transcripts every 5s is wasteful at minute-scale thresholds
_auto_handover_last_checked_at = {"ts": 0.0}


def _auto_handover_prompt():
    return (
        "[CCC auto-handover] This session has been idle long enough that its "
        "prompt cache is close to going cold, so reloading full context later "
        "would be expensive. Before continuing, write a short durable "
        "checkpoint: run `wt add` yourself (use `wt ls` to find an existing "
        "queue for this repo/workstream, or pick a sensible new one if none "
        "fits) with a 2-3 sentence --note covering (1) what's done, (2) "
        "what's left, (3) the next concrete step. File exactly one ticket -- "
        "this is a lightweight just-in-case checkpoint, not a task "
        "breakdown or dedup pass. No other action needed; nothing to ask me."
    )


def _auto_handover_gates_pass(session_id):
    """True only for a live, CCC-owned, idle, headless (no-TTY) Claude spawn.

    Deliberately narrower than compact/clear's gating: auto-handover never
    resurrects a dormant session via `claude --resume` just to have it write a
    note (that would contradict the "survives even if unreachable" goal, since
    a resurrected headless goes stale again seconds later), and never
    keystrokes into a live interactive terminal (that's visibly disruptive if
    a human is mid-thought in that window, unlike an unattended headless spawn).
    """
    cwd = find_session_cwd(session_id)
    status = session_live_status(session_id, cwd)
    if _session_status_is_busy(status):
        return False
    if _pending_ask_user_question_for_session(session_id):
        return False
    has_tty = _is_real_tty(status.get("tty"))
    if has_tty:
        return False
    spawn = _find_live_spawn_entry_for_session(session_id)
    if spawn is None:
        return False
    return True


def _fire_auto_handover_local(session_id):
    """Gate + inject in THIS process's own local state.

    Only correct to call where the live spawn actually lives -- CCC-owned
    Claude headless spawns are tracked in `_spawned_sessions`, which is
    per-process. A normal spawn created via /api/sessions/spawn is dispatched
    to and lives in the WORKER's copy of this module, not the dashboard's.
    Callers must route through the control plane first (see
    _maybe_fire_auto_handover) so this only runs directly when already inside
    the worker (or in a single-process deployment with no separate worker).
    """
    if not _auto_handover_gates_pass(session_id):
        return {"ok": False, "code": "auto_handover_gate_failed"}
    return _inject_text_into_session(
        session_id, _auto_handover_prompt(), mode="send", source="auto-handover",
    )


def _maybe_fire_auto_handover(session_id, entry, now):
    if _detect_session_engine(session_id) != "claude":
        return  # scope: claude sessions only, matching F2's own claude-specific cliff
    try:
        path = _resolve_conversation_path(session_id)
        mtime = os.path.getmtime(path)
    except (OSError, TypeError):
        return
    idle_min = (now - mtime) / 60.0
    if idle_min < _AUTO_HANDOVER_IDLE_MINUTES:
        return
    last_fired = entry.get("last_fired_mtime")
    if last_fired and float(last_fired) >= mtime:
        return  # already fired for this exact idle streak

    # The gate check (_find_live_spawn_entry_for_session) and the injection
    # itself both need to see the WORKER's live spawn state, not the
    # dashboard's own (usually empty, for a worker-dispatched spawn) copy --
    # route the whole gate-and-fire operation there, same as
    # compact_session_context/clear_session_context do at their own top.
    routed = _control_plane_engine_call(
        "claude", "auto_handover_fire", {"session_id": session_id},
        idempotency_key=str(uuid.uuid4()),
    )
    if routed is not None:
        result = routed
    else:
        # No worker available -- fall back to local (correct in a
        # single-process deployment, where there's nowhere else for the
        # spawn state to live).
        result = _fire_auto_handover_local(session_id)

    if result.get("ok"):
        _mark_auto_handover_fired(session_id, mtime)
        _log_activity("auto-handover", "FIRED", f"session={session_id[:8]} idle_min={idle_min:.0f}")
    elif result.get("code") != "auto_handover_gate_failed":
        print(f"[auto-handover] inject failed for {session_id[:8]}: {result.get('error')}", flush=True)


def _run_auto_handover_watchdog_once(now=None):
    """No-op since the toggle started injecting `token-sitter auto-snapshot on`
    directly (see toggleAutoHandoverForPane in app.js). That injected command
    already arms token-sitter's own idle checkpoint for the session, so this
    server-side watchdog firing its own "[CCC auto-handover]" prompt on top
    was a second, redundant checkpoint for the same idle window -- both fired
    within minutes of each other for the same session. Left as a no-op (vs.
    deleted) so the AUTO_HANDOVER_FILE flag + toggle UI keep working; only the
    actual injection is disabled.
    """
    return


def _get_session_override(session_id):
    if not session_id:
        return None
    entry = _load_session_overrides().get(session_id)
    if not isinstance(entry, dict):
        return None
    return entry


def _conv_row_reasoning_effort(sid, overrides, spawn_entry=None):
    """Effort for one list row, read from maps the caller hoisted out of its loop.

    List builders touch every conversation, so this must never reach disk:
    callers pass ONE _load_session_overrides() for the whole batch, the same
    way archived_set / pinned_rank are already hoisted. The override is what
    the user last picked; the spawn-registry entry covers a session that was
    spawned with an effort and never re-picked.
    """
    entry = (overrides or {}).get(str(sid or ""))
    if isinstance(entry, dict):
        effort = str(entry.get("reasoning_effort") or "").strip()
        if effort:
            return effort
    return str((spawn_entry or {}).get("reasoning_effort") or "").strip()


# Codex's `-c model_reasoning_effort=<value>` config override (confirmed via
# `codex --help` / the user's own ~/.codex/config.toml) accepts these values.
CODEX_REASONING_EFFORTS = {"", "low", "medium", "high", "xhigh"}
CLAUDE_REASONING_EFFORTS = {"", "low", "medium", "high", "xhigh", "max"}


def _set_session_override(session_id, model, context_1m, engine, reasoning_effort=""):
    overrides = _load_session_overrides()
    engine = str(engine or "claude")
    overrides[session_id] = {
        "model": str(model),
        "context_1m": _model_context_1m_allowed(model, context_1m, engine),
        "engine": engine,
        "reasoning_effort": str(reasoning_effort or ""),
        "set_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    }
    _save_session_overrides(overrides)


def _clear_session_override(session_id):
    overrides = _load_session_overrides()
    if session_id in overrides:
        del overrides[session_id]
        _save_session_overrides(overrides)


def _short_model_alias(model):
    """Turn `claude-sonnet-4-6` / `claude-sonnet-4-6[1m]` / `sonnet` into the
    alias form `/model` accepts: drop the `claude-` prefix and any `[1m]`
    suffix the caller may have included. Non-Claude model strings pass
    through unchanged (callers shouldn't be invoking this for them, but
    being permissive is cheap)."""
    if not model:
        return ""
    alias = model.strip()
    if alias.lower().startswith("claude-"):
        alias = alias[len("claude-"):]
    # Strip any trailing `[1m]`/`[1M]` — the slash command adds it back when
    # context_1m is true, and we don't want a double suffix.
    for tail in ("[1m]", "[1M]"):
        if alias.endswith(tail):
            alias = alias[: -len(tail)]
    return alias.strip()


def _claude_model_supports_1m(model):
    alias = _short_model_alias(model).lower()
    return alias in ("fable-5", "opus-5", "sonnet-5", "opus-4-8", "opus-4-7")


def _model_context_1m_allowed(model, context_1m, engine="claude"):
    return bool(context_1m) and str(engine or "claude") == "claude" and _claude_model_supports_1m(model)


def _cli_model_flag(model):
    """Normalize a model string for use as a --model CLI argument.

    The /model slash command accepts short aliases like ``sonnet-4-6``, but the
    ``--model`` CLI flag requires the full prefixed ID ``claude-sonnet-4-6`` for
    versioned 4.x models (the CLI rejects bare ``sonnet-4-6``).  The ``[1m]``
    suffix is TUI-only; 1M context is enabled via ``--betas`` instead.
    """
    if not model:
        return ""
    m = model.strip()
    for tail in ("[1m]", "[1M]"):
        if m.endswith(tail):
            m = m[: -len(tail)].strip()
    if not m:
        return ""
    # Versioned aliases like 'sonnet-4-6', 'opus-4-8', 'haiku-4-5', 'fable-5'
    # need the 'claude-' prefix for --model (the /model slash command accepts
    # the bare alias, but the CLI flag does not for these models).
    if not m.lower().startswith("claude-") and re.match(r"^(sonnet|opus|haiku|fable)-\d", m.lower()):
        m = "claude-" + m
    return m


def _build_slash_model_command(model, context_1m):
    """Compose the `/model <id>[1m]` text injected into a live Claude
    session. Returns an empty string if model is missing — caller should
    treat that as a no-op.

    Use the FULL prefixed model ID (e.g. ``claude-haiku-4-5``), not the bare
    versioned alias. The TUI `/model` command only resolves bare *family*
    names (``haiku``/``sonnet``/``opus``/``fable``) or a full model ID; a
    versioned bare alias like ``haiku-4-5`` is rejected at runtime with
    "Model 'haiku-4-5' not found" and the switch silently no-ops (the bug this
    fixes — it hit every versioned model, just first noticed on Haiku).
    ``_cli_model_flag`` prefixes ``claude-`` for versioned 4.x ids and passes
    families / already-prefixed ids through unchanged. The ``[1m]`` suffix is
    a TUI-only affordance the slash command accepts on a full id
    (``claude-opus-4-8[1m]``)."""
    alias = _cli_model_flag(model)
    if not alias:
        return ""
    if _model_context_1m_allowed(model, context_1m, "claude"):
        return f"/model {alias}[1m]"
    return f"/model {alias}"


