def _codex_model_catalog_records():
    """Curated Codex catalog with live CLI limits and OpenAI per-token pricing.

    Merges the local `~/.codex/models_cache.json` (source of truth for what
    the installed CLI advertises) with published pricing/limits. Models the
    cache marks `visibility: hide` are dropped.
    """
    accepted_reasoning = set(_ENGINE_REASONING_EFFORTS.get("codex") or ())
    by_id = {row["id"]: row for row in _codex_models_cache_records()}
    rows = []
    now = datetime.now(tz=timezone.utc).isoformat()
    for row in _CODEX_OPENAI_MODELS:
        mid = row["id"]
        cached = by_id.get(mid, {})
        reasoning = list(row.get("reasoning_efforts") or cached.get("reasoning_efforts") or ())
        reasoning = [r for r in reasoning if r in accepted_reasoning]
        default_effort = row.get("default_reasoning_effort") or cached.get("default_reasoning_effort")
        if default_effort and default_effort not in accepted_reasoning:
            default_effort = reasoning[0] if reasoning else None
        rows.append({
            "id": mid,
            "label": cached.get("label") or row["label"],
            "source": "openai-codex-pricing",
            "available": True,
            "cost_tier": row["cost_tier"],
            "cost_summary": row["cost_summary"],
            "max_context_tokens": row.get("max_context_tokens") or cached.get("max_context_tokens"),
            "max_output_tokens": row.get("max_output_tokens") or cached.get("max_output_tokens"),
            "reasoning_efforts": reasoning,
            "default_reasoning_effort": default_effort,
            "supports_vision": cached.get("supports_vision") or False,
            "supports_tool_call": cached.get("supports_tool_call") or False,
            "supports_reasoning": bool(reasoning),
            "fetched_at": now,
        })
    return rows


def _parse_anthropic_model_overview(markdown):
    """Parse exact model aliases from Anthropic's latest-model table."""
    text = str(markdown or "")
    section = re.search(
        r"(?ims)^#{2,3}\s+(?:Latest models comparison|Compare models)\s*$([\s\S]*?)(?=^#{2,3}\s+|\Z)",
        text,
    )
    if not section:
        return []
    rows = []
    for line in section.group(1).splitlines():
        stripped = line.strip()
        if not (stripped.startswith("|") and stripped.endswith("|")):
            continue
        cells = [cell.strip() for cell in stripped.strip("|").split("|")]
        if len(cells) >= 2:
            rows.append(cells)
    if len(rows) < 3:
        return []

    def clean(value):
        # Row labels may be markdown links: [Context window](https://...)
        value = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", str(value or ""))
        return re.sub(r"[*_`]", "", value).strip()

    header = rows[0]
    aliases = next(
        (row for row in rows[1:] if clean(row[0]).lower() == "claude api alias"),
        None,
    )
    contexts = next(
        (row for row in rows[1:] if clean(row[0]).lower() == "context window"),
        None,
    )
    if not aliases:
        return []
    records = []
    for index in range(1, min(len(header), len(aliases))):
        alias = clean(aliases[index])
        if not re.fullmatch(r"claude-[a-z0-9][a-z0-9.-]*", alias):
            continue
        context = clean(contexts[index]) if contexts and index < len(contexts) else ""
        context_key = context.lower().replace(",", "").replace(" ", "")
        records.append({
            "id": alias.removeprefix("claude-"),
            "label": alias.removeprefix("claude-"),
            "display_name": clean(header[index]),
            "oneM": (
                "1mtoken" in context_key
                or "1000000token" in context_key
            ),
            "source": "anthropic-models-overview",
        })
    return records


def _load_claude_model_catalog_records():
    try:
        data = json.loads(_CLAUDE_MODEL_CATALOG_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return []
    rows = data.get("records") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return []
    return [
        row for row in rows
        if isinstance(row, dict) and _clean_spawn_default_model(row.get("id"))
    ]


def _claude_model_catalog_records():
    """Curated Anthropic catalog with pricing/limits (platform.claude.com docs).

    Unlike Droid/OpenCode, an Anthropic API alias has no per-account
    entitlement gate -- any API key can call any non-retired alias, and
    Anthropic keeps a superseded alias (e.g. opus-4-5 after opus-5 ships)
    callable for a long deprecation window rather than pulling it the
    moment a newer one appears in the docs' "latest models" table. So
    every curated row here is simply available; retire a row by deleting
    it once Anthropic's model-deprecations page marks it retired."""
    now = datetime.now(tz=timezone.utc).isoformat()
    records = []
    for row in _CLAUDE_ANTHROPIC_MODELS:
        records.append({
            "id": row["id"],
            "label": row["label"],
            "source": "anthropic-api-docs",
            "available": True,
            "cost_tier": row["cost_tier"],
            "cost_summary": row["cost_summary"],
            "max_context_tokens": row["max_context_tokens"],
            "max_output_tokens": row["max_output_tokens"],
            "reasoning_efforts": list(row["reasoning_efforts"]),
            "default_reasoning_effort": row["default_reasoning_effort"],
            "supports_vision": True,
            "supports_tool_call": True,
            "supports_reasoning": True,
            "fetched_at": now,
        })
    return records


def _refresh_claude_model_catalog():
    """Refresh the public Anthropic catalog, preserving stale cache on error."""
    request = urllib.request.Request(
        _CLAUDE_MODELS_OVERVIEW_URL,
        headers={
            "Accept": "text/markdown,text/plain;q=0.9,*/*;q=0.5",
            "User-Agent": f"claude-command-center/{__version__}",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=8) as response:
            body = response.read().decode("utf-8", "replace")
        records = _parse_anthropic_model_overview(body)
        if not records:
            return {"ok": False, "error": "Anthropic model table was not recognized"}
        payload = {
            "fetched_at": datetime.now(tz=timezone.utc).isoformat(),
            "source_url": _CLAUDE_MODELS_OVERVIEW_URL,
            "records": records,
        }
        _CLAUDE_MODEL_CATALOG_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = _CLAUDE_MODEL_CATALOG_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
        os.replace(tmp, _CLAUDE_MODEL_CATALOG_FILE)
        _MODEL_CATALOG_CACHE["ts"] = 0.0
        _MODEL_CATALOG_CACHE["data"] = None
        return {"ok": True, **payload}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def _resolve_harness_bin(engine):
    if engine == "codex":
        info = _resolve_codex_bin()
    else:
        return None
    if not info.get("available") or not info.get("bin"):
        return None
    return info["bin"]


def _harness_model_list_result(engine):
    """Best-effort JSON model discovery for harnesses that implement it."""
    engine = _normalize_orchestration_spawn_engine(engine)
    if engine != "codex":
        return {"available": False, "records": []}
    bin_path = _resolve_harness_bin(engine)
    if not bin_path:
        return {"available": False, "records": []}
    candidates = [
        [bin_path, "debug", "models"],
        [bin_path, "models", "list", "--json"],
        [bin_path, "model", "list", "--json"],
    ]
    for cmd in candidates:
        try:
            proc = subprocess.run(
                cmd,
                stdin=subprocess.DEVNULL,
                capture_output=True,
                text=True,
                timeout=4,
            )
        except (OSError, subprocess.SubprocessError):
            continue
        if proc.returncode != 0:
            continue
        text = (proc.stdout or "").strip()
        if not text:
            continue
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            continue
        rows = _model_records_from_json(data, source=f"{engine}-cli", skip_hidden=True)
        if rows:
            return {"available": True, "records": rows, "command": cmd}
    return {"available": False, "records": []}


def _codex_mark_model_availability(catalog, harness_result):
    if not (harness_result or {}).get("available"):
        return
    rows = harness_result.get("records") or []
    listed = {
        _model_catalog_key(row.get("id"))
        for row in rows
        if isinstance(row, dict) and row.get("id")
    }
    if not listed:
        return
    bucket = catalog.get("codex")
    if not isinstance(bucket, dict):
        return
    bucket["availability_source"] = "codex-cli"
    bucket["availability_command"] = " ".join(harness_result.get("command") or [])
    for entry in bucket.get("models") or []:
        key = _model_catalog_key(entry.get("id"))
        available = key in listed
        entry["available"] = available
        if not available:
            entry["availability_reason"] = "Not available in this Codex CLI. Run `codex update`."
    default_key = _model_catalog_key(bucket.get("default"))
    if default_key and default_key not in listed:
        for entry in bucket.get("models") or []:
            if entry.get("available") is not False and entry.get("id"):
                bucket["default"] = entry["id"]
                bucket["default_unavailable_reason"] = (
                    "Saved Codex default is not available in this CLI."
                )
                break


def _codex_model_availability_error(model):
    model = _clean_spawn_default_model(model)
    if not model:
        return None
    try:
        result = _harness_model_list_result("codex")
    except Exception:
        return None
    if not result.get("available"):
        return None
    target = _model_catalog_key(model)
    listed = {
        _model_catalog_key(row.get("id"))
        for row in result.get("records") or []
        if isinstance(row, dict) and row.get("id")
    }
    if target not in listed:
        return f"{model} is unavailable: Not available in this Codex CLI. Run `codex update`."
    return None


def _observed_model_records():
    rows = []

    def add(engine, model, source):
        model = _clean_spawn_default_model(model)
        if model:
            rows.append({"engine": engine, "id": model, "label": model, "source": source})

    try:
        for entry in _load_session_overrides().values():
            if isinstance(entry, dict):
                add(entry.get("engine") or "claude", entry.get("model"), "session-override")
    except Exception:
        pass
    try:
        for entry in _load_spawn_registry():
            if isinstance(entry, dict):
                add(entry.get("engine") or "claude", entry.get("model"), "spawn-registry")
    except Exception:
        pass
    try:
        for entry in _codex_thread_registry_entries().values():
            if isinstance(entry, dict):
                add("codex", entry.get("model"), "codex-registry")
    except Exception:
        pass
    try:
        for entry in _spawned_sessions:
            if isinstance(entry, dict):
                add(entry.get("engine") or "claude", entry.get("model"), "live-spawn")
    except Exception:
        pass
    try:
        for meta in _conv_meta_cache.values():
            if isinstance(meta, dict):
                add(meta.get("engine") or "claude", meta.get("model"), "transcript-cache")
    except Exception:
        pass
    return rows


_CLAUDE_TIER_FAMILIES = ("fable", "opus", "sonnet", "haiku")
_CLAUDE_TIER_DATE_SUFFIX_RE = re.compile(r"-\d{8}$")


def _claude_model_family(model_id):
    """Tier family of a Claude model id ('opus' in 'claude-opus-4-8' / 'opus-4-8'),
    or None for anything that is not a Claude tier model — cross-engine ids
    observed in sessions (gemini-*, gpt-*) and router sentinels like
    '<synthetic>' must not pollute the Claude picker."""
    mid = str(model_id or "").strip().lower()
    if mid.startswith("claude-"):
        mid = mid[len("claude-"):]
    fam = mid.split("-", 1)[0]
    return fam if fam in _CLAUDE_TIER_FAMILIES else None


def _claude_model_version(model_id):
    """Numeric version parts for tier comparison, ignoring an 8-digit date
    suffix ('haiku-4-5-20251001' and 'haiku-4-5' are the same tier)."""
    mid = _CLAUDE_TIER_DATE_SUFFIX_RE.sub("", str(model_id or "").strip().lower())
    if mid.startswith("claude-"):
        mid = mid[len("claude-"):]
    fam = mid.split("-", 1)
    ver = fam[1] if len(fam) > 1 else ""
    parts = []
    for piece in re.split(r"[-.]", ver):
        if piece.isdigit():
            parts.append(int(piece))
    return tuple(parts)


def _prune_claude_models_to_latest_tiers(models):
    """Keep only the newest entry of each tier family in the Claude picker.
    The Anthropic overview catalog lists every historical version
    (opus-4-8/4-7/4-6, sonnet-4-8/4-6, dated haiku aliases); the picker
    should offer the latest of each tier, not a museum. Dated aliases fold
    into their clean id. Order follows first appearance."""
    best = {}   # family -> (version tuple, entry)
    order = []
    for entry in models:
        fid = (entry or {}).get("id")
        fam = _claude_model_family(fid)
        if not fam:
            continue
        ver = _claude_model_version(fid)
        cur = best.get(fam)
        if cur is None:
            best[fam] = (ver, entry)
            order.append(fam)
        elif ver > cur[0] or (ver == cur[0]
                              and _CLAUDE_TIER_DATE_SUFFIX_RE.search(str((cur[1] or {}).get("id") or ""))
                              and not _CLAUDE_TIER_DATE_SUFFIX_RE.search(str(fid))):
            best[fam] = (ver, entry)
    return [best[fam][1] for fam in order]


_ANTIGRAVITY_GENERATION_RE = re.compile(
    r'^(Gemini|Claude)\s+(?:([\d.]+)\s+(Pro|Flash|Sonnet|Opus)|(Pro|Flash|Sonnet|Opus)\s+([\d.]+))'
    r'(?:\s*\([^)]*\))?$',
    re.IGNORECASE,
)
_ANTIGRAVITY_RAW_ID_RE = re.compile(r'^gemini-([\d.]+)-(pro|flash)(?:-preview)?$', re.IGNORECASE)


def _antigravity_version_tuple(ver):
    parts = []
    for piece in str(ver or "").split("."):
        if piece.isdigit():
            parts.append(int(piece))
    return tuple(parts)


def _antigravity_model_generation(model_id):
    """Parse an Antigravity model id/label into (brand, tier, version) for
    tier-family grouping, mirroring _claude_model_family/_claude_model_version.
    Handles both display labels ('Gemini 3.5 Pro (High)', 'Claude Sonnet 4.6
    (Thinking)') and raw lowercase ids ('gemini-3.1-pro-preview'). Returns
    None for ids that don't fit a known generation shape (e.g. 'GPT-OSS 120B
    (Medium)', which has only one tier so pruning is a no-op there anyway)."""
    mid = str(model_id or "").strip()
    if not mid:
        return None
    m = _ANTIGRAVITY_GENERATION_RE.match(mid)
    if m:
        brand = m.group(1).title()
        tier = (m.group(3) or m.group(4)).title()
        ver = m.group(2) or m.group(5)
        return (brand, tier, _antigravity_version_tuple(ver))
    m = _ANTIGRAVITY_RAW_ID_RE.match(mid)
    if m:
        return ("Gemini", m.group(2).title(), _antigravity_version_tuple(m.group(1)))
    return None


def _prune_antigravity_models_to_latest_tiers(models, default_id=None):
    """Keep only the newest generation of each (brand, tier) family in the
    Antigravity picker, mirroring _prune_claude_models_to_latest_tiers. The
    generation hosting the configured default model is always kept too, even
    if a newer generation exists, so the picker never drops the model a
    session is actually running. Entries whose id doesn't parse into a known
    generation (e.g. GPT-OSS) are never pruned."""
    best_version = {}  # (brand, tier) -> version tuple
    for entry in models:
        gen = _antigravity_model_generation((entry or {}).get("id"))
        if not gen:
            continue
        brand, tier, ver = gen
        fam = (brand, tier)
        if fam not in best_version or ver > best_version[fam]:
            best_version[fam] = ver

    keep_generations = {(fam[0], fam[1], ver) for fam, ver in best_version.items()}
    default_gen = _antigravity_model_generation(default_id)
    if default_gen:
        keep_generations.add(default_gen)

    kept = []
    for entry in models:
        gen = _antigravity_model_generation((entry or {}).get("id"))
        if gen is None or gen in keep_generations:
            kept.append(entry)
    return kept


def _build_engine_model_catalog(force_refresh=False):
    now = time.monotonic()
    if (
        not force_refresh
        and _MODEL_CATALOG_CACHE["data"] is not None
        and now - _MODEL_CATALOG_CACHE["ts"] < _MODEL_CATALOG_TTL_SEC
    ):
        return copy.deepcopy(_MODEL_CATALOG_CACHE["data"])

    catalog = {}
    for engine in _ORCHESTRATION_SPAWN_ENGINES:
        catalog[engine] = {
            "default": _spawn_fallback_model_for_engine(engine),
            "supports_custom": _ENGINE_SUPPORTS_CUSTOM_MODELS.get(engine, True),
            # W3-3: whether spawning this engine with a `key_profile` injects
            # BYOK provider keys into the subprocess env (ccc_server/byok.py,
            # BYOK_DIRECT_ENV_ENGINES). Surfaced so the model picker / `ccc
            # models` can show which engines actually honor BYOK today.
            "byok_ready": engine in BYOK_DIRECT_ENV_ENGINES,
            "models": [],
            "_index": {},
        }
        if engine == "claude":
            for row in _claude_model_catalog_records():
                _model_catalog_add(
                    catalog,
                    "claude",
                    row.get("id"),
                    label=row.get("label"),
                    source=row.get("source"),
                    available=row.get("available"),
                    cost_tier=row.get("cost_tier"),
                    cost_summary=row.get("cost_summary"),
                    max_context_tokens=row.get("max_context_tokens"),
                    max_output_tokens=row.get("max_output_tokens"),
                    reasoning_efforts=row.get("reasoning_efforts"),
                    default_reasoning_effort=row.get("default_reasoning_effort"),
                    supports_vision=row.get("supports_vision"),
                    supports_tool_call=row.get("supports_tool_call"),
                    supports_reasoning=row.get("supports_reasoning"),
                )
            for row in _load_claude_model_catalog_records():
                _model_catalog_add(
                    catalog,
                    "claude",
                    row.get("id"),
                    label=row.get("label"),
                    source=row.get("source") or "anthropic-models-overview",
                    oneM=row.get("oneM"),
                    display_name=row.get("display_name"),
                )
        for opt in _ENGINE_CURATED_MODELS.get(engine, ()):
            attrs = {}
            if "oneM" in opt:
                attrs["oneM"] = opt["oneM"]
            _model_catalog_add(
                catalog,
                engine,
                opt.get("id"),
                label=opt.get("label"),
                source="curated",
                **attrs,
            )

    try:
        defaults = _load_spawn_defaults()
        for engine, model in (defaults.get("models") or {}).items():
            _model_catalog_add(catalog, engine, model, source="spawn-default")
            norm = _normalize_orchestration_spawn_engine(engine)
            if norm in catalog and model and _model_catalog_allows_model(norm, model):
                catalog[norm]["default"] = _clean_spawn_default_model(model)
    except Exception:
        pass

    env_defaults = {
        "claude": os.environ.get("CCC_CLAUDE_MODEL"),
        "codex": os.environ.get("CCC_CODEX_MODEL"),
        "gemini": os.environ.get("CCC_GEMINI_MODEL"),
        "cursor": os.environ.get("CCC_CURSOR_MODEL"),
        "antigravity": os.environ.get("CCC_ANTIGRAVITY_MODEL"),
        "kilo": os.environ.get("CCC_KILO_MODEL"),
        "opencode": os.environ.get("CCC_OPENCODE_MODEL"),
        "hermes": os.environ.get("CCC_HERMES_MODEL"),
        "kimi": os.environ.get("CCC_KIMI_MODEL"),
        "grok": os.environ.get("CCC_GROK_MODEL"),
    }
    for engine, model in env_defaults.items():
        _model_catalog_add(catalog, engine, model, source="env")

    _model_catalog_add(catalog, "codex", _codex_configured_model(), source="harness-config")
    _model_catalog_add(catalog, "antigravity", _antigravity_cli_configured_model(), source="harness-config")

    for row in _codex_model_catalog_records():
        _model_catalog_add(
            catalog,
            "codex",
            row.get("id"),
            label=row.get("label"),
            source=row.get("source") or "codex-cache",
            available=row.get("available"),
            cost_tier=row.get("cost_tier"),
            cost_summary=row.get("cost_summary"),
            max_context_tokens=row.get("max_context_tokens"),
            max_output_tokens=row.get("max_output_tokens"),
            description=row.get("description"),
            priority=row.get("priority"),
            reasoning_efforts=row.get("reasoning_efforts"),
            default_reasoning_effort=row.get("default_reasoning_effort"),
            supports_vision=row.get("supports_vision"),
            supports_tool_call=row.get("supports_tool_call"),
            supports_reasoning=row.get("supports_reasoning"),
        )

    harness_results = {}
    for engine in ("codex",):
        harness_result = _harness_model_list_result(engine)
        harness_results[engine] = harness_result
        for row in harness_result.get("records") or []:
            _model_catalog_add(
                catalog,
                engine,
                row.get("id"),
                label=row.get("label"),
                source=row.get("source") or f"{engine}-cli",
                description=row.get("description"),
                priority=row.get("priority"),
                reasoning_efforts=row.get("reasoning_efforts"),
                default_reasoning_effort=row.get("default_reasoning_effort"),
            )

    _codex_mark_model_availability(catalog, harness_results.get("codex"))

    for row in _observed_model_records():
        _model_catalog_add(
            catalog,
            row.get("engine"),
            row.get("id"),
            label=row.get("label"),
            source=row.get("source") or "observed",
        )

    # Devin's model catalog is generated from ``devin models list --format json``
    # so CCC can expose effort suffixes (max, xhigh, low, ...) directly in the
    # model picker. We keep it scoped to the curated families so the list stays
    # usable; Devin accepts custom uids too, so users can still type e.g.
    # claude-opus-5-max-fast.
    try:
        curated_devin_families = [
            opt["id"]
            for opt in _ENGINE_CURATED_MODELS.get("devin", ())
        ]
        for row in _devin_model_catalog_records(curated_devin_families):
            _model_catalog_add(
                catalog,
                "devin",
                row.get("id"),
                label=row.get("label"),
                source=row.get("source") or "devin-cli",
                oneM=row.get("oneM"),
                max_context_tokens=row.get("max_context_tokens"),
                max_output_tokens=row.get("max_output_tokens"),
                cost_tier=row.get("cost_tier"),
                cost_summary=row.get("cost_summary"),
                entitlement=row.get("entitlement"),
                entitlement_summary=row.get("entitlement_summary"),
                entitlement_source=row.get("entitlement_source"),
            )
    except Exception:
        pass

    # Droid's catalog is built from Factory's published model docs and cross-
    # checked against the local Droid CLI. Factory uses usage multipliers, not
    # per-token prices, and has a separate free Droid Core tier.
    try:
        for row in _droid_model_catalog_records():
            _model_catalog_add(
                catalog,
                "droid",
                row.get("id"),
                label=row.get("label"),
                source=row.get("source") or "droid-cli",
                available=row.get("available"),
                availability_reason=row.get("availability_reason"),
                droid_core=row.get("droid_core"),
                multiplier=row.get("multiplier"),
                cost_tier=row.get("cost_tier"),
                cost_summary=row.get("cost_summary"),
                entitlement=row.get("entitlement"),
                entitlement_summary=row.get("entitlement_summary"),
                reasoning_efforts=row.get("reasoning_efforts"),
                default_reasoning_effort=row.get("default_reasoning_effort"),
                promotion_until=row.get("promotion_until"),
                base_multiplier=row.get("base_multiplier"),
                deprecated=row.get("deprecated"),
                notes=row.get("notes"),
            )
    except Exception:
        pass

    # OpenCode's catalog is built from `opencode models --verbose`. Provider
    # IDs are matched against the configured auth.json keys, so only credentialed
    # providers are marked available; the `opencode` built-in provider is always
    # allowed. Cost and limit values are surfaced per-million-tokens.
    try:
        for row in _opencode_model_catalog_records():
            _model_catalog_add(
                catalog,
                "opencode",
                row.get("id"),
                label=row.get("label"),
                source=row.get("source") or "opencode-cli",
                available=row.get("available"),
                availability_reason=row.get("availability_reason"),
                cost_tier=row.get("cost_tier"),
                cost_summary=row.get("cost_summary"),
                max_context_tokens=row.get("max_context_tokens"),
                max_output_tokens=row.get("max_output_tokens"),
                reasoning_efforts=row.get("reasoning_efforts"),
                default_reasoning_effort=row.get("default_reasoning_effort"),
                supports_vision=row.get("supports_vision"),
                supports_audio=row.get("supports_audio"),
                supports_tool_call=row.get("supports_tool_call"),
                supports_reasoning=row.get("supports_reasoning"),
            )
    except Exception:
        pass

    # BYOK-only models (openrouter/tokenrouter virtual routing, see
    # ccc_server/byok.py). These run through OpenCode's own "<provider>/
    # <vendor>/<model>" id format, so they're listed under the opencode
    # engine bucket; `byok: True` plus per-1M-token cost lets the picker
    # and Settings distinguish them from OpenCode's own credentialed models.
    try:
        configured_providers = {
            provider
            for profile in byok_list_profiles()
            for provider in profile.get("providers", [])
        }
        for row in BYOK_MODEL_CATALOG:
            _model_catalog_add(
                catalog,
                "opencode",
                row["id"],
                label=row.get("label"),
                source="byok",
                byok=True,
                provider=row.get("provider"),
                cost_in_per_1m=row.get("cost_in_per_1m"),
                cost_out_per_1m=row.get("cost_out_per_1m"),
                key_configured=row.get("provider") in configured_providers,
            )
    except Exception:
        pass

    if "claude" in catalog:
        catalog["claude"]["models"] = _prune_claude_models_to_latest_tiers(
            catalog["claude"].get("models") or []
        )

    if "antigravity" in catalog:
        catalog["antigravity"]["models"] = _prune_antigravity_models_to_latest_tiers(
            catalog["antigravity"].get("models") or [],
            default_id=catalog["antigravity"].get("default"),
        )

    for bucket in catalog.values():
        bucket.pop("_index", None)
        bucket["models"] = [
            entry for entry in bucket.get("models", [])
            if entry.get("id")
        ]

    payload = {
        "catalog": catalog,
        "engines": {
            engine: [entry["id"] for entry in bucket.get("models", [])]
            for engine, bucket in catalog.items()
        },
        "enforced": [],
        # Per-engine effort ladder, cheap→expensive, alongside the models each
        # engine offers. Codex already ships reasoning_efforts on its per-MODEL
        # rows; this is the engine-level answer Claude and Kimi never had, which
        # is why every picker grew its own hardcoded copy.
        "efforts_by_engine": _reasoning_efforts_by_engine(
            sorted(set(catalog) | set(_ENGINE_REASONING_EFFORTS) | {"kimi"})
        ),
        # Kimi thinking-effort picker metadata (from kimi's config.toml
        # support_efforts / [thinking] effort). The new-session input bar
        # builds its effort select from this when engine=kimi. Kept for
        # back-compat; efforts_by_engine["kimi"] carries the same ladder.
        "kimi_thinking": _kimi_thinking_config(),
    }
    _MODEL_CATALOG_CACHE["ts"] = now
    _MODEL_CATALOG_CACHE["data"] = copy.deepcopy(payload)
    return payload


def _validate_codex_model(model, *, require_available=False):
    """Resolve known Codex aliases and enforce CCC's picker allowlist."""
    if not model:
        return model, None
    key = model.strip().lower()
    alias = _CODEX_MODEL_ALIASES.get(key)
    if alias:
        model = alias
    if not _model_catalog_allows_model("codex", model):
        return model, (
            f"unsupported codex model: {model!r}. Supported codex models: "
            + ", ".join(_ENGINE_KNOWN_MODELS["codex"])
        )
    if require_available:
        unavailable = _codex_model_availability_error(model)
        if unavailable:
            return model, unavailable
    return model, None


def _load_spawn_defaults():
    """Return the server-backed defaults used by new-session spawns.

    These defaults are intentionally server-side rather than localStorage so
    ccc-orchestration and other scripted callers see the same values as the UI.
    Missing file means the historical behavior: Claude + opus, Codex env/gpt,
    Cursor env/auto, and Antigravity's configured CLI model when one exists.
    """
    defaults = {
        "engine": "claude",
        "reasoning_effort": "",
        "auto_compact_k": 250,
        "worker_engine": "",
        "worker_model": "",
        "worker_reasoning_effort": "",
        "worker_auto_compact_k": 250,
        "models": {
            engine: _spawn_fallback_model_for_engine(engine)
            for engine in _ORCHESTRATION_SPAWN_ENGINES
        },
    }
    try:
        raw = json.loads(SPAWN_DEFAULTS_FILE.read_text())
    except (OSError, json.JSONDecodeError):
        return defaults
    if not isinstance(raw, dict):
        return defaults

    engine = _normalize_orchestration_spawn_engine(raw.get("engine"))
    if engine not in _ORCHESTRATION_SPAWN_ENGINES:
        engine = defaults["engine"]

    models = dict(defaults["models"])
    raw_models = raw.get("models")
    if isinstance(raw_models, dict):
        for key, value in raw_models.items():
            norm = _normalize_orchestration_spawn_engine(key)
            if norm not in _ORCHESTRATION_SPAWN_ENGINES:
                continue
            model = _clean_spawn_default_model(value)
            if len(model) <= 200:
                models[norm] = model
    for required in ("claude", "codex", "cursor", "hermes"):
        if not models.get(required):
            models[required] = defaults["models"].get(required) or _spawn_fallback_model_for_engine(required)
    reasoning_effort = _validate_reasoning_effort(
        raw.get("reasoning_effort") or raw.get("effort"), engine,
    )
    # The WatchTower queue-worker default (WT's config.engine() fallback chain
    # reads this key). Separate from `engine`, which is the interactive
    # new-session default (WT-105). Blank = WT picks (codex when installed).
    worker_engine_raw = str(raw.get("worker_engine") or "").strip()
    worker_engine = (
        _normalize_orchestration_spawn_engine(worker_engine_raw)
        if worker_engine_raw else ""
    )
    if worker_engine not in _ORCHESTRATION_SPAWN_ENGINES:
        worker_engine = ""
    # A blank worker_engine means WatchTower decides at dispatch time, so
    # validate against Claude's ladder — the widest one. A level the engine WT
    # picks cannot use is dropped there, not silently erased from the defaults.
    worker_reasoning_effort = _validate_reasoning_effort(
        raw.get("worker_reasoning_effort"), worker_engine or "claude",
    )
    worker_model = _clean_spawn_default_model(raw.get("worker_model"))
    if len(worker_model) > 200:
        worker_model = ""

    auto_compact_k = _validate_auto_compact_k(raw.get("auto_compact_k"))
    worker_auto_compact_k = _validate_auto_compact_k(raw.get("worker_auto_compact_k"))
    return {
        "engine": engine, "models": models,
        "reasoning_effort": reasoning_effort,
        "auto_compact_k": auto_compact_k,
        "worker_engine": worker_engine,
        "worker_model": worker_model,
        "worker_reasoning_effort": worker_reasoning_effort,
        "worker_auto_compact_k": worker_auto_compact_k,
    }


def _save_spawn_defaults(config):
    if not isinstance(config, dict):
        return {"ok": False, "error": "expected JSON object"}
    current = _load_spawn_defaults()
    if "engine" in config:
        engine = _normalize_orchestration_spawn_engine(config.get("engine"))
        if engine not in _ORCHESTRATION_SPAWN_ENGINES:
            return {
                "ok": False,
                "error": f"unsupported engine: {config.get('engine')}",
                "supported_engines": list(_ORCHESTRATION_SPAWN_ENGINES),
            }
        current["engine"] = engine

    if "worker_engine" in config:
        worker_raw = str(config.get("worker_engine") or "").strip()
        worker_engine = (
            _normalize_orchestration_spawn_engine(worker_raw) if worker_raw else ""
        )
        if worker_engine not in (*_ORCHESTRATION_SPAWN_ENGINES, ""):
            return {
                "ok": False,
                "error": f"unsupported worker_engine: {config.get('worker_engine')}",
                "supported_engines": list(_ORCHESTRATION_SPAWN_ENGINES),
            }
        current["worker_engine"] = worker_engine

    if "worker_model" in config:
        worker_model = _clean_spawn_default_model(config.get("worker_model"))
        if len(worker_model) > 200:
            return {"ok": False, "error": "worker_model is too long"}
        current["worker_model"] = worker_model

    if "reasoning_effort" in config or "effort" in config:
        # Validated against the engine this save leaves selected, so Claude can
        # hold "max" and Codex still cannot.
        reasoning_effort = _validate_reasoning_effort(
            config.get("reasoning_effort")
            if "reasoning_effort" in config
            else config.get("effort"),
            current["engine"],
            strict=True,
        )
        if reasoning_effort is None:
            return {
                "ok": False,
                "error": _reasoning_effort_error("reasoning_effort", current["engine"]),
            }
        current["reasoning_effort"] = reasoning_effort

    if "worker_reasoning_effort" in config:
        worker_engine_for_effort = current.get("worker_engine") or "claude"
        worker_reasoning_effort = _validate_reasoning_effort(
            config.get("worker_reasoning_effort"), worker_engine_for_effort, strict=True,
        )
        if worker_reasoning_effort is None:
            return {
                "ok": False,
                "error": _reasoning_effort_error(
                    "worker_reasoning_effort", worker_engine_for_effort,
                ),
            }
        current["worker_reasoning_effort"] = worker_reasoning_effort

    if "auto_compact_k" in config:
        current["auto_compact_k"] = _validate_auto_compact_k(config.get("auto_compact_k"))

    if "worker_auto_compact_k" in config:
        current["worker_auto_compact_k"] = _validate_auto_compact_k(config.get("worker_auto_compact_k"))

    raw_models = config.get("models")
    if raw_models is not None and not isinstance(raw_models, dict):
        return {"ok": False, "error": "models must be an object"}
    if isinstance(raw_models, dict):
        for key, value in raw_models.items():
            engine = _normalize_orchestration_spawn_engine(key)
            if engine not in _ORCHESTRATION_SPAWN_ENGINES:
                return {
                    "ok": False,
                    "error": f"unsupported model engine: {key}",
                    "supported_engines": list(_ORCHESTRATION_SPAWN_ENGINES),
                }
            model = _clean_spawn_default_model(value)
            if len(model) > 200:
                return {"ok": False, "error": f"{engine} model is too long"}
            if engine in ("claude", "codex", "cursor", "hermes") and not model:
                model = _spawn_fallback_model_for_engine(engine)
            current["models"][engine] = model

    payload = {
        "engine": current["engine"],
        "reasoning_effort": current.get("reasoning_effort", ""),
        "auto_compact_k": current.get("auto_compact_k", 250),
        "worker_engine": current.get("worker_engine", ""),
        "worker_model": current.get("worker_model", ""),
        "worker_reasoning_effort": current.get("worker_reasoning_effort", ""),
        "worker_auto_compact_k": current.get("worker_auto_compact_k", 250),
        "models": {
            engine: current["models"].get(engine, "")
            for engine in _ORCHESTRATION_SPAWN_ENGINES
        },
    }
    COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
    tmp = SPAWN_DEFAULTS_FILE.with_suffix(".json.tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2, sort_keys=True)
        f.write("\n")
    tmp.replace(SPAWN_DEFAULTS_FILE)
    return {"ok": True, **payload}


def _validate_auto_compact_k(value, default=250):
    try:
        v = int(value)
    except (TypeError, ValueError):
        return default
    return max(50, min(1000, v))


def _spawn_auto_compact_k_tokens(auto_compact_k=None):
    """Return autocompact threshold in tokens for the current process role."""
    if auto_compact_k is not None:
        return _validate_auto_compact_k(auto_compact_k) * 1000
    is_worker = os.environ.get("CCC_WORKER_PROCESS") == "1"
    key = "worker_auto_compact_k" if is_worker else "auto_compact_k"
    return _validate_auto_compact_k((_load_spawn_defaults() or {}).get(key, 250)) * 1000


def _spawn_env(auto_compact_k=None):
    """Child env for a new spawned session, including autocompact window."""
    env = _question_relay_env()
    tokens = _spawn_auto_compact_k_tokens(auto_compact_k=auto_compact_k)
    if tokens:
        env["CLAUDE_CODE_AUTO_COMPACT_WINDOW"] = str(tokens)
    return env


def _spawn_model_for_engine(engine, explicit_model=None):
    model = _clean_spawn_default_model(explicit_model)
    if model:
        return model
    defaults = _load_spawn_defaults()
    model = _clean_spawn_default_model((defaults.get("models") or {}).get(engine))
    if model:
        return model
    return _spawn_fallback_model_for_engine(engine)


def _spawn_request_engine_and_model(payload):
    payload = payload if isinstance(payload, dict) else {}
    defaults = _load_spawn_defaults()
    engine_raw = payload.get("engine")
    has_engine = isinstance(engine_raw, str) and bool(engine_raw.strip())
    engine = _normalize_orchestration_spawn_engine(engine_raw) if has_engine else defaults["engine"]
    if engine not in _ORCHESTRATION_SPAWN_ENGINES:
        return None, None
    model = _clean_spawn_default_model(payload.get("model"))
    if not model:
        model = _clean_spawn_default_model((defaults.get("models") or {}).get(engine))
    if not model:
        model = _spawn_fallback_model_for_engine(engine)
    return engine, model or None


def _spawn_request_reasoning_effort(payload, engine):
    """Resolve an explicit effort or the persisted spawn default, per engine.

    Engines with no effort ladder resolve to "" without touching the defaults
    file, so every spawn branch can pass the value through unconditionally.
    """
    if not _engine_reasoning_efforts(engine):
        return ""
    payload = payload if isinstance(payload, dict) else {}
    if "reasoning_effort" in payload or "effort" in payload:
        value = payload.get("reasoning_effort") if "reasoning_effort" in payload else payload.get("effort")
    else:
        defaults = _load_spawn_defaults()
        value = defaults.get("reasoning_effort") or ""
    return _validate_reasoning_effort(value, engine)


# Canonical effort ladder, cheap→expensive. Kimi model configs declare their
# own subsets via support_efforts; ordering here is the display/union order.
_KIMI_EFFORT_ORDER = ("low", "medium", "high", "xhigh", "max")


def _kimi_thinking_config():
    """{"efforts": [...], "default": str} from kimi's config.toml.

    efforts = ordered union of every [models."<alias>"] support_efforts
    list; default = [thinking] effort (the CLI's global default). Both empty
    when the config is unreadable or tomllib is unavailable — callers then
    treat any ladder value as acceptable and show the static list."""
    out = {"efforts": [], "default": ""}
    if tomllib is None:
        return out
    try:
        raw = (_kimi_code_home() / "config.toml").read_text(encoding="utf-8")
    except OSError:
        return out
    try:
        data = tomllib.loads(raw)
    except tomllib.TOMLDecodeError:
        return out
    if not isinstance(data, dict):
        return out
    thinking = data.get("thinking")
    if isinstance(thinking, dict):
        out["default"] = str(thinking.get("effort") or "").strip().lower()
    seen = set()
    models = data.get("models")
    if isinstance(models, dict):
        for spec in models.values():
            if not isinstance(spec, dict):
                continue
            levels = spec.get("support_efforts")
            if isinstance(levels, list):
                seen.update(
                    str(x).strip().lower() for x in levels if str(x).strip()
                )
            if not out["default"] and spec.get("default_effort"):
                out["default"] = str(spec.get("default_effort")).strip().lower()
    out["efforts"] = [e for e in _KIMI_EFFORT_ORDER if e in seen]
    return out


def _spawn_request_kimi_effort(payload):
    """Validate an explicit Kimi thinking effort from a spawn payload.

    Blank means "leave kimi's configured default alone". When the local
    config declares support_efforts, reject values outside the union so a
    stale picker can't send something the model would reject; otherwise any
    ladder value passes (older CLI builds coerce it to the default anyway)."""
    payload = payload if isinstance(payload, dict) else {}
    value = str(
        payload.get("reasoning_effort") or payload.get("effort") or ""
    ).strip().lower()
    if not value or value not in _KIMI_EFFORT_ORDER:
        return ""
    supported = _kimi_thinking_config().get("efforts") or []
    if supported and value not in supported:
        return ""
    return value


# Archive view delegates all per-session JSONL inspection to the
# canonical _extract_tail_meta() (defined later in the file), which is
# already mtime-cached and is the same source of truth /api/sessions
# uses. That gives us has_edit / has_commit / has_push from tool-call
# events, tail_pr_number / tail_pr_url from `gh pr create`,
# last_assistant_text, pending_tool, custom_title, last_event_type —
# all without a second pass. Earlier branches of this code ran git
# status per cwd, which couldn't distinguish per-session history
# (every session in the same clone got the same answer) and missed
# has_push entirely.
_ARCHIVE_PILLS_RECENT_WINDOW = 3 * 86400

# PR state cache for the sidebar's "Ready to merge" bucket. Without this,
# every session that ever ran `gh pr create` sticks in "Ready to merge"
# forever — even after the PR is merged or closed. We cache the resolved
# state ("OPEN"/"MERGED"/"CLOSED") per PR URL with a TTL so the bucket
# reflects reality without paying gh-network cost on every refresh. OPEN
# entries expire quickly (a merge should show up within minutes); terminal
# states are cached (near-)permanently — see the TTL constants below.
# Keyed by full PR URL because two sessions can refer to the same PR; the
# cache is shared across them.
_PR_STATE_CACHE = {}
_PR_STATE_LOCK = threading.Lock()
_PR_STATE_TTL = 300  # 5 minutes — short enough to catch a merge, long
# enough that the dashboard's ~10s refresh cadence doesn't fan out to gh.
_PR_STATE_FAILURE_TTL = 30  # Retry gh failures soon; don't pin stale RTM rows.
# Terminal states: MERGED is immutable, so never re-query (10y ≈ forever —
# JSON can't encode inf). A CLOSED-unmerged PR can be reopened, so re-check
# those daily instead of permanently. Before this split, every historical PR
# was re-polled every 5 min: ~85 URLs × 4 GraphQL pts each ≈ 4k pts/hr
# against the account's 5k/hr quota.
_PR_STATE_MERGED_TTL = 10 * 365 * 24 * 3600
_PR_STATE_CLOSED_TTL = 24 * 3600


def _github_pull_api_path(pr_url):
    """Return the gh-api path for a github.com PR URL, or None."""
    try:
        parsed = urllib.parse.urlparse(pr_url or "")
    except (TypeError, ValueError):
        return None
    if parsed.netloc.lower() != "github.com":
        return None
    parts = [urllib.parse.unquote(p) for p in parsed.path.split("/") if p]
    if len(parts) < 4 or parts[2] != "pull" or not parts[3].isdigit():
        return None
    owner, repo, number = parts[0], parts[1], parts[3]
    if not owner or not repo:
        return None
    return f"repos/{owner}/{repo}/pulls/{number}"


def _valid_pr_state(value):
    state = (value or "").strip().upper()
    return state if state in ("OPEN", "MERGED", "CLOSED") else None


def _get_pr_state(pr_url):
    """Resolve a PR's state via `gh pr view`, with TTL cache.

    Returns one of "OPEN" / "MERGED" / "CLOSED", or None if the lookup
    failed (gh missing, unauthed, network down, PR not found). Callers
    treat None as "still ready to merge" — we never hide a real PR
    because gh hiccupped.
    """
    if not pr_url:
        return None
    _hydrate_gh_cache("pr_states", _PR_STATE_CACHE)
    now = time.time()
    with _PR_STATE_LOCK:
        cached = _PR_STATE_CACHE.get(pr_url)
        if cached:
            ttl = cached.get("ttl", _PR_STATE_TTL)
            if (now - cached.get("at", 0)) < ttl:
                return cached.get("state")
    gh_bin = shutil.which("gh") or "gh"
    state = None
    try:
        r = subprocess.run(
            [gh_bin, "pr", "view", pr_url, "--json", "state", "-q", ".state"],
            capture_output=True, text=True, timeout=8,
        )
        if r.returncode == 0:
            state = _valid_pr_state(r.stdout)
    except (subprocess.SubprocessError, OSError):
        state = None

    # `gh pr view <url>` can be more cwd/config-sensitive than the REST API
    # path. Fall back to `gh api` so merged PRs don't linger in Ready to merge
    # just because one resolver path hiccupped.
    if state is None:
        api_path = _github_pull_api_path(pr_url)
        if api_path:
            try:
                r = subprocess.run(
                    [
                        gh_bin, "api", api_path,
                        "--jq",
                        'if .merged_at then "MERGED" elif .state == "closed" then "CLOSED" else "OPEN" end',
                    ],
                    capture_output=True, text=True, timeout=8,
                )
                if r.returncode == 0:
                    state = _valid_pr_state(r.stdout)
            except (subprocess.SubprocessError, OSError):
                state = None
    if state == "MERGED":
        ttl = _PR_STATE_MERGED_TTL
    elif state == "CLOSED":
        ttl = _PR_STATE_CLOSED_TTL
    elif state:
        ttl = _PR_STATE_TTL
    else:
        ttl = _PR_STATE_FAILURE_TTL
    with _PR_STATE_LOCK:
        _PR_STATE_CACHE[pr_url] = {
            "state": state,
            "at": now,
            "ts": now,
            "ttl": ttl,
        }
    _persist_gh_cache("pr_states", _PR_STATE_CACHE)
    return state


def _prime_pr_states(pr_urls):
    """Resolve PR states for a batch of URLs in parallel, populating the
    cache so subsequent _get_pr_state() calls hit cache. Used by the
    list builders to avoid serial gh-fan-out on cold refreshes (worst
    case: cross-folder mode with dozens of unique PRs). No-op for URLs
    already in cache and within TTL.
    """
    now = time.time()
    needed = []
    seen = set()
    with _PR_STATE_LOCK:
        for url in pr_urls:
            if not url or url in seen:
                continue
            seen.add(url)
            cached = _PR_STATE_CACHE.get(url)
            ttl = cached.get("ttl", _PR_STATE_TTL) if cached else _PR_STATE_TTL
            if not cached or (now - cached.get("at", 0)) >= ttl:
                needed.append(url)
    if not needed:
        return
    # Bounded pool — gh handles concurrent reads fine, but we don't want
    # to fork 100 subprocesses if a user has been opening PRs all year.
    with ThreadPoolExecutor(max_workers=8) as ex:
        list(ex.map(_get_pr_state, needed))


def _bust_pr_state_cache(url=None):
    """Force the next _get_pr_state() to re-query gh. If url is given, only
    that URL's entry is dropped; otherwise the whole cache clears. Call after
    a merge/close action so the badge updates immediately instead of waiting
    out the TTL."""
    with _PR_STATE_LOCK:
        if url:
            _PR_STATE_CACHE.pop(url, None)
        else:
            _PR_STATE_CACHE.clear()
    _persist_gh_cache("pr_states", _PR_STATE_CACHE)


# Cache of session ids whose engine CLI (codex/gemini/cursor) is currently
# running, resolved by matching live process command lines against resume
# args. Claude sessions are covered by sidecar markers instead (see below) and
# are NOT included here. Rebuilt at most once per _ENGINE_LIVE_TTL seconds so
# the bulk session list (which calls _archive_session_is_live per row) does a
# single ps scan rather than one per row.
_engine_live_sids_cache = {"ts": 0.0, "sids": frozenset()}
_ENGINE_LIVE_TTL = 4.0
_codex_pool_alive_cache = {"ts": 0.0, "alive": True}


def _live_engine_session_ids():
    """Set of session ids for non-Claude engine CLIs currently running.

    One ps-backed scan per engine, cached for _ENGINE_LIVE_TTL. We only count
    sessions whose id appears in a live process's resume args (the exact-match
    signal), which is cheap and unambiguous — no cwd heuristics here, since the
    bulk list can't afford per-row disambiguation."""
    now = time.time()
    cached = _engine_live_sids_cache
    if now - cached["ts"] < _ENGINE_LIVE_TTL:
        return cached["sids"]
    sids = set()
    try:
        for engine in ("codex", "gemini", "cursor", "grok"):
            for _pid_s, cmd in _raw_engine_process_commands(engine):
                # Pull any resume-arg session id out of the command line. The
                # matcher needs a candidate id, so test each whitespace token
                # that looks like a session id against the exact matcher.
                for tok in cmd.split():
                    if len(tok) >= 16 and _command_targets_engine_session(cmd, tok, engine):
                        sids.add(tok)
        for s in _spawned_sessions:
            engine = str(s.get("engine") or "claude").lower()
            if engine in ("claude", "remote-claude"):
                continue
            try:
                if _poll_spawn_entry(s) is not None:
                    continue
            except Exception:
                continue
            sid = s.get("session_id")
            if not sid:
                log = s.get("log")
                if engine == "codex":
                    sid = _extract_codex_thread_id_from_log(log)
                elif engine == "gemini":
                    sid = _extract_gemini_session_id_from_log(log)
                elif engine == "cursor":
                    sid = _extract_cursor_chat_id_from_log(log) or _cursor_session_id_for_spawn_entry(s)
            if sid:
                sids.add(sid)
    except Exception:
        # Never let liveness detection break the list; fall back to last cache.
        return cached["sids"]
    result = frozenset(sids)
    _engine_live_sids_cache["ts"] = now
    _engine_live_sids_cache["sids"] = result
    return result


# A conversation written this recently still gets the precise (file-scanning)
# liveness probe even if it's not in the cheap live-candidate set — covers
# pool-model Codex, whose rollout changes but carries no resume-arg signal.
# Codex itself treats <5min as "recently written" (session_live_status); 10min
# is a safe backstop. Older, untouched rows skip the probe entirely.
_LIVE_MTIME_WINDOW = 600

# A Claude liveness sidecar (a hook-written marker in SIDECAR_STATE_DIR) only
# proves the session is live while it is FRESH. The hooks never delete these
# markers on session end, and an interactive Claude session carries no
# resume-arg on its command line for the live-process scan to refute — so a
# stale marker would otherwise pin a long-dead session "live" indefinitely
# (observed: sessions idle for days still flagged live). Treat a marker older
# than this window as dead. Tunable: larger keeps idle-but-open sessions lit
# longer; smaller tracks active work more tightly.
_SIDECAR_LIVE_WINDOW = 1800

# How long a sticky `sidecar_status == "active"` (last-completed-tool marker,
# only cleared when the Stop hook fires) still counts as "working" in
# `_session_state_label`. Bridges the between-tools think gap — where no
# `_in_flight.json` exists yet the turn is mid-flight — without letting an
# interrupted/abandoned turn read "working" for the full liveness window. Real
# tool execution (sidecar_in_flight / pending_tool / sub-agent) counts
# regardless of this bound; this only gates the sticky `active` proxy.
_WORKING_GAP_WINDOW = 120

# CCC-174 anti-flicker: how long a LIVE session stays pinned to "waiting" after
# the underlying waiting signal transiently disappears. The three waiting
# triggers (`question_waiting`, `needs_approval`, soft-block prose) are all
# recomputed fresh every poll from flap-prone live state: the Notification
# `_needs_approval` marker is set by the hook and cleared by PostToolUse, and
# the soft-block terminal gate flips the moment a tool starts/stops between
# polls — so a session genuinely parked on the human bounces NEEDS YOU ⇄ IN
# PROGRESS with no real change. We DEMOTE-debounce only: entering "waiting" is
# always immediate (a real ask shows at once); LEAVING it is held for this
# window so a single transient poll can't flicker the section. An ended process
# (state=="ended") drops the pin instantly — you resume, not reply.
_WAITING_STICKY_WINDOW = 90  # seconds
_waiting_sticky_seen = {}    # session_id -> monotonic ts of last real "waiting"


def _stamp_session_state(c):
    """`_session_state_label` plus demote-only "waiting" hysteresis (CCC-174).

    `_session_state_label` stays a pure function (every unit test binds to it
    directly); the stickiness lives here, at the row-stamping sites that own a
    session_id and run once per poll. Returns the coarse state to stamp.

    Rules:
      - raw == "waiting"            → record now, return "waiting".
      - raw != "waiting", live, and last real "waiting" was within the window
                                    → hold "waiting" (damp the transient demotion).
      - otherwise                   → forget the session, return raw.
    """
    raw = _session_state_label(c)
    sid = c.get("session_id") or c.get("id")
    if not sid:
        return raw
    now = time.monotonic()
    if raw == "waiting":
        _waiting_sticky_seen[sid] = now
        return raw
    # A dead process is "ended" — never hold it as waiting (you resume it, you
    # do not reply to it). Drop the pin and report the real state.
    if raw == "ended" or not c.get("is_live"):
        _waiting_sticky_seen.pop(sid, None)
        return raw
    seen = _waiting_sticky_seen.get(sid)
    if seen is not None and (now - seen) < _WAITING_STICKY_WINDOW:
        return "waiting"
    _waiting_sticky_seen.pop(sid, None)
    return raw


# Short-TTL memo for the per-session liveness probe. _archive_session_is_live is
# called PER ROW by the bulk archive/live endpoints (rehydrate, live-activity,
# per-session), and each call runs uncached engine predicates
# (_is_codex/gemini/cursor_session) that hit the filesystem/DB. Under continuous
# dashboard + COO polling that became a per-row lstat storm across many
# concurrent request threads, GIL-bound — the dominant CPU cost `sample` caught
# (os_lstat / take_gil). The same session ids are re-probed every poll cycle by
# every endpoint, so a tiny TTL memo collapses those redundant probes to one per
# session per window. Liveness already lags by the serve TTL (2s) and the engine
# scan TTL (4s), so a ~2s memo introduces no staleness the callers didn't have.
_session_live_cache = {}  # sid -> (ts, bool)
_session_live_lock = threading.Lock()
try:
    _SESSION_LIVE_TTL = max(0.0, float(os.environ.get("CCC_SESSION_LIVE_TTL_SEC", "2")))
except ValueError:
    _SESSION_LIVE_TTL = 2.0


def _archive_session_is_live(session_id):
    """Memoized per-session liveness (see _archive_session_is_live_uncached)."""
    if not session_id or _SESSION_LIVE_TTL <= 0:
        return _archive_session_is_live_uncached(session_id)
    now = time.time()
    with _session_live_lock:
        hit = _session_live_cache.get(session_id)
        if hit is not None and (now - hit[0]) < _SESSION_LIVE_TTL:
            return hit[1]
    live = _archive_session_is_live_uncached(session_id)
    with _session_live_lock:
        _session_live_cache[session_id] = (time.time(), live)
        # Bound the cache: drop entries older than a few TTLs so it can't grow
        # unbounded across the full session history over a long uptime.
        if len(_session_live_cache) > 4096:
            cutoff = time.time() - (_SESSION_LIVE_TTL * 4)
            for k in [k for k, v in _session_live_cache.items() if v[0] < cutoff]:
                _session_live_cache.pop(k, None)
    return live


def _archive_session_is_live_uncached(session_id):
    """A session is "live" if any sidecar marker exists for it (Claude only),
    OR a non-Claude engine CLI (codex/gemini/cursor/antigravity) is running it.

    Claude sidecars are written by Claude Code's hooks. The hook can run
    with a non-Claude session id in scope (e.g. a Claude hook firing a
    `git commit --trailer "Co-authored-by: Cursor"` on behalf of a Cursor
    agent) — that writes a Claude-format sidecar keyed under a Cursor sid,
    polluting liveness detection. The cursor row then falsely lights up
    WIP "Shell" forever. Defense: non-Claude engines NEVER trust the
    Claude sidecar — their liveness comes solely from the live-process
    scan.
    """
    if not session_id:
        return False
    engine = _detect_session_engine(session_id)
    # Kimi sessions share one ACP harness rather than owning a per-session
    # process. As long as that harness is available, a Kimi session can receive
    # queued input once its current turn becomes idle.
    if engine in ("kimi", "grok"):
        return bool(_acp_resolve_bin(engine).get("available"))
    is_non_claude_engine = engine in {
        "codex", "cursor", "gemini", "antigravity", "kilo", "opencode",
    }
    if not is_non_claude_engine and SIDECAR_STATE_DIR.is_dir():
        # Only a FRESH sidecar proves liveness — a stale one is a dead session's
        # leftover marker (see _SIDECAR_LIVE_WINDOW). stat() instead of exists()
        # keeps the syscall count identical while giving us the mtime to gate on.
        now = time.time()
        try:
            for suffix in (".json", "_writes", "_in_flight.json", "_needs_approval.json", "_compacting.json"):
                try:
                    st = (SIDECAR_STATE_DIR / f"{session_id}{suffix}").stat()
                except (OSError, ValueError):
                    continue
                if (now - st.st_mtime) < _SIDECAR_LIVE_WINDOW:
                    return True
        except OSError:
            pass
    if session_id in _live_engine_session_ids():
        return True
    # Pool-model codex (Codex.app `codex app-server`) puts no session id on
    # any command line, so the resume-arg scan above misses it. A codex
    # session whose rollout was written recently (non-None codex_state) and
    # whose engine pool is up is live.
    if engine == "codex":
        return _codex_state_fields(session_id).get("codex_state") is not None
    return False


_LIVE_ACTIVITY_FIELD_KEYS = (
    "is_live",
    "sidecar_status",
    "sidecar_has_writes",
    "sidecar_tool",
    "sidecar_file",
    "sidecar_ts",
    "sidecar_in_flight",
    "is_compacting",
    "compacting_trigger",
    "recently_interrupted",
    "pending_tool",
    "pending_file",
    "last_event_type",
    "codex_state",
    "codex_fresh",
    "codex_state_reason",
    "codex_writer",
    "codex_desktop_attached",
    "needs_approval",
    "needs_approval_message",
    "question_waiting",
    "question_text",
    "question_header",
    "question_preamble",
    "question_options",
    "question_option_details",
    "turn_age_s",
    "stale_tool_call",
    "stale_tool_age_s",
    "stale_tool_threshold_s",
)


def _discover_live_session_ids():
    """Session ids that may have live-work indicators right now.

    Cheap set union: Claude registry, engine CLI resume args, and any
    sidecar marker files on disk. Used by /api/sessions/live-activity so the
    sidebar can refresh WIP chips without re-scanning every JSONL.
    """
    sids = set()
    try:
        sids.update(_load_session_registry().keys())
    except Exception:
        pass
    try:
        sids.update(_live_engine_session_ids())
    except Exception:
        pass
    if SIDECAR_STATE_DIR.is_dir():
        # CANDIDACY GATE: only a sidecar marker FRESH within _SIDECAR_LIVE_WINDOW
        # can make a session live (_archive_session_is_live_uncached rejects
        # older ones on the same window). Sidecar files are never cleaned up, so
        # this dir accumulates one marker per session that ever ran — 300+ stale
        # markers for a handful of live sessions. Feeding the stale ones as
        # candidates makes every live-activity build re-stat hundreds of
        # guaranteed-dead sessions (4 stat()s each, every ~2s). Filter by mtime
        # HERE so the candidate set scales with ACTIVE sessions, not all-time
        # history. Correctness-preserving: a marker too old to prove liveness is
        # dropped from candidacy, never from a genuinely-live result.
        now = time.time()
        try:
            for f in SIDECAR_STATE_DIR.iterdir():
                try:
                    st = f.stat()
                except OSError:
                    continue
                if not stat.S_ISREG(st.st_mode):
                    continue
                if (now - st.st_mtime) >= _SIDECAR_LIVE_WINDOW:
                    continue  # stale marker — cannot indicate a live session
                name = f.stem
                if name.endswith("_writes"):
                    sid = name[: -len("_writes")]
                elif name.endswith("_in_flight"):
                    sid = name[: -len("_in_flight")]
                elif name.endswith("_needs_approval"):
                    sid = name[: -len("_needs_approval")]
                elif name.endswith("_compacting"):
                    sid = name[: -len("_compacting")]
                else:
                    sid = name
                if sid:
                    sids.add(sid)
        except OSError:
            pass
    # ACP-attached sessions (kimi/grok harnesses) own no per-session OS
    # process — the harness is one shared stdio process with no session id
    # on its command line — so neither the registry, the resume-arg scan,
    # nor Claude sidecars ever nominate them. A live ACP session was
    # invisible here: kimi always, and grok whenever the harness (not a
    # `grok --resume` TUI) drives it. The ACP registry is in-memory, so
    # this union is free; gate on recency with the same window as sidecar
    # markers so ancient idle sessions don't flood candidacy (every kimi/
    # grok sid passes the harness-availability liveness probe).
    try:
        now = time.time()
        for harness in (_ACP_HARNESSES or ()):
            try:
                if not _acp_harness_enabled(harness):
                    continue
                with _ACP_LOCK:
                    _acp_load_state(harness)
                    acp_sessions = dict(_ACP_SESSION_STATE.get(harness) or {})
            except Exception:
                continue
            for acp_sid, acp_state in acp_sessions.items():
                if not acp_sid or not isinstance(acp_state, dict):
                    continue
                if not acp_state.get("attached"):
                    continue
                if str(acp_state.get("status") or "") == "closed":
                    continue
                try:
                    updated = float(acp_state.get("updated_at") or 0)
                except (TypeError, ValueError):
                    updated = 0.0
                if updated and (now - updated) < _SIDECAR_LIVE_WINDOW:
                    sids.add(str(acp_sid))
    except Exception:
        pass
    return sids


_GROK_WIRE_TAIL_BYTES = 8192
_GROK_WIRE_TAIL_CACHE = {}  # path -> ((mtime_ns, size), meta) — same idiom as _KIMI_WIRE_TAIL_CACHE


def _grok_wire_tail_meta(transcript_path):
    """Last-turn shape from the tail of a Grok transcript (CCC ACP transcript
    or the on-disk store, whichever _grok_conversation_source picked).

    Events are user_text / assistant / result; a turn is mid-flight when the
    last event is not a result. Bounded tail read, (mtime,size)-keyed cache —
    repeat polls cost one stat."""
    meta = {"last_event_type": None, "mid_turn": False, "wire_mtime": 0.0}
    if not transcript_path:
        return meta
    path = Path(transcript_path)
    try:
        st = path.stat()
    except OSError:
        return meta
    meta["wire_mtime"] = st.st_mtime
    key = (st.st_mtime_ns, st.st_size)
    cache_key = str(path)
    cached = _GROK_WIRE_TAIL_CACHE.get(cache_key)
    if cached and cached[0] == key:
        return dict(cached[1])
    try:
        with path.open("rb") as f:
            if st.st_size > _GROK_WIRE_TAIL_BYTES:
                f.seek(-_GROK_WIRE_TAIL_BYTES, os.SEEK_END)
            raw = f.read(_GROK_WIRE_TAIL_BYTES)
    except OSError:
        return meta
    last_type = None
    for line in raw.decode("utf-8", "replace").split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            ev = json.loads(line)
        except json.JSONDecodeError:
            continue  # the window's first line is usually truncated
        etype = ev.get("type")
        if etype in ("user", "user_text", "assistant", "result"):
            last_type = etype
    meta["last_event_type"] = "user" if last_type == "user_text" else last_type
    meta["mid_turn"] = last_type in ("user", "user_text", "assistant")
    _GROK_WIRE_TAIL_CACHE[cache_key] = (key, dict(meta))
    if len(_GROK_WIRE_TAIL_CACHE) > 512:
        _GROK_WIRE_TAIL_CACHE.pop(next(iter(_GROK_WIRE_TAIL_CACHE)))
    return meta


_ACP_TURN_TRACK = {}  # (harness, sid) -> {"mid_turn": bool, "turn_started_at": epoch|None}


def _acp_live_activity_fields(harness, session_id):
    """Live-activity fields for ACP-harness sessions (kimi/grok).

    These sessions own no per-session OS process and write no Claude sidecar,
    so without this their live rows rendered with no timestamp (age '?') and
    no working/waiting signal at all. Reuses the same bounded, (mtime,size)-
    cached tail reads as the conversation providers; needs_approval comes
    from the ACP registry's pending_permissions (an approval parked on a
    human is the 'waiting' state, e.g. what the auto-approve watcher polls).

    Turn boundaries are tracked by observing mid_turn transitions here (the
    poller calls this every few seconds): False→True stamps turn_started_at,
    True→False clears it. No extra I/O, and honest: a long turn shows up as
    turn_age_s, while a turn whose wire goes silent past CCC_STALE_TOOL_SEC
    (default 900s) raises the dashboard's stale-tool contract — the "Stuck"
    signal. A turn that started before this process did gets turn_age_s
    None, never a fabricated age.
    """
    out = {"sidecar_ts": 0.0, "pending_tool": None, "last_event_type": None}
    state = {}
    try:
        with _ACP_LOCK:
            _acp_load_state(harness)
            state = dict(_ACP_SESSION_STATE.get(harness, {}).get(session_id) or {})
    except Exception:
        state = {}
    out["needs_approval"] = bool(state.get("pending_permissions"))
    if out["needs_approval"]:
        out["needs_approval_message"] = "Approval requested"
    tail = {}
    try:
        if harness == "kimi":
            idx = _kimi_session_index().get(session_id) or {}
            tail = _kimi_wire_tail_meta(idx.get("session_dir"))
        else:
            tail = _grok_wire_tail_meta(_grok_conversation_source(session_id))
        out["sidecar_ts"] = float(tail.get("wire_mtime") or 0)
        out["last_event_type"] = tail.get("last_event_type")
        if tail.get("mid_turn"):
            # A real pending tool beats the between-events think gap; the
            # label mirrors codex's "Thinking" pseudo-tool.
            out["pending_tool"] = tail.get("pending_tool") or "Thinking"
    except Exception:
        tail = {}
    if not out["sidecar_ts"]:
        try:
            out["sidecar_ts"] = float(state.get("updated_at") or 0)
        except (TypeError, ValueError):
            pass
    now = time.time()
    acp_active = str(state.get("status") or "") == "active"
    mid_turn = bool(tail.get("mid_turn")) or acp_active
    track_key = (harness, session_id)
    track = _ACP_TURN_TRACK.get(track_key)
    if track is None:
        track = _ACP_TURN_TRACK[track_key] = {"mid_turn": False, "turn_started_at": None}
        if len(_ACP_TURN_TRACK) > 512:
            _ACP_TURN_TRACK.pop(next(iter(_ACP_TURN_TRACK)))
    if mid_turn and not track["mid_turn"]:
        track["turn_started_at"] = now
    elif not mid_turn and track["mid_turn"]:
        track["turn_started_at"] = None
    track["mid_turn"] = mid_turn
    out["turn_age_s"] = (
        max(0.0, now - track["turn_started_at"]) if track["turn_started_at"] else None
    )
    try:
        threshold = float(_stale_tool_threshold_s())
    except Exception:
        threshold = 900.0
    silence = (now - out["sidecar_ts"]) if out["sidecar_ts"] else 0.0
    out["stale_tool_age_s"] = int(max(0.0, silence))
    out["stale_tool_threshold_s"] = int(threshold)
    out["stale_tool_call"] = bool(
        threshold > 0 and mid_turn and out["sidecar_ts"] and silence >= threshold
    )
    return out


def _live_activity_entry_for_session(session_id):
    """Sidecar-shaped activity snapshot for one session (no JSONL walk)."""
    entry = {"session_id": session_id, "is_live": _archive_session_is_live(session_id)}
    if not entry["is_live"]:
        return entry
    engine = _detect_session_engine(session_id)
    if engine == "codex":
        path = _resolve_codex_rollout_path(session_id)
        tail = _extract_codex_tail_meta(path) if path else {}
        entry.update(_codex_activity_fields_from_tail(tail, True))
        app_activity = _codex_app_server_activity_fields(session_id)
        if app_activity.get("sidecar_status") and not _codex_app_activity_superseded_by_tail(app_activity, tail):
            entry.update(app_activity)
        entry["pending_tool"] = tail.get("pending_tool")
        entry["pending_file"] = tail.get("pending_file")
        entry["last_event_type"] = tail.get("last_event_type")
        entry.update(_codex_state_fields(session_id))
    elif engine == "gemini":
        path = _resolve_gemini_chat_path(session_id)
        tail = _extract_gemini_tail_meta(path) if path else {}
        entry.update(_gemini_activity_fields_from_tail(tail, True))
        entry["pending_tool"] = tail.get("pending_tool")
        entry["pending_file"] = tail.get("pending_file")
        entry["last_event_type"] = tail.get("last_event_type")
    elif engine == "cursor":
        path = _cursor_transcript_path(session_id)
        tail = _extract_cursor_tail_meta(path) if path else {}
        entry.update(_cursor_activity_fields_from_tail(tail, True))
        entry["pending_tool"] = tail.get("pending_tool")
        entry["pending_file"] = tail.get("pending_file")
        entry["last_event_type"] = tail.get("last_event_type")
    elif engine == "antigravity":
        path = _antigravity_transcript_path(session_id)
        tail = _extract_antigravity_tail_meta(path) if path else {}
        entry.update(_antigravity_activity_fields_from_tail(tail, True))
        entry["pending_tool"] = tail.get("pending_tool")
        entry["pending_file"] = tail.get("pending_file")
        entry["last_event_type"] = tail.get("last_event_type")
    elif engine in ("kimi", "grok"):
        entry.update(_acp_live_activity_fields(engine, session_id))
    else:
        _add_sidecar_fields(entry)
    return entry


# Coalescing cache for the live-activity snapshot. /api/sessions/live-activity
# is polled by every dashboard client (browser tab + desktop app); without
# coalescing, each concurrent poll recomputed the whole snapshot, and slow polls
# made clients fire new ones before old ones finished — a pile-up that pinned a
# core on GIL/lock contention. The snapshot is inherently approximate (sidebar
# WIP chips), so serving one ≤TTL-old result to all concurrent callers is fine.
# The lock makes it single-flight: at most one build runs at a time; everyone
# else waits briefly and shares its result.
_LIVE_ACTIVITY_SNAPSHOT_TTL = 10.0
_live_activity_snapshot = {"ts": 0.0, "data": None}
_live_activity_snapshot_lock = threading.Lock()

# ── CCC self-health metrics ─────────────────────────────────────────────────
# Three cheap, in-process signals surfaced in the dashboard's bottom-left bar so
# the daemon's own health is glanceable: this process's CPU%, the wall-clock cost
# of the hot live-activity build, and a rolling count of recent server errors.
# Everything here is O(1) per update and reads nothing off disk on the hot path.
_SERVER_START_TS = time.time()

# ── Headless-resume lifecycle ledger (diagnostic only) ──────────────────────
# Append-only JSONL trace of the warm `claude -p` resume lifecycle so we can
# root-cause why warm processes die between messages and measure cache
# efficiency per resume. Pure observation — nothing here changes spawn/retire
# behavior. Off the hot path: the ledger is written only at lifecycle
# transitions (reuse/spawn/exit/retire/server_start), never per row or per poll
# iteration (the exit write is guarded to fire once via `_cleanup_done`).
if "pytest" in sys.modules:
    # Same rationale as ACTIVITY_LOG_FILE's pytest redirect at line 132:
    # the test suite re-imports this module fresh per test, and without a
    # redirect every test exercising an interrupt-detection code path would
    # write real lines into the live dashboard's resume ledger. Both the
    # current file and the rotation backup must be redirected, since
    # _resume_ledger_append rotates to _RESUME_LEDGER_BACKUP at 5MB.
    _RESUME_LEDGER_FILE = Path(tempfile.gettempdir()) / "ccc-test-resume-ledger.jsonl"
    _RESUME_LEDGER_BACKUP = Path(tempfile.gettempdir()) / "ccc-test-resume-ledger.1.jsonl"
else:
    _RESUME_LEDGER_FILE = COMMAND_CENTER_STATE_DIR / "resume-ledger.jsonl"
    _RESUME_LEDGER_BACKUP = COMMAND_CENTER_STATE_DIR / "resume-ledger.1.jsonl"
_RESUME_LEDGER_MAX_BYTES = 5 * 1024 * 1024
_RESUME_LEDGER_LOCK = threading.Lock()
# Bounded in-memory window feeding /api/health rolling stats — so the health
# poll never reparses the file (perf gate).
_RESUME_LEDGER_WINDOW = collections.deque(maxlen=50)
# sid -> epoch of that sid's most recent exit/cold_resume, for gap computation
# without reparsing the file.
_RESUME_LAST_EPOCH = {}
# sid -> deque of that sid's recent codex_wake_* rows, so the live wake-status
# endpoint (/api/codex-wake-status) can derive the stage timeline with NO file
# scan (perf gate). Bounded per sid AND in the number of tracked sids. Mirrors
# how `_RESUME_LEDGER_WINDOW` is kept — updated only at wake transitions.
_CODEX_WAKE_EVENTS = collections.OrderedDict()
_CODEX_WAKE_MAX_SIDS = 64
_CODEX_WAKE_PER_SID = 24


def _activity_log_preview(text, limit=160):
    """Collapse whitespace and truncate for a one-line log entry.

    Never raises: called from logging paths that must not break the action
    they're recording."""
    try:
        collapsed = " ".join(str(text or "").split())
    except Exception:
        return ""
    if len(collapsed) > limit:
        return collapsed[:limit].rstrip() + "…"
    return collapsed


# Set to True after the first successful mkdir of ACTIVITY_LOG_FILE's parent.
# The mkdir used to run on every _log_activity call; under memory pressure
# that syscall can stall for seconds, and liveness logging happens while
# holding _CODEX_APP_SERVER_LOCK -- stalling every thread waiting on that
# lock (see docs/HANDOFF_codex_appserver_liveness.md). Once the directory
# exists there is nothing to do, so only ever call mkdir again if a write
# actually fails with FileNotFoundError (e.g. the dir was deleted).
_ACTIVITY_LOG_DIR_READY = False


def _log_activity(category, verb, detail):
    """Append one line to the unified activity log (see ACTIVITY_LOG_FILE).

    Format matches ~/.watchtower/activity.log: `TIMESTAMP UTC  CATEGORY  VERB  detail`.
    Best-effort and silent on failure -- logging must never break the caller.

    category/verb are hard-truncated to their field widths (14/9 chars).
    _parse_activity_log_line reads this file back with fixed-width slicing
    -- chosen so `detail` can freely contain the same double-space
    separator used elsewhere in the line -- which only stays correct if
    every category/verb actually fits its column. A future caller passing
    a longer one would otherwise silently corrupt the parse (lost tail
    chars, a shifted detail with stray leading spaces) instead of failing
    loudly; truncating here is the lesser, contained failure.
    """
    global _ACTIVITY_LOG_DIR_READY
    try:
        now = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime()) + " UTC"
        line = f"{str(category)[:14]:<14}  {str(verb)[:9]:<9}{detail}\n"
        line = f"{now}  {line}"
        if not _ACTIVITY_LOG_DIR_READY:
            ACTIVITY_LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
            _ACTIVITY_LOG_DIR_READY = True
        try:
            with open(ACTIVITY_LOG_FILE, "a", encoding="utf-8") as f:
                f.write(line)
        except FileNotFoundError:
            # Directory vanished after we cached it as existing -- recreate
            # and retry once.
            ACTIVITY_LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
            with open(ACTIVITY_LOG_FILE, "a", encoding="utf-8") as f:
                f.write(line)
    except OSError:
        pass


def _parse_activity_log_line(line):
    """Split one `_log_activity` line back into its fields.

    Fixed-width slicing, not a regex split, because `detail` is free text
    and may itself contain the double-space separator used elsewhere in the
    line. Layout (see _log_activity): 23-char UTC timestamp, 2 spaces,
    14-char category, 2 spaces, 9-char verb, then detail with no separator.
    Returns None for a line too short to be one of ours (e.g. a stray
    newline) rather than raising.
    """
    line = line.rstrip("\n")
    if len(line) < 41:
        return None
    return {
        "ts": line[0:23].strip(),
        "category": line[25:39].strip(),
        "verb": line[41:50].strip(),
        "detail": line[50:],
    }


def _read_activity_log(session_id=None, limit=200):
    """Return up to `limit` most recent activity-log lines, oldest first.

    When `session_id` is given, only lines whose raw text contains it are
    kept -- a plain substring match (like grepping the file yourself), not
    a strict field match, so it also surfaces context lines that reference
    the session indirectly (e.g. a codex-app-server WEDGED line logged
    moments before this session's spawn failed). Malformed lines are
    skipped rather than raising.
    """
    try:
        limit = max(1, min(int(limit), 2000))
    except (TypeError, ValueError):
        limit = 200
    try:
        raw_lines = ACTIVITY_LOG_FILE.read_text(encoding="utf-8").splitlines()
    except OSError:
        return []
    if session_id:
        needle = str(session_id)
        raw_lines = [ln for ln in raw_lines if needle in ln]
    parsed = [p for p in (_parse_activity_log_line(ln) for ln in raw_lines) if p]
    return parsed[-limit:]


def _resume_ledger_append(event, sid=None, pid=None, **fields):
    """Append one lifecycle event to the resume ledger. Never raises."""
    try:
        now = time.time()
        rec = {
            "ts": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "epoch": round(now, 3),
            "event": event,
            "sid": sid,
            "pid": pid,
        }
        rec.update(fields)
        line = json.dumps(rec, default=str)
        with _RESUME_LEDGER_LOCK:
            _RESUME_LEDGER_WINDOW.append(rec)
            if event in ("exit", "cold_resume") and sid is not None:
                _RESUME_LAST_EPOCH[sid] = now
            # Feed the per-sid codex wake window (in-memory only; the endpoint
            # never touches the ledger file).
            if sid is not None and isinstance(event, str) and event.startswith("codex_wake"):
                dq = _CODEX_WAKE_EVENTS.get(sid)
                if dq is None:
                    dq = collections.deque(maxlen=_CODEX_WAKE_PER_SID)
                    _CODEX_WAKE_EVENTS[sid] = dq
                _CODEX_WAKE_EVENTS.move_to_end(sid)
                dq.append(rec)
                while len(_CODEX_WAKE_EVENTS) > _CODEX_WAKE_MAX_SIDS:
                    _CODEX_WAKE_EVENTS.popitem(last=False)
            try:
                COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
                try:
                    if (_RESUME_LEDGER_FILE.exists()
                            and _RESUME_LEDGER_FILE.stat().st_size > _RESUME_LEDGER_MAX_BYTES):
                        _RESUME_LEDGER_FILE.replace(_RESUME_LEDGER_BACKUP)
                except OSError:
                    pass
                with open(_RESUME_LEDGER_FILE, "a", encoding="utf-8") as fh:
                    fh.write(line + "\n")
            except OSError:
                pass
    except Exception:
        pass


def _resume_ledger_stats():
    """Rolling stats over the in-memory window for the /api/health `resume`
    object. Reads nothing off disk. Every field tolerates an empty window."""
    empty = {
        "warm_reuse_pct": None,
        "warm_reuse_hits": 0,
        "warm_reuse_attempts": 0,
        "avg_cache_efficiency_pct": None,
        "cold_resumes_window": 0,
        "worst_cache_efficiency_pct": None,
        "avg_lifetime_s": None,
    }
    try:
        with _RESUME_LEDGER_LOCK:
            window = list(_RESUME_LEDGER_WINDOW)
        if not window:
            return empty
        reuse_hit = sum(1 for e in window if e.get("event") == "reuse_hit")
        cold = sum(1 for e in window if e.get("event") == "cold_resume")
        # A resume ATTEMPT is exactly one of: reuse_hit (reused a live warm
        # process) or cold_resume (spawned a fresh `claude --resume`). Denominator
        # is the sum of those two. `reuse_miss` is NOT counted — it is only the
        # annotation logged immediately before every cold_resume, so including it
        # double-counted each cold resume and understated warm reuse.
        attempts = reuse_hit + cold
        warm = int(round(100 * reuse_hit / attempts)) if attempts else None
        effs = [e.get("cache_efficiency_pct") for e in window
                if e.get("event") == "exit"
                and isinstance(e.get("cache_efficiency_pct"), (int, float))]
        avg_eff = round(sum(effs) / len(effs), 1) if effs else None
        worst_eff = min(effs) if effs else None
        lifetimes = [e.get("lifetime_s") for e in window
                     if e.get("event") == "exit"
                     and isinstance(e.get("lifetime_s"), (int, float))]
        avg_life = round(sum(lifetimes) / len(lifetimes), 1) if lifetimes else None
        return {
            "warm_reuse_pct": warm,
            "warm_reuse_hits": reuse_hit,
            "warm_reuse_attempts": attempts,
            "avg_cache_efficiency_pct": avg_eff,
            "cold_resumes_window": cold,
            "worst_cache_efficiency_pct": worst_eff,
            "avg_lifetime_s": avg_life,
        }
    except Exception:
        return empty


def _resume_parse_result_usage(log_path):
    """Read the tail of a stream-json resume log and pull usage/cost from the
    final `"type":"result"` event. Guarded — a missing/malformed log yields {}."""
    out = {}
    try:
        with open(log_path, "rb") as fh:
            try:
                fh.seek(0, 2)
                size = fh.tell()
                fh.seek(max(0, size - 8192))
            except OSError:
                pass
            tail = fh.read()
        text = tail.decode("utf-8", "replace")
        result_line = None
        for ln in reversed(re.split(r"[\r\n]+", text)):
            if '"type":"result"' in ln or '"type": "result"' in ln:
                result_line = ln
                break
        if not result_line:
            return out
        obj = json.loads(result_line)
        usage = obj.get("usage") or {}
        cache_read = int(usage.get("cache_read_input_tokens") or 0)
        cache_creation = int(usage.get("cache_creation_input_tokens") or 0)
        uncached = int(usage.get("input_tokens") or 0)
        out["cache_read"] = cache_read
        out["cache_creation"] = cache_creation
        out["uncached_input"] = uncached
        out["output_tokens"] = int(usage.get("output_tokens") or 0)
        out["num_turns"] = obj.get("num_turns")
        out["cost_usd"] = obj.get("total_cost_usd")
        out["terminal_reason"] = obj.get("subtype") or obj.get("result")
        out["cache_efficiency_pct"] = round(
            100 * cache_read / max(1, cache_read + cache_creation + uncached), 1)
    except Exception:
        return out
    return out


def _resume_entry_started_epoch(entry):
    """Best-effort epoch a spawn entry started at: prefer the stored epoch,
    fall back to parsing the `%Y%m%dT%H%M%S` `started` string."""
    try:
        se = entry.get("started_epoch")
        if se:
            return float(se)
        started = entry.get("started")
        if started:
            return time.mktime(time.strptime(started, "%Y%m%dT%H%M%S"))
    except Exception:
        return None
    return None

# Rolling wall-clock duration (ms) of the REAL (uncached) live-activity build.
# Cache hits aren't recorded — we only want the cost of actual work, which is the
# truest signal for the hottest endpoint. Bounded deque so memory is constant.
_live_build_ms = collections.deque(maxlen=30)
_live_build_lock = threading.Lock()


def _record_live_build_ms(ms):
    with _live_build_lock:
        _live_build_ms.append(float(ms))


def _live_build_stats():
    """{'last', 'avg', 'count'} ms over the last N real builds (None if idle)."""
    with _live_build_lock:
        vals = list(_live_build_ms)
    if not vals:
        return {"last": None, "avg": None, "count": 0}
    return {
        "last": round(vals[-1], 1),
        "avg": round(sum(vals) / len(vals), 1),
        "count": len(vals),
    }

# Rolling timestamps of recent server-side errors (500s / handler exceptions).
# A bounded ring of epoch seconds; the count is computed over a trailing window
# at read time, so we never scan service.err.log on the hot path.
_recent_error_ts = collections.deque(maxlen=200)
_recent_error_lock = threading.Lock()
_RECENT_ERROR_WINDOW_S = 15 * 60  # 15 min


def _record_server_error():
    """Bump the in-process error counter. Call wherever the server handles/logs
    a real error (500 response, handler traceback). Cheap and lock-guarded."""
    with _recent_error_lock:
        _recent_error_ts.append(time.time())


def _recent_error_count(window_s=_RECENT_ERROR_WINDOW_S):
    cutoff = time.time() - window_s
    with _recent_error_lock:
        return sum(1 for t in _recent_error_ts if t >= cutoff)

# Server CPU% sampled the same way Activity Monitor reports it: `ps -p <pid>`.
# Cached for a few seconds because the dashboard polls health frequently and a
# subprocess per poll would be exactly the kind of cost we're trying to avoid.
_server_cpu_cache = {"ts": 0.0, "pct": None}
_server_cpu_lock = threading.Lock()
_SERVER_CPU_TTL = 5.0


def _server_cpu_pct():
    """This daemon's own process CPU%, via `ps -p <pid> -o %cpu=`. Cached for
    _SERVER_CPU_TTL so frequent polls share one cheap sample. Returns float or
    None if ps is unavailable."""
    now = time.time()
    cache = _server_cpu_cache
    if cache["pct"] is not None and now - cache["ts"] < _SERVER_CPU_TTL:
        return cache["pct"]
    with _server_cpu_lock:
        now = time.time()
        if cache["pct"] is not None and now - cache["ts"] < _SERVER_CPU_TTL:
            return cache["pct"]
        pct = None
        try:
            out = subprocess.run(
                ["ps", "-p", str(os.getpid()), "-o", "%cpu="],
                capture_output=True, text=True, timeout=2,
            )
            raw = (out.stdout or "").strip()
            if raw:
                pct = round(float(raw.split()[0]), 1)
        except Exception:
            pct = None
        cache["pct"] = pct
        cache["ts"] = now
        return pct


def build_ccc_health():
    """Snapshot of CCC's own health for the dashboard bottom-left bar:
    cpu (process %), live-build latency (last/avg ms), recent error count,
    and uptime. All cheap / cached — safe to poll."""
    return {
        "cpu": _server_cpu_pct(),
        "build_ms": _live_build_stats(),
        "recent_errors": _recent_error_count(),
        "error_window_min": _RECENT_ERROR_WINDOW_S // 60,
        "uptime_s": round(time.time() - _SERVER_START_TS),
        "pid": os.getpid(),
        "resume": _resume_ledger_stats(),
        "stray_processes_reaped": _stray_reaper_recent_entries(),
        "inject_blocked": _inject_blocked_recent_entries(),
        # ok:false means the worker is running but missing engine-execution-v1
        # (or otherwise stale) -- see _worker_compat_maintenance_check. Cached,
        # refreshed once per Maintenance tick (hourly) plus at boot -- never a
        # live control-plane RPC on this frequently-polled (5s) endpoint.
        "worker_compat": _get_worker_compat_cache(),
    }


def _env_truthy(name, default="0"):
    return os.environ.get(name, default).lower() in ("1", "true", "yes")


def _should_prewarm_throughput_on_startup():
    return _env_truthy("CCC_PREWARM_THROUGHPUT_ON_STARTUP")


# ---------------------------------------------------------------------------
# System health (the /api/system-health endpoint + the dashboard Health panel).
#
# This is the *machine's* health, not CCC's own (build_ccc_health above):
# memory + swap pressure, sustained CPU hogs, and every Claude session rolled
# up with its whole process subtree, last-activity, and whether it's safe to
# reap. Mirrors the standalone mac-health menu-bar plugin so both render from
# the same logic.
#
# "Stale" = idle for a while, measured from the session transcript mtime (each
# turn appends to ~/.claude/projects/*/<uuid>.jsonl, so its mtime is a real
# last-activity clock that freezes when the session goes idle) — NOT process
# age, which says nothing about whether a session is still in use. A session is
# only reapable when it is headless (no TTY = no human in a terminal), idle (no
# encode/transcode child, low tree CPU), and stale. Bursty workers (whisper run
# chunk-by-chunk) and sessions blocked on one long command have a frozen
# transcript too, so they lean on the worker/CPU check, not the clock.
# ---------------------------------------------------------------------------

_SYS_PROJECTS_DIR = os.path.expanduser("~/.claude/projects")
_SYS_SESSION_UUID_RE = re.compile(r"--(?:resume|session-id|sid)\s+([0-9a-fA-F-]{36})")
_SYS_WORKER_RE = re.compile(r"\b(whisper(?:-cli)?|ffmpeg|ffprobe|HandBrakeCLI)\b", re.I)
_SYS_STALE_MIN = 120.0       # idle minutes past which a headless session is reapable
_SYS_BUSY_CPU = 30.0         # tree CPU% above which a session counts as working
_SYS_HOG_CPU = 80.0          # process CPU% to count as a sustained hog
_SYS_HOG_MIN_AGE = 2.0       # minutes alive, to skip brief compile/encode spikes
_SYS_UNIT_MB = {"K": 1 / 1024, "M": 1.0, "G": 1024.0, "T": 1024 * 1024.0}
# Absolute tool paths: the launchd daemon's PATH lacks /usr/sbin, so bare
# `sysctl`/`lsof` silently fail (FileNotFoundError -> ""). On Linux the same
# tools live elsewhere (or not at all), so resolve per platform: prefer the
# shipped macOS path when it exists, else a PATH lookup, else the bare name.
# Missing tools degrade to "" in _sys_run rather than crashing. sysctl and
# vm_stat are macOS-only; on Linux _sys_memory/_sys_cpu use /proc + os instead.
def _resolve_sys_tool(macos_path, name):
    if os.path.exists(macos_path):
        return macos_path
    return shutil.which(name) or name


_SYS_PS = _resolve_sys_tool("/bin/ps", "ps")
_SYS_LSOF = _resolve_sys_tool("/usr/sbin/lsof", "lsof")
_SYS_SYSCTL = _resolve_sys_tool("/usr/sbin/sysctl", "sysctl")
_SYS_VM_STAT = _resolve_sys_tool("/usr/bin/vm_stat", "vm_stat")
_SYS_OSASCRIPT = _resolve_sys_tool("/usr/bin/osascript", "osascript")
_SYS_GUI_APPS = (
    {
        "id": "cursor",
        "name": "Cursor.app",
        "app_name": "Cursor",
        "bundle": "Cursor.app",
    },
    {
        "id": "antigravity",
        "name": "Antigravity.app",
        "app_name": "Antigravity",
        "bundle": "Antigravity.app",
    },
    {
        "id": "codex",
        "name": "Codex.app",
        "app_name": "Codex",
        "bundle": "Codex.app",
    },
)


def _sys_run(cmd, timeout=3):
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout).stdout
    except Exception:
        return ""


def _sys_to_mb(value, unit):
    return float(value) * _SYS_UNIT_MB.get(unit.upper(), 1.0)


def _sys_parse_etime(s):
    """ps etime (SS, MM:SS, HH:MM:SS, DD-HH:MM:SS) -> minutes."""
    days = 0
    if "-" in s:
        d, s = s.split("-", 1)
        try:
            days = int(d)
        except ValueError:
            return 0.0
    try:
        nums = [int(p) for p in s.split(":")]
    except ValueError:
        return 0.0
    if len(nums) == 1:
        h, m, sec = 0, 0, nums[0]
    elif len(nums) == 2:
        h, m, sec = 0, nums[0], nums[1]
    else:
        h, m, sec = nums[0], nums[1], nums[2]
    return days * 1440 + h * 60 + m + sec / 60.0


def _sys_memory_linux():
    """Memory + swap from /proc/meminfo (Linux). Mirrors the macOS shape so the
    same UI panel renders. 'available' uses MemAvailable, the kernel's own
    estimate of reclaimable memory."""
    info = {}
    try:
        with open("/proc/meminfo", "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                m = re.match(r"(\w+):\s+(\d+)\s*kB", line)
                if m:
                    info[m.group(1)] = int(m.group(2)) / 1024.0  # kB -> MB
    except OSError:
        return {
            "total_mb": None, "used_mb": None, "available_mb": 0,
            "compressed_mb": 0, "swap_used_mb": None, "swap_total_mb": None,
            "pressure": None,
        }
    total = info.get("MemTotal")
    available = info.get("MemAvailable", info.get("MemFree", 0))
    used = (total - available) if total else None
    swap_total = info.get("SwapTotal")
    swap_free = info.get("SwapFree")
    swap_used = (swap_total - swap_free) if (swap_total is not None and swap_free is not None) else None
    pressure = None
    if total:
        ap = available / total
        pressure = "critical" if ap < 0.05 else ("elevated" if ap < 0.20 else "ok")
    return {
        "total_mb": round(total) if total else None,
        "used_mb": round(used) if used is not None else None,
        "available_mb": round(available),
        "compressed_mb": 0,  # no direct /proc equivalent
        "swap_used_mb": round(swap_used) if swap_used is not None else None,
        "swap_total_mb": round(swap_total) if swap_total is not None else None,
        "pressure": pressure,
    }


def _sys_memory():
    """Memory + swap, matching Activity Monitor's pressure bar (kernel pressure
    level + available = free+inactive+speculative+purgeable, not top's 'used')."""
    if platform.system() != "Darwin":
        return _sys_memory_linux()
    total_mb = None
    try:
        total_mb = int(_sys_run([_SYS_SYSCTL, "-n", "hw.memsize"]).strip()) / (1024 * 1024)
    except ValueError:
        pass
    pages = {}
    for line in _sys_run([_SYS_VM_STAT]).splitlines():
        m = re.match(r"(.+?):\s+(\d+)\.?\s*$", line.strip())
        if m:
            pages[m.group(1).strip()] = int(m.group(2))
    try:
        page = int(_sys_run([_SYS_SYSCTL, "-n", "hw.pagesize"]).strip() or 16384)
    except ValueError:
        page = 16384
    mb = lambda k: pages.get(k, 0) * page / (1024 * 1024)
    available = mb("Pages free") + mb("Pages inactive") + mb("Pages speculative") + mb("Pages purgeable")
    used = (total_mb - available) if total_mb else None
    swap_used = swap_total = None
    for k, v, u in re.findall(r"(total|used|free)\s*=\s*([\d.]+)([KMGT])",
                              _sys_run([_SYS_SYSCTL, "-n", "vm.swapusage"])):
        if k == "total":
            swap_total = _sys_to_mb(v, u)
        elif k == "used":
            swap_used = _sys_to_mb(v, u)
    pressure = {"1": "ok", "2": "elevated", "4": "critical"}.get(
        _sys_run([_SYS_SYSCTL, "-n", "kern.memorystatus_vm_pressure_level"]).strip())
    if pressure is None and total_mb:
        ap = available / total_mb
        pressure = "critical" if ap < 0.05 else ("elevated" if ap < 0.20 else "ok")
    return {
        "total_mb": round(total_mb) if total_mb else None,
        "used_mb": round(used) if used is not None else None,
        "available_mb": round(available),
        "compressed_mb": round(mb("Pages occupied by compressor")),
        "swap_used_mb": round(swap_used) if swap_used is not None else None,
        "swap_total_mb": round(swap_total) if swap_total is not None else None,
        "pressure": pressure,
    }


def _sys_cpu():
    if platform.system() != "Darwin":
        # Linux: sysctl keys don't exist; use stdlib (also avoids 2 forks).
        try:
            load = list(os.getloadavg())
        except (OSError, AttributeError):
            load = [None, None, None]
        return {"load1": load[0], "load5": load[1], "load15": load[2],
                "cores": os.cpu_count()}
    cores = None
    try:
        cores = int(_sys_run([_SYS_SYSCTL, "-n", "hw.ncpu"]).strip())
    except ValueError:
        pass
    nums = re.findall(r"[\d.]+", _sys_run([_SYS_SYSCTL, "-n", "vm.loadavg"]))
    load = [float(x) for x in nums[:3]] if len(nums) >= 3 else [None, None, None]
    return {"load1": load[0], "load5": load[1], "load15": load[2], "cores": cores}


def _sys_label(cmd):
    exe = cmd.split(None, 1)[0]
    base = exe.rsplit("/", 1)[-1]
    app = re.search(r"/([^/]+)\.app/Contents/", cmd)
    if app:
        return app.group(1)
    if base == "claude":
        return "claude CLI"
    if "python" in base.lower():
        sc = re.search(r"\s([^ ]+\.py)(?:\s|$)", cmd)
        return "Python: " + sc.group(1).rsplit("/", 1)[-1] if sc else "Python"
    return base or cmd[:40]


def _sys_process_rows():
    rows = []
    for line in _sys_run([_SYS_PS, "-axo", "pid=,ppid=,rss=,pcpu=,etime=,tty=,command="]).splitlines():
        parts = line.strip().split(None, 6)
        if len(parts) < 7:
            continue
        try:
            rows.append({
                "pid": int(parts[0]),
                "ppid": int(parts[1]),
                "rss_mb": int(parts[2]) / 1024,
                "cpu": float(parts[3]),
                "etime_min": _sys_parse_etime(parts[4]),
                "tty": parts[5],
                "cmd": parts[6],
            })
        except ValueError:
            continue
    return rows


def _sys_gui_apps(rows):
    """Running GUI app-server engines, aggregated separately from session
    process trees. These are intentionally non-reapable: all conversations live
    inside the shared app process, so the only exposed control is graceful quit."""
    apps = []
    for spec in _SYS_GUI_APPS:
        marker = "/" + spec["bundle"] + "/Contents/"
        matches = [r for r in rows if marker in r.get("cmd", "")]
        if not matches:
            continue
        matches.sort(key=lambda r: r["pid"])
        main = next((r for r in matches if "/Contents/MacOS/" in r.get("cmd", "")), matches[0])
        apps.append({
            "id": spec["id"],
            "name": spec["name"],
            "app_name": spec["app_name"],
            "bundle": spec["bundle"],
            "pid": main["pid"],
            "pids": [r["pid"] for r in matches],
            "rss_mb": round(sum(r["rss_mb"] for r in matches)),
            "cpu": round(sum(r["cpu"] for r in matches), 1),
            "age_min": round(max((r["etime_min"] for r in matches), default=0.0), 1),
            "nprocs": len(matches),
            "reapable": False,
            "control": "quit-app",
            "quit_supported": platform.system() == "Darwin",
        })
    return apps


def _sys_last_activity_min(uuid, now, proj_dirs):
    """Minutes since the session transcript was last written, or None. Stats
    <proj>/<uuid>.jsonl across project dirs — no cwd-encoding assumptions."""
    if not uuid:
        return None
    target = uuid + ".jsonl"
    best = None
    for proj in proj_dirs:
        try:
            mt = os.path.getmtime(os.path.join(_SYS_PROJECTS_DIR, proj, target))
        except OSError:
            continue
        if best is None or mt > best:
            best = mt
    return ((now - best) / 60.0) if best is not None else None


def _sys_cwds(pids):
    """Batch one lsof for every session root's cwd (basename used to tell repos apart)."""
    if not pids:
        return {}
    out = _sys_run([_SYS_LSOF, "-a", "-d", "cwd", "-Fn", "-p", ",".join(map(str, pids))])
    cwds, cur = {}, None
    for line in out.splitlines():
        if line.startswith("p"):
            try:
                cur = int(line[1:])
            except ValueError:
                cur = None
        elif line.startswith("n") and cur is not None:
            cwds.setdefault(cur, line[1:])
    return cwds


def _sys_sessions(rows, now):
    by_pid = {r["pid"]: r for r in rows}
    children = {}
    for r in rows:
        children.setdefault(r["ppid"], []).append(r["pid"])

    def descendants(root):
        seen, stack = [], list(children.get(root, []))
        while stack:
            pid = stack.pop()
            seen.append(pid)
            stack.extend(children.get(pid, []))
        return seen

    try:
        proj_dirs = os.listdir(_SYS_PROJECTS_DIR)
    except OSError:
        proj_dirs = []

    # Authoritative pid -> sessionId (Claude writes ~/.claude/sessions/<pid>.json),
    # so even interactive sessions with no uuid in argv get a real session id —
    # which unlocks their real last-activity (transcript) and CCC name.
    try:
        registry = _load_session_registry()
    except Exception:
        registry = {}
    pid_to_sid, meta_by_sid = {}, {}
    for sid, data in registry.items():
        meta_by_sid[sid] = data
        try:
            pid_to_sid[int(data.get("pid"))] = sid
        except (TypeError, ValueError):
            pass
    # Names, same priority the sidebar uses: user override > registry name >
    # spawn-registry name. Loaded once, not per session.
    try:
        overrides = _load_session_name_overrides()
    except Exception:
        overrides = {}
    spawn_name_by_sid = {}
    try:
        for e in _load_spawn_registry():
            nm = str(e.get("name") or "").strip()
            if not nm:
                continue
            for key in ("session_id", "resumed_sid"):
                k = e.get(key)
                if k:
                    spawn_name_by_sid.setdefault(k, nm)
    except Exception:
        pass

    def _name_for(sid):
        if not sid:
            return None
        nm = overrides.get(sid) or (meta_by_sid.get(sid) or {}).get("name") or spawn_name_by_sid.get(sid)
        return _truncate_session_name(nm) if nm else None

    # Live WT-tracked workers are WatchTower's to release/reap, not ours —
    # surface them (wt_worker flag) but never offer them as reap targets.
    wt_pids, wt_sids = _wt_live_worker_guard()

    sessions = []
    for r in rows:
        if _sys_label(r["cmd"]) != "claude CLI":
            continue
        desc = descendants(r["pid"])
        drows = [by_pid[p] for p in desc if p in by_pid]
        tree_rss = r["rss_mb"] + sum(d["rss_mb"] for d in drows)
        tree_cpu = r["cpu"] + sum(d["cpu"] for d in drows)
        worker = next((d for d in drows if _SYS_WORKER_RE.search(d["cmd"])), None)
        interactive = bool(r["tty"]) and r["tty"] not in ("??", "?", "-", "")
        busy = bool(worker) or tree_cpu >= _SYS_BUSY_CPU
        # Registry pid->sid is authoritative; fall back to the uuid in argv.
        sid = pid_to_sid.get(r["pid"]) or \
            (m.group(1) if (m := _SYS_SESSION_UUID_RE.search(r["cmd"])) else None)
        idle_known = _sys_last_activity_min(sid, now, proj_dirs)
        idle_min = idle_known if idle_known is not None else r["etime_min"]
        wt_worker = r["pid"] in wt_pids or bool(sid and sid in wt_sids)
        sessions.append({
            "pid": r["pid"],
            "session_id": sid,
            "name": _name_for(sid),
            "entrypoint": (meta_by_sid.get(sid) or {}).get("entrypoint"),
            "age_min": round(r["etime_min"], 1),
            "idle_min": round(idle_min, 1),
            "idle_known": idle_known is not None,
            "tree_rss_mb": round(tree_rss),
            "tree_cpu": round(tree_cpu),
            "nprocs": 1 + len(desc),
            "tree_pids": [r["pid"]] + desc,
            "interactive": interactive,
            "busy": busy,
            "worker": _sys_label(worker["cmd"]) if worker else None,
            "wt_worker": wt_worker,
            "reapable": (not interactive) and (not busy) and (not wt_worker)
                        and idle_min >= _SYS_STALE_MIN,
        })

    cwds = _sys_cwds([s["pid"] for s in sessions])
    home = os.path.expanduser("~")
    for s in sessions:
        c = cwds.get(s["pid"], "")
        s["cwd"] = c
        s["cwd_short"] = "~" if c == home else (c.rsplit("/", 1)[-1] if c else "?")

    # Concurrent sessions: 2+ live processes on one session_id (e.g. a headless
    # sdk-cli + a terminal cli both on the same transcript). The data-loss path
    # is unproven (study T1), but a kill here is the riskiest move, so flag them
    # and withhold reaping — the user resolves a concurrent pair deliberately.
    sid_counts = {}
    for s in sessions:
        if s["session_id"]:
            sid_counts[s["session_id"]] = sid_counts.get(s["session_id"], 0) + 1
    for s in sessions:
        s["concurrent"] = bool(s["session_id"]) and sid_counts.get(s["session_id"], 0) >= 2
        if s["concurrent"]:
            s["reapable"] = False

    # Sort by the strength of the case to reap (strongest first), so the best
    # kill targets surface at the top and protected sessions sink:
    #   reapable (stale) > headless-but-recent > working > the one you're in.
    # Within a tier, longer-idle first, then bigger memory win.
    def _kill_rank(s):
        if s["reapable"]:
            tier = 3                                   # stale → kill candidate
        elif not s["interactive"] and not s["busy"]:
            tier = 2                                   # headless idle, not stale yet
        elif s["busy"]:
            tier = 1                                   # working → protected
        else:
            tier = 0                                   # interactive → you're in it
        return (tier, s["idle_min"], s["tree_rss_mb"])
    return sorted(sessions, key=_kill_rank, reverse=True)


def _sys_hogs(rows):
    hogs = [r for r in rows
            if r["cpu"] >= _SYS_HOG_CPU and r["etime_min"] >= _SYS_HOG_MIN_AGE]
    hogs.sort(key=lambda r: r["cpu"], reverse=True)
    return [{"pid": r["pid"], "label": _sys_label(r["cmd"]),
             "cpu": round(r["cpu"]), "etime_min": round(r["etime_min"], 1)}
            for r in hogs[:6]]


_system_health_snapshot = {"ts": 0.0, "data": None}
_system_health_lock = threading.Lock()
_SYSTEM_HEALTH_TTL = 5.0


def _build_system_health_uncached():
    now = time.time()
    rows = _sys_process_rows()
    sessions = _sys_sessions(rows, now)
    apps = _sys_gui_apps(rows)
    reap = [s for s in sessions if s["reapable"]]
    return {
        "ts": now,
        "memory": _sys_memory(),
        "cpu": _sys_cpu(),
        "hogs": _sys_hogs(rows),
        "sessions": sessions,
        "apps": apps,
        "session_totals": {
            "count": len(sessions),
            "tree_rss_mb": round(sum(s["tree_rss_mb"] for s in sessions)),
            "reapable": len(reap),
            "reapable_rss_mb": round(sum(s["tree_rss_mb"] for s in reap)),
        },
        "app_totals": {
            "count": len(apps),
            "rss_mb": round(sum(app["rss_mb"] for app in apps)),
        },
        # The reap policy, so the UI can state exactly what "stale" means
        # without hardcoding (and drifting from) these thresholds.
        "policy": {
            "stale_min": _SYS_STALE_MIN,
            "busy_cpu": _SYS_BUSY_CPU,
        },
    }


def build_system_health(force=False):
    """Machine health for the dashboard Health panel. Coalesced with a 5s TTL
    (manual cache because _ttl_memo is defined far below this point) so the
    panel's poll and any concurrent callers share one ps/lsof sweep. Pass
    force=True to bypass the cache (the reap guard needs a fresh view)."""
    snap = _system_health_snapshot
    now = time.time()
    if not force and snap["data"] is not None and now - snap["ts"] < _SYSTEM_HEALTH_TTL:
        return snap["data"]
    with _system_health_lock:
        now = time.time()
        if not force and snap["data"] is not None and now - snap["ts"] < _SYSTEM_HEALTH_TTL:
            return snap["data"]
        data = _build_system_health_uncached()
        snap["data"] = data
        snap["ts"] = now
        return data


def system_health_reap(pids):
    """SIGTERM the given PIDs, but ONLY those that belong to a currently
    reapable session tree — never an interactive or working session. Recomputes
    the snapshot fresh (cache bypassed) so the guard can't be raced against a
    stale view the client was looking at."""
    health = build_system_health(force=True)
    allowed = set()
    for s in health["sessions"]:
        if s["reapable"]:
            allowed.update(s["tree_pids"])
    want = set(int(p) for p in pids if str(p).lstrip("-").isdigit())
    to_kill = sorted(want & allowed)
    blocked = sorted(want - allowed)
    killed = []
    for pid in to_kill:
        try:
            os.kill(pid, signal.SIGTERM)
            # Attribution: a user-triggered System Health reap. Lets a later
            # `exit` (SIGTERM) row be matched to this CCC-side kill rather than
            # being misread as an external / mystery death.
            _resume_ledger_append("kill", pid=pid, source="system_health_reap")
            _log_activity("kill", "KILL", f"pid={pid} source=system_health_reap")
            killed.append(pid)
        except (ProcessLookupError, PermissionError):
            pass
    # Invalidate so the next poll reflects the kill immediately.
    _system_health_snapshot["data"] = None
    return {"ok": True, "killed": killed, "blocked": blocked}


def system_health_quit_app(app_id, timeout=8):
    spec = next((s for s in _SYS_GUI_APPS if s["id"] == app_id), None)
    if not spec:
        return {"ok": False, "error": "unknown app"}
    if platform.system() != "Darwin":
        return {"ok": False, "error": "graceful app quit is only supported on macOS"}
    script = f'tell application "{spec["app_name"]}" to quit'
    try:
        proc = subprocess.run(
            [_SYS_OSASCRIPT, "-e", script],
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        _system_health_snapshot["data"] = None
        return {
            "ok": False,
            "app_id": spec["id"],
            "app_name": spec["app_name"],
            "error": "quit timed out",
        }
    _system_health_snapshot["data"] = None
    ok = proc.returncode == 0
    out = {
        "ok": ok,
        "app_id": spec["id"],
        "app_name": spec["app_name"],
        "returncode": proc.returncode,
        "hard_kill_offered": False,
    }
    if not ok:
        err = (proc.stderr or proc.stdout or "").strip()
        out["error"] = err or "quit failed"
    return out


_system_processes_snapshot = {"ts": 0.0, "data": None}
_system_processes_lock = threading.Lock()
_SYSTEM_PROCESSES_TTL = 3.0


# ── Process audit: pattern tables ──────────────────────────────────────────
# Signals are combined additively; shields are subtractive. Every table below
# is matched against the full command line (or its basename) of a row from a
# single `ps` call — there is no per-process subprocess anywhere in this path.

_PROC_DEV_SERVER_RE = re.compile(
    r"(?:^|[\s/])(?:next-server|next dev|next start|vite|webpack(?:-dev-server)?|nuxt|remix|astro|"
    r"ng serve|react-scripts|turbopack|nodemon|ts-node-dev|tsx watch|node --watch|bun --hot|"
    r"storybook|expo start|uvicorn|gunicorn|flask run|runserver|rails s(?:erver)?|artisan serve|"
    r"hugo server|jekyll serve|parcel|live-server|browser-sync|http-server)(?:\s|$)"
)
_PROC_LSP_RE = re.compile(
    r"tsserver\.js|typingsInstaller|typescript-language-server|pyright-langserver|basedpyright|pylance|"
    r"\bgopls\b|rust-analyzer|\bclangd\b|\bjdtls\b|lua-language-server|vscode-\w+-language-server|"
    r"eslintServer\.js|eslint-server|tailwindcss-language-server|copilot(?:-agent|-language-server)|"
    r"sourcekit-lsp|solargraph|ruby-lsp|intelephense|vue-language-server|svelte-language-server|"
    r"yaml-language-server|bash-language-server|deno lsp|\bzls\b|haskell-language-server|marksman|"
    r"texlab|ltex-ls|kotlin-language-server|elixir-ls|omnisharp|csharp-ls|terraform-ls|\bnixd\b|"
    r"language[-_]server"
)
_PROC_MCP_RE = re.compile(r"[-_/.]mcp(?:[\s@\b]|$)|mcp[-_]server|@modelcontextprotocol|playwright-mcp|chrome-devtools-mcp")
_PROC_MP_WORKER_RE = re.compile(
    r"multiprocessing\.(?:spawn|resource_tracker|forkserver)|spawn_main\(|resource_tracker import main|"
    r"loky\.backend|--multiprocessing-fork"
)
_PROC_AUTOMATION_BROWSER_RE = re.compile(
    r"--remote-debugging-(?:pipe|port)|--headless|--enable-automation|chrome-headless-shell|"
    r"ms-playwright|\.cache/puppeteer|Chrome for Testing|puppeteer_dev_chrome_profile|playwright_\w+_profile"
)
_PROC_PARENT_PID_RE = re.compile(r"--parent-pid[= ](\d+)")
_PROC_GIT_BASES = frozenset((
    "git", "git-remote-https", "git-remote-http", "git-remote-ssh", "git-credential-osxkeychain",
    "git-credential-manager", "git-lfs", "gh",
))
_PROC_GIT_DAEMON_HINTS = ("fsmonitor--daemon", "credential-cache--daemon", " daemon", "maintenance")
_PROC_STUCK_CLI_BASES = frozenset((
    "grep", "head", "tail", "cat", "find", "wc", "awk", "sed", "sort", "xargs", "tee", "jq", "rg",
    "less", "more", "curl", "wget", "sleep",
))
# Long-lived developer daemons that legitimately live under launchd (PPID 1)
# and never have a TTY. Without this list every one of them reads as an
# idle >48h orphan and lands in "Suspicious" — observed live: ssh-agent 4.0.
_PROC_KNOWN_DAEMON_BASES = frozenset((
    "ssh-agent", "gpg-agent", "dirmngr", "scdaemon", "pinentry",
    "tmux", "screen", "wezterm-mux-server", "zellij",
    "dockerd", "containerd", "containerd-shim", "docker", "com.docker.backend", "com.docker.vpnkit",
    "colima", "limactl", "lima-guestagent", "vfkit", "krunkit", "virtiofsd", "podman", "podman-remote",
    "ollama", "postgres", "postmaster", "redis-server", "mysqld", "mariadbd", "mongod",
    "nginx", "caddy", "httpd", "tailscaled", "syncthing", "mutagen", "mutagen-agent", "watchman",
    "nix-daemon", "cloudflared", "ngrok", "xbar", "unison", "rclone", "gitstatusd",
    "eslint_d", "prettierd", "code-server", "cursor-server", "emacs", "nvim",
))
_PROC_KNOWN_DAEMON_HINTS = ("qemu-system", "emacs --daemon", "nvim --headless --listen", "git fsmonitor--daemon", ".vscode-server", ".cursor-server")
_PROC_TMP_HINTS = ("/tmp/", "/var/folders/", "/.Trash/", "/private/tmp/", "/private/var/folders/")

_CCC_SOURCE_DIR = os.path.dirname(os.path.abspath(__file__))


def _sys_parse_cputime(s):
    """ps `time` (MM:SS.cc, HH:MM:SS, DD-HH:MM:SS) -> minutes of CPU."""
    days = 0
    if "-" in s:
        d, s = s.split("-", 1)
        try:
            days = int(d)
        except ValueError:
            return 0.0
    parts = s.split(":")
    try:
        sec = float(parts[-1])
        mins = int(parts[-2]) if len(parts) >= 2 else 0
        hours = int(parts[-3]) if len(parts) >= 3 else 0
    except (ValueError, IndexError):
        return 0.0
    return days * 1440 + hours * 60 + mins + sec / 60.0


def _sys_launchd_jobs():
    """pid -> launchd label for every job launchd itself is supervising.

    On macOS a PPID of 1 means either 'launchd started this on purpose' or
    'the real parent died and launchd adopted it'. `launchctl list` is the
    only cheap way to tell those apart, and it is one subprocess per snapshot
    rather than one per row."""
    out = _sys_run(["/bin/launchctl", "list"], timeout=3) if platform.system() == "Darwin" else ""
    jobs = {}
    for line in out.splitlines():
        parts = line.split("\t")
        if len(parts) < 3:
            continue
        try:
            jobs[int(parts[0])] = parts[2].strip()
        except ValueError:
            continue
    return jobs


def _sys_ccc_session_pids():
    """PIDs of sessions CCC itself spawned (spawn registry on disk + this
    process's in-memory list). A `claude -p` reparented to launchd because the
    worker restarted is still a live, tracked session — an anchor, not an
    orphan root. Cheap: one small JSON read per snapshot, no RPC."""
    pids = set()
    try:
        for entry in _load_spawn_registry():
            try:
                pids.add(int(entry.get("pid") or 0))
            except (TypeError, ValueError, AttributeError):
                continue
    except Exception:
        pass
    try:
        for entry in list(_spawned_sessions):
            pid = entry.get("pid") if isinstance(entry, dict) else None
            if pid:
                pids.add(int(pid))
    except Exception:
        pass
    pids.discard(0)
    return pids


def _sys_worktree_gitdir_missing(cwd, _memo):
    """True when `cwd` (or an ancestor) is a git worktree whose admin dir is
    gone — the checkout was `git worktree remove`d under a still-running
    process. Memoised per snapshot; stats only, no subprocess."""
    if not cwd or cwd == "/":
        return False
    d = cwd
    for _ in range(8):
        if d in _memo:
            return _memo[d]
        dotgit = os.path.join(d, ".git")
        try:
            if os.path.isfile(dotgit):
                with open(dotgit, "r", encoding="utf-8", errors="replace") as f:
                    head = f.readline().strip()
                missing = False
                if head.startswith("gitdir:"):
                    target = head[len("gitdir:"):].strip()
                    if not os.path.isabs(target):
                        target = os.path.join(d, target)
                    missing = not os.path.exists(target)
                _memo[d] = missing
                return missing
            if os.path.isdir(dotgit):
                _memo[d] = False
                return False
        except OSError:
            _memo[d] = False
            return False
        parent = os.path.dirname(d)
        if parent == d:
            break
        d = parent
    _memo[cwd] = False
    return False


def _build_system_processes_uncached():
    now = time.time()
    uid = os.getuid() if hasattr(os, "getuid") else None

    ps_fmt = "pid=,ppid=,rss=,pcpu=,etime=,time=,stat=,tty=,command="
    ps_cmd = [_SYS_PS, "-axo", ps_fmt]
    if uid is not None and platform.system() == "Darwin":
        ps_cmd = [_SYS_PS, "-u", str(uid), "-o", ps_fmt]

    ps_out = _sys_run(ps_cmd, timeout=5)

    lsof_cmd = [_SYS_LSOF, "-a", "-d", "0,cwd", "-Fpndft"]
    if uid is not None:
        try:
            username = os.getlogin()
        except Exception:
            username = None
        if username:
            lsof_cmd += ["-u", username]
        elif uid is not None:
            lsof_cmd += ["-u", str(uid)]
    lsof_out = _sys_run(lsof_cmd, timeout=5)
    launchd_jobs = _sys_launchd_jobs()
    ccc_session_pids = _sys_ccc_session_pids()

    pid_files = {}
    cur_pid = None
    cur_fd = None
    cur_type = None
    for line in lsof_out.splitlines():
        if not line:
            continue
        tag, val = line[0], line[1:]
        if tag == "p":
            try:
                cur_pid = int(val)
                pid_files[cur_pid] = {"cwd": None, "cwd_exists": True, "fd0": None, "fd0_type": None, "fd0_exists": True}
            except ValueError:
                cur_pid = None
        elif cur_pid is not None:
            if tag == "f":
                cur_fd = val
            elif tag == "t":
                cur_type = val
            elif tag == "n":
                if cur_fd == "cwd":
                    pid_files[cur_pid]["cwd"] = val
                    pid_files[cur_pid]["cwd_exists"] = os.path.exists(val)
                elif cur_fd == "0":
                    pid_files[cur_pid]["fd0"] = val
                    pid_files[cur_pid]["fd0_type"] = cur_type
                    if cur_type == "FIFO":
                        pid_files[cur_pid]["fd0_exists"] = os.path.exists(val)

    my_pid = os.getpid()
    parent_pid = os.getppid()
    ccc_server_path = os.path.join(_CCC_SOURCE_DIR, "server.py")
    ccc_worker_path = os.path.join(_CCC_SOURCE_DIR, "ccc_worker.py")
    empty_files = {"cwd": None, "cwd_exists": True, "fd0": None, "fd0_type": None, "fd0_exists": True}

    # ── pass 1: parse + classify every row (no scoring yet) ──────────────
    rows = {}
    for line in ps_out.splitlines():
        parts = line.strip().split(None, 8)
        if len(parts) < 9:
            continue
        try:
            pid = int(parts[0])
            ppid = int(parts[1])
            rss_mb = int(parts[2]) / 1024.0
            cpu = float(parts[3])
        except (ValueError, IndexError):
            continue
        etime_str, cputime_str, stat, tty, cmd = parts[4], parts[5], parts[6], parts[7], parts[8]
        cmd_base = cmd.split(None, 1)[0].rsplit("/", 1)[-1]
        label = launchd_jobs.get(pid)

        is_system_daemon = (
            cmd.startswith(("/usr/libexec/", "/usr/sbin/", "/System/", "/Library/"))
            or "LAUNCHED_BY_LAUNCHD" in cmd
            or "/System/Library/" in cmd
        )
        is_automation = bool(_PROC_AUTOMATION_BROWSER_RE.search(cmd))
        is_helper = "--type=" in cmd and "crashpad" not in cmd
        is_lsp = bool(_PROC_LSP_RE.search(cmd))
        is_mcp = bool(_PROC_MCP_RE.search(cmd))
        is_dev_server = bool(_PROC_DEV_SERVER_RE.search(cmd))
        is_mp_worker = bool(_PROC_MP_WORKER_RE.search(cmd))
        is_gui = ("/Applications/" in cmd or "Contents/MacOS" in cmd)
        # A GUI path is only a shield while the app that owns it is alive.
        # Automation browsers (Puppeteer/Playwright/chrome-devtools) and any
        # app *helper* / LSP / MCP that has been reparented to launchd are the
        # leak we are hunting, not a desktop app.
        if is_automation or (ppid == 1 and (is_helper or is_lsp or is_mcp)):
            is_gui = False
        is_ccc = (
            pid in (my_pid, parent_pid)
            or ccc_server_path in cmd
            or ccc_worker_path in cmd
            or cmd_base == "ccc_worker.py"
            or "watchtower.cli" in cmd
            or (label or "").startswith(("com.github.claude-command-center", "ai.watchtower"))
        )
        is_known_daemon = (
            cmd_base in _PROC_KNOWN_DAEMON_BASES
            or any(h in cmd for h in _PROC_KNOWN_DAEMON_HINTS)
            or (cmd_base == "ssh" and re.search(r"\s-[a-zA-Z]*[NLRDWM]", cmd) is not None)
        )
        has_tty = bool(tty) and tty not in ("??", "?", "-", "")
        is_ccc_session = pid in ccc_session_pids
        # Anchored = something is deliberately keeping this alive; an orphan
        # tree never roots at an anchored process.
        anchored = (bool(label) or is_system_daemon or is_gui or is_ccc or is_known_daemon
                    or has_tty or is_ccc_session)

        rows[pid] = {
            "pid": pid, "ppid": ppid, "cmd": cmd, "cmd_base": cmd_base, "cpu": cpu, "rss_mb": rss_mb,
            "etime_str": etime_str, "etime_min": _sys_parse_etime(etime_str),
            "cputime_min": _sys_parse_cputime(cputime_str), "stat": stat, "tty": tty,
            "has_tty": has_tty, "label": label, "is_system_daemon": is_system_daemon,
            "is_gui": is_gui, "is_ccc": is_ccc, "is_known_daemon": is_known_daemon,
            "is_automation": is_automation, "is_helper": is_helper, "is_lsp": is_lsp,
            "is_mcp": is_mcp, "is_dev_server": is_dev_server, "is_mp_worker": is_mp_worker,
            "is_ccc_session": is_ccc_session,
            "anchored": anchored, "files": pid_files.get(pid, empty_files),
        }

    # ── pass 2: orphan trees ─────────────────────────────────────────────
    # A row whose ancestry ends at an un-anchored PPID-1 process inherits
    # that process's "launcher is gone" status: `npm exec next dev` (PPID 1)
    # -> `next dev` -> `next-server` at 90% CPU is one leak, not three rows.
    def _orphan_root(pid):
        seen = 0
        cur = rows.get(pid)
        while cur is not None and seen < 64:
            seen += 1
            if cur["ppid"] == 1:
                return cur["pid"] if not cur["anchored"] else None
            if cur["anchored"]:
                return None
            cur = rows.get(cur["ppid"])
        return None

    for r in rows.values():
        root = _orphan_root(r["pid"])
        r["tree_root"] = root
        r["tree_orphan"] = root is not None and root != r["pid"]

    # ── pass 3: score ────────────────────────────────────────────────────
    gitdir_memo = {}
    runaway_children = {}  # orphan-root pid -> first runaway/stuck descendant pid
    procs = []
    for r in rows.values():
        pid, ppid, cmd, stat, cpu = r["pid"], r["ppid"], r["cmd"], r["stat"], r["cpu"]
        files = r["files"]
        etime_min = r["etime_min"]
        has_tty = r["has_tty"]
        is_orphan = ppid == 1 and not r["anchored"]
        tree_orphan = r["tree_orphan"]
        detached = is_orphan or tree_orphan
        score = 0.0
        reasons = []
        shields = []
        kill_hint = None

        def bump(full, half, text_full, text_half=None):
            # Category boosts: full weight when this row itself is orphaned,
            # half when it merely hangs under an orphaned root.
            nonlocal score
            if is_orphan:
                score += full
                reasons.append(text_full)
            elif tree_orphan:
                score += half
                reasons.append(text_half or text_full)

        if not files["cwd_exists"]:
            score += 4.5
            reasons.append("Deleted CWD")
        elif _sys_worktree_gitdir_missing(files["cwd"], gitdir_memo):
            score += 3.5
            reasons.append("Worktree removed (gitdir gone)")
        if files["fd0_type"] == "FIFO" and not files["fd0_exists"]:
            score += 4.5
            reasons.append("Unlinked stdin FIFO")
        if stat.startswith("Z") or "<defunct>" in cmd:
            score += 5.0
            reasons.append("Zombie process (reap: signal parent pid %d)" % ppid)
            kill_hint = "zombie; signals are no-ops, terminate or restart parent pid %d" % ppid

        if any(k in cmd for k in ("fake_claude", "two-node", "test_")):
            score += 3.0
            reasons.append("Test artifact")
        if files["cwd"] and any(p in files["cwd"] for p in _PROC_TMP_HINTS):
            score += 1.5
            reasons.append("Temp/Trash path")

        m = _PROC_PARENT_PID_RE.search(cmd)
        if m:
            declared = int(m.group(1))
            if declared not in rows and declared != 1:
                score += 4.0
                reasons.append("Declared parent pid %d is gone" % declared)

        cmd_base = r["cmd_base"]
        stuck_cli = cmd_base in _PROC_STUCK_CLI_BASES and detached and etime_min >= 10
        if stuck_cli:
            score += 3.5
            reasons.append("Stuck orphan CLI")

        if r["is_automation"] and not r["is_helper"]:
            if is_orphan:
                score += 5.0
                reasons.append("Leaked headless browser (launcher gone)")
            elif tree_orphan:
                score += 3.0
                reasons.append("Headless browser under orphaned tree")
        elif r["is_automation"] and r["is_helper"] and detached:
            score += 3.0
            reasons.append("Helper of leaked headless browser (root pid %s)" % r["tree_root"])
        elif r["is_helper"] and ppid == 1:
            score += 4.0
            reasons.append("Orphaned app helper (main app gone)")

        if r["is_lsp"]:
            bump(4.0, 2.0, "Orphaned language server (editor gone)", "Language server under orphaned tree")
        if r["is_mcp"]:
            bump(3.5, 1.5, "Orphaned MCP server (host gone)", "MCP server under orphaned tree")
        if r["is_mp_worker"]:
            bump(4.5, 2.0, "Orphaned multiprocessing worker (coordinator gone)", "Pool worker under orphaned tree")
        if r["is_dev_server"]:
            bump(2.5, 1.25, "Dev server, launcher gone", "Dev server under orphaned tree")

        if cmd_base in _PROC_GIT_BASES and not has_tty and etime_min >= 30 \
                and not any(h in cmd for h in _PROC_GIT_DAEMON_HINTS):
            score += 3.0
            reasons.append("Stuck git/gh op (>30m, no TTY)")
        if cmd_base == "ssh" and not has_tty and etime_min >= 30 and not r["is_known_daemon"] \
                and ("git@" in cmd or "GIT_PROTOCOL" in cmd):
            score += 2.5
            reasons.append("Stuck git transport (ssh, >30m, no TTY)")

        if is_orphan:
            score += 2.0
            reasons.append("Orphaned (PPID 1)")
        elif tree_orphan:
            score += 1.5
            reasons.append("Parent tree orphaned (root pid %d)" % r["tree_root"])

        if not r["anchored"] or has_tty:
            if etime_min >= 2880:
                score += 1.5
                reasons.append("Running >48h")
            elif etime_min >= 120:
                score += 0.5
                reasons.append("Running >2h")

        runaway = False
        cpu_ratio = (r["cputime_min"] / etime_min) if etime_min >= 30 else 0.0
        if cpu_ratio >= 0.5 and not has_tty and not r["is_ccc"]:
            score += 2.0
            runaway = True
            reasons.append("Sustained high CPU (%d%% avg over %dh, no TTY)" % (round(cpu_ratio * 100), max(1, round(etime_min / 60))))
        if cpu >= 90.0 and etime_min >= 15 and detached and not has_tty:
            score += 2.0
            runaway = True
            reasons.append("Spinning orphan (%d%% CPU)" % round(cpu))
        if (runaway or stuck_cli) and r["tree_root"] and r["tree_root"] != pid:
            runaway_children.setdefault(r["tree_root"], pid)

        if cpu == 0.0 and stat.startswith("S"):
            score += 0.5

        if r["is_ccc"]:
            score -= 10.0
            shields.append("CCC component")
        elif r["is_gui"]:
            score -= 6.0
            shields.append("GUI app")
        elif r["is_system_daemon"]:
            score -= 7.0
            shields.append("macOS system daemon")
        elif r["is_known_daemon"]:
            score -= 4.0
            shields.append("Known dev daemon")
        if r["label"]:
            shields.append("launchd job: %s" % r["label"])
        if r["is_ccc_session"]:
            shields.append("CCC session")
        if has_tty:
            score -= 4.0
            shields.append("Attached TTY")

        procs.append({
            "pid": pid,
            "ppid": ppid,
            "cmd": cmd,
            "cmd_short": _sys_label(cmd),
            "cpu": cpu,
            "cpu_ratio": round(cpu_ratio, 2),
            "cputime_min": round(r["cputime_min"], 1),
            "rss_mb": round(r["rss_mb"], 1),
            "etime": r["etime_str"],
            "etime_min": round(etime_min, 1),
            "stat": stat,
            "tty": r["tty"],
            "has_tty": has_tty,
            "cwd": files["cwd"],
            "cwd_exists": files["cwd_exists"],
            "fd0": files["fd0"],
            "fd0_type": files["fd0_type"],
            "fd0_exists": files["fd0_exists"],
            "launchd_label": r["label"],
            "tree_root": r["tree_root"],
            "tree_orphan": tree_orphan,
            "_raw_score": score,
            "reasons": reasons,
            "shields": shields,
            "kill_hint": kill_hint,
            "can_kill": not r["is_ccc"] and pid > 1 and pid != my_pid and pid != parent_pid,
        })

    # ── pass 4: an orphan root that owns a runaway/stuck child is the thing
    # to kill — `bash -c "... | grep -R | head"` adopted by launchd is one
    # leak, and terminating the root takes the pipeline with it.
    for p in procs:
        child = runaway_children.get(p["pid"])
        if child is not None and p["tree_root"] == p["pid"]:
            p["_raw_score"] += 2.0
            p["reasons"].append("Owns runaway/stuck child (pid %d)" % child)
            p["kill_hint"] = "root of leaked tree; terminating it takes pid %d with it" % child
        score = max(0.0, min(10.0, round(p.pop("_raw_score"), 1)))
        p["score"] = score
        p["risk"] = "critical" if score >= 7.0 else ("suspicious" if score >= 4.0 else ("low" if score >= 1.5 else "safe"))

    procs.sort(key=lambda x: (x["score"], x["cpu"], x["rss_mb"]), reverse=True)
    high_count = sum(1 for p in procs if p["score"] >= 7.0)
    med_count = sum(1 for p in procs if 4.0 <= p["score"] < 7.0)

    return {
        "ts": now,
        "total_count": len(procs),
        "high_risk_count": high_count,
        "medium_risk_count": med_count,
        "processes": procs,
    }


def build_system_processes(force=False):
    snap = _system_processes_snapshot
    now = time.time()
    if not force and snap["data"] is not None and now - snap["ts"] < _SYSTEM_PROCESSES_TTL:
        return snap["data"]
    with _system_processes_lock:
        now = time.time()
        if not force and snap["data"] is not None and now - snap["ts"] < _SYSTEM_PROCESSES_TTL:
            return snap["data"]
        data = _build_system_processes_uncached()
        snap["data"] = data
        snap["ts"] = time.time()
        return data


def system_process_kill(pids, force=False):
    my_pid = os.getpid()
    parent_pid = os.getppid()
    sig = signal.SIGKILL if force else signal.SIGTERM
    sig_name = "SIGKILL" if force else "SIGTERM"
    killed, blocked, errors = [], [], {}
    for p in pids:
        try:
            pid = int(p)
        except (ValueError, TypeError):
            continue
        if pid <= 1 or pid in (my_pid, parent_pid):
            blocked.append(pid)
            continue
        try:
            os.kill(pid, sig)
            killed.append(pid)
            _resume_ledger_append("kill", pid=pid, source=f"system_process_kill_{sig_name.lower()}")
            _log_activity("kill", sig_name, f"pid={pid} source=system_process_kill")
        except ProcessLookupError:
            killed.append(pid)
        except PermissionError:
            blocked.append(pid)
            errors[str(pid)] = "permission denied"
        except Exception as e:
            errors[str(pid)] = str(e)
    _system_processes_snapshot["data"] = None
    _system_health_snapshot["data"] = None
    return {"ok": True, "killed": killed, "blocked": blocked, "errors": errors}


def build_live_sessions_activity():
    """Map session_id → live-work fields for every currently-live session.

    Coalesced: concurrent / rapid polls within _LIVE_ACTIVITY_SNAPSHOT_TTL
    share a single computation. See _live_activity_snapshot."""
    snap = _live_activity_snapshot
    now = time.time()
    if snap["data"] is not None and now - snap["ts"] < _LIVE_ACTIVITY_SNAPSHOT_TTL:
        return snap["data"]
    with _live_activity_snapshot_lock:
        # Another thread may have refreshed it while we waited for the lock.
        now = time.time()
        if snap["data"] is not None and now - snap["ts"] < _LIVE_ACTIVITY_SNAPSHOT_TTL:
            return snap["data"]
        # Time the REAL build — this is the truest health signal for the hot
        # path, and the only place an actual (non-cached) build happens.
        _t0 = time.perf_counter()
        data = _build_live_sessions_activity_uncached()
        _record_live_build_ms((time.perf_counter() - _t0) * 1000.0)
        snap["data"] = data
        snap["ts"] = time.time()
        return data


def _build_live_sessions_activity_uncached():
    out = {}
    # Pool-model Codex threads (desktop app-server) never appear in the
    # resume-arg/sidecar discovery scan — union the cached sqlite candidacy
    # set (same pattern as _auto_unarchive_live_sessions, CCC-435) so a turn
    # running in Codex desktop lights up its WIP chip too.
    candidates = _discover_live_session_ids() | _codex_pool_candidate_sids()
    for sid in candidates:
        if not _archive_session_is_live(sid):
            continue
        raw = _live_activity_entry_for_session(sid)
        out[sid] = {k: raw.get(k) for k in _LIVE_ACTIVITY_FIELD_KEYS}
    return out


def _sessions_state_snapshot():
    """Cheap {session_id: {state, question_waiting, needs_approval}} for every
    currently-live session, reusing the coalesced live-activity snapshot
    (candidacy-gated, ≤1.5s old) — no per-call JSONL walk or subprocess. This
    is the source the /api/sessions/events SSE stream diffs each tick.

    `state` is the canonical four-state label via `_stamp_session_state`, so it
    carries the same CCC-174 "waiting" hysteresis the dashboard applies.
    Sessions absent from the live map are simply not present here; the SSE
    layer treats a disappearance as a transition to "ended".

    Caveat: the sidecar-shaped entry has no `last_assistant_text`, so a
    prose-only soft-block (no formal question_waiting / needs_approval flag)
    reads "idle" here. The formal human-input signals — the ones a monitor
    most cares about — are always reflected.
    """
    out = {}
    try:
        activity = build_live_sessions_activity()
    except Exception:
        return out
    for sid, fields in (activity or {}).items():
        entry = dict(fields or {})
        entry["session_id"] = sid
        try:
            state = _stamp_session_state(entry)
        except Exception:
            state = "idle" if entry.get("is_live") else "ended"
        out[sid] = {
            "state": state,
            "question_waiting": bool(entry.get("question_waiting")),
            "needs_approval": bool(entry.get("needs_approval")),
        }
    return out


_CENSUS_IDENTITY_CACHE_LOCK = threading.Lock()
_CENSUS_IDENTITY_CACHE = {"token": None, "map": {}}


def _census_identity_map():
    """sid → lightweight identity (name/engine/model/effort/repo/parent).

    Sources, lowest priority first so later ones override: the on-disk spawn
    registry, then the archive response cache. The archive read itself is
    hit-only — census never blocks on a build — but when the cache is
    completely cold (fresh server, nobody opened "All repos" yet) it kicks
    the same single-flight background refresh the UI uses, so the NEXT census
    call has full identity instead of staying blind until someone opens the
    dashboard. Memoized on the cache entries' (key, cached_at) plus the
    registry file mtime, so polling census never re-walks the full
    conversation archive (con_0496274e58: no uncached O(all-conversations)
    work on session-state paths)."""
    try:
        registry_mtime = SPAWNED_PIDS_FILE.stat().st_mtime
    except (OSError, NameError):
        registry_mtime = None
    _load_archive_response_cache()
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        cache_empty = not _ARCHIVE_RESPONSE_CACHE
        token = (registry_mtime, tuple(sorted(
            (key, float((entry or {}).get("cached_at") or 0))
            for key, entry in _ARCHIVE_RESPONSE_CACHE.items()
        )))
    if cache_empty:
        try:
            cold_key = _archive_response_cache_key(
                include_prs=False, resolve_pr_states=False,
                resolve_effective=False, resolve_worktree_dirty=False,
            )
            _archive_refresh_response_cache_async(cold_key, {
                "include_prs": False, "resolve_pr_states": False,
                "resolve_effective": False, "resolve_worktree_dirty": False,
            })
        except Exception:
            pass
    with _CENSUS_IDENTITY_CACHE_LOCK:
        if _CENSUS_IDENTITY_CACHE["token"] == token:
            return _CENSUS_IDENTITY_CACHE["map"]
    try:
        spawn_markers = _load_spawn_markers()
    except Exception:
        spawn_markers = {}
    out = {}
    for entry in _load_spawn_registry():
        if not isinstance(entry, dict):
            continue
        ident = {
            "name": entry.get("name") or entry.get("command_summary") or None,
            "engine": entry.get("engine") or None,
            "model": entry.get("model") or None,
            "effort": entry.get("effort") or entry.get("reasoning_effort") or None,
            "repo_path": entry.get("repo_path") or entry.get("cwd") or None,
            "parent_session_id": entry.get("parent_session_id") or None,
            "spawned_via": _infer_session_spawned_via(entry, markers=spawn_markers),
            "has_conversation_row": False,
        }
        for key in ("session_id", "resumed_sid"):
            sid = (entry.get(key) or "").strip()
            if sid:
                out.setdefault(sid, ident)
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        snapshots = [
            list((entry or {}).get("conversations") or [])
            for entry in _ARCHIVE_RESPONSE_CACHE.values()
        ]
    for rows in snapshots:
        for row in rows:
            if not isinstance(row, dict):
                continue
            sid = (row.get("session_id") or row.get("id") or "").strip()
            if not sid:
                continue
            existing = out.get(sid) or {}
            if existing.get("has_conversation_row"):
                continue
            name = row.get("display_name") or row.get("first_message") or existing.get("name")
            if isinstance(name, str):
                name = " ".join(name.split())[:120] or None
            else:
                name = existing.get("name")
            resolved_via = (
                existing.get("spawned_via")
                or _infer_session_spawned_via(row, sid=sid, markers=spawn_markers)
            )
            out[sid] = {
                "name": name,
                "engine": row.get("engine") or existing.get("engine"),
                "model": row.get("model") or existing.get("model"),
                "effort": row.get("reasoning_effort") or row.get("effort") or existing.get("effort"),
                "repo_path": row.get("session_cwd") or existing.get("repo_path"),
                "parent_session_id": row.get("parent_session_id") or existing.get("parent_session_id"),
                "spawned_via": resolved_via,
                "has_conversation_row": True,
                "mtime": row.get("mtime") or row.get("modified") or None,
                "jsonl_path": row.get("jsonl_path") or None,
            }
    # Codex pool threads (Codex.app app-server) reach liveness via
    # _codex_pool_candidate_sids but are in neither the spawn registry nor
    # (yet) the archive cache — they rendered as all-'?' rows. One bulk
    # sqlite read, memoized with the rest of this map, fills identity for
    # threads the other sources missed. has_conversation_row stays False:
    # this only patches LIVE-row identity — ended coverage stays with the
    # archive, whose codex rows carry richer metadata.
    try:
        for row in _codex_fetch_threads(limit=200) or ():
            if not isinstance(row, dict):
                continue
            sid = str(row.get("id") or "").strip()
            if not sid or sid in out:
                continue
            name = row.get("title") or row.get("first_user_message") or None
            if isinstance(name, str):
                name = " ".join(name.split())[:120] or None
            else:
                name = None
            out[sid] = {
                "name": name,
                "engine": "codex",
                "model": row.get("model") or None,
                "effort": row.get("reasoning_effort") or None,
                "repo_path": row.get("cwd") or None,
                "parent_session_id": None,
                "has_conversation_row": False,
                "mtime": _codex_ts_seconds(row, prefix="updated")
                or _codex_ts_seconds(row, prefix="created") or None,
            }
    except Exception:
        pass
    with _CENSUS_IDENTITY_CACHE_LOCK:
        _CENSUS_IDENTITY_CACHE["token"] = token
        _CENSUS_IDENTITY_CACHE["map"] = out
    return out


_CENSUS_PROBE_CACHE = {}  # sid -> ((mtime_ns, size), probe result) — keyed like _conv_head_cache


def _census_probe_transcript(sid):
    """Identity for a census-rowless live session, from its transcript head.

    Two populations land here: CCC's own generated helpers (auto-title bots —
    the archive deliberately skips them, _is_generated_helper_session) and
    brand-new sessions the archive cache simply hasn't rebuilt to include yet.
    Both have a transcript under ~/.claude/projects; read the first ~200 lines
    once for first_message / cwd / model and classify.

    Cached by (mtime_ns, size) like the archive head-parse — a growing live
    transcript re-probes (identity improves as the first model turn lands), a
    stable one never re-reads. Candidacy-gated: called only for live sids
    with no other identity, so cost is O(rowless live), never a bulk
    transcript scan (con_0496274e58).
    Returns {is_helper, first_message, cwd, model} or None (no transcript)."""
    try:
        projects = Path(_SYS_PROJECTS_DIR)
        cand = None
        for proj in projects.iterdir():
            p = proj / f"{sid}.jsonl"
            if p.is_file():
                cand = p
                break
        if cand is None:
            return None
        st = cand.stat()
    except OSError:
        return None
    key = (st.st_mtime_ns, st.st_size)
    hit = _CENSUS_PROBE_CACHE.get(sid)
    if hit is not None and hit[0] == key:
        return hit[1]
    first_message = ""
    cwd = None
    model = None
    try:
        with cand.open("r") as fh:
            for i, line in enumerate(fh):
                if i >= 200:
                    break
                line = line.strip()
                if not line:
                    continue
                try:
                    ev = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not first_message:
                    text = _extract_user_prompt_text(ev)
                    if text:
                        first_message = text
                if not cwd:
                    cwd = ev.get("cwd") or None
                if not model:
                    msg = ev.get("message") or {}
                    if isinstance(msg, dict) and msg.get("model"):
                        model = msg["model"]
                if first_message and cwd and model:
                    break
    except (OSError, UnicodeDecodeError):
        pass
    result = {
        "is_helper": _is_generated_helper_session(first_message),
        "first_message": first_message or None,
        "cwd": cwd,
        "model": model,
    }
    _CENSUS_PROBE_CACHE[sid] = (key, result)
    return result


_CENSUS_UNANSWERED_CACHE = {}  # sid -> ((mtime_ns, size), bool)
_CENSUS_UNANSWERED_TAIL_BYTES = 65536
_CENSUS_UNANSWERED_MAX_LINES = 300


def _census_unanswered_input(sid, transcript_path):
    """True when the transcript's last actor event is a HUMAN message with no
    agent reply after it — the "you injected text into a dead session and
    nothing is listening" state (e.g. 01a05b3d: grok coordinator ended, user
    kept injecting, user_message_chunk rows piled up with no agent turn).

    Reads only the tail (~64KB, ≤300 lines), cached by (mtime_ns, size): a
    dead session's transcript changes only when someone injects again, so the
    verdict re-checks exactly then. Called per census row (bounded by the
    --since window), never a bulk scan (con_0496274e58)."""
    if not transcript_path:
        return False
    try:
        st = os.stat(transcript_path)
    except OSError:
        return False
    key = (st.st_mtime_ns, st.st_size)
    hit = _CENSUS_UNANSWERED_CACHE.get(sid)
    if hit is not None and hit[0] == key:
        return hit[1]
    verdict = False
    try:
        with open(transcript_path, "rb") as fh:
            if st.st_size > _CENSUS_UNANSWERED_TAIL_BYTES:
                fh.seek(-_CENSUS_UNANSWERED_TAIL_BYTES, os.SEEK_END)
            tail = fh.read().decode("utf-8", errors="replace")
        lines = tail.splitlines()[1:] if st.st_size > _CENSUS_UNANSWERED_TAIL_BYTES else tail.splitlines()
        grok = "/.grok/" in transcript_path
        scanned = 0
        for line in reversed(lines):
            if scanned >= _CENSUS_UNANSWERED_MAX_LINES:
                break
            line = line.strip()
            if not line:
                continue
            scanned += 1
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            if grok:
                kind = ((ev.get("params") or {}).get("update") or {}).get("sessionUpdate")
                if kind == "user_message_chunk":
                    verdict = True
                    break
                if kind in ("agent_message_chunk", "turn_completed"):
                    break
            else:
                etype = ev.get("type")
                if etype == "assistant":
                    break
                if etype == "user":
                    text = _extract_user_prompt_text(ev)
                    if text and not _is_transcript_control_text(text):
                        verdict = True
                        break
    except (OSError, UnicodeDecodeError):
        pass
    _CENSUS_UNANSWERED_CACHE[sid] = (key, verdict)
    return verdict


def build_session_census(since_s=None):
    """One-call live census: state + identity + lineage for every live session.

    Answers "what sessions exist and what are they doing right now" — the
    question the dashboard answers by stitching live-activity + the full
    conversation archive + per-session family lookups. Built only from
    cached/coalesced structures: no archive build, no transcript scan. `state`
    is the canonical four-state label via `_stamp_session_state`
    (ended/waiting/working/idle, same as the SSE stream). Rows are sorted by
    most recent activity first; sessions with no usable timestamp sort last
    with last_event_age_s null (never a garbage age).

    With `since_s` (seconds), also merges recently-ENDED archive sessions
    whose last activity falls inside the window (state "ended") — so
    `ccc sessions --since 10h` answers "everything active in the last 10h",
    not just "the live subset of it". Live rows always pass through."""
    try:
        activity = build_live_sessions_activity() or {}
    except Exception:
        activity = {}
    try:
        identity = _census_identity_map()
    except Exception:
        identity = {}
    now = time.time()
    try:
        spawn_markers = _load_spawn_markers()
    except Exception:
        spawn_markers = {}
    children_of = {}
    for sid in activity:
        parent = (identity.get(sid) or {}).get("parent_session_id") or ""
        if parent:
            children_of.setdefault(parent, []).append(sid)
    rows = []
    for sid, fields in activity.items():
        entry = dict(fields or {})
        entry["session_id"] = sid
        try:
            state = _stamp_session_state(entry)
        except Exception:
            state = "idle" if entry.get("is_live") else "ended"
        try:
            ts = float(entry.get("sidecar_ts") or 0)
        except (TypeError, ValueError):
            ts = 0.0
        age = None if ts <= 0 or ts > now + 60 else max(0.0, now - ts)
        ident = identity.get(sid) or {}
        helper = False
        if not ident:
            probe = _census_probe_transcript(sid)
            if probe:
                if probe.get("is_helper"):
                    helper = True
                    ident = {
                        "engine": "claude",
                        "name": "[helper] " + ((probe.get("first_message") or "auto-title")[:60]),
                        "repo_path": None,
                        "parent_session_id": None,
                        "has_conversation_row": False,
                    }
                else:
                    name = probe.get("first_message")
                    if isinstance(name, str):
                        name = " ".join(name.split())[:120] or None
                    ident = {
                        "engine": "claude",
                        "model": probe.get("model"),
                        "name": name,
                        "repo_path": probe.get("cwd"),
                        "parent_session_id": None,
                        "has_conversation_row": False,
                    }
        parent = ident.get("parent_session_id") or None
        rows.append({
            "session_id": sid,
            "state": state,
            "engine": ident.get("engine"),
            "model": ident.get("model"),
            "effort": ident.get("effort"),
            "name": ident.get("name"),
            "repo_path": ident.get("repo_path"),
            "parent_session_id": parent,
            "spawned_via": _infer_session_spawned_via(ident, sid=sid, markers=spawn_markers),
            "children": sorted(children_of.get(sid) or ()),
            "last_event_age_s": age,
            "pending_tool": entry.get("pending_tool") or entry.get("sidecar_tool") or None,
            "question_waiting": bool(entry.get("question_waiting")),
            "needs_approval": bool(entry.get("needs_approval")),
            "has_conversation_row": bool(ident.get("has_conversation_row")),
            "helper": helper,
            "unanswered_input": False,
            "turn_age_s": entry.get("turn_age_s"),
            "stuck": bool(entry.get("stale_tool_call")),
            "stuck_age_s": entry.get("stale_tool_age_s") or None,
        })
    if since_s is not None:
        try:
            since_s = float(since_s)
        except (TypeError, ValueError):
            since_s = None
    if since_s is not None and since_s >= 0:
        for sid, ident in identity.items():
            if sid in activity or not ident.get("has_conversation_row"):
                continue
            try:
                mtime = float(ident.get("mtime") or 0)
            except (TypeError, ValueError):
                continue
            if mtime <= 0 or (now - mtime) > since_s:
                continue
            rows.append({
                "session_id": sid,
                "state": "ended",
                "engine": ident.get("engine"),
                "model": ident.get("model"),
                "effort": ident.get("effort"),
                "name": ident.get("name"),
                "repo_path": ident.get("repo_path"),
                "parent_session_id": ident.get("parent_session_id") or None,
                "spawned_via": _infer_session_spawned_via(ident, sid=sid, markers=spawn_markers),
                "children": [],
                "last_event_age_s": max(0.0, now - mtime),
                "pending_tool": None,
                "question_waiting": False,
                "needs_approval": False,
                "has_conversation_row": True,
                "helper": False,
                "unanswered_input": _census_unanswered_input(sid, ident.get("jsonl_path")),
                "turn_age_s": None,
                "stuck": False,
                "stuck_age_s": None,
            })
    rows.sort(key=lambda r: (
        r["last_event_age_s"] is None,
        r["last_event_age_s"] if r["last_event_age_s"] is not None else 0.0,
    ))
    return {"ok": True, "now": now, "sessions": rows}


def _decode_project_slug(slug):
    """Best-effort reverse of _encode_project_slug. The encoding is lossy
    (every non-alphanumeric becomes `-`), so a single slug can map to many
    candidate paths; we pick the first one that exists on disk by walking
    from `/` and absorbing as many consecutive `-`-separated parts into
    each path component as needed to find an existing dir.

    Returns a Path (existing) or None when no candidate resolves. Used by
    find_all_conversations to give a clean folder label for slugs whose
    repo has hyphens in the name (e.g. `my-finance-app`).
    """
    if not slug.startswith("-"):
        return None
    parts = slug[1:].split("-")

    def search(prefix, remaining):
        if not remaining:
            return prefix if prefix.is_dir() else None
        for k in range(1, len(remaining) + 1):
            name = "-".join(remaining[:k])
            candidate = prefix / name
            if candidate.is_dir():
                result = search(candidate, remaining[k:])
                if result is not None:
                    return result
        return None

    try:
        return search(Path("/"), parts)
    except (OSError, ValueError):
        return None


_GENERATED_HELPER_SESSION_PREFIXES = (
    "Produce a concise 4-8 word title summarizing what the user is trying to do",
    "Produce a concise 4-8 word title for the GitHub issue below",
)

_TRANSCRIPT_CONTROL_PREFIXES = (
    "<system-reminder>",
    "<command-",
    "<local-command",
    "<bash-",
    "<kimi-skill-loaded",
)


def _is_transcript_control_text(text):
    """Return True for Claude Code bookkeeping stored as user transcript text."""
    normalized = (text or "").strip()
    return (
        (
            normalized.startswith("[Request interrupted by user")
            and normalized.endswith("]")
        )
        or normalized.startswith(_TRANSCRIPT_CONTROL_PREFIXES)
    )


def _extract_command_invocation_text(text):
    """Turn Claude Code slash-command bookkeeping into the typed command."""
    head = (text or "").lstrip()
    if not (head.startswith("<command-name>") or head.startswith("<command-message>")):
        return ""
    m = re.search(r"<command-name>([^<]+)</command-name>", head)
    cmd_name = html.unescape(m.group(1).strip()) if m else ""
    if not cmd_name:
        m2 = re.search(r"<command-message>([^<]+)</command-message>", head)
        if m2:
            raw = html.unescape(m2.group(1).strip())
            cmd_name = raw if raw.startswith("/") else ("/" + raw)
    if not cmd_name:
        return ""
    m_args = re.search(r"<command-args>([^<]*)</command-args>", head)
    cmd_args = html.unescape(m_args.group(1).strip()) if m_args else ""
    return (cmd_name + (" " + cmd_args if cmd_args else "")).strip()


def _clean_claude_goal_objective(text):
    obj = (text or "").strip()
    obj = re.sub(r"^(?:[-*]\s+)+", "", obj).strip()
    return obj


def _apply_claude_goal_command(meta, command_text):
    """Update tail metadata from a visible Claude `/goal ...` command."""
    cmd = (command_text or "").strip()
    if not cmd.lower().startswith("/goal"):
        return
    rest = cmd[len("/goal"):].strip()
    if not rest:
        return
    first, _, remainder = rest.partition(" ")
    action = first.strip().lower()
    if action in ("clear", "cancel", "reset", "remove"):
        meta["goal"] = ""
        meta["goal_status"] = ""
        return
    if action in ("pause", "paused"):
        if meta.get("goal"):
            meta["goal_status"] = "paused"
        return
    if action in ("resume", "active", "start"):
        if meta.get("goal"):
            meta["goal_status"] = "active"
        return
    if action in ("block", "blocked"):
        if meta.get("goal"):
            meta["goal_status"] = "blocked"
        return
    if action in ("complete", "completed", "done"):
        if meta.get("goal"):
            meta["goal_status"] = "complete"
        return
    objective = remainder if action in ("set", "edit") and remainder else rest
    objective = _clean_claude_goal_objective(objective)
    if objective:
        meta["goal"] = objective
        meta["goal_status"] = "active"


_HOST_SYSTEM_INSTRUCTION_RE = re.compile(
    r"^\s*<system_instruction>.*?</system_instruction>\s*",
    re.DOTALL | re.IGNORECASE,
)


def _strip_host_system_instruction(text):
    """Drop a host wrapper prepended to a user prompt by the launching app.

    Conductor prefixes the first prompt of every workspace it starts with a
    <system_instruction> block ("You are working inside Conductor..."). It is
    machine provenance, not something the user typed, so every CCC surface
    that answers "what was asked" — sidebar title, kanban card, last_prompt —
    wants the text after the closing tag. Stripping happens here, at the one
    place transcript user text is read, so it applies to Claude, Codex and
    anything else Conductor launches rather than to one engine's title path.
    """
    if text is None:
        return ""
    return _HOST_SYSTEM_INSTRUCTION_RE.sub("", str(text), count=1)


def _extract_user_prompt_text(ev):
    """Extract user-visible prompt text from a JSONL event.

    Claude Code records slash/local-command bookkeeping as user messages in
    the transcript. Those rows are useful for replay, but they should not be
    treated as the session's title/original ask in CCC.
    """
    if ev.get("type") != "user" or ev.get("isMeta"):
        return ""
    msg = _safe_parse_message(ev.get("message", {}))
    text = _extract_text_from_content(msg.get("content", ""))
    if _is_transcript_control_text(text):
        # A slash command like "/goal ..." is still control-prefixed
        # bookkeeping (<command-name>...), but it carries a real,
        # human-typed ask in <command-args>. Surface that instead of
        # blanking first_message — otherwise a session whose only prompt
        # was a slash command reads as [EMPTY] forever even with a full
        # transcript (CCC-979).
        return _extract_command_invocation_text(text)
    text = _strip_host_system_instruction(text)
    return _strip_ccc_session_state_instruction(text).strip()


def _extract_queued_command_prompt(ev):
    """Extract a queued human prompt from Claude Code attachment events.

    When the user types while Claude is busy, recent Claude Code builds write
    the prompt as an attachment:

      {"type": "attachment", "attachment": {"type": "queued_command", ...}}

    Those prompts are real user-visible turns and should render in CCC's
    transcript pane. Background task notifications also use queued_command,
    so only commandMode=prompt is treated as chat input.
    """
    if ev.get("type") != "attachment":
        return None
    attachment = ev.get("attachment")
    if not isinstance(attachment, dict):
        return None
    if attachment.get("type") != "queued_command":
        return None
    if attachment.get("commandMode") != "prompt":
        return None
    prompt = attachment.get("prompt", "")
    origin = attachment.get("origin")
    peer = None
    if isinstance(origin, dict) and origin.get("kind") == "peer":
        peer = _peer_block_from_origin(origin)
        body = str(origin.get("body") or "").strip()
        if not body:
            body = _peer_body_from_wrapped(_extract_text_from_content(prompt))
        return {"text": body, "images": [], "peer": peer}
    text = _extract_text_from_content(prompt)
    if _is_transcript_control_text(text):
        return None
    images = _extract_images_from_content(prompt)
    display_text = "" if (text == "[image]" and images) else text
    display_text = _strip_ccc_session_state_instruction(display_text).strip()
    if display_text or images:
        return {"text": display_text, "images": images}
    return None


def _is_generated_helper_session(first_message):
    """Return True for CCC's own throwaway utility prompts."""
    text = (first_message or "").lstrip()
    if not text:
        return False
    if text.startswith(_GENERATED_HELPER_SESSION_PREFIXES):
        return True
    return (
        text.startswith("Use the Read tool to open this image:")
        and "Then output ONLY a single JSON line" in text[:500]
    )


def _is_unclaimed_claude_prewarm(
    first_message, tail_meta, session_id=None, spawn_registry_by_sid=None,
):
    """Hide an internal reservation until it receives its first real prompt."""
    if str(first_message or "").strip():
        return False
    registry_entry = (
        (spawn_registry_by_sid or {}).get(str(session_id or "")) or {}
    )
    return bool(registry_entry.get("prewarm")) or (
        str((tail_meta or {}).get("agent_name") or "").strip() == "ccc-prewarm"
    )


def _registry_epoch_seconds(value):
    try:
        ts = float(value)
    except (TypeError, ValueError):
        return 0.0
    if ts > 10_000_000_000:
        ts = ts / 1000.0
    return ts if ts > 0 else 0.0


def _spawn_registry_entry_for_session(session_id, engine=None):
    sid = str(session_id or "").strip()
    if not sid:
        return None
    try:
        entries = _load_spawn_registry()
    except Exception:
        return None
    for entry in entries:
        if entry.get("session_id") != sid and entry.get("resumed_sid") != sid:
            continue
        if engine and entry.get("engine") != engine:
            continue
        return entry
    if engine in (None, "codex"):
        reg = _codex_thread_registry_entry(sid)
        if reg:
            shaped = _codex_thread_registry_spawn_shape(reg)
            shaped.update({
                "session_id": sid,
                "engine": "codex",
                "codex_thread_registry": True,
            })
            return shaped
    return None


def _spawn_registry_entries_by_session(engine=None):
    """Return registry entries keyed by native session id.

    Used by list builders so they do not re-read the registry once per row.
    """
    out = {}
    try:
        entries = _load_spawn_registry()
    except Exception:
        return out
    for entry in entries:
        if engine and entry.get("engine") != engine:
            continue
        for key in ("session_id", "resumed_sid"):
            sid = str(entry.get(key) or "").strip()
            if sid and sid not in out:
                out[sid] = entry
    if engine in (None, "codex"):
        for sid, entry in _codex_thread_registry_entries().items():
            if sid and sid not in out:
                shaped = _codex_thread_registry_spawn_shape(entry)
                shaped.update({
                    "session_id": sid,
                    "engine": "codex",
                    "codex_thread_registry": True,
                })
                out[sid] = shaped
    return out


def _apply_auto_title(display_name, spawn_named, session_id, overridden):
    """Let a CCC auto-title win over a launch slug that keeps being re-written.

    CCC re-appends its `--name` slug as a custom-title on every turn, so an
    auto-title written into the transcript gets clobbered within a turn. The
    recorded title (stored beside the marker) is the durable copy: prefer it
    whenever the row would otherwise render the launch name, and clear
    spawn_named so the row reads as titled.

    Returns (display_name, spawn_named).
    """
    if overridden or not spawn_named:
        return display_name, spawn_named
    auto = _auto_titled_session_ids().get(session_id) or ""
    if not auto:
        return display_name, spawn_named
    return auto, False


def _tail_meta_spawn_named(tail_meta):
    """True when Claude's transcript still reflects its launch --name."""
    custom_title = str((tail_meta or {}).get("custom_title") or "").strip()
    agent_name = str((tail_meta or {}).get("agent_name") or "").strip()
    return bool(custom_title and agent_name and custom_title == agent_name)


def _live_registry_conversation_row(
    session_id,
    meta,
    *,
    folder_path=None,
    folder_label=None,
    name_overrides=None,
    archived_set=None,
    trashed_set=None,
    pinned_rank=None,
    repo_pins=None,
    resolve_worktree_dirty=True,
):
    """Build a row for a live Claude session whose JSONL does not exist yet."""
    sid = str(session_id or "").strip()
    if not sid:
        return None
    cwd = str((meta or {}).get("cwd") or "").strip()
    if cwd and (_path_is_within(cwd, _SCRATCH_DIR) or "command-center/scratch" in cwd):
        return None
    spawn_entry = _spawn_registry_entry_for_session(sid, engine="claude") or {}
    if (
        spawn_entry.get("spawned_via") == "ccc-ask"
        or (meta or {}).get("spawned_via") == "ccc-ask"
        or spawn_entry.get("kind") == "assistant"
    ):
        return None
    natural_folder_path = folder_path or (_find_git_root(cwd) if cwd else "") or cwd
    natural_folder_label = folder_label or (
        _resolve_dir_case(natural_folder_path) if natural_folder_path else "Live session"
    )
    row_folder_path = natural_folder_path
    row_folder_label = natural_folder_label
    pinned_repo = False
    pin_target = (repo_pins or {}).get(sid)
    if pin_target and pin_target != row_folder_path:
        try:
            if Path(pin_target).is_dir():
                row_folder_path = pin_target
                row_folder_label = Path(pin_target).name
                pinned_repo = True
        except OSError:
            pass

    overrides = name_overrides or {}
    spawn_prompt = _strip_ccc_session_state_instruction(
        spawn_entry.get("command_summary") or ""
    ).strip()
    spawn_name = str(spawn_entry.get("name") or "").strip()
    parent_session_id = str(spawn_entry.get("parent_session_id") or "").strip()
    auto_title = _auto_titled_session_ids().get(sid) or ""
    display_name = (
        overrides.get(sid)
        or (meta or {}).get("name")
        or auto_title
        or spawn_name
        or (f"Session in {natural_folder_label}" if natural_folder_label and natural_folder_label not in ("Live session",) else f"Live session {sid[:8]}")
    )
    spawn_named = bool(spawn_name and display_name == spawn_name and not overrides.get(sid))
    mtime = (
        _registry_epoch_seconds((meta or {}).get("updatedAt"))
        or _registry_epoch_seconds((meta or {}).get("startedAt"))
        or time.time()
    )
    branch = _git_branch_for_cwd(cwd)
    cwd_is_worktree = bool(cwd and (Path(cwd) / ".git").is_file())
    row = {
        "id": sid,
        "session_id": sid,
        "jsonl_path": "",
        "slug": _encode_project_slug(row_folder_path) if row_folder_path else "live-session",
        "folder_label": row_folder_label,
        "folder_path": row_folder_path,
        "pinned_repo": pinned_repo,
        "source": "interactive",
        "engine": "claude",
        "timestamp": "",
        "session_cwd": cwd,
        "session_cwd_exists": bool(cwd and Path(cwd).is_dir()),
        "session_cwd_is_worktree": cwd_is_worktree,
        "mtime": mtime,
        "modified": mtime,
        "modified_human": time.strftime("%Y-%m-%d %H:%M", time.localtime(mtime)),
        "size": 0,
        "first_message": _prompt_fragment(spawn_prompt, 200) if spawn_prompt else "",
        "last_prompt": _prompt_fragment(spawn_prompt, 200) if spawn_prompt else "",
        "ai_title": None,
        "branch": branch,
        "git_branch": branch,
        "effective_branch": branch,
        "effective_kind": "worktree" if cwd_is_worktree else None,
        "display_name": display_name,
        "spawn_named": spawn_named,
        "name_overridden": bool(overrides.get(sid)),
        "auto_titled": sid in _auto_titled_session_ids(),
        "archived": sid in (archived_set or set()),
        "trashed": sid in (trashed_set or set()),
        "recently_unarchived": _is_recently_unarchived(sid),
        "verified": False,
        "pinned": sid in (pinned_rank or {}),
        "pin_rank": (pinned_rank or {}).get(sid),
        "worktree_dirty": (
            _worktree_dirty_cached(cwd, mtime) if resolve_worktree_dirty and cwd else False
        ),
        "has_commit": False,
        "has_push": False,
        "has_edit": False,
        "tail_pr_number": None,
        "tail_pr_url": None,
        "pr_state": None,
        "is_live": True,
        "spawn_pid": (meta or {}).get("pid"),
        "last_assistant_text": "",
        "last_event_type": None,
        "pending_tool": None,
        "pending_file": None,
        "sidecar_status": None,
        "sidecar_has_writes": False,
        "sidecar_tool": None,
        "sidecar_file": None,
        "sidecar_ts": 0,
        "sidecar_in_flight": False,
        "needs_approval": False,
        "needs_approval_message": "",
        "question_waiting": False,
        "question_text": "",
        "question_header": "",
        "question_preamble": "",
        "question_options": [],
        "question_option_details": [],
        "parent_session_id": parent_session_id,
        "continued_from_session_id": _continued_from_session_id_from_text(spawn_prompt),
        **_registry_row_overlay(meta),
    }
    try:
        _add_sidecar_fields(row)
    except Exception:
        pass
    return row


# ── Parallel transcript prewarm ────────────────────────────────────────────
# A cold archive scan (no _conv_meta_cache on disk: first ever run, or any
# _CONV_META_SCHEMA_VERSION bump, which drops the whole file) re-parses every
# transcript serially. On a real corpus that measured 147s for 6148 files /
# 6.9 GB, and the sidebar sits on "Loading archive…" for all of it.
#
# _extract_tail_meta is a pure path -> dict function, which makes it a clean
# process-pool boundary. Threads would not help: the work is json.loads and
# regex, neither of which releases the GIL. Workers import server without ever
# running main(), so _INTERRUPT_EVENTS_ENABLED stays False there and the parse
# has no emission side effect -- the parent re-emits from the cached meta when
# it later hits the cache (see _emit_interrupts_from_meta).
#
# Only cold files go to the pool. A warm cache means zero misses, no pool, and
# no cost, which is the common case.
_TAIL_META_PREWARM_MIN = 64  # below this the pool costs more than it saves


def _tail_meta_prewarm_workers():
    if os.environ.get("CCC_ARCHIVE_PARALLEL", "1") in ("0", "false", "no"):
        return 0
    try:
        cpus = os.cpu_count() or 2
    except Exception:
        cpus = 2
    return max(0, min(8, cpus - 2))


def _tail_meta_prewarm_one(path_str):
    """Pool worker: parse one transcript, hand its meta back to the parent."""
    try:
        return path_str, _extract_tail_meta(Path(path_str))
    except Exception:
        return path_str, None


def _conv_meta_cache_is_cold(path, stat_result=None):
    """True when _extract_tail_meta would have to re-parse this file."""
    try:
        st = stat_result if stat_result is not None else path.stat()
    except OSError:
        return False
    cached = _conv_meta_cache.get(str(path))
    return not (cached and cached.get("cache_key") == (st.st_mtime_ns, st.st_size))


def _prewarm_conv_meta_parallel(cold_paths, progress_step=None):
    """Fill _conv_meta_cache for `cold_paths` across a process pool.

    Best-effort: any failure falls back to leaving the cache cold, and the
    serial walk re-parses exactly as it did before. Returns how many entries
    were filled.
    """
    workers = _tail_meta_prewarm_workers()
    if workers < 2 or len(cold_paths) < _TAIL_META_PREWARM_MIN:
        return 0
    filled = 0
    try:
        import concurrent.futures as _futures
        path_strs = [str(p) for p in cold_paths]
        if progress_step:
            progress_step(
                "transcripts", state="running", count=0, total=len(path_strs),
                detail=f"Parsing {len(path_strs)} transcripts across {workers} workers.",
            )
        with _futures.ProcessPoolExecutor(max_workers=workers) as pool:
            # chunksize=1 on purpose: transcripts range from a few KB to
            # ~90 MB, so any batching hands one worker a run of giants while
            # the rest idle. Per-item dispatch costs nothing next to a parse.
            for path_str, meta in pool.map(_tail_meta_prewarm_one, path_strs, chunksize=1):
                if not isinstance(meta, dict) or not meta:
                    continue
                with _conv_meta_cache_lock:
                    _conv_meta_cache[path_str] = meta
                filled += 1
                if progress_step and filled % 200 == 0:
                    progress_step(
                        "transcripts", state="running",
                        count=filled, total=len(path_strs),
                    )
    except Exception:
        # Pool unavailable (sandbox, fork restriction, spawn failure) or a
        # worker died. The serial walk below still produces correct rows.
        return filled
    return filled


def _prewarm_claude_transcripts(projects_root, progress_step=None):
    """Collect cold Claude transcripts under projects_root and prewarm them."""
    if _tail_meta_prewarm_workers() < 2:
        return 0
    cold = []
    try:
        for project_dir in projects_root.iterdir():
            if not project_dir.is_dir():
                continue
            if _is_scratch_project_dir(project_dir):
                continue
            try:
                entries = list(project_dir.iterdir())
            except OSError:
                continue
            for f in entries:
                if not f.name.endswith(".jsonl"):
                    continue
                try:
                    st = f.stat()
                except OSError:
                    continue
                if not stat.S_ISREG(st.st_mode):
                    continue
                if _conv_meta_cache_is_cold(f, st):
                    cold.append((st.st_size, f))
    except OSError:
        return 0
    if len(cold) < _TAIL_META_PREWARM_MIN:
        return 0
    # Biggest first: the pool drains the long files while short ones fill the
    # gaps behind them, instead of ending on one ~90 MB straggler with seven
    # idle workers. Sizes come from the stat already taken above.
    cold.sort(key=lambda pair: pair[0], reverse=True)
    return _prewarm_conv_meta_parallel(
        [f for _, f in cold], progress_step=progress_step,
    )


def find_all_conversations(
    limit_per_folder=None,
    resolve_pr_states=True,
    resolve_effective=True,
    resolve_worktree_dirty=True,
    only_jsonl_paths=None,
    progress_step=None,
):
    """Walk ~/.claude/projects/ for every subdir and return a flat list of
    conversation metadata across every folder you've ever Claude-Code'd in.

    Powers the multi-repo conversation archive: read-only browse of every
    JSONL on disk, regardless of whether a CCC server is currently running
    for that folder. Slow on cold scan (proportional to total JSONL count),
    so callers should expect ~seconds latency the first time. No caching
    layer in v1 — add later if it bites.

    Each entry:
        {session_id, jsonl_path, slug, folder_label, folder_path,
         mtime, size, first_message, git_branch}

    Folder resolution: known-repo paths from recent + custom files give a
    real label; unknown slugs fall back to a best-effort decode (replace
    `-` with `/` and verify) or just the raw slug.

    only_jsonl_paths: incremental mode (W84). When set (absolute path
    strings), build rows ONLY for those Claude transcripts — skip every
    other file, the registry-only augmentation, and the non-Claude engine
    finders. Callers merge the result into a cached full row set
    (_archive_merge_incremental_rows); rows for sources skipped here are
    carried over from that cache.
    """
    _only_dirs = None
    if only_jsonl_paths is not None:
        only_jsonl_paths = {str(p) for p in only_jsonl_paths}
        _only_dirs = {os.path.dirname(p) for p in only_jsonl_paths}
    projects_root = Path.home() / ".claude" / "projects"
    projects_root_exists = projects_root.is_dir()

    # Cold-scan fast path: parse every uncached transcript across a process
    # pool before the serial walk below asks for them one at a time. On a warm
    # cache this finds nothing cold and returns immediately. Skipped for
    # incremental scans, which are a handful of files by construction.
    if projects_root_exists and only_jsonl_paths is None:
        try:
            _prewarm_claude_transcripts(projects_root, progress_step=progress_step)
        except Exception:
            pass

    # Build slug → repo_path map for label resolution.
    known_by_slug = {}
    try:
        for repo in (_load_recent_repos() + _load_custom_repos()):
            try:
                known_by_slug[_encode_project_slug(repo)] = repo
            except Exception:
                pass
    except Exception:
        pass

    # Global state files keyed by session_id alone — same source of truth
    # the active-repo session list reads. Merging them in here lets the
    # archive view show user renames and route archived sessions into the
    # Archived bucket without a server-per-repo.
    try:
        name_overrides = _load_session_name_overrides()
    except Exception:
        name_overrides = {}
    try:
        archived_set, trashed_set = _load_conversation_lifecycle_sets()
    except Exception:
        archived_set, trashed_set = set(), set()
    try:
        pinned_list = _load_pinned_conversations()
    except Exception:
        pinned_list = []
    pinned_rank = _pinned_rank_map(pinned_list)
    try:
        repo_pins = _load_repo_pins()
    except Exception:
        repo_pins = {}
    spawn_registry_by_sid = _spawn_registry_entries_by_session(engine="claude")
    # One read for the whole corpus scan — never per row.
    try:
        spawn_markers = _load_spawn_markers()
    except Exception:
        spawn_markers = {}
    try:
        session_overrides = _load_session_overrides()
    except Exception:
        session_overrides = {}

    # Liveness gate, built once. The cheap "could be live right now" set —
    # Claude registry (one cached `ps`), engine resume-arg scan, sidecar marker
    # files — instead of running _archive_session_is_live (which scans every
    # Gemini/Codex file to classify the engine) for all ~1000 archive rows.
    # Below, only sessions in this set or written within _LIVE_MTIME_WINDOW get
    # the precise probe; the vast majority of rows are old and untouched and
    # resolve to not-live for free. This is the dominant cost of the build.
    try:
        live_candidates = _discover_live_session_ids()
    except Exception:
        live_candidates = set()

    out = []
    seen_session_ids = set()
    _now = time.time()

    # Full scans rebuild the workflow-owner map from scratch; incremental
    # scans (only_jsonl_paths) update only the dirs they walk. A session that
    # starts a workflow rewrites its parent transcript (Workflow tool_use +
    # result), which flips the corpus signature and lands that dir in the
    # next incremental scan — so the map never misses a new workflow owner
    # for more than one refresh.
    if only_jsonl_paths is None:
        _ARCHIVE_WORKFLOW_SESSION_DIRS.clear()

    project_dirs = []
    if projects_root_exists:
        project_dirs = _archive_canonical_project_dirs(projects_root)

    for project_dir in project_dirs:
        if _only_dirs is not None and str(project_dir) not in _only_dirs:
            continue
        if _is_scratch_project_dir(project_dir):
            continue
        slug = project_dir.name

        repo_path = known_by_slug.get(slug)
        if repo_path:
            folder_label = _resolve_dir_case(repo_path)
            folder_path = repo_path
        else:
            decoded = _decode_project_slug(slug)
            if decoded:
                folder_label = _resolve_dir_case(str(decoded)) or slug
                folder_path = str(decoded)
            else:
                folder_label = _slug_to_label(slug)
                folder_path = slug

        # If this is a worktree dir (<parent>-wt-<name>), normalise
        # folder_label to the parent repo name so sessions group under
        # the parent, and stash the worktree suffix for the UI badge.
        _wt_worktree_label = None
        _wt_idx = folder_label.find("-wt-")
        if _wt_idx > 0:
            _wt_worktree_label = folder_label[_wt_idx + 4:]  # e.g. "gemini"
            folder_label = folder_label[:_wt_idx]             # e.g. "claude-command-center"
        elif not repo_path:
            # Nested `<repo>/.worktrees/<name>` dirs encode to
            # `...-worktrees-<name>` (the `/` and `.` both become `-`).
            # When the worktree has since been deleted, `_decode_project_slug`
            # can't resolve it and folder_label falls back to the raw encoded
            # slug -- strip the suffix so these still bucket under the parent
            # repo's label instead of surfacing as an unreadable orphan chip
            # in a category of their own (CCC-760).
            _wtd_match = re.search(r"-+worktrees-(.+)$", folder_label)
            if _wtd_match:
                _wt_worktree_label = _wtd_match.group(1)
                folder_label = folder_label[:_wtd_match.start()]

        try:
            jsonls = []
            for f in project_dir.iterdir():
                # Session subdirs (<sid>/subagents/...) fall out of the same
                # iterdir for free (DirEntry d_type, no extra stat). One
                # is_dir probe each keeps _ARCHIVE_WORKFLOW_SESSION_DIRS to
                # genuine workflow owners only.
                if f.is_dir():
                    if (f / "subagents" / "workflows").is_dir():
                        _ARCHIVE_WORKFLOW_SESSION_DIRS[f.name] = f
                    continue
                if only_jsonl_paths is not None and str(f) not in only_jsonl_paths:
                    continue
                if f.is_file() and f.name.endswith(".jsonl"):
                    try:
                        jsonls.append((f, f.stat()))
                    except OSError:
                        continue
        except OSError:
            continue

        jsonls.sort(key=lambda pair: pair[1].st_mtime, reverse=True)
        if limit_per_folder:
            jsonls = jsonls[:limit_per_folder]

        for f, stat in jsonls:
            session_id = f.stem
            if session_id in seen_session_ids:
                continue
            seen_session_ids.add(session_id)

            first_message = None
            timestamp = None
            git_branch = None
            session_cwd = None
            # Head-parse cache: the first ~20 lines (first_message / launch
            # branch / timestamp / cwd) never change after the session starts,
            # but this loop re-opened and re-JSON-parsed every transcript on
            # every poll — ~1274 file opens + json.loads per call, the dominant
            # warm cost once the tail-meta cache is hit. Cache by (mtime_ns,
            # size) just like _extract_tail_meta; archived transcripts resolve
            # for free. Reuse the already-stat'd `stat` — no extra syscall.
            _head_key = (stat.st_mtime_ns, stat.st_size)
            _hc = _conv_head_cache.get(str(f))
            if _hc is not None and _hc[0] == _head_key:
                first_message, git_branch, timestamp, session_cwd = _hc[1]
            else:
                try:
                    with open(f, "r") as fh:
                        for i, line in enumerate(fh):
                            if i >= 20:
                                break
                            line = line.strip()
                            if not line:
                                continue
                            try:
                                ev = json.loads(line)
                            except json.JSONDecodeError:
                                continue
                            if not first_message:
                                text = _extract_user_prompt_text(ev)
                                if text:
                                    first_message = text
                            if not git_branch:
                                git_branch = ev.get("gitBranch") or ev.get("git_branch")
                            if not timestamp:
                                timestamp = ev.get("timestamp")
                            if not session_cwd:
                                session_cwd = ev.get("cwd")
                            if first_message and git_branch and timestamp and session_cwd:
                                break
                except (OSError, UnicodeDecodeError):
                    pass
                _conv_head_cache[str(f)] = (
                    _head_key,
                    (first_message, git_branch, timestamp, session_cwd),
                )

            if _is_generated_helper_session(first_message):
                continue
            # Skip _resolve_session_cwd here — this is a cross-project
            # bulk scan, and the relocation walk per stale-cwd row hangs
            # /api/conversations/all on cold cache. Resolution still
            # happens lazily via find_session_cwd / find_conversations
            # (per-repo, cached) when the UI actually needs the cwd.

            # Reuse _extract_tail_meta — same source of truth /api/sessions
            # uses, mtime-cached. Pulls per-session signals from JSONL
            # tool-use events: has_edit (Edit/Write/NotebookEdit), has_commit
            # (`git commit` Bash), has_push (`git push` Bash), tail_pr_number
            # / tail_pr_url (`gh pr create` URL). It also records whether a
            # session ever used `cd <path>` / `git -C <path>`, which lets the
            # archive skip effective-repo inference for the common no-drift
            # case instead of walking tool paths for every recent transcript.
            try:
                tail_meta = _extract_tail_meta(f) or {}
            except Exception:
                tail_meta = {}
            if _is_unclaimed_claude_prewarm(
                first_message, tail_meta, session_id, spawn_registry_by_sid,
            ):
                continue

            # Tool-call inference — match what extract_session_workspace
            # does for active sessions. The JSONL's first-event cwd /
            # gitBranch reflect where the session was *launched*, but the
            # user often `cd`s into a worktree partway through, so the
            # branch chip would show "main" even when Claude has been
            # editing in `feat/foo` for hours. _infer_effective_repo walks
            # the session's tool-call paths and finds the dominant git
            # repo; it's mtime-cached internally so the cost amortizes.
            #
            # Recency gate: cold sessions older than the pills window have
            # static cwd/branch — the user can't have cd'd into a worktree
            # since "now" if the JSONL hasn't been touched in days. Skipping
            # inference there is the difference between a 1s and a 25s cold
            # scan on a ~1k-session archive (each call shells out to git
            # 1-4 times for rev-parse / branch / upstream / ahead-behind).
            effective_cwd = session_cwd or folder_path or ""
            effective_branch = git_branch
            effective_kind = None
            is_recent_for_inference = (
                (_now - stat.st_mtime) < _ARCHIVE_PILLS_RECENT_WINDOW
            )
            try:
                # Pass the already-stat'd mtime so the function can hit
                # its cache without re-walking PROJECTS_ROOT for every
                # session (otherwise 936 × 68 = ~63k stat calls per batch).
                eff = _infer_effective_repo(
                    session_id,
                    literal_cwd=session_cwd or folder_path,
                    jsonl_mtime=stat.st_mtime,
                ) if (
                    resolve_effective
                    and is_recent_for_inference
                    and tail_meta.get("has_external_cd")
                ) else None
            except Exception:
                eff = None
            if eff and eff.get("top"):
                effective_cwd = eff["top"]
                if eff.get("branch"):
                    effective_branch = eff["branch"]
                effective_kind = eff.get("kind")  # 'worktree' / 'clone' / 'other'

            # Worktree detection: prefer the inferred kind when available;
            # fall back to path-shape heuristics on the resolved cwd. Path
            # heuristics catch worktrees the user picked manually that
            # don't match `_infer_effective_repo`'s "dominant repo" rule.
            cwd_is_worktree = (
                effective_kind == "worktree"
                or "/.worktrees/" in effective_cwd
                or "/.claude/worktrees/" in effective_cwd
                or "-wt-" in Path(effective_cwd).name
                or Path(effective_cwd).parent.name.endswith("-wt")
            )

            # Per-row folder bucket. A user pin moves the row to a different
            # repo group without touching the transcript or fudging the
            # underlying session_cwd / branch / pills (those still reflect
            # reality). Pin is honored only when the target dir still
            # exists; stale pins fall back to the natural repo.
            row_folder_path = folder_path
            row_folder_label = folder_label
            pinned_repo = False
            pin_target = repo_pins.get(session_id)
            if pin_target and pin_target != folder_path:
                try:
                    if Path(pin_target).is_dir():
                        row_folder_path = pin_target
                        row_folder_label = Path(pin_target).name
                        pinned_repo = True
                except OSError:
                    pass

            spawn_named = _tail_meta_spawn_named(tail_meta)
            # Pick up any /rename done in the terminal — Claude Code writes
            # those as `custom-title` events with the new name, same shape
            # as our spawn-time titles. Old logic only honored custom_title
            # when it equaled agent_name (spawn_named), so a user /rename
            # diverged from agent_name and got dropped — matches Claude
            # Desktop behavior to take any custom_title verbatim.
            display_name = (
                name_overrides.get(session_id)
                or tail_meta.get("custom_title")
                or tail_meta.get("agent_name")
                or tail_meta.get("ai_title")
                or None
            )
            display_name, spawn_named = _apply_auto_title(
                display_name, spawn_named, session_id, bool(name_overrides.get(session_id)),
            )
            has_edit = bool(tail_meta.get("has_edit"))
            has_commit = bool(tail_meta.get("has_commit"))
            has_push = bool(tail_meta.get("has_push"))
            pr_number = tail_meta.get("tail_pr_number")
            pr_url = tail_meta.get("tail_pr_url")
            # worktree_dirty is a current-state signal (uncommitted edits
            # right now), not a per-session one. Use the cached probe
            # against the effective worktree, same as /api/sessions does.
            # last-meaningful activity (fallback to file mtime) — gates both the
            # worktree probe and the liveness probe to recently-active rows.
            _last_ts = tail_meta.get("last_meaningful_ts") or stat.st_mtime
            worktree_dirty = False
            try:
                # Only probe last-meaningful-ts'd sessions to keep this
                # cheap; old archive rows rarely need this state.
                if resolve_worktree_dirty and (_now - _last_ts) < (3 * 86400) and effective_cwd:
                    worktree_dirty = _worktree_dirty_cached(effective_cwd, _last_ts)
            except Exception:
                worktree_dirty = False
            # Only plausibly-live sessions get the precise (Gemini/Codex
            # file-scanning) liveness probe; stale rows are not live for free.
            if session_id in live_candidates or (_now - _last_ts) < _LIVE_MTIME_WINDOW:
                is_live = _archive_session_is_live(session_id)
            else:
                is_live = False

            # Sidecar overlay (Round 3): for live sessions, merge in the
            # sidecar's snapshot of "what is the agent doing right now"
            # — tool name, file, in-flight flag, needs-approval marker.
            # Cheap (one or two file reads per live session) and unlocks
            # the live-tool pill / sending pulse / needs-approval signal
            # on archive rows for free, since the existing renderer reads
            # these exact fields.
            sidecar_fields = {
                "sidecar_status": None,
                "sidecar_has_writes": False,
                "sidecar_tool": None,
                "sidecar_file": None,
                "sidecar_ts": 0,
                "sidecar_in_flight": False,
                "needs_approval": False,
                "needs_approval_message": "",
                "question_waiting": False,
                "question_text": "",
                "question_header": "",
                "question_preamble": "",
                "question_options": [],
                "question_option_details": [],
            }
            if is_live:
                _entry = {"session_id": session_id, "is_live": True}
                try:
                    _add_sidecar_fields(_entry)
                    for k in sidecar_fields:
                        if k in _entry:
                            sidecar_fields[k] = _entry[k]
                except Exception:
                    pass

            # Use transcript activity for the row timestamp. The JSONL file
            # can be rewritten later by metadata-only entries such as
            # custom-title updates; those should not make an old session look
            # active again in the archive list.
            row_mtime = tail_meta.get("last_meaningful_ts") or stat.st_mtime
            model = tail_meta.get("model") or ""
            latest_tok = tail_meta.get("latest_input_tokens") or 0
            peak_tok = tail_meta.get("peak_input_tokens") or 0
            _ov_1m = (session_overrides.get(session_id) or {}).get("context_1m")
            # Peak, not latest: a turn that once exceeded 200k proves the
            # session is running the 1M variant even if a later turn (e.g.
            # after /compact) reports fewer tokens — the variant doesn't
            # revert mid-session, so the limit shouldn't either (CCC-943).
            if _ov_1m or "[1m]" in model.lower() or max(latest_tok, peak_tok) > 200_000:
                ctx_limit = 1_000_000
            else:
                ctx_limit = 200_000
            spawn_entry = spawn_registry_by_sid.get(session_id) or {}
            parent_session_id = str(spawn_entry.get("parent_session_id") or "").strip()
            if not parent_session_id:
                parent_session_id = _parent_session_id_from_return_address_text(first_message)
            out.append({
                "session_id": session_id,
                "source": "interactive",
                "engine": "claude",
                "jsonl_path": str(f),
                "slug": slug,
                "folder_label": row_folder_label,
                "folder_path": row_folder_path,
                "pinned_repo": pinned_repo,
                # Surface the inferred effective cwd / branch — these are
                # what the renderer's branch chip + worktree leaf read,
                # and they reflect where Claude actually edited (after
                # any `cd` into a worktree), not the launch values.
                "session_cwd": effective_cwd,
                "session_cwd_exists": bool(
                    effective_cwd and Path(effective_cwd).is_dir()
                ),
                "session_cwd_is_worktree": cwd_is_worktree,
                # Both keys carry the same recency timestamp. The per-repo
                # /api/sessions builder emits "modified"; this archive builder
                # historically emitted only "mtime". Clients fall back across
                # both (c.modified || c.mtime), but emitting both keeps the two
                # payload shapes identical so a consumer reading either field
                # never silently gets null.
                "mtime": row_mtime,
                "modified": row_mtime,
                "size": stat.st_size,
                "first_message": first_message[:200] if first_message else None,
                "ai_title": (tail_meta.get("ai_title") or None),
                # Both keys: `branch`/`git_branch` is the JSONL's literal
                # gitBranch (what the row defaults to when no inference);
                # `effective_branch`/`effective_kind` carry the tool-call
                # inference. The renderer prefers effective_branch and
                # uses effective_kind === 'worktree' to decide the
                # 🌿 leaf — without these the leaf never shows for
                # archive rows whose session was launched in a clone but
                # edited a sibling worktree.
                "branch": effective_branch,
                "git_branch": effective_branch,
                "effective_branch": effective_branch,
                "effective_kind": effective_kind,
                "display_name": display_name,
                "spawn_named": spawn_named,
                "name_overridden": bool(name_overrides.get(session_id)),
                "auto_titled": session_id in _auto_titled_session_ids(),
                "archived": session_id in archived_set,
                "trashed": session_id in trashed_set,
                "recently_unarchived": _is_recently_unarchived(session_id),
                "pinned": session_id in pinned_rank,
                "pin_rank": pinned_rank.get(session_id),
                # State pills + PR# + live flag — sourced from _extract_tail_meta
                # (per-session JSONL tool-use scan) plus a cached current-
                # state probe for worktree_dirty.
                "worktree_dirty": worktree_dirty,
                "has_commit": has_commit,
                "has_push": has_push,
                "has_edit": has_edit,
                "tail_pr_number": pr_number,
                "tail_pr_url": pr_url,
                # Resolved PR state ("OPEN" / "MERGED" / "CLOSED" / None).
                # Filled in below via a parallel prime pass so we don't
                # serially fan out to gh on cold-cache refreshes. None
                # means gh failed and the row stays visible to be safe.
                "pr_state": None,
                "is_live": is_live,
                # When the session lives in a sibling worktree dir (e.g.
                # "claude-command-center-wt-gemini"), folder_label is
                # normalised to the parent repo name and this field carries
                # the suffix so the UI can render a "wt-gemini" badge.
                "worktree_label": _wt_worktree_label,
                # Last assistant text — passed through so anyone re-enabling
                # the subtitle in archive can see it. Currently hidden via
                # _hideAskHtml flag in the UI shaper.
                "last_assistant_text": _archive_bound_assistant_text(tail_meta.get("last_assistant_text")),
                # Attention API: the soft-block detector + ?state= filter read
                # these terminal-vs-working signals. All already computed by
                # _extract_tail_meta above, so surfacing them is free (no extra
                # parse / no subprocess). Without them the cross-repo attention
                # feed can't tell a paused-for-question session from a working
                # one whose sub-agent is still running.
                "last_event_type": tail_meta.get("last_event_type"),
                "pending_tool": tail_meta.get("pending_tool"),
                "pending_file": tail_meta.get("pending_file"),
                "subagent_in_flight_count": tail_meta.get("subagent_in_flight_count", 0),
                # Workflow runs (Workflow tool) — only computed for sessions
                # the iterdir above proved own a subagents/workflows dir.
                # Rehydrate recomputes these per serve, so live status does
                # not depend on this build-time snapshot being fresh.
                "workflows": (
                    _session_workflow_runs(
                        _ARCHIVE_WORKFLOW_SESSION_DIRS.get(session_id),
                        session_id,
                        now=_now,
                    )
                    if session_id in _ARCHIVE_WORKFLOW_SESSION_DIRS else []
                ),
                "session_state": _parse_session_state(tail_meta.get("last_assistant_text")),
                "goal": tail_meta.get("goal") or "",
                "goal_status": tail_meta.get("goal_status") or "",
                "parent_session_id": parent_session_id,
                # Re-layered per cheap serve by _rehydrate_archive_cached_rows
                # too (same reason as parent_session_id above: a fresh full
                # build like this one needs its own copy so the enriched
                # /list variants — resolve_prs/resolve_worktrees/resolve_
                # effective, which rebuild from scratch here rather than
                # patching a cached snapshot — carry the field too.
                "spawned_via": _infer_session_spawned_via(
                    spawn_entry, sid=session_id,
                    markers=spawn_markers, spawn_registry_by_sid=spawn_registry_by_sid,
                ),
                "continued_from_session_id": _continued_from_session_id_from_text(first_message),
                # Context % badge — same fields as find_conversations so
                # archive rows can render sidebar usage without opening the
                # session pane.
                "model": model,
                # Transcript-first (see find_conversations). Re-layered per
                # serve by _rehydrate_archive_cached_rows, since the user can
                # repick effort long after this row was cached.
                "reasoning_effort": tail_meta.get("reasoning_effort") or _conv_row_reasoning_effort(
                    session_id, session_overrides, spawn_entry,
                ),
                "latest_input_tokens": latest_tok,
                "lifetime_tokens": tail_meta.get("lifetime_tokens") or 0,
                "cost_usd": tail_meta.get("cost_usd") or 0.0,
                "cost_breakdown_usd": tail_meta.get("cost_breakdown_usd") or {},
                "total_input_tokens": tail_meta.get("total_input_tokens") or 0,
                "total_cache_creation_tokens": tail_meta.get("total_cache_creation_tokens") or 0,
                "total_cache_read_tokens": tail_meta.get("total_cache_read_tokens") or 0,
                "total_output_tokens": tail_meta.get("total_output_tokens") or 0,
                "live_context_tokens": tail_meta.get("live_context_tokens") or 0,
                "live_context_limit": tail_meta.get("live_context_limit") or 0,
                "live_context_percent": tail_meta.get("live_context_percent") or 0,
                "context_limit": ctx_limit,
                **_token_optimizer_quality_for_session(session_id),
                # Sidecar overlay — only meaningful when is_live; cold
                # rows get safe defaults that suppress the live pill.
                **sidecar_fields,
            })

    # Incremental mode: rows for everything below (registry-only sessions,
    # non-Claude engines, remote) are carried over from the cached snapshot
    # by the merging caller; regenerating them here would replace rich cached
    # rows with partial ones. Overlays (pins, WT names, lanes) are reapplied
    # at serve time by _rehydrate_archive_cached_rows.
    if only_jsonl_paths is not None:
        if resolve_pr_states:
            _prime_pr_states(r.get("tail_pr_url") for r in out)
            for r in out:
                url = r.get("tail_pr_url")
                if url:
                    r["pr_state"] = _get_pr_state(url)
        _apply_pinned_conversation_fields(out, pinned_list)
        _apply_watchtower_worker_display_names(out)
        _apply_session_lane_overrides(out)
        _apply_spawn_markers(out)
        return out

    # Claude can have a live process registry entry before it has written
    # a project JSONL. Surface those registry-only sessions so UUID search
    # and active-session discovery do not silently miss them.
    try:
        for sid, meta in _load_session_registry().items():
            if sid in seen_session_ids:
                continue
            row = _live_registry_conversation_row(
                sid,
                meta,
                name_overrides=name_overrides,
                archived_set=archived_set,
                trashed_set=trashed_set,
                pinned_rank=pinned_rank,
                repo_pins=repo_pins,
                resolve_worktree_dirty=resolve_worktree_dirty,
            )
            if row:
                out.append(row)
                seen_session_ids.add(sid)
    except Exception:
        pass

    # Add Codex threads to the archive too. They live in ~/.codex/state_*.sqlite
    # instead of ~/.claude/projects, but the row shape below matches the archive
    # renderer's existing Claude session rows.
    try:
        out.extend(find_codex_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass

    # Add Gemini sessions to the archive too. They live in ~/.gemini/tmp/
    # and have their own JSON format, but find_gemini_conversations returns
    # rows compatible with the archive renderer.
    try:
        out.extend(find_gemini_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass

    # Add Cursor agent transcripts from ~/.cursor/projects.
    try:
        out.extend(find_cursor_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass

    # Add Antigravity sessions to the archive. Antigravity stores JSONL
    # transcripts under ~/.gemini/antigravity/brain/<uuid>/.
    try:
        out.extend(find_antigravity_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(find_kilo_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(find_opencode_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(find_aider_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(find_hermes_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(find_kimi_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    # Add Copilot CLI sessions to the archive. They live under ~/.copilot
    # (session-store.db + session-state/*/events.jsonl).
    try:
        out.extend(find_copilot_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    # Add Grok CLI sessions to the archive. They live under ~/.grok
    # (sessions/<encoded-cwd>/<uuid>/ dirs and/or grok.db).
    try:
        out.extend(find_grok_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    # Add Devin cloud sessions to the archive. They come from the Devin API
    # (DEVIN_API_KEY); no key or any API failure yields an empty list.
    try:
        out.extend(find_devin_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
        ))
    except Exception:
        pass
    # Add Devin CLI (local) sessions to the archive. They come from the
    # Devin CLI's SQLite DB (~/.local/share/devin/cli/sessions.db).
    try:
        out.extend(find_devin_cli_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
        ))
    except Exception:
        pass
    # Add VS Code Copilot Chat sessions to the archive. They live in VS
    # Code's user-data workspaceStorage/*/chatSessions stores (plus the
    # empty-window store under globalStorage).
    try:
        out.extend(find_copilotchat_conversations(
            include_old=True,
            repo_only=False,
            limit=limit_per_folder,
            resolve_pr_states=resolve_pr_states,
            resolve_worktree_dirty=resolve_worktree_dirty,
        ))
    except Exception:
        pass
    try:
        out.extend(_find_remote_sessions(limit=limit_per_folder))
    except Exception:
        pass

    if resolve_pr_states:
        # Parallel-resolve PR states for every row that recorded a PR URL.
        # Hits the in-process cache on warm refreshes; bounded thread pool
        # keeps the cold path under ~half a second even for hundreds of PRs.
        _prime_pr_states(r.get("tail_pr_url") for r in out)
        for r in out:
            url = r.get("tail_pr_url")
            if url:
                r["pr_state"] = _get_pr_state(url)
    # Live peer-registry overlay (bridge session id, Claude busy/idle status,
    # tmux/socket coordinates) — same layering as find_conversations.
    try:
        registry = _load_session_registry()
        for r in out:
            if r.get("engine") == "claude":
                r.update(_registry_row_overlay(registry.get(r.get("session_id"))))
    except Exception:
        pass
    _apply_pinned_conversation_fields(out, pinned_list)
    out.sort(key=lambda r: r["mtime"], reverse=True)
    _sort_pinned_conversations_first(out, pinned_list)
    # CCC-505: the cross-repo archive (this function) skipped the WT overlay
    # that find_all_sessions applies, so a dormant session whose display_name
    # was clipped at self-rename time (e.g. "CCC#496: ...sc…") never got the
    # unclipped rest attached — it just looked permanently truncated here.
    _apply_watchtower_worker_display_names(out)
    _apply_session_lane_overrides(out)
    _apply_spawn_markers(out)
    return out


# v7 persists the transcript stat map alongside cached rows. Detached refresh
# workers and restarted servers can then calculate a file-level delta instead
# of forgetting the previous signature's inputs and rebuilding every session.
_ARCHIVE_RESPONSE_CACHE_SCHEMA_VERSION = 7
_ARCHIVE_RESPONSE_CACHE_FILE = COMMAND_CENTER_STATE_DIR / "archive-conversations-cache.json"


def _archive_response_cache_build_id():
    """Identifies the row-shaping code version for the persisted archive cache.

    CCC-1031: this used to be a sha1 over (path, mtime, size) of server.py +
    every ccc_server/*.py, so ANY edit to those files - including an unrelated
    comment or a routine dev-session change in this actively-edited repo -
    busted the 22MB persisted cache and forced a ~100s cold rebuild on the
    next restart. Row-shaping changes big enough to need a rebuild already
    have an explicit, developer-maintained signal:
    _ARCHIVE_RESPONSE_CACHE_SCHEMA_VERSION (bumped in the same commit that
    changes what an entry looks like, see the v7 comment above). Key off that
    instead of source mtimes."""
    return str(_ARCHIVE_RESPONSE_CACHE_SCHEMA_VERSION)


_ARCHIVE_RESPONSE_CACHE_BUILD_ID = _archive_response_cache_build_id()
# The all-repos archive payload can be several MB on machines with years of
# agent history. Refreshing it every 30 seconds keeps the Python server in a
# near-permanent scan/JSON cycle and starves click-to-open requests. Keep the
# default conservative for freshness, but make it tunable for power users.
try:
    _ARCHIVE_RESPONSE_CACHE_FRESH_TTL = max(
        30.0,
        float(os.environ.get("CCC_ARCHIVE_CACHE_TTL_SEC", "300")),
    )
except ValueError:
    _ARCHIVE_RESPONSE_CACHE_FRESH_TTL = 300.0
_ARCHIVE_RESPONSE_CACHE_LOCK = threading.Lock()
_ARCHIVE_RESPONSE_CACHE_LOADED = False
_ARCHIVE_RESPONSE_CACHE = {}
_ARCHIVE_RESPONSE_REFRESHING = set()


def _archive_response_cache_key(
    *,
    include_prs=False,
    resolve_pr_states=False,
    resolve_effective=False,
    resolve_worktree_dirty=False,
):
    return (
        f"include_prs={int(bool(include_prs))};"
        f"resolve_prs={int(bool(resolve_pr_states))};"
        f"resolve_effective={int(bool(resolve_effective))};"
        f"resolve_worktrees={int(bool(resolve_worktree_dirty))}"
    )


def _load_archive_response_cache():
    global _ARCHIVE_RESPONSE_CACHE_LOADED
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        if _ARCHIVE_RESPONSE_CACHE_LOADED:
            return
        _ARCHIVE_RESPONSE_CACHE_LOADED = True
    try:
        with _ARCHIVE_RESPONSE_CACHE_FILE.open("r") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError, ValueError):
        return
    if not isinstance(data, dict):
        return
    if data.get("schema_version") != _ARCHIVE_RESPONSE_CACHE_SCHEMA_VERSION:
        return
    if data.get("build_id") != _ARCHIVE_RESPONSE_CACHE_BUILD_ID:
        return
    entries = data.get("entries")
    if not isinstance(entries, dict):
        return
    signature_maps = data.get("signature_maps")
    restored_signature_maps = {}
    if isinstance(signature_maps, dict):
        for signature, raw_map in signature_maps.items():
            if not isinstance(signature, str) or not isinstance(raw_map, dict):
                continue
            raw_files = raw_map.get("files")
            raw_extras = raw_map.get("extras")
            if not isinstance(raw_files, dict) or not isinstance(raw_extras, dict):
                continue
            files = {}
            for transcript_path, values in raw_files.items():
                if (
                    isinstance(transcript_path, str)
                    and isinstance(values, (list, tuple))
                    and len(values) == 2
                    and all(isinstance(value, (int, float)) for value in values)
                ):
                    files[transcript_path] = (int(values[0]), int(values[1]))
            extras = {
                extra_path: int(mtime)
                for extra_path, mtime in raw_extras.items()
                if isinstance(extra_path, str) and isinstance(mtime, (int, float))
            }
            restored_signature_maps[signature] = (files, extras)
    keep = {}
    for key, entry in entries.items():
        if not isinstance(key, str) or not isinstance(entry, dict):
            continue
        if not isinstance(entry.get("conversations"), list):
            continue
        keep[key] = {
            "cached_at": float(entry.get("cached_at") or 0),
            "conversations": entry.get("conversations") or [],
            "signature": entry.get("signature") or None,
        }
    if keep:
        with _ARCHIVE_RESPONSE_CACHE_LOCK:
            _ARCHIVE_RESPONSE_CACHE.update(keep)
        try:
            for _entry in keep.values():
                note_archive_build(_entry.get("cached_at"))  # perf_events warm/cold ledger
        except NameError:
            pass
    if restored_signature_maps:
        with _archive_sig_lock:
            _ARCHIVE_STATMAP_BY_SIG.update(restored_signature_maps)
            while len(_ARCHIVE_STATMAP_BY_SIG) > _ARCHIVE_STATMAP_MAX:
                _ARCHIVE_STATMAP_BY_SIG.pop(next(iter(_ARCHIVE_STATMAP_BY_SIG)))


_ARCHIVE_RESPONSE_CACHE_SAVE_MIN_INTERVAL_S = 30.0
_ARCHIVE_RESPONSE_CACHE_LAST_SAVE_AT = 0.0


def _save_archive_response_cache(force=False):
    """Persist the response cache, debounced: incremental archive merges call
    this per merge and the snapshot is ~17MB, so every live session used to
    cost a ~180ms disk write on the request thread. It's a rebuildable cache
    — losing ≤30s of merges to a crash only costs one rebuild."""
    global _ARCHIVE_RESPONSE_CACHE_LAST_SAVE_AT
    now = time.time()
    if not force and now - _ARCHIVE_RESPONSE_CACHE_LAST_SAVE_AT < _ARCHIVE_RESPONSE_CACHE_SAVE_MIN_INTERVAL_S:
        return
    _ARCHIVE_RESPONSE_CACHE_LAST_SAVE_AT = now
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        entries = dict(_ARCHIVE_RESPONSE_CACHE)
    referenced_signatures = {
        entry.get("signature")
        for entry in entries.values()
        if isinstance(entry, dict) and entry.get("signature")
    }
    with _archive_sig_lock:
        signature_maps = {
            signature: {
                "files": {
                    transcript_path: list(values)
                    for transcript_path, values in files.items()
                },
                "extras": dict(extras),
            }
            for signature, (files, extras) in _ARCHIVE_STATMAP_BY_SIG.items()
            if signature in referenced_signatures
        }
    snapshot = {
        "schema_version": _ARCHIVE_RESPONSE_CACHE_SCHEMA_VERSION,
        "build_id": _ARCHIVE_RESPONSE_CACHE_BUILD_ID,
        "entries": entries,
        "signature_maps": signature_maps,
    }
    try:
        _ARCHIVE_RESPONSE_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = _ARCHIVE_RESPONSE_CACHE_FILE.with_suffix(".json.tmp")
        with tmp.open("w") as f:
            json.dump(snapshot, f)
        tmp.replace(_ARCHIVE_RESPONSE_CACHE_FILE)
    except OSError as e:
        print(f"  [archive-cache] save failed: {e}")


def _archive_response_cache_get(key):
    _load_archive_response_cache()
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        entry = _ARCHIVE_RESPONSE_CACHE.get(key)
        if not entry:
            return None
        return {
            "cached_at": float(entry.get("cached_at") or 0),
            "conversations": [dict(r) for r in (entry.get("conversations") or []) if isinstance(r, dict)],
            "signature": entry.get("signature") or None,
        }


def _archive_response_cache_signature(key):
    """Signature of the persisted entry for `key`, without copying its rows
    (the full getter deep-copies every conversation dict — too heavy for a
    per-poll predicate)."""
    _load_archive_response_cache()
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        entry = _ARCHIVE_RESPONSE_CACHE.get(key)
        return (entry or {}).get("signature") or None


def _archive_response_cache_put(key, conversations, signature=None):
    rows = [dict(r) for r in (conversations or []) if isinstance(r, dict)]
    _put_ts = time.time()
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        _ARCHIVE_RESPONSE_CACHE[key] = {
            "cached_at": _put_ts,
            "conversations": rows,
            "signature": signature,
        }
    try:
        note_archive_build(_put_ts)  # perf_events warm/cold ledger
    except NameError:
        pass
    _save_archive_response_cache()


def _archive_response_cache_is_stale(entry):
    return (time.time() - float(entry.get("cached_at") or 0)) > _ARCHIVE_RESPONSE_CACHE_FRESH_TTL


def _archive_response_refreshing(key):
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        return key in _ARCHIVE_RESPONSE_REFRESHING


def _archive_response_refresh_begin(key):
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        if key in _ARCHIVE_RESPONSE_REFRESHING:
            return False
        _ARCHIVE_RESPONSE_REFRESHING.add(key)
        return True


def _archive_response_refresh_end(key):
    with _ARCHIVE_RESPONSE_CACHE_LOCK:
        _ARCHIVE_RESPONSE_REFRESHING.discard(key)


# Cross-key build lock. The ?all=1 endpoints use different cache keys for the
# plain sidebar and PR/worktree-enriched rows, but both parse the same transcript
# corpus. Per-key locks still allowed those variants to rebuild concurrently;
# native sampling caught two _archive_serve_refresh threads saturating one core
# while each retained its own thousands-row working set. Serialize the GIL-bound
# build/rehydrate phase across variants. Requests still serve stale snapshots
# immediately while the one background owner refreshes.
_ARCHIVE_BUILD_LOCKS = {}
_ARCHIVE_BUILD_GLOBAL_LOCK = threading.Lock()


def _archive_build_lock(key):
    return _ARCHIVE_BUILD_GLOBAL_LOCK


# TTL-memoized wrapper around the corpus fingerprint. The fingerprint is a
# stat-only walk of the WHOLE transcript corpus (thousands of files), but it is
# GLOBAL — identical for every archive cache key. Without memoization each
# cache key's background refresh (dashboard + COO board + every filter/sort
# combo poll distinct keys) re-walked the entire corpus independently, so N
# concurrently-refreshing keys meant N full-corpus scandir passes every serve
# TTL. That O(keys × all-files) scandir per window is the sustained CPU burn
# `sample` caught across the `refresh` threads. Caching the signature for a
# short window collapses it to ONE walk per window shared by all keys. The TTL
# stays within the serve cache's existing staleness tolerance, so it introduces
# no correctness window the serve path didn't already have.
try:
    _ARCHIVE_SIG_TTL = max(0.0, float(os.environ.get("CCC_ARCHIVE_SIG_TTL_SEC", "2")))
except ValueError:
    _ARCHIVE_SIG_TTL = 2.0
_archive_sig_cache = {"ts": 0.0, "sig": None}
_archive_sig_lock = threading.Lock()

# Per-signature stat maps, retained from the signature walk (which already
# stats every transcript — this just stops discarding the result). Keyed by
# the signature hash, value is ({jsonl_path: (mtime_ns, size)}, {extra: mtime}).
# Two remembered signatures ⇒ an exact file-level diff of what changed between
# them, which is what lets _archive_compute_rows re-parse ONLY the touched
# transcripts instead of rebuilding all ~1000+ rows on every corpus change.
# Small LRU: entries are ~100KB each; live corpora produce a new signature
# every few seconds and only the cached response entries' signatures matter.
_ARCHIVE_STATMAP_BY_SIG = {}
_ARCHIVE_STATMAP_MAX = 16
# A delta larger than this falls back to the full rebuild — the incremental
# path exists for the steady-state "a handful of sessions wrote" case, not to
# re-implement the builder for bulk changes (restores, migrations, first run).
try:
    _ARCHIVE_INCR_MAX_FILES = max(0, int(os.environ.get("CCC_ARCHIVE_INCR_MAX_FILES", "200")))
except ValueError:
    _ARCHIVE_INCR_MAX_FILES = 200


def _archive_bound_assistant_text(text, head=700, tail=700):
    """Bound last_assistant_text on archive rows. The UI never renders more
    than the first 700 chars and the soft-block detector only scores the
    last 700 — shipping the full multi-KB body was ~43% of the archive
    payload and per-row regex/split CPU on every rehydrate. session_state
    was already computed from the full text upstream."""
    text = text or ""
    if len(text) <= head + tail + 3:
        return text
    return text[:head] + "..." + text[-tail:]


def _archive_corpus_signature():
    """Corpus fingerprint, memoized for _ARCHIVE_SIG_TTL so concurrent per-key
    refreshes share one full-corpus walk instead of each re-scanning it."""
    if _ARCHIVE_SIG_TTL > 0:
        now = time.time()
        with _archive_sig_lock:
            c = _archive_sig_cache
            if c["sig"] is not None and (now - c["ts"]) < _ARCHIVE_SIG_TTL:
                return c["sig"]
    sig, files, extras = _archive_corpus_signature_parts()
    with _archive_sig_lock:
        if _ARCHIVE_SIG_TTL > 0:
            _archive_sig_cache["ts"] = time.time()
            _archive_sig_cache["sig"] = sig
        _ARCHIVE_STATMAP_BY_SIG.pop(sig, None)
        _ARCHIVE_STATMAP_BY_SIG[sig] = (files, extras)
        while len(_ARCHIVE_STATMAP_BY_SIG) > _ARCHIVE_STATMAP_MAX:
            _ARCHIVE_STATMAP_BY_SIG.pop(next(iter(_ARCHIVE_STATMAP_BY_SIG)))
    return sig


def _archive_signature_delta(old_sig, new_sig):
    """File-level diff between two remembered corpus signatures.

    Returns (changed_paths, removed_paths, refresh_engines) — changed covers
    added AND edited Claude transcripts, refresh_engines names non-Claude
    engines whose rows must be rebuilt and merged engine-wide — or None when
    a full rebuild is required: unknown signature (restart, LRU eviction), a
    non-Claude engine source changed that we cannot rebuild in isolation
    (those are dir-granularity in the signature, so no file diff exists), or
    the delta is too large to be worth the incremental path.

    Hermes is the one engine source with an isolated refresh path: its
    state.db mtime flips per internal event, and treating that like the
    dir-granular sources forced a full O(all-rows) rebuild on every poll
    while a hermes session ran (measured 60-95s burns). Rebuilding hermes
    rows alone is milliseconds.
    """
    if not old_sig or not new_sig or old_sig == new_sig:
        return None
    with _archive_sig_lock:
        old = _ARCHIVE_STATMAP_BY_SIG.get(old_sig)
        new = _ARCHIVE_STATMAP_BY_SIG.get(new_sig)
    if not old or not new:
        return None
    old_files, old_extras = old
    new_files, new_extras = new
    refresh_engines = set()
    if old_extras != new_extras:
        changed_extras = {
            k for k in set(old_extras) | set(new_extras)
            if old_extras.get(k) != new_extras.get(k)
        }
        isolated = set()
        if changed_extras & {_ARCHIVE_HERMES_EXTRA_KEY}:
            isolated.add(_ARCHIVE_HERMES_EXTRA_KEY)
            refresh_engines.add("hermes")
        # Codex gets the same isolated treatment, for the same reason. A newly
        # spawned Codex thread only ever shows up as a day-dir mtime bump (its
        # rollouts are date-nested), which is dir-granular and so used to force
        # the full-rebuild path -- meaning the new session could not appear
        # until a background O(all-rows) rebuild finished and a later poll
        # picked it up. Measured: 49.6s from spawn to the row existing in a
        # built list. Rebuilding codex rows alone is ~0.2s warm.
        codex_keys = changed_extras & _archive_codex_extra_keys()
        if codex_keys:
            isolated |= codex_keys
            refresh_engines.add("codex")
        if changed_extras - isolated:
            return None
    changed = [p for p, st in new_files.items() if old_files.get(p) != st]
    removed = [p for p in old_files if p not in new_files]
    if not changed and not removed and not refresh_engines:
        return None
    if _ARCHIVE_INCR_MAX_FILES <= 0 or len(changed) > _ARCHIVE_INCR_MAX_FILES:
        return None
    return changed, removed, refresh_engines


def _archive_merge_engine_rows(cached_rows, engine, fresh_rows):
    """Replace one engine's whole row set in the cached rows (engine-scoped
    refresh). Unlike _archive_merge_incremental_rows — which patches by
    session id — this also drops that engine's vanished sessions, and leaves
    every other engine's rows byte-identical."""
    kept = [
        r for r in cached_rows or []
        if str((r or {}).get("engine") or (r or {}).get("source") or "") != engine
    ]
    kept.extend(fresh_rows or [])
    return kept


def _archive_merge_incremental_rows(cached_rows, fresh_rows, removed_paths):
    """Merge freshly-built rows for changed transcripts into the cached row
    set: replace by session id (falling back to jsonl path), drop rows whose
    transcript was removed, append genuinely new sessions. Ordering is not
    this function's job — _rehydrate_archive_cached_rows re-sorts by mtime
    and re-applies pinned-first on every serve.
    """
    removed = set(removed_paths or [])
    fresh_by_key = {}
    for r in fresh_rows or []:
        if not isinstance(r, dict):
            continue
        k = r.get("session_id") or r.get("id") or r.get("jsonl_path")
        if k:
            fresh_by_key[k] = r
    out = []
    for raw in cached_rows or []:
        if not isinstance(raw, dict):
            continue
        jp = raw.get("jsonl_path")
        if jp and jp in removed:
            continue
        k = raw.get("session_id") or raw.get("id") or jp
        if k and k in fresh_by_key:
            out.append(fresh_by_key.pop(k))
            continue
        out.append(raw)
    out.extend(fresh_by_key.values())
    return out


def _archive_corpus_signature_uncached():
    """Signature hash only — see _archive_corpus_signature_parts."""
    return _archive_corpus_signature_parts()[0]


def _archive_canonical_project_dirs(projects_root):
    """Return each physical Claude project directory once, in stable order.

    `~/.claude/projects` may contain convenience symlinks. Walking both a
    symlink and its target doubles a large archive's stat/parsing work while
    contributing no distinct sessions, so canonicalize the top-level dirs
    before either archive path scans their JSONL files.
    """
    try:
        candidates = sorted(e.path for e in os.scandir(projects_root) if e.is_dir())
    except OSError:
        return []
    out = []
    seen = set()
    for candidate in candidates:
        try:
            directory = Path(candidate).resolve()
        except (OSError, RuntimeError):
            continue
        if _is_scratch_project_dir(directory):
            continue
        key = str(directory)
        if key in seen or not directory.is_dir():
            continue
        seen.add(key)
        out.append(directory)
    return out


# The hermes gateway DB is signature-gated at FILE granularity (its mtime
# flips per event) — see _archive_signature_delta, which converts hermes-only
# churn into an engine-scoped row refresh instead of a full rebuild.
_ARCHIVE_HERMES_EXTRA_PATH = Path.home() / ".hermes" / "state.db"
_ARCHIVE_HERMES_EXTRA_KEY = str(_ARCHIVE_HERMES_EXTRA_PATH)


def _archive_codex_extra_keys():
    """Signature-extra keys that a new/updated Codex thread can move.

    Must stay in lockstep with what _archive_corpus_signature_parts folds in
    for Codex, or a codex-only delta silently falls back to a full rebuild.
    """
    keys = {str(Path.home() / ".codex" / "sessions")}
    keys.update(str(p) for p in _codex_rollout_day_dirs())
    return keys


def _codex_rollout_day_dirs():
    """Date-nested Codex rollout dirs whose mtime marks a NEW thread.

    Codex writes one rollout JSONL per thread into
    ~/.codex/sessions/YYYY/MM/DD, so the store root only changes at year
    rollover and is useless as a change signal (observed 50 days stale on a
    reporting user's machine). The day directory is the right granularity:
    adding a thread creates a file in it (dir mtime moves), while an existing
    transcript growing does not. Yesterday is included so a session started
    just before midnight still invalidates the cache.
    """
    root = Path.home() / ".codex" / "sessions"
    now = time.time()
    return [
        root / time.strftime("%Y/%m/%d", time.localtime(now - offset))
        for offset in (0, 86400)
    ]


def _archive_antigravity_extra_paths():
    """Antigravity brain dirs whose mtime marks a session lifecycle event.

    Two gaps made headless agy sessions invisible to the archive signature.
    First, only the desktop app's store (~/.gemini/antigravity/brain) was
    covered; the CLI store (~/.gemini/antigravity-cli/brain), where every
    headless `agy -p` session lives, produced no invalidation signal at all.
    Second, the store ROOT's mtime only flips when a session dir is added or
    removed — the transcript a row is built from materializes later, when
    brain/<sid>/.system_generated/ is created (minutes into a run; observed
    10+ min while the desktop language server was busy), which bumps only the
    session dir's mtime. Folding in each session dir catches both events with
    stat-only cost, same shape as the codex day-dirs above.
    """
    paths = []
    for root in (ANTIGRAVITY_BRAIN, ANTIGRAVITY_CLI_BRAIN):
        paths.append(root)
        try:
            with os.scandir(root) as it:
                for entry in it:
                    try:
                        if entry.is_dir(follow_symlinks=False):
                            paths.append(Path(entry.path))
                    except OSError:
                        continue
        except OSError:
            continue
    return paths


def _archive_corpus_signature_parts():
    """Cheap stat-only fingerprint of the conversation corpus on disk.

    No JSON parse, no subprocess, no per-row liveness probe — just the
    (mtime_ns, size) of every Claude transcript plus the mtime of the engine
    transcript roots and CCC state dirs that feed archive rows. Two identical
    signatures ⇒ nothing the archive build reads has changed, so the persisted
    response payload can be served as-is without an O(all-sessions) rebuild.

    A new/edited/removed transcript flips a file's mtime (and the dir mtime),
    so the signature changes and the cache invalidates immediately — no TTL
    staleness window for the dominant Claude corpus. Engine sources beyond
    ~/.claude/projects are covered at directory granularity (their root mtime
    changes when sessions are added/removed); in-place edits there fall back to
    the build cache's own (mtime,size) gating on the next signature change.

    Deliberately EXCLUDES fast-changing live state (sidecar markers, the spawned
    registry): those mutate on every poll while a session is live, so folding
    them in would bust the build cache constantly and pin the CPU. Live state is
    not part of the expensive build — it is layered back on by
    _rehydrate_archive_cached_rows and coalesced by the serve cache, so it does
    not need to gate the transcript-parse cache.
    """
    parts = []
    files = {}
    extras_map = {}
    projects_root = Path.home() / ".claude" / "projects"
    for directory in _archive_canonical_project_dirs(projects_root):
        try:
            with os.scandir(directory) as it:
                for e in it:
                    if not e.name.endswith(".jsonl"):
                        continue
                    try:
                        st = e.stat()
                    except OSError:
                        continue
                    parts.append(f"{e.path}|{st.st_mtime_ns}|{st.st_size}")
                    files[e.path] = (st.st_mtime_ns, st.st_size)
        except OSError:
            continue
    # Fold in dir-level mtimes of sibling engine transcript stores so adds /
    # removes / renames there also bust the cache. stat() only — cheap. These
    # are transcript corpora (not live state), so they are safe to gate on.
    for extra in [
        # Year-rollover granularity only -- kept so a brand-new ~/.codex tree
        # registers, but it CANNOT see new threads on its own: Codex nests
        # rollouts by date, so _codex_rollout_day_dirs() below is what actually
        # detects a session being added.
        Path.home() / ".codex" / "sessions",
        *_codex_rollout_day_dirs(),
        Path.home() / ".cursor" / "projects",
        # Antigravity, both stores: the desktop app's brain AND the CLI brain
        # (where headless `agy -p` sessions live), plus each session dir so a
        # transcript materializing mid-run invalidates the cache too.
        *_archive_antigravity_extra_paths(),
        _ARCHIVE_HERMES_EXTRA_PATH,
        # Kimi sessions dir — NOT session_index.jsonl: that file's mtime
        # flips on per-turn updates, which forced a full O(all-rows) archive
        # rebuild every poll while a kimi session ran. The dir mtime only
        # changes when sessions are added/removed, which is exactly the
        # granularity the archive needs.
        _kimi_code_home() / "sessions",
        _ACP_TRANSCRIPT_DIR / "kimi",
        _copilot_home() / "session-state",
        _grok_home() / "sessions",
        _grok_home() / "grok.db",
        # Devin cloud has no local store; its on-disk API cache file only
        # rewrites when the session list actually changes, so its mtime is
        # exactly the add/remove signal the archive needs.
        _devin_sessions_cache_path(),
        # Devin CLI: NOT sessions.db / its WAL (both flip on every streamed
        # token, which would force a full archive rebuild per poll while a
        # session runs). The CLI creates one lock file per session at start
        # and removes it at exit, so the lock dir's mtime is the add/remove
        # signal. Without this a freshly spawned Devin CLI session only
        # landed in the sidebar when some OTHER engine's corpus happened to
        # change.
        DEVIN_CLI_LOCKS_DIR,
    ]:
        try:
            mt = os.stat(extra).st_mtime_ns
        except OSError:
            continue
        parts.append(f"{extra}|{mt}")
        extras_map[str(extra)] = mt
    # VS Code Copilot Chat stores: one chatSessions dir per workspace plus
    # each app's empty-window store. Dir mtimes flip on session add/remove,
    # which is exactly the granularity the archive needs.
    for chat_dir in _copilotchat_chat_dirs():
        try:
            mt = os.stat(chat_dir).st_mtime_ns
        except OSError:
            continue
        parts.append(f"{chat_dir}|{mt}")
        extras_map[str(chat_dir)] = mt
    parts.sort()
    h = hashlib.sha1()
    for p in parts:
        h.update(p.encode("utf-8", "replace"))
        h.update(b"\n")
    h.update(str(len(parts)).encode())
    return h.hexdigest(), files, extras_map


# Short-TTL coalescing cache for the fully-rehydrated ?all=1 payload. The
# dashboard AND the COO board both poll these endpoints; without coalescing,
# every concurrent poll re-ran _rehydrate_archive_cached_rows — whose dominant
# cost is the per-live-session _archive_session_is_live probe (engine
# classification scans, ~25ms each). Under real polling those probes serialized
# on the GIL and held the endpoint at 1-2s + a sustained CPU burn. Same fix and
# rationale as _live_activity_snapshot's 1.5s window: serve one ≤TTL-old
# rehydrated snapshot to all concurrent callers. Transcript-derived fields
# (state / ended_blocked / question from JSONL) are signature-gated and stay
# fresh on any real change; only process-liveness/sidecar lag, by ≤TTL. Live
# activity has its own lightweight overlay, so aligning full-row refreshes with
# the existing five-minute persisted-cache TTL avoids continuous work on large,
# actively-written corpora without delaying working/waiting indicators.
try:
    _ARCHIVE_SERVE_TTL = max(0.0, float(os.environ.get("CCC_ARCHIVE_SERVE_TTL_SEC", "300")))
except ValueError:
    _ARCHIVE_SERVE_TTL = 300.0
_archive_serve_cache = {}      # key -> {"ts", "rows", "ver"} (+ optional prebuilt body)
_archive_serve_lock = threading.Lock()
_archive_serve_refreshing = {}  # key -> start-time epoch, for in-flight background refreshes
_archive_serve_generation = 0
_archive_serve_version = 0       # monotonic per store; tags prebuilt response bodies

# Prebuilt response bodies for /api/conversations/list, keyed by
# (archive cache key, window, from_cache, body version). The list path serves
# the shared serve-snapshot row list (copy_rows=False) whenever no in-memory
# overlay appended rows, so for a given snapshot version + window the projected
# payload is byte-identical across the N tabs polling it — previously each
# poll paid json.dumps + sha1 + gzip over the whole payload (13 MB for
# window=all on large archives). Validity is by snapshot version, verified
# per request: bare version when rows ARE the stored snapshot (identity),
# or (version, overlay content hash) when ACP/Devin overlay rows were
# appended — _archive_list_body_ver — so a snapshot swap or any overlay
# content change always misses and rebuilds.
_ARCHIVE_LIST_BODY_CACHE = {}  # (cache_key, window, from_cache) -> {"ver", "raw", "gzip", "etag"}
_ARCHIVE_LIST_BODY_LOCK = threading.Lock()
_ARCHIVE_LIST_BODY_CACHE_MAX = 24


def _archive_refresh_slot_available(key, now):
    """True if `key` has no background refresh in flight, or the one it has
    has been running past _ARCHIVE_REFRESH_WATCHDOG_S -- treated as abandoned
    so a new attempt gets spawned instead of trusting the flag forever. Must
    be called with _archive_serve_lock already held (same lock guards
    _archive_serve_refreshing everywhere else)."""
    started = _archive_serve_refreshing.get(key)
    return started is None or (now - started) > _ARCHIVE_REFRESH_WATCHDOG_S


def _archive_serve_cache_store(key, rows, generation, ts=None):
    """Store rows only if no lifecycle mutation invalidated their build.

    `ts` defaults to now (a genuine fresh build). The cold-restart path
    passes the persisted entry's own build time instead -- stamping a
    known-stale snapshot with "now" bought it a free 300s TTL grace window
    on every restart, on top of however stale it already was, which is
    exactly backwards: a restart should make a stale snapshot MORE eligible
    for an immediate refresh, not less.
    """
    global _archive_serve_version
    with _archive_serve_lock:
        if generation != _archive_serve_generation:
            return False
        _archive_serve_version += 1
        _archive_serve_cache[key] = {
            "ts": ts if ts is not None else time.time(),
            "rows": rows, "ver": _archive_serve_version,
        }
        return True


def _archive_serve_ver_for_rows(key, rows):
    """The serve entry's version IFF it currently holds exactly this row list
    (identity) — 0 otherwise. Body prebuilding keys off this so a response
    body can never be cached against rows it wasn't serialized from."""
    with _archive_serve_lock:
        sc = _archive_serve_cache.get(key)
        if sc is not None and sc.get("rows") is rows:
            return sc.get("ver", 0)
    return 0


def _clear_archive_serve_cache():
    global _archive_serve_generation
    with _archive_serve_lock:
        _archive_serve_cache.clear()
        _archive_serve_generation += 1


def _restamp_archive_serve_cache_after_mutation():
    """Keep first paint correct after archive/trash/lane state changes.

    These mutations used to clear the warm serve cache outright. The next
    poll then fell back to the persisted (pre-mutation) response cache, where
    lifecycle flags can be overlaid but lane assignments cannot, leaving the
    conversation list visibly stale until a detached rebuild completed. Keep
    the newest in-memory rows instead, apply the cheap sidecar-backed fields,
    and age the snapshot so the next poll starts that rebuild off-thread.

    Advancing the generation still prevents an older detached refresh from
    publishing rows it built before the mutation. Response bodies are
    intentionally discarded by creating fresh snapshot entries.
    """
    global _archive_serve_generation, _archive_serve_version
    with _archive_serve_lock:
        # Read the mutation sidecars while holding the publication lock. A
        # concurrent mutation that starts earlier but waits longer must not
        # publish its now-obsolete view after a newer mutation has restamped
        # the snapshot.
        try:
            archived_set, trashed_set = _load_conversation_lifecycle_sets()
        except Exception:
            archived_set, trashed_set = set(), set()
        try:
            lane_overrides = _load_session_lane_overrides()
        except Exception:
            lane_overrides = {}
        _archive_serve_generation += 1
        refreshed = {}
        for key, entry in _archive_serve_cache.items():
            rows = []
            for original in entry.get("rows") or []:
                if not isinstance(original, dict):
                    continue
                row = dict(original)
                sid = row.get("session_id") or row.get("id")
                if sid:
                    row["archived"] = sid in archived_set
                    row["trashed"] = sid in trashed_set
                    row["all_lane_override"] = lane_overrides.get(str(sid), "")
                rows.append(row)
            _archive_serve_version += 1
            refreshed[key] = {
                "ts": 0.0,
                "rows": rows,
                "ver": _archive_serve_version,
            }
        _archive_serve_cache.clear()
        _archive_serve_cache.update(refreshed)
        # Existing workers are for the previous generation. Their finally
        # blocks only remove their own timestamp, so clearing these slots lets
        # the next poll queue a current-generation detached refresh at once.
        _archive_serve_refreshing.clear()


# Coalescing cache for the spawned-session list on the ?all=1 hot path.
# list_spawned_sessions() runs best-effort desktop-visibility/registry side
# effects per spawned entry (_spawn_session_id_from_entry), so a box with a
# dozen+ spawned agents spends ~1-2s in it — per request, uncoalesced. After the
# archive build was cached this became the dominant cost of /api/{sessions,
# conversations}?all=1, which the dashboard AND COO board poll. Coalesce it on
# the same short window as the serve cache: the side effects still fire (at most
# once per window) and concurrent polls share one result.
_archive_spawned_cache = {"ts": 0.0, "data": None}
_archive_spawned_lock = threading.Lock()
_archive_spawned_refreshing = False


def _archive_spawned_refresh():
    global _archive_spawned_refreshing
    try:
        data = list_spawned_sessions()
        with _archive_spawned_lock:
            _archive_spawned_cache["ts"] = time.time()
            _archive_spawned_cache["data"] = data
    except Exception as e:
        print(f"  [spawned-cache] refresh failed: {e}")
    finally:
        with _archive_spawned_lock:
            _archive_spawned_refreshing = False


def _archive_spawned_coalesced():
    """Spawned-session list for the ?all=1 hot path, stale-while-revalidate.

    list_spawned_sessions() costs ~1-2s on a box with a dozen+ spawned agents
    (best-effort desktop-visibility side effects per entry), so blocking the
    request on it — even coalesced — leaves one unlucky poll per window stalled.
    Instead: serve the last known list immediately and refresh in the background
    when it goes stale. The request path never pays the cost (after a one-time
    cold build); the side effects run off-thread; staleness is ≤ the serve TTL
    plus one refresh. Spawned sessions appear/finish slowly, so this is safe.
    """
    global _archive_spawned_refreshing
    if _ARCHIVE_SERVE_TTL <= 0:
        return list_spawned_sessions()
    start_refresh = False
    with _archive_spawned_lock:
        data = _archive_spawned_cache["data"]
        age = time.time() - _archive_spawned_cache["ts"]
        if data is None:
            # A cold spawned-session scan can be the slowest part of all=1:
            # each retained spawn may need process and transcript discovery.
            # Serve an empty snapshot for this first poll and populate the
            # cache off-thread; the next poll receives the full list.
            if not _archive_spawned_refreshing:
                _archive_spawned_refreshing = True
                start_refresh = True
        else:
            if age >= _ARCHIVE_SERVE_TTL and not _archive_spawned_refreshing:
                _archive_spawned_refreshing = True
                threading.Thread(target=_archive_spawned_refresh, daemon=True).start()
            return [dict(r) for r in data]
    if not start_refresh:
        return []
    refresh_thread = threading.Thread(target=_archive_spawned_refresh, daemon=True)
    refresh_thread.start()
    # Preserve the prior first-response shape when discovery is genuinely
    # cheap, without letting a slow registry/transcript walk own the request.
    refresh_thread.join(timeout=0.05)
    with _archive_spawned_lock:
        data = _archive_spawned_cache["data"]
    return [dict(r) for r in (data or [])]


def _archive_all_rows_cached(cache_options):
    """Archive rows for an ?all=1 request, served from the persisted response
    cache when the on-disk corpus is unchanged.

    Three tiers, cheapest first:
      1. Coalescing serve cache: a fully-rehydrated snapshot ≤_ARCHIVE_SERVE_TTL
         old for the same corpus signature → return a copy immediately, so
         concurrent dashboard/COO polls share one rehydrate instead of each
         re-probing liveness.
      2. Signature-matched response cache: rehydrate the persisted rows (cheap —
         refresh only fast-changing live/sidecar/name/pin state, same transform
         /api/conversations/all's stale-serve uses) with NO O(all-sessions)
         rebuild.
      3. Miss / changed corpus: rebuild once under a per-key lock so concurrent
         pollers don't stampede the CPU (the bug that wedged the server),
         persist with the new signature, return raw build rows (identical shape
         to today's direct-build response).

    Returns (rows, from_cache: bool). from_cache is False only when tier 3 ran.
    """
    key = _archive_response_cache_key(**cache_options)
    return _archive_serve_rows(key, cache_options)


