def _archive_list_window(value):
    value = (value or "all").strip().lower()
    return value if value in ("8h", "1d", "7d", "all") else "all"


def _archive_list_window_cutoff(window, now=None):
    # "8h" is the "Now" window — the current working shift, not a calendar day.
    seconds = {"8h": 8 * 3600, "1d": 86400, "7d": 7 * 86400}.get(_archive_list_window(window))
    return (time.time() if now is None else now) - seconds if seconds else None


def _archive_list_row_ts(row):
    for key in ("modified", "mtime", "last_interacted", "last_activity", "last_mtime",
                "archived_at", "closed_at", "started_at"):
        try:
            ts = float((row or {}).get(key) or 0)
        except (TypeError, ValueError):
            continue
        if math.isfinite(ts) and ts > 0:
            return ts / 1000 if ts > 100000000000 else ts
    return 0


def _archive_list_window_allows_row(row, cutoff):
    if not cutoff:
        return True
    engine = ((row or {}).get("engine") or (row or {}).get("source") or "").lower()
    return bool((row or {}).get("pinned")) or engine == "hermes" or _archive_list_row_ts(row) >= cutoff


def _archive_list_project_row(row):
    out = {key: copy.deepcopy(row[key]) for key in _ARCHIVE_LIST_FIELDS if key in row}
    # CCC-863: cheap in-memory lookup (no file I/O) -- surfaces the live
    # countdown for a session parked on a usage-limit auto-resume.
    sid = row.get("session_id") or row.get("id")
    if sid:
        resume_at = usage_limit_resume_at_for_session(sid)
        if resume_at:
            out["usage_limit_resume_at"] = resume_at
    return out


def _archive_list_project_rows(rows, *, window="all", now=None):
    cutoff = _archive_list_window_cutoff(window, now=now)
    return [
        _archive_list_project_row(row) for row in (rows or [])
        if isinstance(row, dict) and _archive_list_window_allows_row(row, cutoff)
    ]


def _archive_list_rows_cached(cache_options, *, window="all", now=None):
    rows, from_cache = _archive_all_rows_cached(cache_options)
    return _archive_list_project_rows(rows, window=window, now=now), from_cache


def _archive_list_source_rows_cached(cache_options, *, force_refresh=False):
    """Read-only full snapshot feeding the projected sidebar list.

    The list response immediately projects a small 1d/7d window into fresh
    dictionaries, so copying all historical rows first is pure allocator churn.
    Normal polls do not need a synchronous stale refresh: live chips come from
    the separate live-activity overlay, while a single background refresh
    updates transcript-derived fields for the next list poll. Explicit
    stale_ok=0 requests schedule freshness after a mutation or new-session
    landing without making the HTTP request wait for the archive scan.
    """
    key = _archive_response_cache_key(**cache_options)
    rows, from_cache, _snap_ver = _archive_serve_rows_versioned(
        key,
        cache_options,
        copy_rows=False,
        force_refresh=force_refresh,
    )
    # ACP sessions (Kimi/GLM) live in memory before their first transcript
    # lands and before the archive background refresh picks them up. Without
    # this overlay, a brand-new ACP session appears in the UI via the pending
    # spawn card, then vanishes on the next /api/conversations/list poll
    # because the cached snapshot has not refreshed yet, then reappears ~30s
    # later when the refresh completes. Merge in-memory attached sessions
    # cheaply so the sidebar never drops them in that window.
    overlay = _archive_overlay_acp_sessions(rows)
    if overlay:
        rows = list(rows or []) + overlay
    # Same gap for Devin CLI: the session row exists in sessions.db within a
    # second of spawn, but the archive snapshot only picks it up after the
    # next full background rebuild (~20s+ on a large corpus). The Devin CLI
    # list is memoized per session, so asking it here costs a few stat()s on
    # a cached poll and ~0.1s when the DB changed.
    devin_overlay = _archive_overlay_devin_cli_sessions(rows)
    if devin_overlay:
        rows = list(rows or []) + devin_overlay
    extra = (overlay or []) + (devin_overlay or [])
    return rows, from_cache, _archive_list_body_ver(key, rows, extra)


def _archive_list_body_ver(key, rows, extra):
    """Body-cache version for the /list payload.

    Without overlay rows the payload is a pure projection of the stored
    serve snapshot, so the snapshot's own version suffices (an identity
    check). With overlays appended the row list is rebuilt per request and
    the identity check always misses -- which forced json.dumps + sha1 +
    gzip over the ~12MB payload on EVERY poll whenever an ACP/Devin session
    was attached (permanent on an always-on agent box, and GIL-bound work
    in the request thread). The overlay list is only a handful of rows, so
    serializing just those and folding a content hash into the version
    restores body replay without serving stale overlay bytes: any overlay
    row content change changes the version.
    """
    with _archive_serve_lock:
        sc = _archive_serve_cache.get(key)
        if sc is None:
            return 0
        base = sc.get("rows") or []
        ver = sc.get("ver", 0)
        if rows is base:
            return ver
        if not extra or len(rows) != len(base) + len(extra):
            return 0
        if any(a is not b for a, b in zip(rows, base)):
            return 0
        sig = hashlib.sha1(
            json.dumps(extra, sort_keys=True, separators=(",", ":"), default=str).encode()
        ).hexdigest()
        return (ver, sig)


# A Devin CLI row missing from the snapshot is overlaid only while it is
# plausibly "just spawned": live, or modified within this window. Older rows
# absent from the snapshot were dropped on purpose (per-folder limits).
_ARCHIVE_DEVIN_OVERLAY_WINDOW_S = 15 * 60


def _archive_overlay_devin_cli_sessions(rows, now=None):
    """Archive-shaped Devin CLI rows that are live or recent but missing from
    the cached snapshot. Rows come from the same producer that feeds the
    archive build, so their shape is identical."""
    try:
        if not _devin_cli_db_path().is_file():
            return []
    except OSError:
        return []
    existing = set()
    for r in (rows or []):
        sid = r.get("session_id") or r.get("id")
        if sid:
            existing.add(str(sid))
    try:
        # Never block /list (and therefore trash POSTs queued behind it) on a
        # multi-second Devin CLI sessions.db rebuild. Serve cache/stale rows;
        # a cold miss with the rebuild lock held returns [].
        devin_rows = find_devin_cli_conversations(
            include_old=True, repo_only=False, stale_ok=True,
        )
    except Exception:
        return []
    now = time.time() if now is None else now
    cutoff = now - _ARCHIVE_DEVIN_OVERLAY_WINDOW_S
    out = []
    for r in devin_rows:
        sid = str(r.get("session_id") or r.get("id") or "")
        if not sid or sid in existing:
            continue
        if not (r.get("is_live") or float(r.get("modified") or 0) >= cutoff):
            continue
        out.append(r)
    return out


def _archive_overlay_acp_sessions(rows):
    """Return archive-shaped rows for ACP sessions live in memory but missing
    from the cached archive snapshot. Called by the lightweight /list path so
    new Kimi/GLM sessions stay visible between creation and the next archive
    refresh."""
    if not _ACP_HARNESSES:
        return []
    try:
        spawn_markers = _load_spawn_markers()
    except Exception:
        spawn_markers = {}
    existing = set()
    for r in (rows or []):
        sid = r.get("session_id") or r.get("id")
        if sid:
            existing.add(str(sid))
    try:
        name_overrides = _load_session_name_overrides()
    except Exception:
        name_overrides = {}
    try:
        archived_set, trashed_set = _load_conversation_lifecycle_sets()
    except Exception:
        archived_set, trashed_set = set(), set()
    try:
        pinned_list = _load_pinned_conversations()
    except Exception:
        pinned_list = []
    pinned_rank = _pinned_rank_map(pinned_list)
    out = []
    now = time.time()
    for harness in _ACP_HARNESSES:
        if not _acp_harness_enabled(harness):
            continue
        with _ACP_LOCK:
            sessions = dict(_ACP_SESSION_STATE.get(harness) or {})
        if not sessions:
            continue
        label = (_ACP_HARNESSES.get(harness) or {}).get("label", harness)
        for sid, state in sessions.items():
            sid = str(sid)
            if not sid or sid in existing:
                continue
            if not (state and state.get("attached")):
                continue
            status = str((state.get("status") or "")).strip()
            if status == "closed":
                continue
            cwd = str((state.get("cwd") or "")).strip()
            if not cwd:
                continue
            try:
                cwd_exists = Path(cwd).is_dir()
            except OSError:
                cwd_exists = False
            folder_label = Path(cwd).name or cwd or label
            updated_at = float(state.get("updated_at") or 0)
            transcript_path = _acp_transcript_path(harness, sid)
            try:
                transcript_mtime = transcript_path.stat().st_mtime
            except OSError:
                transcript_mtime = 0
            mtime = max(updated_at, transcript_mtime) or now
            first_message = _acp_transcript_first_prompt(harness, sid) or ""
            title = str(state.get("title") or "").strip()
            display_name = (
                name_overrides.get(sid)
                or _truncate_session_name(title)
                or (first_message[:80] if first_message else None)
                or f"{label} session"
            )
            model = str(state.get("model") or "").strip()
            is_live = status == "active"
            row = {
                "id": sid,
                "session_id": sid,
                "source": harness,
                "engine": harness,
                "jsonl_path": str(transcript_path),
                "slug": _encode_project_slug(cwd) if cwd else "",
                "folder_label": folder_label,
                "folder_path": cwd,
                "pinned_repo": False,
                "session_cwd": cwd,
                "session_cwd_exists": cwd_exists,
                "session_cwd_is_worktree": False,
                "mtime": mtime,
                "modified": mtime,
                "last_interacted": mtime,
                "size": 0,
                "first_message": first_message[:200] if first_message else None,
                "ai_title": title or None,
                "branch": "",
                "git_branch": "",
                "effective_branch": None,
                "effective_kind": None,
                "display_name": display_name,
                "spawn_named": "",
                "name_overridden": bool(name_overrides.get(sid)),
                "archived": sid in archived_set,
                "trashed": sid in trashed_set,
                "recently_unarchived": False,
                "verified": sid in set(_load_verified_conversations() or []),
                "pinned": sid in pinned_rank,
                "pin_rank": pinned_rank.get(sid),
                "worktree_dirty": False,
                "has_commit": False,
                "has_push": False,
                "has_edit": False,
                "tail_pr_number": None,
                "tail_pr_url": None,
                "pr_state": None,
                "is_live": is_live,
                "worktree_label": None,
                "last_assistant_text": "",
                "last_event_type": None,
                "pending_tool": None,
                "pending_file": None,
                "pending_tool_ts": 0,
                "stale_tool_call": False,
                "stale_tool_age_s": 0,
                "stale_tool_threshold_s": 0,
                "stale_tool_queued_input": "",
                "subagent_count": 0,
                "subagent_in_flight_count": 0,
                "subagent_recent": [],
                "workflows": [],
                "session_state": None,
                "goal": "",
                "goal_status": "",
                "parent_session_id": "",
                "model": model,
                "reasoning_effort": None,
                "latest_input_tokens": 0,
                "lifetime_tokens": 0,
                "cost_usd": 0.0,
                "cost_breakdown_usd": {},
                "total_input_tokens": 0,
                "total_cache_creation_tokens": 0,
                "total_cache_read_tokens": 0,
                "total_output_tokens": 0,
                "live_context_tokens": 0,
                "live_context_limit": 0,
                "live_context_percent": 0,
                "context_limit": 200000,
                "sidecar_status": None,
                "sidecar_has_writes": False,
                "sidecar_tool": None,
                "sidecar_file": None,
                "sidecar_ts": 0,
                "sidecar_in_flight": False,
                "needs_approval": False,
                "needs_approval_message": "",
                "question_waiting": False,
                "question_text": "",
                "question_header": "",
                "question_preamble": "",
                "question_options": [],
                "question_option_details": [],
                "can_headless_resume": False,
                "can_app_resume": False,
                "hermes_source": "",
                "hermes_origin": "",
                "hermes_profile": "",
                "hermes_chat_type": "",
                "hermes_tool_calls": 0,
                "all_lane_override": "",
                "source_platform": "",
                "thread_source": "",
                "tail_issue_number": None,
                "spawn_pid": sid if is_live else None,
                "state": "working" if is_live else "idle",
                "ended_blocked": False,
                **_token_optimizer_quality_for_session(sid),
            }
            row["spawned_via"] = _infer_session_spawned_via(row, sid=sid, markers=spawn_markers)
            out.append(row)
    return out


_row_flicker_seen = {}      # sid -> epoch last served on a window="all" poll
_row_flicker_missing = {}   # sid -> epoch first NOT served after being seen
_ROW_FLICKER_FRESH_WINDOW_S = 15 * 60   # only track recently-active sids — a
                                         # row scrolling out on age isn't the
                                         # "new session vanishes" bug being chased
_ROW_FLICKER_FORGET_S = 30 * 60


def _trace_row_flicker(rows, now=None):
    """Log ADD/REMOVE transitions of recently-active sids in the payload
    actually served by /api/conversations/list (window=all polls only, so
    a tab switching window scope doesn't read as a mass disappearance).

    Diagnostic-only, added because "new session appears, vanishes ~30s,
    reappears" (screenshot-reported, not yet root-caused) needs proof of
    WHERE the row drops — server corpus vs client-side filtering — before
    a fix can be attempted. See _traceRowFlicker in app.js for the client
    side of the same trace; both write to the same service.out.log so a
    server-only drop (this function fires, app.js's [ARCHIVE-DIAG] does not
    see the sid missing from its own last-good set) is distinguishable from
    a client-side drop (this function stays quiet, app.js logs it alone).
    """
    try:
        now = time.time() if now is None else now
        fresh_by_sid = {}
        for r in rows or []:
            if not isinstance(r, dict):
                continue
            sid = r.get("session_id") or r.get("id")
            if not sid:
                continue
            if (now - _archive_list_row_ts(r)) < _ROW_FLICKER_FRESH_WINDOW_S:
                fresh_by_sid[sid] = r
        now_ids = set(fresh_by_sid)
        _ts = time.strftime("%H:%M:%S")
        for sid in now_ids:
            missing_at = _row_flicker_missing.pop(sid, None)
            if missing_at is not None:
                print(f"[ROW-FLICKER] {_ts} reappeared sid={sid} gap={now - missing_at:.0f}s", flush=True)
            _row_flicker_seen[sid] = now
        for sid, last_seen in list(_row_flicker_seen.items()):
            if sid in now_ids or sid in _row_flicker_missing:
                continue
            if now - last_seen > _ROW_FLICKER_FORGET_S:
                _row_flicker_seen.pop(sid, None)
                continue
            _row_flicker_missing[sid] = now
            print(
                f"[ROW-FLICKER] {_ts} disappeared sid={sid} last_seen_ago={now - last_seen:.0f}s "
                f"fresh_rows_served={len(now_ids)}",
                flush=True,
            )
        if len(_row_flicker_seen) > 5000:
            cutoff = now - _ROW_FLICKER_FORGET_S
            for sid, ts in list(_row_flicker_seen.items()):
                if ts < cutoff:
                    _row_flicker_seen.pop(sid, None)
    except Exception:
        pass


def _archive_list_payload(rows, *, window="all", now=None, cached=None):
    window = _archive_list_window(window)
    projected = _archive_list_project_rows(rows, window=window, now=now)
    if window == "all":
        _trace_row_flicker(projected, now=now)
    payload = {
        "ok": True,
        "conversations": projected,
        "count": len(projected),
        "total_count": sum(isinstance(row, dict) for row in (rows or [])),
        "window": window,
        "fields": list(_ARCHIVE_LIST_FIELDS),
    }
    if cached is not None:
        payload["cached"] = bool(cached)
    return payload


def _stamp_archive_state(rows):
    """Stamp the single-source-of-truth coarse `state` + `ended_blocked` onto
    every archive row, IN PLACE.

    Same stamp /api/sessions applies via _apply_session_query_params, lifted into
    the snapshot itself so it is cache-safe: it lands in the stale-while-revalidate
    serve cache and the persisted-rows cold serve, so /api/conversations?all=1
    (which has no post-serve projection pass) carries `state`/`ended_blocked` on
    every warm hit, not just on a cold build. Pure string/flag work on fields
    already merged onto the row — no subprocess, no transcript parse — so it is
    safe to run at build/rehydrate time on all rows. Additive: touches only the
    two keys.
    """
    for r in rows or []:
        if isinstance(r, dict):
            r["state"] = _stamp_session_state(r)
            r["ended_blocked"] = _session_ended_blocked(r)
    return rows


def _stamp_archive_goals(rows):
    """Stamp the current codex `/goal` objective + status onto codex rows, IN
    PLACE, at serve time.

    Goal lives in ~/.codex/goals_1.sqlite — outside the transcript corpus
    signature and not re-layered by _rehydrate_archive_cached_rows — so a goal
    set or cleared after the persisted build would never reach the row without
    this pass. ONE batched, cached snapshot read (no per-row DB work), so it is
    cache-safe to run on every warm serve, exactly like _stamp_archive_state.
    Additive: only touches `goal`/`goal_status`, and only on codex rows.
    """
    snap = _codex_goals_snapshot()
    for r in rows or []:
        if not isinstance(r, dict) or r.get("engine") != "codex":
            continue
        sid = r.get("session_id") or r.get("id")
        g = snap.get(sid) if sid else None
        if g:
            r["goal"] = g.get("objective") or ""
            r["goal_status"] = g.get("status") or ""
        else:
            r["goal"] = ""
            r["goal_status"] = ""
    return rows


def _archive_compute_rows(key, cache_options, serve_generation=None):
    """Produce archive rows under the per-key build lock (single-flight).

    Signature-gated: unchanged transcript corpus → rehydrate the persisted rows
    (cheap, refreshes only live/sidecar state); changed → rebuild, reusing the
    per-(mtime,size) parse cache so only the touched sessions re-parse. Updates
    both the persisted response cache and the in-memory serve snapshot.
    Returns (rows, from_cache).
    """
    if serve_generation is None:
        with _archive_serve_lock:
            serve_generation = _archive_serve_generation
    sig = _archive_corpus_signature()
    lock = _archive_build_lock(key)
    with lock:
        entry = _archive_response_cache_get(key)
        if entry and entry.get("signature") == sig:
            rows = _rehydrate_archive_cached_rows(entry.get("conversations") or [])
            from_cache = True
        else:
            rows = None
            # Incremental tier: the corpus changed, but if we know exactly
            # WHICH transcripts changed (both signatures' stat maps are still
            # in memory) re-parse only those and merge into the cached rows.
            # This is what keeps a brand-new session's list/search visibility
            # at "one refresh" instead of "one full O(all-rows) rebuild"
            # (~12s warm, 60-95s live under GIL contention — measured, W84).
            # include_prs entries are excluded: their row set carries a
            # list-level open-PR overlay the delta build can't reproduce.
            if entry and not cache_options.get("include_prs"):
                delta = _archive_signature_delta(entry.get("signature"), sig)
                if delta is not None:
                    changed, removed, refresh_engines = delta
                    try:
                        fresh = find_all_conversations(
                            resolve_pr_states=cache_options.get("resolve_pr_states", False),
                            resolve_effective=cache_options.get("resolve_effective", False),
                            resolve_worktree_dirty=cache_options.get("resolve_worktree_dirty", False),
                            only_jsonl_paths=set(changed),
                        ) if changed else []
                        merged = _archive_merge_incremental_rows(
                            entry.get("conversations") or [], fresh, removed,
                        )
                        if "hermes" in refresh_engines:
                            merged = _archive_merge_engine_rows(
                                merged,
                                "hermes",
                                find_hermes_conversations(
                                    include_old=True,
                                    repo_only=False,
                                    resolve_pr_states=cache_options.get("resolve_pr_states", False),
                                    resolve_worktree_dirty=cache_options.get("resolve_worktree_dirty", False),
                                ),
                            )
                        if "codex" in refresh_engines:
                            merged = _archive_merge_engine_rows(
                                merged,
                                "codex",
                                find_codex_conversations(
                                    include_old=True,
                                    repo_only=False,
                                    resolve_pr_states=cache_options.get("resolve_pr_states", False),
                                    resolve_worktree_dirty=cache_options.get("resolve_worktree_dirty", False),
                                ),
                            )
                        _archive_response_cache_put(key, merged, signature=sig)
                        _save_conv_meta_cache()
                        rows = _rehydrate_archive_cached_rows(merged)
                        from_cache = True
                    except Exception as e:
                        print(f"  [archive-cache] incremental refresh failed, rebuilding: {e}")
                        rows = None
            if rows is None:
                rows = _build_archive_conversations(**cache_options)
                _archive_response_cache_put(key, rows, signature=sig)
                _save_conv_meta_cache()
                from_cache = False
    if not from_cache:
        # The cache branches already ran all three stamps inside
        # _rehydrate_archive_cached_rows; the full-build branch stamps state
        # internally but not goals/WT badges. Stamping again here duplicated
        # the work on every cache-hit refresh (~0.2-0.5s on big archives).
        _stamp_archive_goals(rows)
        _apply_watchtower_worker_display_names(rows)
    if _ARCHIVE_SERVE_TTL > 0:
        _archive_serve_cache_store(key, rows, serve_generation)
    return rows, from_cache


try:
    # 2026-08-05: measured this timing out at exactly 180s against the real
    # corpus (~3930 conversations, resolve_effective + resolve_pr_states +
    # resolve_worktree_dirty all on) while the dashboard was busy -- an
    # isolated run of the identical worker command took ~80s with no
    # contention. Every attempt was failing this way, back to back, so the
    # served snapshot never advanced even with the watchdog above correctly
    # un-wedging the slot each time: self-healing into "spawn a replacement
    # that also times out" is not actually healed. 420s gives real headroom
    # over the observed 2-3x contention slowdown; CCC_ARCHIVE_REFRESH_
    # WORKER_TIMEOUT_SEC still overrides for a corpus far outside this range.
    _ARCHIVE_REFRESH_WORKER_TIMEOUT = max(
        30.0, float(os.environ.get("CCC_ARCHIVE_REFRESH_WORKER_TIMEOUT_SEC", "420"))
    )
except ValueError:
    _ARCHIVE_REFRESH_WORKER_TIMEOUT = 420.0
# 2026-08-04 incident: something held _ARCHIVE_BUILD_GLOBAL_LOCK forever (the
# subprocess it wraps has its own timeout, but acquiring the lock itself did
# not), which silently froze the served archive snapshot for hours -- every
# stale poll saw the key already marked "refreshing" and skipped spawning a
# replacement, with nothing to log and nothing to restart into. Margin beyond
# the worker's own timeout for legitimate lock-wait under real contention.
_ARCHIVE_REFRESH_WATCHDOG_S = _ARCHIVE_REFRESH_WORKER_TIMEOUT + 60.0


def _archive_refresh_worker_main(encoded_options, output_path):
    """Build one archive snapshot in a short-lived, low-priority process."""
    try:
        # This is the __main__ dispatch for --archive-refresh-worker, which
        # exits via SystemExit before ever reaching main()'s normal startup
        # sequence -- so the per-file (mtime, size) parse cache that makes a
        # rebuild only touch changed sessions was never loaded here. Every
        # detached refresh has been doing a full cold re-parse of the whole
        # corpus, every time, which is the actual reason these were slow
        # enough to hit the subprocess timeout in the first place.
        _load_conv_meta_cache()
        if hasattr(os, "nice"):
            try:
                os.nice(10)
            except OSError:
                pass
        raw_options = base64.urlsafe_b64decode(encoded_options.encode("ascii"))
        cache_options = json.loads(raw_options.decode("utf-8"))
        if not isinstance(cache_options, dict):
            raise ValueError("archive worker options must be an object")
        cache_options = {
            name: bool(cache_options.get(name, False))
            for name in (
                "include_prs",
                "resolve_pr_states",
                "resolve_effective",
                "resolve_worktree_dirty",
            )
        }
        key = _archive_response_cache_key(**cache_options)
        rows, from_cache = _archive_compute_rows(key, cache_options)
        result = {
            "ok": True,
            "key": key,
            "rows": rows,
            "from_cache": bool(from_cache),
        }
    except Exception as exc:
        result = {"ok": False, "error": str(exc)}
    try:
        with open(output_path, "w", encoding="utf-8") as output_file:
            json.dump(result, output_file, separators=(",", ":"))
    except OSError as exc:
        print(f"archive refresh worker could not write its result: {exc}", file=sys.stderr)
        return 1
    return 0 if result.get("ok") else 1


def _archive_compute_rows_detached(key, cache_options, serve_generation):
    """Run GIL-heavy archive parsing outside the dashboard server process.

    The worker is deliberately one-shot: its parser allocations disappear on
    exit instead of permanently raising the daemon's RSS. The parent only
    decodes the completed row snapshot and publishes it atomically.
    """
    output_fd, output_name = tempfile.mkstemp(
        prefix="ccc-archive-refresh-", suffix=".json",
    )
    os.close(output_fd)
    encoded_options = base64.urlsafe_b64encode(
        json.dumps(cache_options, sort_keys=True).encode("utf-8")
    ).decode("ascii")
    env = dict(os.environ)
    # The worker has no HTTP callers and exits after one build, so an in-memory
    # serve snapshot there is wasted work. It still updates the durable response
    # cache consumed by future workers and server restarts.
    env["CCC_ARCHIVE_SERVE_TTL_SEC"] = "0"
    command = [
        sys.executable,
        str(Path(__file__).resolve()),
        "--archive-refresh-worker",
        encoded_options,
        output_name,
    ]
    # Serialize variants in the parent. The lock cannot coordinate separate
    # processes, but holding it around the one-shot worker prevents two
    # option variants from parsing the same corpus concurrently. A bounded
    # acquire, not `with lock:` -- the subprocess below has its own timeout,
    # but plain lock acquisition did not, so whatever wedged the lock on
    # 2026-08-04 blocked every subsequent refresh attempt forever with no
    # exception, no log line, nothing to restart into. Failing loud beats
    # hanging silent even when it can't fix the underlying stuck holder.
    try:
        if not _ARCHIVE_BUILD_GLOBAL_LOCK.acquire(timeout=_ARCHIVE_REFRESH_WATCHDOG_S):
            raise RuntimeError(
                "archive refresh worker could not acquire the build lock within "
                f"{_ARCHIVE_REFRESH_WATCHDOG_S:.0f}s -- another refresh is stuck holding it"
            )
        try:
            completed = subprocess.run(
                command,
                cwd=str(CCC_ROOT),
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=_ARCHIVE_REFRESH_WORKER_TIMEOUT,
            )
        finally:
            _ARCHIVE_BUILD_GLOBAL_LOCK.release()
        try:
            result = json.loads(Path(output_name).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            detail = (completed.stderr or completed.stdout or "").strip()[-500:]
            raise RuntimeError(
                f"archive refresh worker produced no result: {exc}; {detail}"
            ) from exc
        if completed.returncode != 0 or not result.get("ok"):
            detail = result.get("error") or (completed.stderr or "").strip()[-500:]
            raise RuntimeError(f"archive refresh worker failed: {detail}")
        if result.get("key") != key:
            raise RuntimeError("archive refresh worker returned the wrong cache variant")
        rows = result.get("rows")
        if not isinstance(rows, list):
            raise RuntimeError("archive refresh worker returned invalid rows")
        if _ARCHIVE_SERVE_TTL > 0:
            _archive_serve_cache_store(key, rows, serve_generation)
        return rows, bool(result.get("from_cache"))
    finally:
        try:
            os.unlink(output_name)
        except OSError:
            pass


def _archive_serve_refresh(key, cache_options, serve_generation, started_at):
    global _archive_serve_refreshing
    try:
        _archive_compute_rows_detached(key, cache_options, serve_generation)
    except Exception as e:
        print(f"  [archive-serve] background refresh failed: {e}")
    finally:
        with _archive_serve_lock:
            # Only clear the slot if it still belongs to THIS attempt. The
            # watchdog in _archive_refresh_slot_available can start a second
            # attempt for the same key once the first has been in flight
            # implausibly long; if that first one eventually does return, it
            # must not clobber the second attempt's own bookkeeping.
            if _archive_serve_refreshing.get(key) == started_at:
                _archive_serve_refreshing.pop(key, None)


def _overlay_conversation_lifecycle_flags(rows):
    """Re-stamp archived/trashed from the lifecycle sidecars, in place.

    Lifecycle mutations (archive/trash/merge) clear the in-memory serve cache
    but not the durable response cache, whose rows still carry pre-mutation
    flags. The cold-serve fallback below would otherwise serve those stale
    flags — resurrecting a just-trashed row in the dashboard until the next
    detached refresh landed. One batched sidecar read, no per-row I/O, so it
    stays cheap on the cold-serve path that exists to avoid rehydration cost.
    """
    try:
        archived_set, trashed_set = _load_conversation_lifecycle_sets()
    except Exception:
        return rows
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        sid = row.get("session_id") or row.get("id")
        if sid:
            row["archived"] = sid in archived_set
            row["trashed"] = sid in trashed_set
    return rows


def _archive_serve_rows(key, cache_options):
    rows, from_cache, _snap_ver = _archive_serve_rows_versioned(key, cache_options)
    return rows, from_cache


def _archive_serve_rows_versioned(
    key,
    cache_options,
    *,
    copy_rows=True,
    force_refresh=False,
):
    """Archive rows for an ?all=1 request, stale-while-revalidate.

    The endpoint is polled continuously by the dashboard AND the COO board, and
    in a live environment a session is almost always writing its JSONL — so the
    corpus signature changes on nearly every poll. Blocking each poll on the
    signature-gated rebuild (~1-2s, GIL-bound) is exactly the sustained CPU
    drain we are killing. Instead:

      - fresh snapshot (< serve TTL) → return a copy immediately (or a
        read-only reference for callers that project before responding);
      - stale snapshot → return it immediately AND kick a single background
        refresh (the request never pays the rebuild);
      - no snapshot yet (cold) → build once synchronously.

    Same shape and tolerance as _live_activity_snapshot and the sibling
    /api/conversations/all?stale_ok serve: transcript-derived fields
    (state/ended_blocked/question) and live state lag by at most the serve TTL
    plus one background refresh. The signature still gates the actual rebuild, so
    a changed corpus re-parses only the touched sessions.

    Returns (rows, from_cache, snap_ver). from_cache is False only on the cold
    build. snap_ver is the serve snapshot's version when the returned rows are
    exactly the stored snapshot (the /api/conversations/all sender prebuilds
    body+etag+gzip per version), else 0.
    """
    global _archive_serve_refreshing
    if _ARCHIVE_SERVE_TTL <= 0:
        rows, from_cache = _archive_compute_rows(key, cache_options)
        return rows, from_cache, 0
    now = time.time()
    with _archive_serve_lock:
        serve_generation = _archive_serve_generation
        sc = _archive_serve_cache.get(key)
        if sc is not None:
            stored_rows = sc.get("rows") or []
            rows = [dict(r) for r in stored_rows] if copy_rows else stored_rows
            snap_ver = sc.get("ver", 0)
            stale = force_refresh or (now - sc.get("ts", 0)) >= _ARCHIVE_SERVE_TTL
            if stale and _archive_refresh_slot_available(key, now):
                _archive_serve_refreshing[key] = now
                spawn = True
            else:
                spawn = False
        else:
            rows = None
            snap_ver = 0
            spawn = False
    if rows is not None:
        if spawn:
            # A structural "cheap" prediction is not a latency bound. On a
            # large real archive, even the rehydrate-only tier repeatedly took
            # 3-32s and monopolized the GIL, delaying unrelated conversation
            # opens. Once a snapshot exists, freshness work is therefore
            # always asynchronous; this request returns the snapshot now.
            threading.Thread(
                target=_archive_serve_refresh,
                args=(key, cache_options, serve_generation, now),
                daemon=True,
            ).start()
        return rows, True, snap_ver
    # Cold (e.g. just after a restart): the in-memory serve snapshot is empty.
    # Rather than block this first caller on a full rebuild (~20-30s cold), serve
    # the persisted response payload from the last run as-is. Rehydrating every
    # historical row here is itself an O(all rows), GIL-heavy operation; live
    # chips arrive through the dedicated live-activity overlay. Normal startup
    # trusts this snapshot for the serve TTL. If an enriched option variant has
    # no persisted entry yet, it borrows the base rows for first paint and fills
    # that variant in the detached worker. An explicit freshness request also
    # starts the detached build.
    # Only a truly first-ever run with no persisted cache builds synchronously.
    entry = _archive_response_cache_get(key)
    borrowed_base_snapshot = False
    if not entry:
        base_key = _archive_response_cache_key()
        if key != base_key:
            entry = _archive_response_cache_get(base_key)
            borrowed_base_snapshot = bool(entry and entry.get("conversations"))
    if entry and entry.get("conversations"):
        rows = _overlay_conversation_lifecycle_flags([
            dict(row) for row in (entry.get("conversations") or [])
            if isinstance(row, dict)
        ])
        stored = _archive_serve_cache_store(
            key, rows, serve_generation, ts=entry.get("cached_at"),
        )
        entry_stale = (now - float(entry.get("cached_at") or 0)) >= _ARCHIVE_SERVE_TTL
        with _archive_serve_lock:
            if (
                stored
                and (force_refresh or borrowed_base_snapshot or entry_stale)
                and _archive_refresh_slot_available(key, now)
            ):
                _archive_serve_refreshing[key] = now
                spawn = True
            else:
                spawn = False
        if spawn:
            threading.Thread(
                target=_archive_serve_refresh,
                args=(key, cache_options, serve_generation, now),
                daemon=True,
            ).start()
        returned_rows = [dict(r) for r in rows] if copy_rows else rows
        return returned_rows, True, _archive_serve_ver_for_rows(key, rows)
    # Nothing persisted yet — build once synchronously.
    rows, from_cache = _archive_compute_rows(key, cache_options, serve_generation)
    return rows, from_cache, _archive_serve_ver_for_rows(key, rows)


_ARCHIVE_SIDECAR_DEFAULTS = {
    "sidecar_status": None,
    "sidecar_has_writes": False,
    "sidecar_tool": None,
    "sidecar_file": None,
    "sidecar_ts": 0,
    "sidecar_in_flight": False,
    "needs_approval": False,
    "needs_approval_message": "",
    "question_waiting": False,
    "question_text": "",
    "question_header": "",
    "question_preamble": "",
    "question_options": [],
    "question_option_details": [],
}


_SPAWN_RECENT_WINDOW_SEC = 120.0


def _spawn_is_recent(spawn_entry, now=None):
    """True while a spawn is new enough that an empty transcript means
    "still starting", not "created and never used"."""
    raw = str((spawn_entry or {}).get("spawned_at") or "").strip()
    if not raw:
        return False
    try:
        ts = time.mktime(time.strptime(raw, "%Y%m%dT%H%M%S"))
    except (ValueError, OverflowError):
        return False
    return 0 <= ((now or time.time()) - ts) <= _SPAWN_RECENT_WINDOW_SEC


def _rehydrate_archive_cached_rows(rows):
    """Apply fast-changing state to cached archive rows before responding."""
    try:
        name_overrides = _load_session_name_overrides()
    except Exception:
        name_overrides = {}
    try:
        archived_set, trashed_set = _load_conversation_lifecycle_sets()
    except Exception:
        archived_set, trashed_set = set(), set()
    try:
        verified_set = set(_load_verified_conversations())
    except Exception:
        verified_set = set()
    try:
        pinned_list = _load_pinned_conversations()
    except Exception:
        pinned_list = []
    pinned_rank = _pinned_rank_map(pinned_list)
    try:
        spawn_registry_by_sid = _spawn_registry_entries_by_session()
    except Exception:
        spawn_registry_by_sid = {}
    # One read for the whole list, never per row (same rule as the registry).
    try:
        spawn_markers = _load_spawn_markers()
    except Exception:
        spawn_markers = {}
    # Effort lives in a side file the model picker rewrites, so a cached row
    # can be arbitrarily stale. Re-layer it here like the other user-mutable
    # state above; one read for the whole list, never one per row.
    try:
        session_overrides = _load_session_overrides()
    except Exception:
        session_overrides = {}

    # Same liveness gate as the build path. This rehydrate runs on EVERY
    # stale-cache serve — the path the dashboard hits on each load — so an
    # ungated per-row _archive_session_is_live (which scans every Gemini/Codex
    # file to classify the engine) for all ~1000 rows was the real recurring
    # "10s to load" even when the response cache was warm. Probe only the cheap
    # live-candidate set + recently-written rows; the rest are not live for free.
    try:
        live_candidates = _discover_live_session_ids()
    except Exception:
        live_candidates = set()
    # Peer-registry state (bridge session id, Claude busy/idle, tmux/socket)
    # changes as fast as liveness, so re-layer it per serve like the rest of
    # the volatile fields above; _load_session_registry is 3s-memoized.
    try:
        session_registry = _load_session_registry()
    except Exception:
        session_registry = {}
    _now_rehydrate = time.time()

    # Codex names a thread seconds AFTER the spawn returns, and that name lands
    # in state_*.sqlite, which the corpus signature deliberately ignores (see
    # _codex_titles_snapshot). Without re-layering it here the row stays
    # "(untitled)" until an unrelated change invalidates the cache. Loaded lazily
    # so a corpus with no Codex rows never touches the DB at all.
    _codex_titles = None

    hydrated = []
    for raw in rows or []:
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        sid = row.get("session_id") or row.get("id")
        if sid:
            override = name_overrides.get(sid)
            if override:
                row["display_name"] = override
                row["name_overridden"] = True
            else:
                # Keep whatever display_name the parser already derived
                # (which, for dormant sessions, includes any custom-title
                # event the user wrote via `/rename` in Claude Code OR the
                # rename_session() write-through to the JSONL). Previously
                # we set display_name=None for interactive sessions without
                # a side-car override — that wiped the JSONL-derived rename
                # on every fetch and the client fell back to the AI title.
                # Don't lose user intent recorded in the JSONL.
                row["name_overridden"] = False
                if row.get("engine") == "codex":
                    if _codex_titles is None:
                        try:
                            _codex_titles = _codex_titles_snapshot()
                        except Exception:
                            _codex_titles = {}
                    fresh = _codex_titles.get(sid)
                    if fresh:
                        title = fresh["title"]
                        first_message = fresh["first_user_message"]
                        name = _codex_display_name(
                            fresh, title=title, first_message=first_message
                        )
                        if name:
                            row["display_name"] = name
                        # Mirrors the build path: only call it an AI title when
                        # Codex actually summarized rather than copying the ask.
                        row["ai_title"] = (
                            title if (title and title != first_message) else None
                        )
                        if row["ai_title"] is None:
                            try:
                                _request_codex_auto_title(sid, fresh=fresh)
                            except Exception:
                                pass

            # A just-spawned session reaches the list BEFORE its engine has
            # written the prompt anywhere we read it: the row lands at ~5s,
            # Codex writes title and first_user_message at ~7s. For that window
            # the row rendered as "(untitled)" wearing an [EMPTY] chip, which
            # is a fair description of the transcript and a bad description of
            # what is happening. CCC sent the prompt, so it can say so.
            #
            # display_name is filled in (nothing better exists yet, and the
            # engine's own title overwrites it the moment it lands), but
            # first_message is deliberately NOT faked: [EMPTY] must keep
            # meaning "no transcript". The client suppresses the chip on
            # spawn_recent instead, so a genuinely created-but-unused session
            # still shows it.
            if sid and not row.get("first_message"):
                spawn = spawn_registry_by_sid.get(sid) or {}
                prompt = str(spawn.get("prompt") or "").strip()
                if prompt:
                    if not row.get("display_name"):
                        row["display_name"] = _truncate_session_name(prompt)
                    if _spawn_is_recent(spawn, _now_rehydrate):
                        row["spawn_recent"] = True

            row["archived"] = sid in archived_set
            row["trashed"] = sid in trashed_set
            row["recently_unarchived"] = _is_recently_unarchived(sid, _now_rehydrate)
            row["verified"] = sid in verified_set
            # Live-first, matching the model beside it (CCC-466): a row states
            # what the session last RAN at. An observed transcript value always
            # wins, whichever engine parsed it, because a picked-but-not-yet-
            # applied override would otherwise show indefinitely on a session
            # provably running something else. CCC's side files are the
            # fallback for a session with no assistant turn yet.
            if not row.get("reasoning_effort"):
                row["reasoning_effort"] = _conv_row_reasoning_effort(
                    sid, session_overrides, spawn_registry_by_sid.get(sid),
                )
            row["pinned"] = sid in pinned_rank
            row["pin_rank"] = pinned_rank.get(sid)
            spawn_parent_id = str(
                (spawn_registry_by_sid.get(sid) or {}).get("parent_session_id") or ""
            ).strip()
            if not spawn_parent_id:
                spawn_parent_id = _parent_session_id_from_return_address_text(
                    row.get("first_message")
                )
            if not spawn_parent_id and sid in spawn_registry_by_sid and row.get("jsonl_path"):
                spawn_parent_id = _parent_session_id_from_transcript_return_address(
                    row.get("jsonl_path")
                )
            if not spawn_parent_id:
                spawn_parent_id = str(_session_graph.parent_of(sid) or "").strip()
            if spawn_parent_id:
                row["parent_session_id"] = spawn_parent_id
            else:
                row.setdefault("parent_session_id", "")
            # How this session's spawn request arrived (cli/ui/ui-automated/
            # api), tagged onto the registry entry at spawn time (CCC-1026
            # follow-up) or inferred from launch metadata.
            row["spawned_via"] = _infer_session_spawned_via(
                row, sid=sid,
                markers=spawn_markers, spawn_registry_by_sid=spawn_registry_by_sid,
            )
            # Continuation lineage specifically (F2 "Continue in a new
            # session" / usage-limit auto-resume): the origin marker only
            # appears in continuation prompts, never in subagent spawns, so
            # this stays empty for ordinary spawned workers.
            continued_from = _continued_from_session_id_from_text(
                row.get("first_message")
            )
            if (
                not continued_from
                and sid in spawn_registry_by_sid
                and row.get("jsonl_path")
            ):
                continued_from = _continued_from_session_id_from_transcript(
                    row.get("jsonl_path")
                )
            row["continued_from_session_id"] = continued_from

            row_ts = row.get("mtime") or row.get("modified") or 0
            if sid in live_candidates or (_now_rehydrate - row_ts) < _LIVE_MTIME_WINDOW:
                is_live = _archive_session_is_live(sid)
            else:
                is_live = False
            row["is_live"] = is_live
            if row.get("engine") == "claude":
                row.update(_registry_row_overlay(session_registry.get(sid)))
            for k, v in _ARCHIVE_SIDECAR_DEFAULTS.items():
                row[k] = copy.deepcopy(v)
            if is_live:
                live_row = {"session_id": sid, "is_live": True}
                try:
                    _add_sidecar_fields(live_row)
                    for k in _ARCHIVE_SIDECAR_DEFAULTS:
                        if k in live_row:
                            row[k] = live_row[k]
                except Exception:
                    pass
            if row.get("engine") == "kimi" or row.get("source") == "kimi":
                # Kimi turn-shape fields (last_event_type / pending_tool /
                # stale_tool_call) can't wait for a corpus-signature rebuild —
                # wire appends deliberately don't bust it. One stat per row.
                try:
                    _restamp_kimi_row_tail_fields(row)
                except Exception:
                    pass
            # Workflow runs: the corpus signature deliberately ignores
            # journals (fast-changing live state), so recompute here per
            # serve like the sidecar overlay. Gated to proven workflow
            # owners; the journal parse itself is (mtime,size)-cached, so a
            # quiet run costs a couple of stat calls and nothing else.
            _wf_subdir = _ARCHIVE_WORKFLOW_SESSION_DIRS.get(sid)
            if _wf_subdir is not None:
                try:
                    row["workflows"] = _session_workflow_runs(
                        _wf_subdir, sid, now=_now_rehydrate
                    )
                except Exception:
                    pass
        hydrated.append(row)

    _apply_pinned_conversation_fields(hydrated, pinned_list)
    hydrated.sort(key=lambda r: r.get("mtime") or r.get("modified") or 0, reverse=True)
    _sort_pinned_conversations_first(hydrated, pinned_list)
    _apply_session_lane_overrides(hydrated)
    _apply_spawn_markers(hydrated)
    _stamp_archive_state(hydrated)
    # Layer the current codex goal on every rehydrate (one batched, cached read)
    # so the stale_ok serve the dashboard polls reflects goal set/clear without
    # waiting for a full transcript-signature rebuild.
    _stamp_archive_goals(hydrated)
    # Same reasoning for WT ticket badges: without this, a session that closes
    # a new ticket only gets its display_name refreshed on the next full
    # transcript-signature rebuild, not on every cache-hit serve.
    _apply_watchtower_worker_display_names(hydrated)
    return hydrated


def _archive_cached_payload(key):
    entry = _archive_response_cache_get(key)
    if not entry:
        return None
    rows = _rehydrate_archive_cached_rows(entry.get("conversations") or [])
    return {
        "conversations": rows,
        "count": len(rows),
        "cached": True,
        "stale": _archive_response_cache_is_stale(entry),
        "refreshing": _archive_response_refreshing(key),
        "cached_at": entry.get("cached_at") or 0,
    }


def _build_archive_conversations(
    *,
    include_prs=False,
    resolve_pr_states=False,
    resolve_effective=False,
    resolve_worktree_dirty=False,
    progress_step=None,
):
    def progress(key, **kwargs):
        if progress_step:
            progress_step(key, **kwargs)

    progress("folders",     state="running")
    progress("transcripts", state="running")
    progress("infer",       state="running")
    progress("worktrees",   state="running")
    progress("codex",       state="running")
    progress("cursor",      state="running")
    progress("antigravity", state="running")
    progress("hermes",      state="running")
    raw_convs = find_all_conversations(
        resolve_pr_states=resolve_pr_states,
        resolve_effective=resolve_effective,
        resolve_worktree_dirty=resolve_worktree_dirty,
        progress_step=progress,
    )
    count = len(raw_convs or [])
    progress("folders",     state="done")
    progress("transcripts", state="done", count=count, total=count, detail=f"{count} conversations parsed.")
    if resolve_effective:
        progress("infer",       state="done")
    else:
        progress("infer",       state="skipped", detail="Deferred until archive rows are visible.")
    if resolve_worktree_dirty:
        progress("worktrees",   state="done")
    else:
        progress("worktrees",   state="skipped", detail="Deferred until archive rows are visible.")
    progress("codex",       state="done")
    progress("cursor",      state="done")
    progress("antigravity", state="done")
    progress("hermes",      state="done")
    if include_prs:
        progress("pr_states",   state="running", detail="gh pr view per known PR URL.")
        convs = conversations_with_open_prs(raw_convs)
        progress("pr_states",   state="done")
    else:
        convs = raw_convs
        progress("pr_states",   state="skipped", detail="Deferred until archive rows are visible.")
    progress("issues",      state="skipped", detail="Loaded by /api/issues/all.")
    progress("group_chats", state="skipped", detail="Loaded by /api/group-chats/archived.")
    _stamp_archive_state(convs)
    return convs


def archive_window_since_epoch(window: str, now: float | None = None) -> float | None:
    """Translate the public archive window into a server-side time bound."""
    seconds = {"8h": 8 * 60 * 60, "1d": 24 * 60 * 60, "7d": 7 * 24 * 60 * 60}.get(window)
    if seconds is None:
        return None
    return (time.time() if now is None else now) - seconds


def _archive_refresh_response_cache_async(key, options):
    if not _archive_response_refresh_begin(key):
        return False

    def refresh():
        try:
            # Signature BEFORE the build: files that change mid-build make the
            # entry conservatively stale (next refresh re-checks), never
            # wrongly fresh. Persisting without a signature disabled the
            # sig-match/incremental fast paths for this key entirely.
            sig = _archive_corpus_signature()
            convs = _build_archive_conversations(**options)
            _archive_response_cache_put(key, convs, signature=sig)
            _save_conv_meta_cache()
        except Exception as e:
            print(f"  [archive-cache] background refresh failed: {e}")
        finally:
            _archive_response_refresh_end(key)

    threading.Thread(target=refresh, daemon=True).start()
    return True


def load_known_repos():
    """Auto-detect projects for the picker by scanning $HOME.

    Returns one entry per direct child of $HOME that looks like a project —
    either a git repo (`.git/`) or a Claude workspace (`.claude/`). Skips
    dotfile dirs themselves so the list stays clean. Sorted alphabetically.
    Falls back to cwd when nothing is found so the picker is never empty.
    """
    home = Path.home()
    repos = []
    try:
        for entry in sorted(home.iterdir(), key=lambda p: p.name.lower()):
            if not entry.is_dir() or entry.name.startswith("."):
                continue
            is_git = (entry / ".git").is_dir()
            is_claude = (entry / ".claude").is_dir()
            if not (is_git or is_claude):
                continue
            repos.append({"path": str(entry.resolve()), "label": entry.name})
    except OSError:
        pass
    if not repos:
        cwd = Path.cwd().resolve()
        repos.append({"path": str(cwd), "label": cwd.name})
    # Merge in user-picked repos (folders outside $HOME, or nested ones the scan
    # missed). Label with parent dir when it disambiguates a duplicate name.
    scanned_paths = {r["path"] for r in repos}
    scanned_labels = {r["label"] for r in repos}
    for custom_path in _load_custom_repos():
        if custom_path in scanned_paths:
            continue
        name = Path(custom_path).name
        if name in scanned_labels:
            label = f"{name} ({Path(custom_path).parent.name})"
        else:
            label = name
        repos.append({"path": custom_path, "label": label})
    # Re-order: recently-used repos first (in recency order), then the rest
    # in the original alphabetical order. The picker modal uses this ordering
    # to group a "Recent" section above the long list.
    recent = _load_recent_repos()
    if recent:
        by_path = {r["path"]: r for r in repos}
        ordered = []
        seen = set()
        for p in recent:
            if p in by_path and p not in seen:
                ordered.append(by_path[p])
                seen.add(p)
        for r in repos:
            if r["path"] not in seen:
                ordered.append(r)
        repos = ordered
    return repos


def _which(cmd):
    """Return the absolute path of `cmd` on PATH, or None. shutil-free so the
    file stays stdlib-only without importing shutil at module top."""
    import shutil
    return shutil.which(cmd)


def _iter_common_cli_candidates(cmd):
    """Yield common user-install locations that launchd often omits from PATH."""
    home = Path.home()
    fixed = [
        Path("/opt/homebrew/bin") / cmd,
        Path("/usr/local/bin") / cmd,
        home / ".local" / "bin" / cmd,
        home / ".npm-global" / "bin" / cmd,
        home / "Library" / "pnpm" / cmd,
        home / ".volta" / "bin" / cmd,
        home / ".bun" / "bin" / cmd,
        home / ".asdf" / "shims" / cmd,
        home / ".nodenv" / "shims" / cmd,
        home / ".local" / "share" / "mise" / "shims" / cmd,
    ]
    seen = set()
    for p in fixed:
        s = str(p)
        if s not in seen:
            seen.add(s)
            yield p
    glob_roots = [
        (home / ".nvm" / "versions" / "node", f"*/bin/{cmd}"),
        (home / ".fnm" / "node-versions", f"*/installation/bin/{cmd}"),
    ]
    for root, pattern in glob_roots:
        if not root.is_dir():
            continue
        try:
            paths = sorted(root.glob(pattern), reverse=True)
        except OSError:
            continue
        for p in paths:
            s = str(p)
            if s not in seen:
                seen.add(s)
                yield p
    try:
        hidden_bin_paths = sorted(home.glob(f".*/bin/{cmd}"), reverse=True)
    except OSError:
        hidden_bin_paths = []
    for p in hidden_bin_paths:
        s = str(p)
        if s not in seen:
            seen.add(s)
            yield p


def _resolve_claude_bin():
    """Locate a usable Claude Code CLI binary.

    LaunchAgents inherit a sparse PATH, so relying only on Popen(["claude", ...])
    produces opaque FileNotFoundError failures even when an interactive shell can
    run Claude. CCC_CLAUDE_BIN is the explicit escape hatch; common user-install
    locations cover Homebrew, npm/nvm/fnm, Volta, asdf, mise, and similar setups.
    """
    env_bin = (os.environ.get("CCC_CLAUDE_BIN") or "").strip()
    if env_bin:
        expanded = os.path.expanduser(env_bin)
        if os.path.isfile(expanded) and os.access(expanded, os.X_OK):
            return {"available": True, "bin": expanded, "source": "env"}
        return {
            "available": False,
            "bin": None,
            "code": "claude_unavailable",
            "reason": f"CCC_CLAUDE_BIN is set to {env_bin!r} but it isn't an executable file",
        }
    which_bin = shutil.which("claude")
    if which_bin:
        return {"available": True, "bin": which_bin, "source": "path"}
    for candidate in _iter_common_cli_candidates("claude"):
        if candidate.is_file() and os.access(candidate, os.X_OK):
            return {"available": True, "bin": str(candidate), "source": "candidate"}
    return {
        "available": False,
        "bin": None,
        "code": "claude_unavailable",
        "reason": "Claude Code CLI not found. Install Claude Code or set CCC_CLAUDE_BIN.",
    }


_CLAUDE_SPAWN_CAPABILITIES_LOCK = threading.Lock()
_CLAUDE_SPAWN_CAPABILITIES = {}
_CLAUDE_SPAWN_CAPABILITY_PROBES = set()


def _probe_claude_spawn_capabilities(bin_path=None):
    """Probe spawn flags once, outside the warm request path.

    Older Claude Code releases must retain CCC's existing log-discovery and
    completed-block stream behavior, so a failed probe deliberately publishes
    an all-false (but ready) record rather than guessing.
    """
    if not bin_path:
        resolved = _resolve_claude_bin()
        bin_path = resolved.get("bin") if resolved.get("available") else None
    record = {
        "ready": True,
        "bin": str(bin_path or ""),
        "session_id": False,
        "partial_messages": False,
    }
    if bin_path:
        try:
            completed = subprocess.run(
                [str(bin_path), "--help"],
                capture_output=True,
                text=True,
                timeout=5,
            )
            help_text = f"{completed.stdout or ''}\n{completed.stderr or ''}"
            if completed.returncode == 0:
                record["session_id"] = "--session-id" in help_text
                record["partial_messages"] = "--include-partial-messages" in help_text
        except (subprocess.TimeoutExpired, FileNotFoundError, OSError):
            pass
    with _CLAUDE_SPAWN_CAPABILITIES_LOCK:
        _CLAUDE_SPAWN_CAPABILITIES[str(bin_path or "")] = dict(record)
    return record


def _claude_spawn_capabilities(bin_path):
    """Return only already-probed capabilities; never block a warm spawn."""
    key = str(bin_path or "")
    with _CLAUDE_SPAWN_CAPABILITIES_LOCK:
        record = _CLAUDE_SPAWN_CAPABILITIES.get(key)
    if record:
        return dict(record)
    return {
        "ready": False,
        "bin": key,
        "session_id": False,
        "partial_messages": False,
    }


def _schedule_claude_spawn_capability_probe():
    """Warm the flag cache once in each process that may own a spawn."""
    resolved = _resolve_claude_bin()
    if not resolved.get("available"):
        return False
    bin_path = str(resolved.get("bin") or "")
    with _CLAUDE_SPAWN_CAPABILITIES_LOCK:
        if bin_path in _CLAUDE_SPAWN_CAPABILITIES or bin_path in _CLAUDE_SPAWN_CAPABILITY_PROBES:
            return False
        _CLAUDE_SPAWN_CAPABILITY_PROBES.add(bin_path)

    def worker():
        try:
            _probe_claude_spawn_capabilities(bin_path)
        finally:
            with _CLAUDE_SPAWN_CAPABILITIES_LOCK:
                _CLAUDE_SPAWN_CAPABILITY_PROBES.discard(bin_path)

    threading.Thread(
        target=worker,
        daemon=True,
        name="ccc-claude-spawn-capabilities",
    ).start()
    return True


# ── In-app update: version check + self-update ─────────────────────────────
# The UI pings /api/version/check on load; if the local __version__ is behind
# the latest GitHub release tag, it shows a "Update available" pill. Clicking
# the pill posts to /api/self-update, which runs
#     git fetch origin && git reset --hard origin/main
# in the install directory (pre-flight checked for local mods + branch=main),
# writes the response, and then os.execvp's the server back onto itself so
# the new code is running.
_VERSION_CHECK_CACHE = {"ts": 0.0, "data": None}
_VERSION_CHECK_TTL = 6 * 60 * 60  # 6h — GitHub unauth limit is 60/h/IP


def _install_dir():
    """Dir containing server.py — this is the git clone we'd update."""
    return Path(__file__).resolve().parent


def _compute_server_code_rev():
    """git HEAD of this install at process start — the build stamp doctor
    checks use to tell a live server apart from what's on disk.

    Computed once at import time, not on each call: a `git pull` landing
    while this process is still running must NOT make it look current when
    it's actually still running the code it loaded at start."""
    try:
        out = subprocess.check_output(
            ["git", "-C", str(_install_dir()), "rev-parse", "HEAD"],
            stderr=subprocess.DEVNULL, timeout=2,
        ).decode("utf-8", "replace").strip()
        return out or ""
    except (OSError, subprocess.CalledProcessError, subprocess.TimeoutExpired):
        return ""


_SERVER_CODE_REV = _compute_server_code_rev()


_CCC_DASHBOARD_LAUNCHD_LABEL = "com.github.claude-command-center"
_WORKER_LAUNCHD_LABEL = "com.github.claude-command-center.worker"


def _repo_version_on_disk():
    """`__version__` declared by the server.py currently on disk (post-pull)."""
    try:
        for line in (_install_dir() / "server.py").read_text(
            encoding="utf-8", errors="replace"
        ).splitlines():
            if line.startswith('__version__ = "'):
                return line.split('"')[1]
    except (OSError, IndexError):
        pass
    return ""


def _restart_stale_worker():
    """Restart the execution worker if it is running an older server.py.

    The in-app update re-execs the dashboard directly (os.execvp), bypassing
    run.sh's ensure_worker_current gate -- so the modal update path must make
    the same check itself, or the worker keeps running pre-upgrade code
    forever. Mirrors run.sh's rules: a worker too old to report
    server_version counts as stale; a null server_version means it never
    imported server (its first RPC loads the new code from disk -- leave it).
    Best-effort and never raised into: the pull already succeeded, and a
    worker that stays old for one more launch is caught by run.sh's gate.
    """
    try:
        health = _control_plane_request("health")
    except Exception as e:
        return {"restarted": False, "reason": f"worker health unreachable ({e})"}
    if not isinstance(health, dict) or not health.get("ok"):
        return {"restarted": False, "reason": "no healthy worker"}
    worker = health.get("worker") if isinstance(health.get("worker"), dict) else {}
    repo_version = _repo_version_on_disk()
    loaded = worker.get("server_version")
    stale = ("server_version" not in worker) or (
        bool(loaded) and bool(repo_version) and loaded != repo_version
    )
    if not stale:
        return {"restarted": False, "reason": "current", "server_version": loaded}
    return _restart_worker_process(worker, was=loaded, now=repo_version)


def _restart_worker_process(worker=None, *, was=None, now=None):
    """Restart the execution worker, whatever its version.

    Split out of _restart_stale_worker so the Maintenance UI can restart the
    worker on demand (a server.py fix only goes live in the worker once this
    runs -- worker_engines.py lazily imports server, so the worker holds its
    own copy of that module state).

    Prefers launchd; falls back to kill + detached respawn for install paths
    with no worker service (Homebrew's single service, the DMG app spawn).
    """
    if worker is None:
        try:
            health = _control_plane_request("health")
        except Exception:
            health = {}
        worker = health.get("worker") if isinstance(health, dict) and isinstance(health.get("worker"), dict) else {}
    target = f"gui/{os.getuid()}/{_WORKER_LAUNCHD_LABEL}"
    kicked = False
    if _launchd_restart_targets_pid(_WORKER_LAUNCHD_LABEL, worker.get("pid")):
        try:
            proc = subprocess.run(
                ["launchctl", "kickstart", "-k", target],
                capture_output=True, text=True, timeout=10,
            )
            kicked = proc.returncode == 0
        except (OSError, subprocess.TimeoutExpired):
            kicked = False
    outcome = {"restarted": True, "was": was, "now": now}
    if kicked:
        outcome["via"] = "launchd"
        return outcome
    # No launchd worker service on this install path (Homebrew's single
    # service, DMG app spawn): kill + respawn detached, mirroring run.sh,
    # or the dashboard runs workerless until the next launch.
    outcome["via"] = "respawn"
    pid = worker.get("pid")
    try:
        if pid:
            os.kill(int(pid), signal.SIGTERM)
            for _ in range(20):
                try:
                    os.kill(int(pid), 0)
                except OSError:
                    break
                time.sleep(0.1)
        log_dir = COMMAND_CENTER_STATE_DIR / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        out = open(log_dir / "worker.out.log", "a")
        err = open(log_dir / "worker.err.log", "a")
        subprocess.Popen(
            [sys.executable, str(_install_dir() / "ccc_worker.py")],
            stdin=subprocess.DEVNULL, stdout=out, stderr=err,
            start_new_session=True,
        )
    except OSError as e:
        outcome["restarted"] = False
        outcome["reason"] = f"kill/respawn failed ({e})"
    return outcome


def _safe_worker_restart_precheck(reason_prefix="worker-restart"):
    """Shared safety gate before killing the worker process.

    Originally lived only inline in the /api/restart/all handler, which is
    why a worker-only restart (/api/restart/worker) used to skip straight to
    launchctl kickstart with none of it: no check for a Kimi turn this
    dashboard still owns (Kimi has no adopt path, so a kill mid-turn loses
    it outright), no attempt to hand live sessions to the worker before it
    dies, no drain so a turn in flight gets a clean stopping point instead
    of being cut off. That asymmetry was the actual answer to "when is it
    safe to restart the worker" -- the safe sequence existed, it just wasn't
    attached to the button people actually use for a worker-only restart.

    Returns (ok, error_response_or_None, adopted, protected). `adopted` and
    `protected` are the raw control-plane responses, worth threading into
    the final response so a caller can see how much was actually saved.
    """
    local_active = _dashboard_owned_active_executions()
    active_kimi = [item for item in local_active if item.get("engine") == "kimi"]
    if active_kimi:
        return False, {
            "ok": False,
            "error": (
                "A Kimi turn is still owned by this dashboard. "
                "Wait for it to finish before restarting."
            ),
            "active": active_kimi,
        }, None, None
    adopted = _control_plane_request("engine.adopt", {}, engine_timeout=True)
    if adopted.get("code") == "method_not_found":
        adopted = {"ok": False, "available": False}
    if adopted.get("available") and not adopted.get("ok"):
        return False, {
            "ok": False,
            "error": adopted.get("error") or "worker could not adopt sessions",
        }, adopted, None
    if not adopted.get("available") and local_active:
        return False, {
            "ok": False,
            "error": (
                "Agent work is still owned by this dashboard and the "
                "persistent worker is unavailable. Start the worker or "
                "wait for the active turn before restarting."
            ),
            "active": local_active,
        }, adopted, None
    protected = _control_plane_request("drain.set", {
        "enabled": True,
        "reason": f"{reason_prefix}:{uuid.uuid4()}",
    })
    if protected.get("available") and not protected.get("ok"):
        return False, {
            "ok": False,
            "error": protected.get("error") or "worker refused safe drain",
        }, adopted, protected
    return True, None, adopted, protected


def _wait_worker_healthy(timeout_s=20.0, interval_s=0.5):
    """Poll control-plane health until the restarted worker answers again.

    launchctl kickstart (and the kill+respawn fallback) both return before
    the new process has finished booting and re-bound its control-plane
    listener -- calling work.reconcile immediately after would just race a
    process that isn't there yet. Bounded at 20s so a worker that fails to
    come back doesn't hang the restart response indefinitely; the caller
    still reports what it knows either way.
    """
    deadline = time.time() + timeout_s
    while time.time() < deadline:
        try:
            health = _control_plane_request("health")
        except Exception:
            health = {}
        if isinstance(health, dict) and health.get("ok"):
            return True
        time.sleep(interval_s)
    return False


# ── Worker compatibility self-heal ──────────────────────────────────────────
# run.sh's boot-time worker-compat check (~line 606: "engine-execution-v1" in
# capabilities, kill + let a fresh worker start) only runs once, at dashboard
# startup. If the worker happens to be busy at that exact instant, run.sh just
# logs "using compatibility execution" and moves on -- there is no retry, no
# re-check, no UI signal. A worker that is busy-at-boot and idle five minutes
# later then keeps running stale/incompatible code for as long as the
# dashboard stays up (observed: ~2h in production, 2026-08-28), silently
# degrading every engine spawn to legacy dashboard execution until an
# unrelated later restart happens to catch it idle.
#
# _worker_compat_maintenance_check() re-applies run.sh's exact rule on every
# Maintenance tick (see hermes._engine_maintenance_once, hourly via
# _ENGINE_UPDATE_INTERVAL_SEC) instead of once at boot: idle + missing
# engine-execution-v1 -> retire and let a fresh one start. A busy worker is
# always left alone, matching run.sh's "never roll an older worker with
# unresolved work". This is additive to run.sh's own check, not a
# replacement -- it exists to catch exactly the case that check's one-shot
# nature misses.
_WORKER_COMPAT_CACHE_LOCK = threading.Lock()
_WORKER_COMPAT_CACHE = {
    "ok": True,
    "reachable": None,
    "idle": None,
    "pid": None,
    "worker_server_version": None,
    "repo_version": None,
    "capabilities": [],
    "checked_at": None,
}


def _worker_compat_snapshot(health=None):
    """Build the worker_compat status dict from a control-plane health reply.

    `ok` is True only when the worker answered (reachable) AND advertises
    engine-execution-v1 -- the same condition run.sh's boot check gates on.
    Also backs /api/health's worker_compat field (build_ccc_health), via the
    cache below, so the UI and the self-heal below agree on one definition.
    """
    if health is None:
        try:
            health = _control_plane_request("health")
        except Exception:
            health = {}
    if not isinstance(health, dict):
        health = {}
    worker = health.get("worker") if isinstance(health.get("worker"), dict) else {}
    capabilities = list(worker.get("capabilities") or [])
    reachable = bool(health.get("ok"))
    compatible = "engine-execution-v1" in capabilities
    idle = not any(int(health.get(key) or 0) for key in ("active", "queued", "uncertain"))
    return {
        "ok": reachable and compatible,
        "reachable": reachable,
        "idle": idle,
        "pid": worker.get("pid"),
        "worker_server_version": worker.get("server_version"),
        "repo_version": _repo_version_on_disk() or __version__,
        "capabilities": capabilities,
    }


def _set_worker_compat_cache(snapshot):
    with _WORKER_COMPAT_CACHE_LOCK:
        _WORKER_COMPAT_CACHE.clear()
        _WORKER_COMPAT_CACHE.update(snapshot)
        _WORKER_COMPAT_CACHE["checked_at"] = time.time()


def _get_worker_compat_cache():
    with _WORKER_COMPAT_CACHE_LOCK:
        return dict(_WORKER_COMPAT_CACHE)


def _worker_compat_self_heal_restart(reason_prefix="worker-compat-selfheal"):
    """Drain, restart, and reconcile the worker.

    Reuses the exact safety sequence /api/restart/worker exposes as a manual
    button (_safe_worker_restart_precheck -> _restart_worker_process ->
    _wait_worker_healthy -> reconcile -> lift the drain), so an automatic
    retire triggered by the maintenance tick is exactly as safe as a human
    clicking the button -- same Kimi-turn guard, same drain, same adopt.
    """
    ok, precheck_err, adopted, protected = _safe_worker_restart_precheck(
        reason_prefix=reason_prefix,
    )
    if not ok:
        return {"ok": False, "restarted": False, "precheck_error": precheck_err}
    outcome = _restart_worker_process()
    healthy = False
    if outcome.get("restarted"):
        healthy = _wait_worker_healthy()
        if healthy:
            _control_plane_request("work.reconcile", {})
            _control_plane_request("drain.set", {
                "enabled": False,
                "reason": "worker restart complete",
            })
    return {
        "ok": bool(outcome.get("restarted")),
        "restarted": bool(outcome.get("restarted")),
        "worker": outcome,
        "worker_reachable": healthy,
        "adopted": int((adopted or {}).get("adopted") or 0),
        "drain_queued": int((protected or {}).get("queued") or 0),
    }


def _worker_compat_maintenance_check():
    """Periodic backstop for run.sh's one-shot boot-time worker-compat check.

    Called once per Maintenance tick. Updates the cache /api/health reads
    unconditionally; retires the worker only when it is BOTH idle (per the
    worker's own active/queued/uncertain counts) AND missing
    engine-execution-v1. Never touches a busy worker, an already-compatible
    worker, or an unreachable one (that is a different problem -- Maintenance
    already has _start_control_plane_worker for "no worker at all").
    """
    try:
        health = _control_plane_request("health")
    except Exception:
        health = {}
    snapshot = _worker_compat_snapshot(health)
    _set_worker_compat_cache(snapshot)
    if not snapshot["reachable"] or snapshot["ok"] or not snapshot["idle"]:
        return snapshot
    try:
        pid = int(snapshot.get("pid") or 0)
    except (TypeError, ValueError):
        pid = 0
    if pid <= 1:
        return snapshot
    result = _worker_compat_self_heal_restart()
    print(
        "  [maintenance] retired idle worker running stale/incompatible code "
        f"(pid {pid}, capabilities={snapshot['capabilities']}): "
        f"restarted={result.get('restarted')}"
    )
    _set_worker_compat_cache(_worker_compat_snapshot())
    return snapshot


def _ccc_last_updated_iso():
    """ISO-8601 timestamp of the most recent change to this install.

    Prefers `git log -1 --format=%cI HEAD` so a fresh `git pull` (or
    self-update) reflects immediately, even when no source file mtime
    changed. Falls back to server.py mtime when git is unavailable
    (e.g. zip install). Returns "" on total failure.
    """
    try:
        out = subprocess.check_output(
            ["git", "-C", str(_install_dir()), "log", "-1", "--format=%cI", "HEAD"],
            stderr=subprocess.DEVNULL,
            timeout=2,
        ).decode("utf-8", "replace").strip()
        if out:
            return out
    except Exception:
        pass
    try:
        import datetime as _dt
        ts = Path(__file__).resolve().stat().st_mtime
        return _dt.datetime.fromtimestamp(ts).astimezone().isoformat()
    except Exception:
        return ""


def _strip_v(tag):
    if not tag:
        return ""
    return tag[1:] if tag.startswith(("v", "V")) else tag


def _semver_tuple(s):
    """Coerce 'X.Y.Z' → (X, Y, Z). Non-numeric chunks → 0. Trailing '-rc1' etc
    is stripped. Used only for the 'is the local behind?' comparison."""
    parts = (s or "").split("-", 1)[0].split(".")
    out = []
    for p in parts[:3]:
        try:
            out.append(int(p))
        except ValueError:
            out.append(0)
    while len(out) < 3:
        out.append(0)
    return tuple(out)


def _fetch_latest_release():
    """Hit GitHub's latest-release endpoint. Returns dict or raises on failure.
    Stdlib-only — urllib.request. Short timeout so we never hang the UI."""
    url = "https://api.github.com/repos/amirfish1/claude-command-center/releases/latest"
    req = urllib.request.Request(url, headers={
        "User-Agent": f"claude-command-center/{__version__}",
        "Accept": "application/vnd.github+json",
    })
    with urllib.request.urlopen(req, timeout=5) as resp:
        return json.loads(resp.read().decode("utf-8"))


def _version_check(force=False):
    """Return {ok, current, latest, behind, changelog_url} for the UI.
    Caches for 6h to stay well under GitHub's unauthenticated rate limit.
    Never raises — network / parse errors come back as {ok:false, error}."""
    now = time.time()
    if not force and _VERSION_CHECK_CACHE["data"] and (now - _VERSION_CHECK_CACHE["ts"]) < _VERSION_CHECK_TTL:
        return _VERSION_CHECK_CACHE["data"]
    try:
        rel = _fetch_latest_release()
    except Exception as e:
        # 404 (no releases yet), network error, timeout, JSON error — all
        # handled identically: surface to the client, keep the server up.
        data = {"ok": False, "current": __version__, "error": str(e)}
        _VERSION_CHECK_CACHE["data"] = data
        _VERSION_CHECK_CACHE["ts"] = now
        return data
    latest = _strip_v(rel.get("tag_name") or "")
    current = __version__
    behind = _semver_tuple(current) < _semver_tuple(latest) if latest else False
    changelog_url = (
        f"https://github.com/amirfish1/claude-command-center/compare/"
        f"v{current}...v{latest}"
    ) if behind else (rel.get("html_url") or "")
    data = {
        "ok": True,
        "current": current,
        "latest": latest,
        "behind": behind,
        "changelog_url": changelog_url,
    }
    _VERSION_CHECK_CACHE["data"] = data
    _VERSION_CHECK_CACHE["ts"] = now
    return data


def _git(args, cwd, timeout=10):
    """Run `git <args>` in cwd. Returns (rc, stdout, stderr) — stderr trimmed."""
    try:
        r = subprocess.run(
            ["git"] + list(args),
            cwd=str(cwd),
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        return r.returncode, r.stdout, (r.stderr or "").strip()
    except FileNotFoundError:
        return 127, "", "git not found on PATH"
    except subprocess.TimeoutExpired:
        return 124, "", f"git {' '.join(args)} timed out"


# ── The WatchTower half of "check for updates" ─────────────────────────
# CCC and WatchTower are one system with two checkouts: CCC does
# `import watchtower.queue` in-process and shells out to `wt`, so pulling
# CCC's own tree alone leaves the queue engine — the thing that actually
# dispatches workers — on whatever revision it was installed at. The button
# whose entire purpose is "bring me up to date" would leave half the system
# stale.
#
# The spec's restart order, all three steps load-bearing:
#   1. update WatchTower — via scripts/install-watchtower.sh, the single
#      shared implementation every launch path already uses.
#   2. `wt stop` && `wt start` — the daemon is a long-lived process that
#      loaded watchtower.* at launch and keeps executing the code it read
#      then. Skip this and step 1 is a silent no-op: new code on disk, old
#      code reconciling the queue.
#   3. restart CCC — done by the caller via _schedule_restart(); server.py
#      memoises its WatchTower capability probes (_WT_IMPORT_AVAILABLE_CACHE)
#      for the process lifetime, so a WatchTower that just gained `wt import`
#      stays invisible until the process is replaced.
#
# Nothing in steps 1–2 is fatal. A WatchTower failure degrades the update to
# "CCC moved, WT did not", which is exactly what this button did before.

# The installer is fast in the common case (already importable -> a
# `git pull --ff-only`), but a cold clone + `pip install -e` on a fresh
# machine is not. This runs on the request thread with the client waiting on
# the response, so the ceiling is "slow but still a UI", not "however long
# pip wants".
_WT_UPDATE_TIMEOUT = 180
_WT_DAEMON_TIMEOUT = 30
_WT_WORKERS_PROBE_TIMEOUT = 10


def _watchtower_install_script():
    """Path to the shared install/update script, or None when this install
    predates it. It ships in the same clone as server.py, so it is only
    missing on a partial checkout or on an older CCC that has just pulled but
    is still running the previous process's code."""
    p = _install_dir() / "scripts" / "install-watchtower.sh"
    return p if p.is_file() else None


def _wt_live_workers():
    """Live WatchTower workers, as [{worker_id, queue}, ...]. Empty = nobody
    is mid-ticket and the daemon is safe to bounce.

    Asks `wt workers --json` first: WatchTower owns worker liveness (its own
    pruning and reap rules decide what "live" means), and this must not
    second-guess it. Falls back to workers.json — which `_wt_read_workers`
    already filters on real os.kill liveness — when `wt` is not on PATH.

    Deliberately not `_wt_cli_available()`: that memoises the lookup for the
    process lifetime, and the update we are in the middle of is precisely the
    event that can make `wt` appear."""
    rows = None
    wt_cli = _find_wt_cli()
    if wt_cli:
        try:
            proc = subprocess.run(
                [wt_cli, "workers", "--json"],
                capture_output=True, text=True, timeout=_WT_WORKERS_PROBE_TIMEOUT,
            )
            if proc.returncode == 0:
                parsed = json.loads(proc.stdout or "[]")
                if isinstance(parsed, list):
                    rows = parsed
        except (OSError, ValueError, subprocess.TimeoutExpired):
            rows = None
    if rows is None:
        rows = _wt_read_workers()
    out = []
    for w in rows:
        if not isinstance(w, dict) or not w.get("alive"):
            continue
        out.append({
            "worker_id": str(w.get("worker_id") or ""),
            "queue": str(w.get("queue") or ""),
        })
    return out


def _update_watchtower():
    """Step 1: refresh WatchTower through scripts/install-watchtower.sh.

    Returns {ok, ...}; never raises. `skipped` marks "this install has no
    installer script", which is a degrade and not a failure."""
    script = _watchtower_install_script()
    if script is None:
        return {
            "ok": False, "skipped": True,
            "reason": "scripts/install-watchtower.sh not present in this install",
        }
    env = dict(os.environ)
    # The user just explicitly asked to be brought up to date. That outranks
    # the installer's once-a-day back-off, which exists to keep CCC restarts
    # from becoming a network call per restart.
    env["CCC_WATCHTOWER_FORCE"] = "1"
    # We bounce the daemon ourselves below, and only when no worker is
    # mid-ticket. Letting the script run `wt start` here would just start the
    # daemon on the old code we are about to stop.
    env["CCC_SKIP_WATCHTOWER_DAEMON"] = "1"
    # Install into the interpreter running server.py, not whatever `python3`
    # resolves to: CCC needs the importable library in *this* process, which
    # is the same reason the installer refuses pipx.
    env.setdefault("CCC_PYTHON", sys.executable or "python3")
    try:
        # Invoked through `bash` rather than executed directly so a checkout
        # that lost the exec bit (zip/DMG extraction) still works.
        proc = subprocess.run(
            ["bash", str(script)],
            cwd=str(_install_dir()), env=env,
            capture_output=True, text=True, timeout=_WT_UPDATE_TIMEOUT,
        )
    except (OSError, subprocess.TimeoutExpired) as e:
        return {"ok": False, "error": str(e) or e.__class__.__name__}
    # The script narrates what it did on stdout; the tail is what a user needs
    # to see when it went wrong ("python 3.9 is below the 3.11 minimum", etc).
    log = [ln for ln in (proc.stdout or "").splitlines() if ln.strip()][-10:]
    if proc.returncode != 0:
        err = (proc.stderr or "").strip()[:400]
        return {"ok": False, "error": err or f"installer exited {proc.returncode}",
                "log": log}
    return {"ok": True, "log": log}


def _restart_wt_daemon():
    """Step 2: `wt stop` then `wt start`.

    Prefers the `wt` binary and falls back to the module form, because `wt`
    lands in the user scripts dir and that is routinely off PATH — the
    library is importable either way, and it is by construction the same
    interpreter CCC runs on."""
    wt = _wt_cli_path()
    base = [wt] if wt else [sys.executable or "python3", "-m", "watchtower.cli"]
    steps = {}
    for step in ("stop", "start"):
        try:
            proc = subprocess.run(
                base + [step], capture_output=True, text=True,
                timeout=_WT_DAEMON_TIMEOUT,
            )
        except (OSError, subprocess.TimeoutExpired) as e:
            steps[step] = str(e) or e.__class__.__name__
            return {"ok": False, "error": f"wt {step}: {steps[step]}", "steps": steps}
        steps[step] = proc.returncode
    # `stop` against an already-stopped daemon is a no-op that may still exit
    # non-zero; `start` is the step that has to succeed for the new code to be
    # the code that runs.
    if steps.get("start") != 0:
        return {"ok": False, "error": f"wt start exited {steps.get('start')}",
                "steps": steps}
    return {"ok": True, "steps": steps}


def _self_update():
    """Run the pre-flight + pull, then bring WatchTower up with it. Returns a
    response dict; the caller is responsible for writing it to the client
    BEFORE the restart fires."""
    d = _install_dir()
    if not (d / ".git").exists():
        return {"ok": False, "error": "not a git clone", "install_dir": str(d)}
    rc, out, err = _git(["status", "--porcelain"], d)
    if rc != 0:
        return {"ok": False, "error": f"git status failed: {err or 'rc={}'.format(rc)}"}
    if out.strip():
        paths = [ln[3:] for ln in out.splitlines() if len(ln) > 3]
        return {"ok": False, "error": "local changes present", "paths": paths}
    rc, branch, err = _git(["rev-parse", "--abbrev-ref", "HEAD"], d)
    if rc != 0:
        return {"ok": False, "error": f"git rev-parse failed: {err or 'rc={}'.format(rc)}"}
    branch = branch.strip()
    if branch != "main":
        return {"ok": False, "error": f"on branch {branch!r}, not main"}
    rc, _, err = _git(["fetch", "origin", "--quiet"], d, timeout=30)
    if rc != 0:
        return {"ok": False, "error": f"git fetch failed: {err or 'rc={}'.format(rc)}"}
    rc, _, err = _git(["reset", "--hard", "origin/main", "--quiet"], d)
    if rc != 0:
        return {"ok": False, "error": f"git reset failed: {err or 'rc={}'.format(rc)}"}
    rc, sha, _ = _git(["rev-parse", "HEAD"], d)
    # Bust the 6h cache so the post-restart UI reads fresh latest/current.
    _VERSION_CHECK_CACHE["ts"] = 0.0
    _VERSION_CHECK_CACHE["data"] = None
    result = {"ok": True, "new_sha": (sha or "").strip()}

    # The dashboard restarts via os.execvp, which bypasses run.sh's
    # ensure_worker_current gate -- so the modal update path does its own
    # stale-worker check here, while the freshly-pulled code is on disk.
    result["worker"] = _restart_stale_worker()
    if result["worker"].get("restarted"):
        print(
            f"  [self-update] worker restarted ({result['worker'].get('via')}): "
            f"was {result['worker'].get('was') or 'pre-version-reporting'}, "
            f"now {result['worker'].get('now')}"
        )

    # CCC's own tree is current. Now the other half of the system — see the
    # restart-order note above. Both sub-results are reported, never raised:
    # the CCC pull already succeeded and must not be reported as a failure
    # because WatchTower could not be reached.
    result["watchtower"] = _update_watchtower()
    if not result["watchtower"].get("ok"):
        # The client reloads onto the new CCC seconds from now, so the
        # response is a poor place to be read carefully. The terminal log
        # outlives it.
        print("  [self-update] WatchTower not refreshed: "
              f"{result['watchtower'].get('error') or result['watchtower'].get('reason')}")
    live = _wt_live_workers()
    if live:
        # `wt stop` takes the watcher down along with the workers it
        # supervises. Killing an agent mid-ticket loses its uncommitted work
        # and leaves the ticket claimed-but-abandoned, which is strictly worse
        # than a daemon running yesterday's code for another hour. Defer, and
        # say so — the next quiet restart (or the user) picks it up.
        result["wt_daemon"] = {
            "ok": True, "deferred": True,
            "reason": f"{len(live)} WatchTower worker(s) still running — "
                      "daemon restart deferred so nothing is killed mid-ticket",
            "workers": live[:10],
        }
        print(f"  [self-update] {result['wt_daemon']['reason']}")
    else:
        result["wt_daemon"] = _restart_wt_daemon()

    # Step 3 is the caller's os.execvp, which is what genuinely clears the
    # capability memos. Clear them here too so this process is not left
    # asserting a stale answer if that restart never fires.
    _reset_wt_capability_caches()
    return result


# ── In-app bug reporting ───────────────────────────────────────────────
# The UI surfaces a "Report a bug" link in the topbar that opens a small
# modal (title + description + auto-collected context). On submit, the
# client posts to /api/bug-report; the handler shells out to `gh issue
# create` against amirfish1/claude-command-center. If `gh` isn't
# available we return the rendered markdown so the UI can offer a
# copy-to-clipboard fallback for manual filing.
_BUG_REPORT_REPO = "amirfish1/claude-command-center"
# Screenshot support (macOS only): the modal can capture an area screenshot
# via `screencapture -i`, which is then committed to a dedicated public
# branch (`bug-screenshots`) of this repo so the issue body can render the
# image inline via raw.githubusercontent.com. If the push fails (random OSS
# user without write access) we keep the local copy and tell the user to
# drag-drop manually. The local save ALWAYS happens first so the image is
# never lost regardless of upload outcome.
_BUG_SCREENSHOT_DIR = Path.home() / ".claude" / "command-center" / "bug-screenshots"
_BUG_SCREENSHOT_WT = Path.home() / ".claude" / "command-center" / "bug-screenshots-wt"
_BUG_SCREENSHOT_BRANCH = "bug-screenshots"
_PRIVATE_SUPPORT_ENDPOINT = (
    "https://support.claude-command-center.workers.dev/v1/report"
)
_UUID4_RE = re.compile(
    r"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
)
_REPORT_ID_RE = re.compile(r"^RPT-[0-9A-F]{8}$")


def _send_private_diagnostic(payload, endpoint=None):
    """Validate and relay exactly the report text the user reviewed."""
    allowed = {"schema_version", "request_id", "ccc_version", "report_text"}
    if not isinstance(payload, dict) or set(payload) != allowed:
        return {"ok": False, "error": "invalid diagnostic envelope"}
    request_id = str(payload.get("request_id") or "").lower()
    report_text = payload.get("report_text")
    if payload.get("schema_version") != 1 or not _UUID4_RE.fullmatch(request_id):
        return {"ok": False, "error": "invalid diagnostic envelope"}
    if (not isinstance(report_text, str) or not report_text.strip()
            or len(report_text) > _DIAGNOSTIC_TEXT_MAX_CHARS):
        return {
            "ok": False,
            "error": "diagnostic text must be 1 to 48000 characters",
        }
    outbound = {
        "schema_version": 1,
        "request_id": request_id,
        "ccc_version": str(payload.get("ccc_version") or ""),
        "report_text": report_text,
    }
    target = (
        endpoint or os.environ.get("CCC_PRIVATE_SUPPORT_ENDPOINT")
        or _PRIVATE_SUPPORT_ENDPOINT
    )
    request = urllib.request.Request(
        target,
        data=json.dumps(outbound).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            result = json.loads(response.read(4096))
    except urllib.error.HTTPError as error:
        return {
            "ok": False,
            "error": "private support rejected the report (HTTP %d)" % error.code,
        }
    except (urllib.error.URLError, TimeoutError, ValueError) as error:
        return {
            "ok": False,
            "error": "private support is unavailable: %s" % error,
        }
    report_id = str(result.get("report_id") or "") if isinstance(result, dict) else ""
    if not isinstance(result, dict) or result.get("ok") is not True or not _REPORT_ID_RE.fullmatch(report_id):
        return {
            "ok": False,
            "error": "private support returned an invalid response",
        }
    return {"ok": True, "report_id": report_id}


def _build_bug_report_body(description, ccc_version, user_agent, session_id,
                           screenshot_url=None, screenshot_local_path=None,
                           reporter_name=None, reporter_contact=None):
    """Render the GitHub issue body (markdown). Pure — no I/O — so it's
    cheap to also return on the failure path for clipboard fallback.

    Screenshot rendering: if `screenshot_url` is given we embed it as an
    inline image (the happy path — image was pushed to the bug-screenshots
    branch). Otherwise if `screenshot_local_path` is given we surface the
    local path with a drag-drop instruction so the user can manually
    attach it to the issue after it's filed.

    `reporter_name` / `reporter_contact` are optional self-identification
    from the modal; when either is present a single ``Reporter:`` line is
    added after the Context table. Callers must sanitize them first (see
    `_create_bug_report_issue`)."""
    lines = [
        "## Description",
        "",
        description.strip(),
        "",
    ]
    if screenshot_url:
        lines += [
            "## Screenshot",
            "",
            f"![screenshot]({screenshot_url})",
            "",
        ]
    elif screenshot_local_path:
        lines += [
            "## Screenshot",
            "",
            f"📎 Saved locally at `{screenshot_local_path}`. After this issue "
            "opens, drag the file into a comment to attach it.",
            "",
        ]
    lines += [
        "## Context",
        "",
        "| Field | Value |",
        "|---|---|",
        f"| **CCC version** | `{ccc_version or '-'}` |",
        f"| **Session** | `{session_id or '-'}` |",
        f"| **User agent** | `{user_agent or '-'}` |",
        "",
    ]
    if reporter_name or reporter_contact:
        reporter = f"Reporter: {reporter_name or ''}"
        if reporter_contact:
            reporter += (" " if reporter_name else "") + f"({reporter_contact})"
        lines += [reporter, ""]
    lines += [
        "_Reported via the in-app Report a bug feature._",
    ]
    return "\n".join(lines)


def _sanitize_reporter_field(value):
    """Clamp a free-text reporter field for safe markdown embedding:
    string-coerce, strip newlines/control chars (they would break the
    single-line ``Reporter:`` format), cap at 200 chars."""
    if not isinstance(value, str):
        return ""
    cleaned = "".join(ch for ch in value if ch == " " or (ch.isprintable() and not ch.isspace()))
    return cleaned.strip()[:200]


def _resolve_screencapture_bin():
    """Locate the macOS `screencapture` binary.

    On every Mac the binary lives at /usr/sbin/screencapture, but /usr/sbin
    is missing from PATH when CCC is launched outside a login shell (e.g.
    by launchd, or by Claude Code itself). Prefer the absolute path; fall
    back to PATH lookup for non-standard installs.

    Returns the absolute path string, or None if the binary truly isn't
    on the system.
    """
    fixed = "/usr/sbin/screencapture"
    if os.path.isfile(fixed) and os.access(fixed, os.X_OK):
        return fixed
    return shutil.which("screencapture")


def _capture_screenshot_native(timeout=120):
    """Trigger the macOS area-screenshot picker (`screencapture -i`) and
    return the resulting PNG as base64. Blocks until the user finishes
    drawing the rectangle, presses Esc to cancel, or `timeout` elapses.

    Returns one of:
      {ok: True,  image_b64: "...", mime: "image/png", path: "/tmp/..."}
      {ok: False, cancelled: True}                  — user pressed Esc
      {ok: False, error: "..."}                     — non-mac, timeout, etc.

    macOS-only: `screencapture` is a shipped system tool. On other OSes we
    return an explanatory error so the UI can hide / explain the feature.
    """
    if platform.system() != "Darwin":
        _log_macos_only("screenshots")
        return {"ok": False, "error": "Screenshots are macOS-only."}
    screencapture_bin = _resolve_screencapture_bin()
    if not screencapture_bin:
        # Should be unreachable on a real Mac (`/usr/sbin/screencapture` is
        # shipped with the OS), but surface a friendly error if a stripped
        # install or a hardened sandbox really is missing it.
        return {"ok": False, "error": "`screencapture` not found - is this a full macOS install?"}
    # NamedTemporaryFile(delete=False) so screencapture (a separate process)
    # can write to the path; we reap it ourselves once we've base64-encoded.
    tmp = tempfile.NamedTemporaryFile(prefix="ccc-bug-", suffix=".png", delete=False)
    tmp_path = tmp.name
    tmp.close()
    try:
        # `-i` is interactive: shows the crosshair / area-selector overlay.
        # `-x` suppresses the camera-shutter sound so this isn't disruptive
        # in a quiet office. The user draws an area; on Esc the file is left
        # zero-bytes and screencapture exits 0.
        try:
            proc = subprocess.run(
                [screencapture_bin, "-i", "-x", tmp_path],
                capture_output=True, text=True, timeout=timeout,
            )
        except subprocess.TimeoutExpired:
            return {"ok": False, "error": f"screencapture timed out after {timeout}s"}
        if proc.returncode != 0:
            err = (proc.stderr or proc.stdout or "").strip()[:200]
            return {"ok": False, "error": err or f"screencapture exited {proc.returncode}"}
        try:
            data = Path(tmp_path).read_bytes()
        except OSError as e:
            return {"ok": False, "error": f"could not read capture: {e}"}
        # Esc / cancel leaves a zero-byte file behind. Treat as cancellation.
        if not data:
            return {"ok": False, "cancelled": True}
        return {
            "ok": True,
            "image_b64": base64.b64encode(data).decode("ascii"),
            "mime": "image/png",
            "path": tmp_path,
            "bytes": len(data),
        }
    finally:
        # The client got the bytes inline; the temp file is no longer
        # needed. Best-effort cleanup so /tmp doesn't fill up over time.
        try:
            os.unlink(tmp_path)
        except OSError:
            pass


def _save_screenshot_locally(image_b64):
    """Decode `image_b64` and write to ~/.claude/command-center/bug-screenshots/.
    Returns the absolute path on success, or raises ValueError on bad input.
    Called on the bug-report submission path BEFORE the upload attempt so
    the screenshot survives even if everything else fails."""
    try:
        raw = base64.b64decode(image_b64, validate=True)
    except (ValueError, TypeError) as e:
        raise ValueError(f"invalid base64: {e}") from e
    if not raw:
        raise ValueError("empty screenshot")
    _BUG_SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
    # Filename: timestamp + short random suffix so back-to-back submissions
    # in the same second don't collide.
    fname = f"bug-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{os.urandom(3).hex()}.png"
    out = _BUG_SCREENSHOT_DIR / fname
    out.write_bytes(raw)
    return str(out)


def _github_owner_repo_from_url(url):
    # Match git@github.com:owner/repo(.git) and https://github.com/owner/repo(.git).
    m = re.match(r"^git@github\.com:([^/]+)/([^/]+?)(?:\.git)?$", url)
    if not m:
        m = re.match(r"^https?://github\.com/([^/]+)/([^/]+?)(?:\.git)?/?$", url)
    if not m:
        return None
    return (m.group(1), m.group(2))


def _origin_owner_repo():
    """Return (owner, repo) parsed from the install dir's `origin` remote, or
    None if the dir isn't a clone or the URL doesn't look like GitHub.
    Used to build the raw.githubusercontent.com URL for embedded screenshots
    AND to derive the push URL for the bug-screenshots branch."""
    rc, out, _ = _git(["remote", "get-url", "origin"], _install_dir())
    if rc != 0:
        return None
    return _github_owner_repo_from_url(out.strip())


_GITHUB_OWNER_LOGIN_CACHE = {"ts": 0.0, "owners": set()}
_GITHUB_OWNER_LOGIN_TTL = 300.0


def _github_owner_login_candidates():
    """GitHub owners considered "mine" for all-repo issue/PR feeds.

    Prefer explicit configuration and the authenticated `gh` login. Fall back
    to this install's origin owner so OSS/source installs still get a narrow
    feed without hardcoding a username in the public repo.
    """
    now = time.time()
    cached = _GITHUB_OWNER_LOGIN_CACHE.get("owners") or set()
    if cached and (now - float(_GITHUB_OWNER_LOGIN_CACHE.get("ts") or 0)) < _GITHUB_OWNER_LOGIN_TTL:
        return set(cached)
    owners = set()
    raw_env = os.environ.get("CCC_GITHUB_OWNERS") or os.environ.get("CCC_GITHUB_OWNER") or ""
    for part in raw_env.replace(";", ",").split(","):
        p = part.strip().lower()
        if p:
            owners.add(p)
    try:
        r = subprocess.run(
            ["gh", "api", "user", "--jq", ".login"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if r.returncode == 0 and r.stdout.strip():
            owners.add(r.stdout.strip().lower())
    except (OSError, subprocess.SubprocessError):
        pass
    origin = _origin_owner_repo()
    if origin and origin[0]:
        owners.add(str(origin[0]).lower())
    _GITHUB_OWNER_LOGIN_CACHE["owners"] = set(owners)
    _GITHUB_OWNER_LOGIN_CACHE["ts"] = now
    return owners


def _github_repo_owner_for_path(repo_path):
    """Return the GitHub origin owner for a local repo path, or ''."""
    try:
        p = Path(repo_path).expanduser().resolve()
    except (OSError, ValueError, RuntimeError):
        return ""
    if not p.is_dir():
        return ""
    rc, out, _ = _git(["remote", "get-url", "origin"], p, timeout=3)
    if rc != 0:
        return ""
    parsed = _github_owner_repo_from_url(out.strip())
    return (parsed[0] if parsed else "") or ""


def _push_screenshot_to_branch(local_path, commit_subject):
    """Copy `local_path` into the bug-screenshots scratch worktree, commit,
    and push. Returns one of:
      {ok: True,  raw_url: "https://raw.githubusercontent.com/.../<file>"}
      {ok: False, error: "..."}

    The scratch worktree at ~/.claude/command-center/bug-screenshots-wt/
    is reused across runs. On first run the `bug-screenshots` branch
    doesn't exist on origin so we create it as an orphan (no parent
    commits — keeps it clean of main's history)."""
    install = _install_dir()
    rc, origin_url, err = _git(["remote", "get-url", "origin"], install)
    if rc != 0:
        return {"ok": False, "error": f"no origin remote: {err or 'rc={}'.format(rc)}"}
    origin_url = origin_url.strip()
    owner_repo = _origin_owner_repo()
    if not owner_repo:
        return {"ok": False, "error": f"origin URL not recognised as GitHub: {origin_url}"}
    owner, repo = owner_repo

    wt = _BUG_SCREENSHOT_WT
    # Always rebuild the scratch dir if it isn't a healthy git clone — this
    # keeps the logic dead-simple and avoids subtle stuck-state bugs (e.g.
    # half-applied orphan switch from a prior crashed run). The cost is one
    # extra `git init` + fetch per submission, which is negligible.
    if not (wt / ".git").is_dir():
        shutil.rmtree(wt, ignore_errors=True)
        wt.mkdir(parents=True, exist_ok=True)
        rc, _, err = _git(["init", "--quiet", "-b", "main"], wt)
        if rc != 0:
            # Older git without -b flag — retry without it.
            shutil.rmtree(wt, ignore_errors=True)
            wt.mkdir(parents=True, exist_ok=True)
            rc, _, err = _git(["init", "--quiet"], wt)
            if rc != 0:
                return {"ok": False, "error": f"git init failed: {err}"}
        rc, _, err = _git(["remote", "add", "origin", origin_url], wt)
        if rc != 0:
            return {"ok": False, "error": f"git remote add failed: {err}"}

    # Try to fetch the existing bug-screenshots branch. If origin doesn't
    # have it yet (first push ever), we'll create it as an orphan below.
    rc, _, fetch_err = _git(
        ["fetch", "origin", _BUG_SCREENSHOT_BRANCH, "--quiet"], wt, timeout=30,
    )
    branch_on_origin = (rc == 0)

    if branch_on_origin:
        # Hard-reset to remote so we don't accumulate junk commits locally
        # when the user submits multiple bug reports.
        rc, _, err = _git(
            ["checkout", "-B", _BUG_SCREENSHOT_BRANCH,
             f"origin/{_BUG_SCREENSHOT_BRANCH}", "--quiet"], wt,
        )
        if rc != 0:
            return {"ok": False, "error": f"checkout bug-screenshots failed: {err}"}
    else:
        # First-ever push: create the branch as an orphan so its history is
        # independent from main. Wipe any tracked files left over from a
        # previous half-baked run (`git switch --orphan` doesn't touch the
        # working tree).
        rc, _, err = _git(["switch", "--orphan", _BUG_SCREENSHOT_BRANCH], wt)
        if rc != 0:
            # `git switch` requires git 2.23+. On ancient git fall back to
            # the symbolic-ref + rm-cached dance.
            rc, _, err = _git(
                ["symbolic-ref", "HEAD", f"refs/heads/{_BUG_SCREENSHOT_BRANCH}"], wt,
            )
            if rc != 0:
                return {"ok": False, "error": f"orphan branch create failed: {err}"}
            # Drop any stale index entries so the orphan starts empty.
            _git(["rm", "-rf", "--cached", "--quiet", "."], wt)
        # Clean the working tree of any leftover files (other than .git).
        for entry in wt.iterdir():
            if entry.name == ".git":
                continue
            try:
                if entry.is_dir():
                    shutil.rmtree(entry)
                else:
                    entry.unlink()
            except OSError:
                pass

    # Configure local user/email for the commit so this works on a fresh
    # box without ~/.gitconfig user.email set. Safe scope: --local only
    # touches this scratch dir's .git/config, never global config.
    _git(["config", "--local", "user.name", "Command Center"], wt)
    _git(["config", "--local", "user.email", "ccc-bug-report@localhost"], wt)

    # Copy the screenshot in under its basename and stage it explicitly —
    # never `git add -A`, both because of the multi-agent rule and because
    # we want to be defensive about anything else lingering in the WT.
    fname = Path(local_path).name
    dest = wt / fname
    try:
        shutil.copy2(local_path, dest)
    except OSError as e:
        return {"ok": False, "error": f"copy failed: {e}"}

    rc, _, err = _git(["add", fname], wt)
    if rc != 0:
        return {"ok": False, "error": f"git add failed: {err}"}

    # Cap the commit subject so a pathological title doesn't push the
    # commit message over GitHub's display limits.
    subject = (commit_subject or "screenshot").strip()
    if len(subject) > 100:
        subject = subject[:100].rstrip() + "…"
    rc, _, err = _git(
        ["commit", "-m", f"add screenshot: {subject}", "--quiet"], wt,
    )
    if rc != 0:
        return {"ok": False, "error": f"git commit failed: {err}"}

    rc, _, err = _git(
        ["push", "-u", "origin", _BUG_SCREENSHOT_BRANCH, "--quiet"], wt, timeout=30,
    )
    if rc != 0:
        return {"ok": False, "error": f"git push failed: {err[:300] if err else 'rc={}'.format(rc)}"}

    raw_url = (
        f"https://raw.githubusercontent.com/{owner}/{repo}/"
        f"{_BUG_SCREENSHOT_BRANCH}/{urllib.parse.quote(fname)}"
    )
    return {"ok": True, "raw_url": raw_url, "filename": fname}


def _bug_log(msg):
    """Single-line stderr logger for the bug-report flow. Useful when the
    push succeeds silently but the user-side render looks off — easier to
    grep `[bug-report]` in the server console than to hunt timestamps."""
    print(f"[bug-report] {msg}", file=sys.stderr, flush=True)


def _create_bug_report_issue(payload):
    """Validate the payload, build a GitHub issue, file it via `gh`.

    Returns one of:
      {ok: True,  url: ".../issues/N", number: N,
       screenshot_needs_manual?: True, screenshot_path?: "<abs>"}
      {ok: False, error: "...",  markdown: "..."}   # gh missing / failed
      {ok: False, error: "..."}                     # validation failure
    The `markdown` key on the failure path lets the client offer a
    copy-to-clipboard fallback so the user can file it manually.

    Optional `screenshot_b64` field: PNG bytes (base64, no data: prefix).
    Always saved locally first; then we try to push to the bug-screenshots
    branch for inline rendering. On push failure the issue body falls back
    to the local path + drag-drop instructions, and the response carries
    `screenshot_needs_manual=true` so the client can `open -R` the file
    and surface the issue URL for manual attachment.

    Optional `reporter_name` / `reporter_contact` fields: free-text
    self-identification, sanitized and rendered as a `Reporter:` line in
    the issue body when present.
    """
    # The modal collapsed Title+Description into a single Details field, so
    # we derive the issue title from the first non-empty line. We still
    # accept an explicit `title` from older clients / programmatic callers.
    description = (payload.get("description") or "").strip()
    if not description:
        return {"ok": False, "error": "details are required"}
    title = (payload.get("title") or "").strip()
    if not title:
        for line in description.splitlines():
            candidate = line.strip()
            if candidate:
                title = candidate
                break
    if not title:
        # Should be unreachable because `description` is non-empty above,
        # but guard anyway so we never ship an empty title to gh.
        return {"ok": False, "error": "details are required"}
    # Cap title at a friendly length so the GitHub issue list stays readable.
    # GitHub itself accepts 256 chars; 120 keeps things tidy.
    if len(title) > 120:
        title = title[:120].rstrip() + "…"

    ccc_version = (payload.get("ccc_version") or "").strip() or __version__
    user_agent = (payload.get("user_agent") or "").strip()
    session_id = (payload.get("session_id") or "").strip()
    # Optional self-identification from the modal — sanitized to a single
    # short line before it goes anywhere near the markdown body.
    reporter_name = _sanitize_reporter_field(payload.get("reporter_name"))
    reporter_contact = _sanitize_reporter_field(payload.get("reporter_contact"))

    # ── Screenshot pre-flight ──
    # Save first (always), then try to push, then build the body. The
    # `screenshot_*` locals stay None when no image was supplied so the
    # body builder skips the screenshot section entirely.
    screenshot_b64 = (payload.get("screenshot_b64") or "").strip()
    screenshot_local_path = None
    screenshot_url = None
    screenshot_needs_manual = False
    if screenshot_b64:
        try:
            screenshot_local_path = _save_screenshot_locally(screenshot_b64)
            _bug_log(f"screenshot saved locally at {screenshot_local_path}")
        except ValueError as e:
            # Bad base64 isn't fatal — we just skip the screenshot section
            # so the bug report itself still gets filed. Log loudly so the
            # client-side bug is findable.
            _bug_log(f"screenshot decode failed, skipping: {e}")
            screenshot_local_path = None
        if screenshot_local_path:
            push = _push_screenshot_to_branch(screenshot_local_path, title)
            if push.get("ok"):
                screenshot_url = push["raw_url"]
                _bug_log(f"screenshot pushed: {screenshot_url}")
            else:
                screenshot_needs_manual = True
                _bug_log(f"screenshot push failed, using local fallback: {push.get('error')}")

    body = _build_bug_report_body(
        description, ccc_version, user_agent, session_id,
        screenshot_url=screenshot_url,
        screenshot_local_path=screenshot_local_path if screenshot_needs_manual else None,
        reporter_name=reporter_name,
        reporter_contact=reporter_contact,
    )
    fallback_md = f"## {title}\n\n{body}"

    if not _which("gh"):
        return {
            "ok": False,
            "error": "gh CLI not found on PATH - copy the markdown and file the issue manually.",
            "markdown": fallback_md,
            "repo_url": f"https://github.com/{_BUG_REPORT_REPO}/issues/new",
            "screenshot_path": screenshot_local_path,
        }

    try:
        # `gh issue create` prints the issue URL on stdout when it succeeds.
        # We pipe body via --body-file=- so we don't have to worry about
        # arbitrary user input being interpreted by the shell — there is
        # no shell (subprocess.run with a list).
        proc = subprocess.run(
            ["gh", "issue", "create",
             "-R", _BUG_REPORT_REPO,
             "--label", "bug",
             "--title", title,
             "--body-file", "-"],
            input=body,
            capture_output=True, text=True, timeout=20,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "gh issue create timed out", "markdown": fallback_md,
                "screenshot_path": screenshot_local_path}
    except (OSError, subprocess.SubprocessError) as e:
        return {"ok": False, "error": f"gh failed to launch: {e}", "markdown": fallback_md,
                "screenshot_path": screenshot_local_path}

    if proc.returncode != 0:
        err = (proc.stderr or proc.stdout or "").strip()[:400]
        return {
            "ok": False,
            "error": err or f"gh issue create exited {proc.returncode}",
            "markdown": fallback_md,
            "repo_url": f"https://github.com/{_BUG_REPORT_REPO}/issues/new",
            "screenshot_path": screenshot_local_path,
        }

    url = (proc.stdout or "").strip().splitlines()[-1] if proc.stdout else ""
    number = None
    m = re.search(r"/issues/(\d+)", url)
    if m:
        number = int(m.group(1))
    result = {"ok": True, "url": url, "number": number}
    if screenshot_needs_manual and screenshot_local_path:
        result["screenshot_needs_manual"] = True
        result["screenshot_path"] = screenshot_local_path
    return result


def _reveal_bug_screenshot(path_str):
    """Reveal `path_str` in Finder via `open -R`. Sandbox-clamped to the
    bug-screenshots dir so this can't be abused to reveal arbitrary files.
    Used by the manual-attach fallback after the issue is filed."""
    if platform.system() != "Darwin":
        _log_macos_only("revealFile")
        return {"ok": False, "error": "macOS-only"}
    if not path_str:
        return {"ok": False, "error": "missing path"}
    try:
        rp = Path(path_str).expanduser().resolve(strict=False)
        root = _BUG_SCREENSHOT_DIR.resolve()
    except OSError as e:
        return {"ok": False, "error": str(e)}
    if not (str(rp).startswith(str(root) + os.sep) or rp == root):
        return {"ok": False, "error": "path outside bug-screenshots sandbox"}
    if not rp.exists():
        return {"ok": False, "error": "file not found", "path": str(rp)}
    try:
        subprocess.Popen(["open", "-R", str(rp)])
        return {"ok": True, "path": str(rp)}
    except OSError as e:
        return {"ok": False, "error": str(e)}


# ── Page annotations ───────────────────────────────────────────────────
# Local-only notes created from the browser overlay. Each annotation stores
# the user's note plus enough page/element/viewport anchors for a later agent
# to reopen the page and inspect the same visual area.

_LONE_SURROGATE_RE = re.compile("[{}-{}]".format(chr(0xD800), chr(0xDFFF)))


def _strip_lone_surrogates(s):
    """Remove unpaired UTF-16 surrogate code points (U+D800..U+DFFF).

    JS strings are UTF-16; the browser's clipboard / pasted-image / selection
    APIs can leave a lone high or low surrogate in the payload sent to
    /api/annotations (or any other text field). Python stores those as-is
    in `str`, but `json.dumps` happily serialises them, and the Anthropic
    API rejects the resulting request with
        "API Error: 400 The request body is not valid JSON:
         no low surrogate in string: line 1 column N (char N)"
    Strip the unpaired code points at the boundary so downstream injection
    paths can never feed broken UTF-16 into the API. Paired surrogates
    (i.e. real astral-plane chars like emoji) are already collapsed into
    a single Python code point above U+FFFF and do not match this regex.
    """
    if not s:
        return s
    return _LONE_SURROGATE_RE.sub("", s)


def _strip_spawn_payload_surrogates(payload):
    """Drop unpaired UTF-16 surrogates from every string in a spawn payload.

    Browser callers build spawn names/prompts by manipulating UTF-16 JS
    strings; an emoji cut mid-pair arrives as a lone surrogate that
    ``json.loads`` keeps, and the next strict UTF-8 encode downstream
    (control-plane socket write, engine stdin, sqlite store) then raises
    ``UnicodeEncodeError: surrogates not allowed`` — killing the spawn before
    any registry row exists (OPS-935). Strip them at the HTTP boundary so the
    effective spawn request is always encodable.
    """
    def _clean(value):
        if isinstance(value, str):
            return _strip_lone_surrogates(value)
        if isinstance(value, dict):
            return {key: _clean(val) for key, val in value.items()}
        if isinstance(value, list):
            return [_clean(item) for item in value]
        return value
    return _clean(payload)


def _annotation_text(value, max_len=4000):
    s = "" if value is None else str(value)
    s = _strip_lone_surrogates(s).replace("\x00", "").strip()
    if len(s) > max_len:
        return s[:max_len].rstrip() + "…"
    return s


def _annotation_number(value, default=0.0):
    try:
        n = float(value)
    except (TypeError, ValueError):
        return default
    if n != n or n in (float("inf"), float("-inf")):
        return default
    if n < -1000000 or n > 1000000:
        return default
    return round(n, 2)


def _annotation_rect(value):
    raw = value if isinstance(value, dict) else {}
    return {
        "x": _annotation_number(raw.get("x")),
        "y": _annotation_number(raw.get("y")),
        "width": max(0.0, _annotation_number(raw.get("width"))),
        "height": max(0.0, _annotation_number(raw.get("height"))),
    }


def _annotation_screen(value):
    raw = value if isinstance(value, dict) else {}
    screen = _annotation_rect(raw)
    screen["estimated"] = bool(raw.get("estimated"))
    screen["window_screen_x"] = _annotation_number(raw.get("window_screen_x"))
    screen["window_screen_y"] = _annotation_number(raw.get("window_screen_y"))
    screen["outer_width"] = max(0.0, _annotation_number(raw.get("outer_width")))
    screen["outer_height"] = max(0.0, _annotation_number(raw.get("outer_height")))
    screen["chrome_border_x"] = max(0.0, _annotation_number(raw.get("chrome_border_x")))
    screen["chrome_offset_y"] = max(0.0, _annotation_number(raw.get("chrome_offset_y")))
    screen["device_pixel_ratio"] = max(1.0, min(4.0, _annotation_number(raw.get("device_pixel_ratio"), 1.0)))
    return screen


def _annotation_element(value):
    raw = value if isinstance(value, dict) else {}
    return {
        "tag": _annotation_text(raw.get("tag"), 64).lower(),
        "id": _annotation_text(raw.get("id"), 256),
        "role": _annotation_text(raw.get("role"), 128),
        "selector": _annotation_text(raw.get("selector"), 400),
        "href": _annotation_text(raw.get("href"), 400),
        "text": _annotation_text(raw.get("text"), 200),
    }


def _load_annotations():
    try:
        data = json.loads(ANNOTATIONS_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, ValueError):
        return []
    if isinstance(data, dict):
        data = data.get("annotations", [])
    if not isinstance(data, list):
        return []
    return [item for item in data if isinstance(item, dict)]


def _write_annotations(items):
    ANNOTATIONS_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = ANNOTATIONS_FILE.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps({"annotations": items}, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(tmp, ANNOTATIONS_FILE)


def _frontmost_window_bounds_for_capture():
    """Return (bounds_dict, None) or (None, reason) for the frontmost macOS
    window's on-screen bounds (points).

    `id of window` (needed for `screencapture -l <id>`) stopped resolving
    reliably on recent macOS versions for many apps -- not just Electron/
    WebView ones. It fails the same way (AppleEvent -1728) even for a plain
    Terminal.app window that is definitely open and frontmost (OPS-63).
    `position`/`size` of the window remain readable via System Events, so
    capture by absolute screen rect instead of by window id.
    """
    if platform.system() != "Darwin":
        return None, "window capture is macOS-only"
    script = r'''
tell application "System Events"
  tell (first application process whose frontmost is true)
    if (count of windows) is 0 then return ""
    set w to window 1
    set {px, py} to position of w
    set {sw, sh} to size of w
    return (px as string) & "," & (py as string) & "," & (sw as string) & "," & (sh as string)
  end tell
end tell
'''
    # The System Events query races the Window Server around annotate time
    # (the user just clicked something) and can transiently return a stale
    # frontmost app or empty output -- OPS-63 follow-up. A couple of quick
    # retries clears most of these without needing a user-visible fallback.
    last_err = None
    for attempt in range(3):
        if attempt:
            time.sleep(0.15)
        try:
            proc = subprocess.run(
                ["osascript", "-e", script],
                capture_output=True,
                text=True,
                timeout=4,
            )
        except (OSError, subprocess.SubprocessError) as e:
            last_err = f"osascript failed: {e}"
            continue
        if proc.returncode != 0:
            last_err = (proc.stderr or "").strip()[:200] or f"osascript exited {proc.returncode}"
            continue
        out = (proc.stdout or "").strip()
        parts = out.split(",")
        if len(parts) != 4:
            last_err = f"unexpected osascript output: {out[:100]!r}"
            continue
        try:
            x, y, width, height = (float(p) for p in parts)
        except ValueError:
            last_err = f"non-numeric osascript output: {out[:100]!r}"
            continue
        if width <= 0 or height <= 0:
            last_err = f"zero-size window ({width}x{height})"
            continue
        return {"x": x, "y": y, "width": width, "height": height}, None
    reason = last_err or "could not resolve front window"
    if last_err:
        print(f"[annotation-capture] frontmost window bounds failed after retries: {last_err}", file=sys.stderr, flush=True)
        # "not allowed assistive access" (-25211) means macOS denied
        # Accessibility to whatever process runs the CCC server -- a
        # DIFFERENT permission than Screen Recording, and the generic
        # screencapture-failure hint below doesn't mention it. Surface the
        # actual fix instead of sending the user to the wrong settings pane.
        if "assistive access" in last_err.lower() or "-25211" in last_err:
            reason = (
                "macOS denied Accessibility access to the CCC server process "
                "(osascript/System Events, -25211) -- grant Accessibility to "
                "the app/binary running CCC's server in System Settings -> "
                "Privacy & Security -> Accessibility, then retry"
            )
    return None, reason


def _capture_annotation_window_crop(screen, viewport_crop, annotation_id):
    """Capture the front window's real on-screen bounds and crop directly to
    the viewport-relative region via `screencapture -R`.

    More reliable than guessing global screen coordinates from the browser
    (the browser's own screen-position estimate can be off enough to
    produce a rect that doesn't intersect any display -- OPS-63).
    """
    if platform.system() != "Darwin":
        return None, "window capture is macOS-only"
    screencapture_bin = _resolve_screencapture_bin()
    if not screencapture_bin:
        return None, "screencapture not found"
    bounds, bounds_err = _frontmost_window_bounds_for_capture()
    if not bounds:
        return None, bounds_err or "could not resolve front window"
    crop = _annotation_rect(viewport_crop)
    if crop["width"] < 3 or crop["height"] < 3:
        return None, "crop region too small"
    screen = screen if isinstance(screen, dict) else {}
    border_x = max(0.0, _annotation_number(screen.get("chrome_border_x")))
    chrome_y = max(0.0, _annotation_number(screen.get("chrome_offset_y")))
    x = int(round(bounds["x"] + crop["x"] + border_x))
    y = int(round(bounds["y"] + crop["y"] + chrome_y))
    width = int(round(crop["width"]))
    height = int(round(crop["height"]))
    if width < 3 or height < 3:
        return None, "crop region too small"
    ANNOTATION_SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
    out = ANNOTATION_SCREENSHOT_DIR / f"{annotation_id}.png"
    try:
        proc = subprocess.run(
            [screencapture_bin, "-x", "-R", f"{x},{y},{width},{height}", str(out)],
            capture_output=True,
            text=True,
            timeout=8,
        )
    except (OSError, subprocess.SubprocessError) as e:
        return None, f"window screencapture failed: {e}"
    if proc.returncode != 0:
        err = (proc.stderr or proc.stdout or "").strip()[:300]
        try:
            out.unlink(missing_ok=True)
        except OSError:
            pass
        hint = err or f"window screencapture exited {proc.returncode}"
        low = hint.lower()
        if "intersect" in low or "display" in low or "could not create" in low:
            # Window was offscreen/minimized/on another Space, or the process
            # lacks Screen Recording permission — both yield a non-actionable
            # macOS stderr. Surface the fix so the agent (or its user) can act.
            hint += (
                " (bring the CCC browser window fully on-screen - not minimized "
                "or on another Space - and grant Screen Recording permission to "
                "your terminal/Claude Code in System Settings → Privacy & Security)"
            )
        return None, hint
    try:
        if not out.is_file() or out.stat().st_size <= 0:
            return None, "window screencapture produced no image"
    except OSError:
        return None, "window screencapture file missing"
    return str(out), None


def _capture_annotation_screen_rect(screen_rect, annotation_id):
    """Best-effort non-interactive capture of the selected screen rect.

    Browser APIs can only estimate the viewport-to-screen transform. If that
    estimate is off, the annotation still has URL/selector/rect/text anchors;
    the screenshot path is an optional convenience.

    Returns (path, error_message).
    """
    if platform.system() != "Darwin":
        return None, "screen-region capture is macOS-only"
    screencapture_bin = _resolve_screencapture_bin()
    if not screencapture_bin:
        return None, "screencapture not found"
    rect = _annotation_rect(screen_rect)
    x = int(round(rect["x"]))
    y = int(round(rect["y"]))
    w = int(round(rect["width"]))
    h = int(round(rect["height"]))
    if w < 3 or h < 3 or w > 10000 or h > 10000:
        return None, "screen region too small"
    if x < -10000 or y < -10000 or x > 100000 or y > 100000:
        return None, "screen region out of bounds"
    ANNOTATION_SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
    out = ANNOTATION_SCREENSHOT_DIR / f"{annotation_id}.png"
    try:
        proc = subprocess.run(
            [screencapture_bin, "-x", "-R", f"{x},{y},{w},{h}", str(out)],
            capture_output=True,
            text=True,
            timeout=8,
        )
    except (OSError, subprocess.SubprocessError) as e:
        return None, f"screencapture failed: {e}"
    if proc.returncode != 0:
        err = (proc.stderr or proc.stdout or "").strip()[:300]
        try:
            out.unlink(missing_ok=True)
        except OSError:
            pass
        hint = err or f"screencapture exited {proc.returncode}"
        if "could not create" in hint.lower() or proc.returncode == 1:
            hint += " (capture failed; check Screen Recording permission, window focus, or region bounds)"
        return None, hint
    try:
        if out.stat().st_size <= 0:
            out.unlink(missing_ok=True)
            return None, "screencapture produced an empty file"
    except OSError:
        return None, "screencapture file missing"
    return str(out), None


def _capture_annotation_screenshot_native(payload, annotation_id):
    """Try window crop, then estimated screen rect. Returns (path, error)."""
    errors = []
    screen = payload.get("screen") if isinstance(payload.get("screen"), dict) else {}
    viewport = payload.get("viewport_crop")
    if isinstance(viewport, dict):
        path, err = _capture_annotation_window_crop(screen, viewport, annotation_id)
        if path:
            return path, None
        if err:
            errors.append(err)
    path, err = _capture_annotation_screen_rect(screen, annotation_id)
    if path:
        return path, None
    if err:
        errors.append(err)
    return None, "; ".join(errors) if errors else "screenshot capture failed"


def _save_annotation_screenshot_b64(image_b64, annotation_id):
    try:
        raw = base64.b64decode(str(image_b64 or ""), validate=True)
    except (ValueError, TypeError) as e:
        raise ValueError(f"invalid base64: {e}") from e
    if not raw:
        raise ValueError("empty screenshot")
    if len(raw) > 25 * 1024 * 1024:
        raise ValueError("screenshot too large")
    ANNOTATION_SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
    out = ANNOTATION_SCREENSHOT_DIR / f"{annotation_id}.png"
    out.write_bytes(raw)
    return str(out)


def _minimize_front_window_for_capture():
    if platform.system() != "Darwin":
        return None
    script = r'''
tell application "System Events"
  set frontProc to first application process whose frontmost is true
  set frontPid to unix id of frontProc
  set frontName to name of frontProc
  set actionTaken to "none"
  try
    if (count of windows of frontProc) > 0 then
      set value of attribute "AXMinimized" of window 1 of frontProc to true
      set actionTaken to "window"
    end if
  on error
    try
      set visible of frontProc to false
      set actionTaken to "app"
    end try
  end try
  return (frontPid as text) & tab & frontName & tab & actionTaken
end tell
'''
    try:
        proc = subprocess.run(
            ["osascript", "-e", script],
            capture_output=True,
            text=True,
            timeout=4,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if proc.returncode != 0:
        return None
    parts = (proc.stdout or "").strip().split("\t")
    if len(parts) < 3:
        return None
    return {"pid": parts[0], "name": parts[1], "action": parts[2]}


def _restore_window_after_capture(window_info):
    if platform.system() != "Darwin" or not window_info:
        return
    pid = str(window_info.get("pid") or "").strip()
    if not pid.isdigit():
        return
    script = f'''
tell application "System Events"
  set targetProc to first application process whose unix id is {pid}
  set visible of targetProc to true
  try
    repeat with w in windows of targetProc
      try
        if (value of attribute "AXMinimized" of w) is true then
          set value of attribute "AXMinimized" of w to false
        end if
      end try
    end repeat
  end try
  set frontmost of targetProc to true
end tell
'''
    try:
        subprocess.run(
            ["osascript", "-e", script],
            capture_output=True,
            text=True,
            timeout=4,
        )
    except (OSError, subprocess.SubprocessError):
        pass


def capture_annotation_screen(minimize=True):
    window_info = _minimize_front_window_for_capture() if minimize else None
    if window_info:
        time.sleep(0.25)
    result = _capture_screenshot_native()
    _restore_window_after_capture(window_info)
    if window_info:
        result["window_action"] = window_info.get("action")
        result["window_app"] = window_info.get("name")
    return result


def list_annotations(limit=100):
    try:
        limit = int(limit or 100)
    except (TypeError, ValueError):
        limit = 100
    limit = max(1, min(limit, 500))
    with _ANNOTATIONS_LOCK:
        items = _load_annotations()
    return {"ok": True, "annotations": list(reversed(items[-limit:])), "count": len(items)}


def create_annotation(payload):
    if not isinstance(payload, dict):
        return {"ok": False, "error": "expected JSON object"}
    note = _annotation_text(payload.get("note"), 2000)
    if not note:
        return {"ok": False, "error": "note is required"}
    created_at = datetime.now(tz=timezone.utc).isoformat()
    annotation_id = f"ann-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{os.urandom(3).hex()}"
    screen = _annotation_screen(payload.get("screen"))
    annotation = {
        "id": annotation_id,
        "created_at": created_at,
        "note": note,
        "url": _annotation_text(payload.get("url"), 1000),
        "title": _annotation_text(payload.get("title"), 200),
        "session_id": _annotation_text(payload.get("session_id"), 160),
        "repo_path": _annotation_text(payload.get("repo_path"), 500),
        "rect": _annotation_rect(payload.get("rect")),
        "screen": screen,
        "element": _annotation_element(payload.get("element")),
        "source": _annotation_text(payload.get("source"), 80) or "browser-page",
    }
    screenshot_b64 = _annotation_text(payload.get("screenshot_b64"), 40 * 1024 * 1024)
    screenshot_warning = None
    if screenshot_b64:
        try:
            annotation["screenshot_path"] = _save_annotation_screenshot_b64(
                screenshot_b64, annotation_id
            )
        except ValueError as e:
            screenshot_warning = str(e)
    if not annotation.get("screenshot_path") and payload.get("capture_screen", True):
        screenshot_path, capture_err = _capture_annotation_screenshot_native(
            payload, annotation_id
        )
        if screenshot_path:
            annotation["screenshot_path"] = screenshot_path
        elif capture_err:
            screenshot_warning = capture_err
    if screenshot_warning and not annotation.get("screenshot_path"):
        annotation["screenshot_warning"] = screenshot_warning
    with _ANNOTATIONS_LOCK:
        items = _load_annotations()
        items.append(annotation)
        # Keep the file bounded. The newest annotations are usually the only
        # relevant ones for active agent handoff.
        if len(items) > 500:
            items = items[-500:]
        _write_annotations(items)
    result = {"ok": True, "annotation": annotation}
    if screenshot_warning and not annotation.get("screenshot_path"):
        result["screenshot_warning"] = screenshot_warning
    return result


def _normalize_annotation_queue_name(value):
    text = str(value or "").strip().lower()
    text = re.sub(r"[\s_-]+", " ", text)
    return text


def _annotation_queue_submission_key(text, meta, project):
    """Return a stable key for one in-flight annotation queue submission."""
    meta = meta if isinstance(meta, dict) else {}
    fields = {
        "annotation_id": str(meta.get("annotation_id") or meta.get("id") or ""),
        "note": str(meta.get("note") or ""),
        "url": str(meta.get("url") or ""),
        "title": str(meta.get("title") or ""),
        "selector": str(meta.get("selector") or ""),
        "screenshot_path": str(meta.get("screenshot_path") or ""),
        "repo_path": str(meta.get("repo_path") or ""),
        "source": str(meta.get("source") or ""),
        "lane": str(meta.get("lane") or ""),
        "project": str(project or meta.get("project") or ""),
        "text": text,
    }
    return hashlib.sha256(json.dumps(fields, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()


def _find_annotation_ux_queue_session(queue_name=ANNOTATION_UX_FIXES_QUEUE_NAME):
    """Find the newest Claude session in the CCC repo with the queue name."""
    repo_path = resolve_repo_path(str(CCC_ROOT))
    target = _normalize_annotation_queue_name(queue_name)
    matches = []
    try:
        live_sids = set(_load_session_registry().keys())
        rows = find_conversations(repo_path, include_old=True, live_sids=live_sids)
    except Exception:
        rows = []
    for row in rows:
        sid = row.get("session_id") or row.get("id")
        if not sid:
            continue
        names = [
            row.get("display_name"),
            row.get("ai_title"),
        ]
        if row.get("spawn_named"):
            names.append(row.get("display_name"))
        if any(_normalize_annotation_queue_name(name) == target for name in names if name):
            matches.append(row)
    if not matches:
        return None
    matches.sort(
        key=lambda row: (
            1 if row.get("is_live") else 0,
            float(row.get("last_interacted") or row.get("modified") or row.get("mtime") or 0),
        ),
        reverse=True,
    )
    return matches[0]


def enqueue_annotation_ux_fixes_queue(
    text, queue_name=ANNOTATION_UX_FIXES_QUEUE_NAME, engine="claude", meta=None, inject=False, project=""
):
    """Append annotation context to the durable, numbered UX-fixes queue.

    By default this no longer interrupts any session: it records a numbered
    ``open`` item that survives across sessions and that any session can later
    *claim* when it is free (see ``watchtower.queue``). This is the anti-
    interruption behaviour — captures stop derailing long-running work.

    Pass ``inject=True`` to additionally fall back to the legacy behaviour of
    injecting into / spawning the named ``queue_name`` session.
    """
    text = _annotation_text(text, 24000)
    if not text:
        return {"ok": False, "error": "missing text", "status": 400}

    # Require an actionable anchor. A note alone gives a fix-worker nothing to
    # locate, so it blocks the ticket and the queue silts up (CCC-396..402). An
    # anchor is at least one of: a CSS selector, a screenshot path, or a URL.
    _meta_for_anchor = meta if isinstance(meta, dict) else {}
    _has_anchor = bool(
        str(_meta_for_anchor.get("selector") or "").strip()
        or str(_meta_for_anchor.get("screenshot_path") or "").strip()
        or str(_meta_for_anchor.get("url") or "").strip()
    )
    if not _has_anchor:
        return {
            "ok": False,
            "error": "Annotation needs an element, screenshot, or URL before it can go to the fix queue",
            "status": 400,
        }

    repo_path = resolve_repo_path(str(CCC_ROOT))

    # Durable record first — this is the source of truth a human refers to by
    # number and a second session can see. Never interrupts anyone.
    meta = meta if isinstance(meta, dict) else {}
    # Only default repo_path to the CCC repo for CCC-origin captures. A product
    # source (e.g. "bym") that omits repo_path must NOT be clobbered to CCC_ROOT,
    # or repo-path-wins project routing misfiles the item as CCC.
    _src = str(meta.get("source") or "ccc").lower()
    _repo_path = str(meta.get("repo_path") or "")
    if not _repo_path and _src in ("", "ccc"):
        _repo_path = CCC_ROOT
    _url = str(meta.get("url") or "")
    # An annotation's page title is often the generic application title. Use
    # the annotator's note for the queue name, unless a linked GitHub issue
    # supplies an authoritative title.
    _title = (
        github_issue_title(_url)
        or str(meta.get("note") or "").strip()
        or str(meta.get("title") or "")
    )
    _submission_key = _annotation_queue_submission_key(text, meta, project)
    with _ANNOTATION_QUEUE_SUBMISSIONS_LOCK:
        if _submission_key in _ANNOTATION_QUEUE_SUBMISSIONS_IN_FLIGHT:
            return {
                "ok": False,
                "error": "This annotation is already being submitted",
                "status": 409,
            }
        _ANNOTATION_QUEUE_SUBMISSIONS_IN_FLIGHT.add(_submission_key)
    try:
        item = _q.enqueue(
            note=meta.get("note") or text,
            text=text,
            source=str(meta.get("source") or "ccc"),
            annotation_id=str(meta.get("annotation_id") or meta.get("id") or ""),
            url=_url,
            title=_title,
            selector=str(meta.get("selector") or ""),
            screenshot_path=str(meta.get("screenshot_path") or ""),
            repo_path=_repo_path,
            lane=str(meta.get("lane") or "normal"),
            project=str(project or meta.get("project") or ""),
        )
    except Exception as e:  # never lose a capture to a queue error
        item = None
        queue_error = str(e)
    else:
        queue_error = None
    finally:
        with _ANNOTATION_QUEUE_SUBMISSIONS_LOCK:
            _ANNOTATION_QUEUE_SUBMISSIONS_IN_FLIGHT.discard(_submission_key)

    # Dispatch (nudge a live worker, else spawn) after persisting. Reconciliation
    # can read other GitHub-backed queues and take several seconds while GitHub
    # is degraded; the annotation POST must acknowledge its durable ticket
    # without waiting for that best-effort follow-up.
    if item and _WT_WORKERS_AVAILABLE and _wt_workers is not None:
        def _dispatch():
            try:
                _wt_workers.dispatch_after_enqueue(
                    str(item.get("project") or ""), str(item.get("ref") or ""))
            except Exception:
                pass

        threading.Thread(
            target=_dispatch,
            name="ccc-annotation-dispatch",
            daemon=True,
        ).start()

    if not inject:
        if item:
            return {
                "ok": True,
                "action": "queued",
                "number": item.get("number"),
                "queue_name": queue_name,
                "repo_path": repo_path,
                "item": item,
            }
        return {"ok": False, "action": "queue", "error": queue_error or "enqueue failed"}

    # Locked for the full find-existing-or-spawn decision (see the lock's
    # definition near _ANNOTATION_QUEUE_SUBMISSIONS_LOCK) so a second
    # near-simultaneous call for the same queue_name waits for this one to
    # either inject or finish spawning, instead of racing it.
    with _annotation_queue_spawn_lock(queue_name):
        existing = _find_annotation_ux_queue_session(queue_name)
        if existing:
            sid = existing.get("session_id") or existing.get("id")
            # CCC must never interrupt a possibly-mid-turn session on its
            # own (see the interrupt-asks contract above _file_interrupt_ask).
            # This picks an EXISTING live worker automatically — the human
            # filed a ticket, but didn't choose to interrupt whatever that
            # worker happens to be mid-turn on right now. File an approval
            # ask instead of steering straight through.
            existing_spawn = _find_live_spawn_entry_for_session(sid)
            if existing_spawn is not None and _spawn_entry_active_tool_child(existing_spawn):
                _file_interrupt_ask(
                    sid, "annotate-queue",
                    f"A new \"{queue_name}\" annotation ticket arrived but this "
                    "session is mid-turn. Approve to steer it now, dismiss to "
                    "leave it running (the ticket stays queued).",
                    {"kind": "sigterm-steer", "pid": existing_spawn.get("pid"),
                     "text": text, "session_id": sid},
                    name=str(existing.get("name") or ""),
                )
                return {
                    "ok": True,
                    "action": "queued",
                    "number": item.get("number") if item else None,
                    "queue_name": queue_name,
                    "repo_path": repo_path,
                    "item": item,
                    "note": "target session is mid-turn; filed an interrupt-ask instead of steering",
                }
            injected = _inject_text_into_session(
                sid, text, mode="steer", source="annotate-queue"
            )
            if injected.get("ok"):
                _record_interaction(sid)
                return {
                    "ok": True,
                    "action": "injected",
                    "queue_name": queue_name,
                    "session_id": sid,
                    "repo_path": repo_path,
                    "inject": injected,
                }
            return {
                "ok": False,
                "action": "inject",
                "queue_name": queue_name,
                "session_id": sid,
                "repo_path": repo_path,
                "error": injected.get("error") or "inject failed",
                "inject": injected,
            }

        if engine == "antigravity":
            spawned = spawn_session_antigravity(text, name=queue_name, repo_path=repo_path)
        elif engine == "gemini":
            spawned = spawn_session_gemini(text, name=queue_name, repo_path=repo_path)
        elif engine == "kilo":
            spawned = spawn_session_kilo(text, name=queue_name, repo_path=repo_path)
        elif engine == "opencode":
            spawned = spawn_session_opencode(text, name=queue_name, repo_path=repo_path)
        elif engine == "cursor":
            spawned = spawn_session_cursor(text, name=queue_name, repo_path=repo_path)
        else:
            spawned = spawn_session(text, name=queue_name, repo_path=repo_path)

        if not spawned.get("ok"):
            out = {
                "ok": False,
                "action": "spawn",
                "queue_name": queue_name,
                "repo_path": repo_path,
                "error": spawned.get("error") or "spawn failed",
                "spawn": spawned,
            }
            if spawned.get("code") == "claude_unavailable":
                out["status"] = 503
            return out

        sid = None
        log_path = spawned.get("log")
        if log_path:
            sid = _morning_resolve_session_id_from_log(log_path, max_wait_s=8.0)
        if sid:
            try:
                _save_session_name_override(sid, queue_name)
            except OSError:
                pass
            _record_interaction(sid)

        return {
            "ok": True,
            "action": "spawned",
            "queue_name": queue_name,
            "session_id": sid,
            "repo_path": repo_path,
            "pid": spawned.get("pid"),
            "spawn": spawned,
        }


def _launchd_job_pid(label, timeout=3):
    """PID launchd currently associates with `label`, or None.

    `launchctl list <label>` only prints a `"PID" = N;` line while the job
    is actively running; a stopped/never-loaded job yields no match, which
    callers should treat as "nothing else is claiming this label right
    now" rather than an error."""
    try:
        proc = subprocess.run(
            ["launchctl", "list", label],
            capture_output=True, text=True, timeout=timeout,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if proc.returncode != 0:
        return None
    m = re.search(r'"PID"\s*=\s*(\d+)', proc.stdout or "")
    return int(m.group(1)) if m else None


def _launchd_restart_targets_pid(label, expected_pid, timeout=3):
    """True when `launchctl kickstart -k <label>` is safe to trust as having
    restarted the process we mean (self, for the dashboard; the known
    worker pid, for the worker).

    A plist existing on disk only means the label is *installed*, not that
    it's what's actually serving this port: a manually started dev/
    duplicate instance (e.g. CCC_ALLOW_DUPLICATE_REPO=1 on another port),
    or a stray process left over from an old worktree, can hold the port
    while the launchd-registered job sits elsewhere or isn't running at
    all. Kickstarting the label in that case restarts a process nobody is
    talking to, `returncode == 0` still reads as success, and the live
    process nobody touched keeps serving stale code — the exact "restart
    said ok but nothing changed" symptom this guards against.

    Safe: the label isn't currently running under launchd at all (kickstart
    starts it fresh, no other live copy to conflict with), or its tracked
    PID matches what we expect. Unsafe: something else is already running
    under that label and we can't confirm it's the process we mean.
    """
    running_pid = _launchd_job_pid(label, timeout=timeout)
    if running_pid is None:
        return True
    if not expected_pid:
        return False
    return int(running_pid) == int(expected_pid)


def _schedule_restart(delay=0.5):
    """Arm a launchctl kickstart or os.execvp() that replaces this process with a fresh
    `python server.py` after `delay` seconds. Called AFTER the HTTP response
    is flushed so the client sees {ok:true} before the socket dies."""
    def _go():
        try:
            sys.stdout.flush()
            sys.stderr.flush()
        except Exception:
            pass
        if sys.platform == "darwin":
            service_label = "com.github.claude-command-center"
            plist_path = Path.home() / "Library" / "LaunchAgents" / f"{service_label}.plist"
            if plist_path.is_file() and _launchd_restart_targets_pid(service_label, os.getpid()):
                try:
                    proc = subprocess.run(
                        ["launchctl", "kickstart", "-k", f"gui/{os.getuid()}/{service_label}"],
                        capture_output=True,
                        timeout=5,
                    )
                    if proc.returncode == 0:
                        return
                except Exception:
                    pass
        os.execvp(sys.executable, [sys.executable, str(Path(__file__).resolve())])
    t = threading.Timer(delay, _go)
    t.daemon = True
    t.start()


def _load_network_config():
    """Read persisted network config from NETWORK_CONFIG_FILE.

    Returns a dict with the three keys we care about, defaults filled in:
      {"bind_host": str|None, "allowed_origins": [str], "trust_tailnet": bool}
    Missing file or malformed JSON returns the empty default — same-origin
    behaviour falls back to env vars + loopback, which is the safe baseline.
    """
    default = {"bind_host": None, "allowed_origins": [], "trust_tailnet": False}
    try:
        raw = json.loads(NETWORK_CONFIG_FILE.read_text())
    except (OSError, json.JSONDecodeError):
        return default
    if not isinstance(raw, dict):
        return default
    bind_host = raw.get("bind_host")
    if not isinstance(bind_host, str) or not bind_host.strip():
        bind_host = None
    raw_origins = raw.get("allowed_origins") or []
    origins = []
    if isinstance(raw_origins, list):
        for item in raw_origins:
            if isinstance(item, str) and item.strip():
                origins.append(item.strip())
    return {
        "bind_host": bind_host.strip() if bind_host else None,
        "allowed_origins": origins,
        "trust_tailnet": bool(raw.get("trust_tailnet")),
    }


def _save_network_config(config):
    """Persist `config` to NETWORK_CONFIG_FILE. Only the three known keys are
    written — the function silently drops anything else so a bad POST body
    can't smuggle extra fields onto disk."""
    bind_host = config.get("bind_host")
    if bind_host is not None:
        bind_host = str(bind_host).strip() or None
    raw_origins = config.get("allowed_origins") or []
    origins = []
    if isinstance(raw_origins, list):
        for item in raw_origins:
            if isinstance(item, str) and item.strip():
                origins.append(item.strip())
    payload = {
        "bind_host": bind_host,
        "allowed_origins": origins,
        "trust_tailnet": bool(config.get("trust_tailnet")),
    }
    COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
    NETWORK_CONFIG_FILE.write_text(json.dumps(payload, indent=2))
    return payload


# Car Mode key names -> the env var each maps to when we launch the voice agent.
_CAR_MODE_KEYS = {
    "anthropic_api_key": "ANTHROPIC_API_KEY",
    "deepgram_api_key": "DEEPGRAM_API_KEY",
}


def _load_car_mode_config():
    """Read stored Car Mode API keys. Missing/malformed file -> empty dict (the
    keys then fall back to os.environ / ccc-voice/.env at launch)."""
    try:
        raw = json.loads(CAR_MODE_CONFIG_FILE.read_text())
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(raw, dict):
        return {}
    out = {}
    for key in _CAR_MODE_KEYS:
        val = raw.get(key)
        if isinstance(val, str) and val.strip():
            out[key] = val.strip()
    return out


def _save_car_mode_config(config):
    """Persist only the known Car Mode keys (never smuggle extra fields to disk).
    An empty string clears that key. Returns the set of key names now stored."""
    existing = _load_car_mode_config()
    for key in _CAR_MODE_KEYS:
        if key not in (config or {}):
            continue  # not in this request -> leave as-is
        val = config.get(key)
        if isinstance(val, str) and val.strip():
            existing[key] = val.strip()
        else:
            existing.pop(key, None)  # blank -> clear
    COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
    tmp = CAR_MODE_CONFIG_FILE.with_suffix(".json.tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(existing, f, indent=2, sort_keys=True)
        f.write("\n")
    tmp.replace(CAR_MODE_CONFIG_FILE)
    try:
        os.chmod(CAR_MODE_CONFIG_FILE, 0o600)  # keys are secrets — owner-only
    except OSError:
        pass
    return set(existing.keys())


def _car_mode_effective_keys():
    """Which Car Mode keys are available from EITHER stored config or the
    environment. Returns {"anthropic": bool, "deepgram": bool}. Never returns the
    values themselves. The launcher also honours ccc-voice/.env, so a user with
    keys only in that file still works — this just drives the UI's capability copy."""
    cfg = _load_car_mode_config()
    return {
        "anthropic": bool(cfg.get("anthropic_api_key") or os.environ.get("ANTHROPIC_API_KEY")),
        "deepgram": bool(cfg.get("deepgram_api_key") or os.environ.get("DEEPGRAM_API_KEY")),
    }


def _car_mode_status_mode(keys):
    """Map available keys -> capability mode string (see /api/car-mode/status)."""
    if not keys["anthropic"]:
        return "unavailable_no_anthropic"
    if not keys["deepgram"]:
        return "degraded_no_deepgram"  # dispatcher works, but no STT/TTS -> no hands-free voice
    return "voice"


def _detect_tailnet_origins(port):
    """Return ({available, running, hostname, ips, origins}) describing the
    local Tailscale node, or `available=False` when the CLI is missing.

    Origins are built from the magic-DNS hostname plus each tailscale IP, on
    HTTP at the supplied port — what a phone on the tailnet would see in its
    Origin header when hitting CCC. Never raises; any error path returns
    `available=False`/`running=False` so callers can degrade gracefully.
    """
    blank = {"available": False, "running": False, "hostname": "", "ips": [], "origins": []}
    try:
        proc = subprocess.run(
            ["tailscale", "status", "--json"],
            capture_output=True, text=True, timeout=4,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return blank
    if proc.returncode != 0 or not proc.stdout.strip():
        return {**blank, "available": True}
    try:
        data = json.loads(proc.stdout)
    except json.JSONDecodeError:
        return {**blank, "available": True}
    self_node = data.get("Self") or {}
    hostname = (self_node.get("DNSName") or "").rstrip(".")
    raw_ips = self_node.get("TailscaleIPs") or data.get("TailscaleIPs") or []
    ips = [ip for ip in raw_ips if isinstance(ip, str)]
    backend = (data.get("BackendState") or "").strip()
    running = backend.lower() == "running"
    origins = []
    if hostname:
        origins.append(f"http://{hostname}:{port}")
    for ip in ips:
        if ":" in ip:  # IPv6 needs brackets in the URL
            origins.append(f"http://[{ip}]:{port}")
        else:
            origins.append(f"http://{ip}:{port}")
    return {
        "available": True,
        "running": running,
        "hostname": hostname,
        "ips": ips,
        "origins": origins,
    }


def _resolve_runtime_network(port, bind_host=None):
    """Merge env vars, persisted config, and Tailscale auto-detect into the
    final {bind_host, allowed_origins[]} the server should use this run.

    Priority:
      bind_host: explicit bind_host arg > env CCC_BIND_HOST > config.bind_host > "127.0.0.1"
      allowed_origins: union of env CCC_ALLOWED_ORIGIN, config.allowed_origins,
        and detected tailnet origins (when trust_tailnet is on)
      trust_tailnet: env CCC_TRUST_TAILNET in {"1","true","yes","on"}
        OR config.trust_tailnet
    Returns (bind_host, allowed_origins, info) where `info` summarizes which
    layers contributed — purely for the startup banner and the GET endpoint.
    """
    config = _load_network_config()
    env_bind = os.environ.get("CCC_BIND_HOST", "").strip()
    bind_host = bind_host or env_bind or (config["bind_host"] or "127.0.0.1")

    # Ephemeral verification servers (CCC_EPHEMERAL=1) must never expose the
    # network: force loopback regardless of CCC_BIND_HOST or config. Ad-hoc
    # snapshot/QA servers inherit the primary session's env, which previously
    # leaked a 0.0.0.0 bind onto the LAN (OPS-30/36/38/39). Pairs with the
    # write_port_file() CCC_EPHEMERAL skip so they also can't clobber port.txt.
    if os.environ.get("CCC_EPHEMERAL"):
        if env_bind and env_bind not in ("127.0.0.1", "localhost"):
            print(f"   CCC_EPHEMERAL set: ignoring CCC_BIND_HOST={env_bind}, forcing 127.0.0.1")
        bind_host = "127.0.0.1"
        env_bind = ""

    env_trust = os.environ.get("CCC_TRUST_TAILNET", "").strip().lower() in ("1", "true", "yes", "on")
    trust_tailnet = env_trust or config["trust_tailnet"]

    env_origins = [o.strip() for o in os.environ.get("CCC_ALLOWED_ORIGIN", "").split(",") if o.strip()]
    origins = []
    seen = set()
    for src in (env_origins, config["allowed_origins"]):
        for o in src:
            if o not in seen:
                seen.add(o)
                origins.append(o)
    tailnet_info = _detect_tailnet_origins(port) if trust_tailnet else {"available": False, "running": False, "hostname": "", "ips": [], "origins": []}
    if trust_tailnet:
        for o in tailnet_info["origins"]:
            if o not in seen:
                seen.add(o)
                origins.append(o)

    info = {
        "bind_host": bind_host,
        "allowed_origins": origins,
        "trust_tailnet": trust_tailnet,
        "env_overrides": {
            "bind_host": bool(env_bind),
            "trust_tailnet": env_trust,
            "allowed_origins": bool(env_origins),
        },
        "tailnet": tailnet_info,
        "config_file_origins": list(config["allowed_origins"]),
        "config_file_bind_host": config["bind_host"],
        "config_file_trust_tailnet": config["trust_tailnet"],
        "port": port,
    }
    return bind_host, origins, info


# Cache the healthcheck — it walks ~/.claude/projects and shells out to `gh`,
# both of which are slow (multi-hundred-ms on a populated machine). The UI hits
# this endpoint on every page load; without a cache it dominated the network
# critical path. TTL is short so a failing dep still recovers within ~30s.
_HEALTHCHECK_CACHE = {"ts": 0.0, "data": None}
_HEALTHCHECK_TTL_SEC = 30.0
_HEALTHCHECK_CACHE_LOCK = threading.Lock()

# Separate longer cache for the `gh auth status` subprocess. Even after the
# outer healthcheck cache expires, this avoids re-shelling out for 5 minutes.
_GH_AUTH_CACHE = {"ts": 0.0, "check": None}
_GH_AUTH_TTL_SEC = 300.0


def _gh_auth_check_cached(gh_path):
    now = time.monotonic()
    if _GH_AUTH_CACHE["check"] is not None and now - _GH_AUTH_CACHE["ts"] < _GH_AUTH_TTL_SEC:
        return _GH_AUTH_CACHE["check"]
    try:
        r = subprocess.run(
            ["gh", "auth", "status"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode != 0:
            check = {
                "id": "gh_cli",
                "label": "GitHub CLI",
                "status": "warn",
                "message": "`gh` installed but not authenticated",
                "hint": "Run `gh auth login` in your terminal, then refresh.",
            }
        else:
            user = ""
            m = re.search(r"account\s+(\S+)", r.stderr or r.stdout or "")
            if m:
                user = m.group(1)
            check = {
                "id": "gh_cli",
                "label": "GitHub CLI",
                "status": "ok",
                "message": f"Authenticated{f' as @{user}' if user else ''}",
            }
    except (subprocess.SubprocessError, OSError) as e:
        check = {
            "id": "gh_cli",
            "label": "GitHub CLI",
            "status": "error",
            "message": f"`gh auth status` failed: {e}",
            "hint": "Check `gh` install. Run `gh auth status` manually for details.",
        }
    _GH_AUTH_CACHE["ts"] = now
    _GH_AUTH_CACHE["check"] = check
    return check


def _run_healthcheck():
    """Probe every external dependency and surface a structured diagnosis.

    Each check returns:
      - status: "ok" / "warn" / "error"
      - message: human-readable one-liner
      - hint: actionable next step (only present on warn/error)

    The UI renders a setup banner that lists only the failing checks.
    Empty UI without explanation is the worst first-run experience.
    """
    now = time.monotonic()
    cached = _HEALTHCHECK_CACHE["data"]
    if cached is not None and now - _HEALTHCHECK_CACHE["ts"] < _HEALTHCHECK_TTL_SEC:
        return cached
    # A cold dashboard boot can issue several healthcheck requests together.
    # Serialize the expensive filesystem/subprocess probe and recheck after
    # waiting so that only the first caller performs it.
    with _HEALTHCHECK_CACHE_LOCK:
        now = time.monotonic()
        cached = _HEALTHCHECK_CACHE["data"]
        if cached is not None and now - _HEALTHCHECK_CACHE["ts"] < _HEALTHCHECK_TTL_SEC:
            return cached
        out = _build_healthcheck()
        _HEALTHCHECK_CACHE["ts"] = now
        _HEALTHCHECK_CACHE["data"] = out
        return out


def _has_claude_session_file(projects_dir):
    """Return whether Claude has session data without walking the archive."""
    try:
        return next(projects_dir.rglob("*.jsonl"), None) is not None
    except OSError:
        return False


def _build_healthcheck():
    out = {"checks": []}

    # ── claude CLI ────────────────────────────────────────────────────
    claude_info = _resolve_claude_bin()
    projects_dir = Path.home() / ".claude" / "projects"
    if not claude_info.get("available"):
        out["checks"].append({
            "id": "claude_cli",
            "label": "Claude Code CLI",
            "status": "error",
            "message": "Claude Code CLI not found",
            "hint": claude_info.get("reason") or "Install Claude Code: https://docs.claude.com/en/docs/claude-code",
        })
    elif not projects_dir.is_dir():
        out["checks"].append({
            "id": "claude_cli",
            "label": "Claude Code CLI",
            "status": "warn",
            "message": "`claude` installed but no sessions yet",
            "hint": "Run `claude` once in any repo to generate session data, then refresh.",
        })
    else:
        out["checks"].append({
            "id": "claude_cli",
            "label": "Claude Code CLI",
            "status": "ok",
            "message": (
                "Found session data on disk"
                if _has_claude_session_file(projects_dir)
                else "No session files found yet"
            ),
        })

    # ── gh CLI ────────────────────────────────────────────────────────
    gh_path = _which("gh")
    if not gh_path:
        out["checks"].append({
            "id": "gh_cli",
            "label": "GitHub CLI",
            "status": "warn",
            "message": "`gh` not found on PATH (issue board disabled)",
            "hint": "Install: `brew install gh`  (or see https://cli.github.com/)",
        })
    else:
        out["checks"].append(_gh_auth_check_cached(gh_path))

    # ── Repo list state ───────────────────────────────────────────────
    try:
        repo_count = len(load_known_repos())
    except Exception:
        repo_count = 0
    out["checks"].append({
        "id": "repo_list",
        "label": "Known repos",
        "status": "ok" if repo_count else "warn",
        "message": (
            f"{repo_count} repo{'s' if repo_count != 1 else ''} available"
            if repo_count else
            "No repo folders discovered yet"
        ),
        "hint": None if repo_count else "Add a repo from the repo picker.",
    })

    # Overall summary: worst status wins.
    statuses = [c["status"] for c in out["checks"]]
    if "error" in statuses:
        out["overall"] = "error"
    elif "warn" in statuses:
        out["overall"] = "warn"
    else:
        out["overall"] = "ok"
    return out


STATIC_DIR = CCC_ROOT / "static"
MORNING_STATIC_DIR = STATIC_DIR / "morning"
# Where a user's own Applications-rail apps live: one directory per app id,
# each with an index.html served at /view/<id> and assets at /app-static/<id>/.
# Deliberately outside the repo checkout — a public clone is the wrong place
# for personal apps, and `git clean` or a reinstall would wipe them.
USER_APPS_DIR = COMMAND_CENTER_STATE_DIR / "apps"
# Extension allowlist + Content-Type map shared by the /static/ and
# /app-static/ asset routes. Adding a type here is the only place to do it.
# .html is intentionally absent: pages are served by /view/<id>, not as assets.
STATIC_CT_MAP = {
    ".css": "text/css",
    ".js": "application/javascript",
    ".svg": "image/svg+xml",
    ".webmanifest": "application/manifest+json",
    ".json": "application/json",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".ico": "image/x-icon",
}


def _safe_nav_url(url):
    """True when `url` is safe to drop into an href we render ourselves.

    Only same-origin absolute paths (`/foo`) and http(s) URLs qualify. The
    config file is user-owned, but its values reach the DOM as `href`, so a
    `javascript:` entry would execute — cheap to refuse, so we refuse."""
    u = str(url or "").strip()
    if not u or len(u) > 500:
        return False
    if u.startswith("//"):          # protocol-relative — scheme is ambiguous
        return False
    return u.startswith("/") or u.startswith("http://") or u.startswith("https://")


def _custom_links_config():
    """Parse ~/.claude/command-center/custom-links.json.

    Accepts the original bare list of {label, url} links, or
    {"links": [...], "proxies": {"<name>": <port>}, "apps": [...]} where
    proxies feeds the /proxy/<name>/ loopback forwarder and apps feeds the
    left Applications rail (see /api/apps). Returns (links, proxies, apps);
    malformed or absent file returns empty all three."""
    try:
        raw = json.loads(
            (COMMAND_CENTER_STATE_DIR / "custom-links.json").read_text())
    except Exception:
        return [], {}, []
    raw_links = raw.get("links", []) if isinstance(raw, dict) else raw
    raw_proxies = raw.get("proxies", {}) if isinstance(raw, dict) else {}
    raw_apps = raw.get("apps", []) if isinstance(raw, dict) else []
    links = [{"label": str(l.get("label", ""))[:40],
              "url": str(l.get("url", ""))[:500]}
             for l in (raw_links if isinstance(raw_links, list) else [])
             if isinstance(l, dict) and l.get("label")
             and _safe_nav_url(l.get("url"))]
    proxies = {}
    if isinstance(raw_proxies, dict):
        for name, port in raw_proxies.items():
            if re.fullmatch(r"[a-z0-9_-]+", str(name)) and str(port).isdigit():
                proxies[str(name)] = int(port)
    apps = []
    seen_ids = set()
    for a in (raw_apps if isinstance(raw_apps, list) else []):
        if not isinstance(a, dict):
            continue
        app_id = str(a.get("id", "")).strip()
        if not re.fullmatch(r"[a-z0-9_-]{1,40}", app_id) or app_id in seen_ids:
            continue
        if not a.get("label") or not _safe_nav_url(a.get("url")):
            continue
        seen_ids.add(app_id)
        apps.append({
            "id": app_id,
            # 24 chars: the rail is 64px wide, longer labels wrap badly.
            "label": str(a.get("label"))[:24],
            "icon": str(a.get("icon", "") or "•")[:8],
            "url": str(a.get("url"))[:500],
            "builtin": False,
        })
    return links, proxies, apps

def _discover_user_apps():
    """Scan ~/.claude/command-center/apps/*/app.json for installed apps.

    Discovery rather than registration: dropping a folder in is enough, no
    second edit to custom-links.json. A directory without a readable app.json
    is skipped silently — half-written or half-removed apps must not break the
    rail, which is the only navigation CCC has.

    Directory scan of one shallow folder, no subprocess and no session work;
    /api/apps is fetched once per page load, never polled."""
    apps = []
    try:
        entries = sorted(USER_APPS_DIR.iterdir())
    except OSError:
        return apps
    for d in entries:
        if not d.is_dir() or not re.fullmatch(r"[a-z0-9_-]{1,40}", d.name):
            continue
        try:
            meta = json.loads((d / "app.json").read_text())
        except Exception:
            continue
        if not isinstance(meta, dict) or not meta.get("label"):
            continue
        # `url` is optional: an app that ships an index.html is served at
        # /view/<id> and needs to declare nothing beyond its label.
        url = meta.get("url") or f"/view/{d.name}"
        if not _safe_nav_url(url):
            continue
        if url.startswith("/view/") and not (d / "index.html").is_file():
            continue
        apps.append({
            "id": d.name,
            "label": str(meta.get("label"))[:24],
            "icon": str(meta.get("icon", "") or "\N{LARGE BLUE CIRCLE}")[:8],
            "url": str(url)[:500],
            "builtin": False,
        })
    return apps


_APPS_WRITE_LOCK = threading.Lock()


def _apps_config_path():
    return COMMAND_CENTER_STATE_DIR / "custom-links.json"


def _apps_config_mutate(fn):
    """Read custom-links.json, hand the dict to `fn`, write it back.

    Serialised on a lock and written through a temp file: the Applications
    settings page and the rail both touch this file, and a torn write would
    cost the user every app they have."""
    with _APPS_WRITE_LOCK:
        path = _apps_config_path()
        try:
            cfg = json.loads(path.read_text())
            if not isinstance(cfg, dict):        # legacy bare list of links
                cfg = {"links": cfg}
        except Exception:
            cfg = {}
        result = fn(cfg)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(cfg, indent=2) + "\n")
        tmp.replace(path)
        return result


def _resolve_apps(include_disabled=False):
    """The ordered app list behind /api/apps and the rail.

    Built-ins, then manifest apps, then discovered folders. `app_order` in the
    config reorders by id; anything unlisted keeps its natural position at the
    end. Disabled apps are dropped unless the settings page asks for them."""
    apps = [
        {"id": "sessions", "label": "Sessions", "icon": "\N{SPEECH BALLOON}",
         "url": "/", "builtin": True},
        {"id": "queues", "label": "Queues", "icon": "\N{CLIPBOARD}",
         "url": "/q2.html", "builtin": True},
    ]
    if MORNING_ENABLED:
        apps.append({"id": "morning", "label": "Morning",
                     "icon": "\N{BLACK SUN WITH RAYS}", "url": "/morning",
                     "builtin": True})
    # Decision Inbox: the hourly stalled-work scanner + token governor
    # (ccc_server/decision_inbox.py). Ships with the repo but is not core
    # navigation, so it can be switched off from the Applications page.
    apps.append({"id": "decision-inbox", "label": "Decisions",
                 "icon": "\N{BALLOT BOX WITH CHECK}", "url": "/decision-inbox.html",
                 "builtin": False})
    apps.append({"id": "spawn-ledger", "label": "Spawn Ledger",
                 "icon": "\N{BAR CHART}", "url": "/spawn-ledger",
                 "builtin": False})
    manifest_apps = _custom_links_config()[2]
    apps.extend(manifest_apps)
    # An id already declared in the manifest wins: that is how a user renames,
    # re-icons, or repositions a discovered app without editing its folder.
    claimed = {a["id"] for a in apps}
    apps.extend(a for a in _discover_user_apps() if a["id"] not in claimed)

    try:
        raw = json.loads(_apps_config_path().read_text())
        order = raw.get("app_order") if isinstance(raw, dict) else None
        disabled = raw.get("app_disabled") if isinstance(raw, dict) else None
    except Exception:
        order, disabled = None, None
    disabled = set(disabled) if isinstance(disabled, list) else set()
    for a in apps:
        # Core navigation cannot be switched off — the rail would strand you.
        a["enabled"] = a["id"] not in disabled or a.get("builtin", False)
        # Where the rail actually navigates. Absolute URLs go through the
        # /app/<id> wrapper so an app opens inside the CCC window instead of
        # throwing you into a browser tab.
        a["nav"] = a["url"] if a["url"].startswith("/") else f"/app/{a['id']}"
    if isinstance(order, list):
        rank = {str(i): n for n, i in enumerate(order)}
        apps.sort(key=lambda a: rank.get(a["id"], len(rank) + 1))
    if not include_disabled:
        apps = [a for a in apps if a["enabled"]]
    return apps


