# Shown above a framed app that bounces anonymous visitors to a login. The
# explanation matters: the user IS signed in, in their own tab, and without
# this the frame just looks broken.
_APP_LOGIN_NOTICE = """<div class="needs-login">
    <span>&#9888;</span>
    <div class="grow">This page needs you signed in, and a signed-in session
      cannot travel into an embedded page &mdash; browsers withhold
      <code>SameSite=Lax</code> cookies from a frame on another site. You will
      see it logged out here even though your own tab is fine.</div>
    <a href="{url}" target="_blank" rel="noopener">Open in browser &#8599;</a>
  </div>"""


_LOGIN_PROBE_CACHE = {}
_LOGIN_PROBE_TTL = 300.0


def _requires_login(url):
    """Best-effort: does this URL bounce an anonymous visitor to a login?

    Worth knowing because a framed page can never be signed in. Session
    cookies are almost always `SameSite=Lax`, which browsers refuse to send
    on a cross-site iframe request, so the frame renders logged-out no matter
    who you are in your own tab. Detecting it lets us say so instead of
    showing a login form that cannot succeed.

    Unauthenticated HEAD with redirects disabled, 4s cap, cached for 5
    minutes. Any failure answers False — a wrong banner is worse than none."""
    now = time.time()
    hit = _LOGIN_PROBE_CACHE.get(url)
    if hit and now - hit[0] < _LOGIN_PROBE_TTL:
        return hit[1]

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *a, **k):
            return None

    verdict = False
    try:
        req = urllib.request.Request(url, method="HEAD")
        req.add_header("User-Agent", "CCC-app-probe")
        try:
            resp = urllib.request.build_opener(_NoRedirect).open(req, timeout=4)
            status, location = resp.status, resp.headers.get("Location", "")
        except urllib.error.HTTPError as e:
            status, location = e.code, e.headers.get("Location", "")
        if status in (401, 403):
            verdict = True
        elif 300 <= status < 400:
            target = (location or "").lower()
            verdict = any(w in target for w in
                          ("login", "signin", "sign-in", "auth", "sso"))
    except Exception:
        verdict = False
    _LOGIN_PROBE_CACHE[url] = (now, verdict)
    return verdict


def _render_app_frame(app):
    """Fill in the external-app wrapper.

    Module scope on purpose: `_do_GET` binds a local named `html` further
    down, which shadows the stdlib module for the whole function."""
    notice = ""
    if _requires_login(app["url"]):
        notice = _APP_LOGIN_NOTICE.format(
            url=html.escape(app["url"], quote=True))
    return _APP_FRAME_HTML.format(
        label=html.escape(app["label"]),
        url=html.escape(app["url"], quote=True),
        host=html.escape(urllib.parse.urlparse(app["url"]).netloc or app["url"]),
        notice=notice,
    )


_APP_STARTER_HTML = """<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="utf-8">
<title>{label}</title>
<script src="/static/app-rail.js" defer></script>
<style>
  body {{ margin: 0; background: #0f1115; color: #e6e9ee;
         font: 14px/1.6 -apple-system, BlinkMacSystemFont, sans-serif; }}
  .wrap {{ padding: 40px; max-width: 720px; }}
  h1 {{ font-size: 20px; margin: 0 0 8px; }}
  p {{ color: #8a929e; }}
  code {{ color: #5ac8fa; font-family: ui-monospace, Menlo, monospace; }}
</style>
</head>
<body>
  <div class="wrap">
    <h1>{label}</h1>
    <p>Empty app. Edit <code>index.html</code> in this folder, or point an agent at it.</p>
    <p>It is served same-origin, so it can call any CCC <code>/api/*</code> route.
       Assets in the folder are available at <code>/app-static/{app_id}/</code>.</p>
  </div>
</body>
</html>
"""

_APP_EMBED_HTML = """<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="utf-8">
<title>{label}</title>
<script src="/static/app-rail.js" defer></script>
<style>
  html, body {{ height: 100%; margin: 0; background: #0f1115; }}
  body {{ display: flex; flex-direction: column; }}
  iframe {{ flex: 1; border: 0; width: 100%; }}
  .offline {{ padding: 40px; text-align: center; color: #9aa4b2;
             font: 14px/1.7 -apple-system, sans-serif; display: none; }}
</style>
</head>
<body>
  <!-- Same-origin via CCC's /proxy route: a direct iframe to another local
       port renders blank in the Mac app, which cancels navigation off the
       dashboard port. -->
  <iframe id="f" src="/proxy/{app_id}/" title="{label}"></iframe>
  <div class="offline" id="off">Nothing is serving on port {port}.</div>
  <script>
    fetch('/proxy/{app_id}/').then(function (r) {{
      if (!r.ok) {{ throw new Error(String(r.status)); }}
    }}).catch(function () {{
      document.getElementById('f').style.display = 'none';
      document.getElementById('off').style.display = 'block';
    }});
  </script>
</body>
</html>
"""


def _app_id_from_label(label, taken):
    """Slugify a label into a free app id."""
    base = re.sub(r"[^a-z0-9]+", "-", str(label).lower()).strip("-")[:32]
    base = base or "app"
    candidate = base
    n = 2
    while candidate in taken:
        candidate = f"{base}-{n}"[:40]
        n += 1
    return candidate


def _apps_add(payload):
    """Create an app from the Applications settings form.

    kind=url    → a manifest entry, no files.
    kind=port   → a folder whose index.html iframes /proxy/<id>/, plus the
                  proxy port registration.
    kind=blank  → a folder with a starter page to build into.
    """
    label = str(payload.get("label") or "").strip()[:24]
    if not label:
        return {"ok": False, "error": "A name is required."}
    icon = str(payload.get("icon") or "").strip()[:8] or "\N{LARGE BLUE CIRCLE}"
    kind = str(payload.get("kind") or "url")
    taken = {a["id"] for a in _resolve_apps(include_disabled=True)}
    app_id = _app_id_from_label(label, taken)

    if kind == "url":
        url = str(payload.get("url") or "").strip()
        if not _safe_nav_url(url):
            return {"ok": False,
                    "error": "Enter a web address starting with https://"}
        entry = {"id": app_id, "label": label, "icon": icon, "url": url}
    elif kind == "port":
        port = str(payload.get("port") or "").strip()
        if not port.isdigit() or not (1 <= int(port) <= 65535):
            return {"ok": False, "error": "Enter a port number, like 8770."}
        d = USER_APPS_DIR / app_id
        d.mkdir(parents=True, exist_ok=True)
        (d / "app.json").write_text(
            json.dumps({"label": label, "icon": icon}, indent=2) + "\n")
        (d / "index.html").write_text(_APP_EMBED_HTML.format(
            label=html.escape(label), app_id=app_id, port=int(port)))
        _apps_config_mutate(lambda cfg: cfg.setdefault("proxies", {}).update(
            {app_id: int(port)}))
        entry = None
    elif kind == "blank":
        d = USER_APPS_DIR / app_id
        d.mkdir(parents=True, exist_ok=True)
        (d / "app.json").write_text(
            json.dumps({"label": label, "icon": icon}, indent=2) + "\n")
        (d / "index.html").write_text(_APP_STARTER_HTML.format(
            label=html.escape(label), app_id=app_id))
        entry = None
    else:
        return {"ok": False, "error": f"Unknown app kind: {kind}"}

    # Pin the new app to the end of the rail. Without this it lands wherever
    # the merge order puts it — manifest apps sort ahead of discovered ones —
    # and "I just added it, where did it go?" is a bad first impression.
    order = [a["id"] for a in _resolve_apps(include_disabled=True)]

    def commit(cfg):
        if entry is not None:
            cfg.setdefault("apps", []).append(entry)
        cfg["app_order"] = [i for i in order if i != app_id] + [app_id]
    _apps_config_mutate(commit)
    return {"ok": True, "id": app_id}


def _apps_remove(app_id):
    """Drop an app from the rail. Folder contents are moved aside, never
    deleted — an app can hold the only copy of something the user wrote."""
    app_id = str(app_id or "")
    if not re.fullmatch(r"[a-z0-9_-]{1,40}", app_id):
        return {"ok": False, "error": "Unknown app."}
    if app_id in ("sessions", "queues", "morning"):
        return {"ok": False, "error": "Built-in apps can't be removed."}

    def drop(cfg):
        cfg["apps"] = [a for a in cfg.get("apps", [])
                       if isinstance(a, dict) and a.get("id") != app_id]
        cfg.get("proxies", {}).pop(app_id, None)
        for key in ("app_order", "app_disabled"):
            if isinstance(cfg.get(key), list):
                cfg[key] = [i for i in cfg[key] if i != app_id]
    _apps_config_mutate(drop)

    folder = USER_APPS_DIR / app_id
    if folder.is_dir():
        graveyard = USER_APPS_DIR / ".removed"
        graveyard.mkdir(parents=True, exist_ok=True)
        dest = graveyard / app_id
        n = 2
        while dest.exists():
            dest = graveyard / f"{app_id}-{n}"
            n += 1
        try:
            folder.replace(dest)
        except OSError as e:
            return {"ok": True, "warning": f"App removed; folder kept: {e}"}
    return {"ok": True}


def _apps_arrange(payload):
    """Persist rail order and which apps are switched off."""
    ids = payload.get("order")
    disabled = payload.get("disabled")
    valid = re.compile(r"[a-z0-9_-]{1,40}")

    def apply(cfg):
        if isinstance(ids, list):
            cfg["app_order"] = [str(i) for i in ids
                                if valid.fullmatch(str(i))][:200]
        if isinstance(disabled, list):
            cfg["app_disabled"] = [str(i) for i in disabled
                                   if valid.fullmatch(str(i))][:200]
    _apps_config_mutate(apply)
    return {"ok": True}


# ── Optional Morning view plugin ──────────────────────────────────────────
# The Morning view (goals/strategic/tactical/braindump) is highly opinionated
# to one user's workflow. Files (morning.py, morning_store.py, static/morning/,
# scripts/ingest_apple_notes.py, ingesters/) are gitignored and may not be
# present — we detect both the import success AND the user's opt-in env var
# before enabling routes.
#
# CI guarantees nothing in the core depends on these — the smoke test boots
# the server with NO morning files present and asserts startup succeeds.
try:
    import morning  # noqa: F401  — used inside route handlers
    _MORNING_IMPORTABLE = True
except ImportError:
    morning = None
    _MORNING_IMPORTABLE = False
MORNING_ENABLED = (
    _MORNING_IMPORTABLE
    and os.environ.get("CCC_ENABLE_MORNING", "").strip().lower() in ("1", "true", "yes", "on")
)

PORT = int(os.environ.get("PORT", 8090))
# Slow-request threshold (ms). Requests taking at least this long get a single
# [SLOW] line on stdout; everything faster stays silent. Tune via CCC_SLOW_REQ_MS.
try:
    SLOW_REQ_MS = float(os.environ.get("CCC_SLOW_REQ_MS", "500"))
except (TypeError, ValueError):
    SLOW_REQ_MS = 500.0
# Set in main() after _resolve_runtime_network. Module-level so functions
# called at runtime can reach it without threading the value through every
# call site.
BIND_HOST = "127.0.0.1"
# Optional title-prefix noise stripper. Comma-separated prefixes.
# Empty by default; set `CCC_TITLE_STRIP=ACME,FOO` to strip `[ACME ...]` and `[FOO ...]` from titles.
TITLE_STRIP_PREFIXES = [p for p in os.environ.get("CCC_TITLE_STRIP", "").split(",") if p]

# Same-origin allowlist extension. Origins listed here are accepted on top of
# the loopback defaults (localhost / 127.0.0.1 / [::1]) so the UI can be
# reached from another device on a trusted network (Tailscale, VPN). Three
# layers feed this list at startup, all merged into the final ALLOWED_ORIGINS:
#   1. CCC_ALLOWED_ORIGIN env var — comma-separated full origins
#   2. ~/.claude/command-center/network.json `allowed_origins` field
#   3. Tailscale auto-detect when `trust_tailnet` is on (config or env)
# Format: scheme://host[:port], e.g. `http://my-mac.tailnet.ts.net:8090`.
# The server has no auth, so every entry here is a peer that can run commands
# as you — see SECURITY.md. Mutated by `_resolve_runtime_network` in main().
ALLOWED_ORIGINS = [o.strip() for o in os.environ.get("CCC_ALLOWED_ORIGIN", "").split(",") if o.strip()]
# Populated in main() once the file + env + tailnet layers are merged. The
# GET /api/network-config handler returns this verbatim so the UI can show
# the user exactly what's trusted on this run, including which env vars
# are pinning values they can't override from the UI.
RUNTIME_NETWORK_INFO = None

# Optional org-tagger for multi-tenant apps. Set CCC_ORG_PATTERNS as
# `Label1:pat1a|pat1b;Label2:pat2`. The server scans each GitHub issue body
# for the patterns and tags the card with `org: "Label1"`, letting the UI
# group backlog by org. Leave unset and every issue is tagged `org: null`.
_org_spec = os.environ.get("CCC_ORG_PATTERNS", "")
ORG_PATTERNS = []
for chunk in _org_spec.split(";"):
    if ":" not in chunk:
        continue
    label, pats = chunk.split(":", 1)
    label = label.strip()
    alts = [p.strip() for p in pats.split("|") if p.strip()]
    if label and alts:
        try:
            ORG_PATTERNS.append((label, re.compile("|".join(alts), re.IGNORECASE)))
        except re.error:
            pass


def _detect_issue_org(body):
    """Return the first matching org label for an issue body, or None."""
    if not body or not ORG_PATTERNS:
        return None
    for label, rx in ORG_PATTERNS:
        if rx.search(body):
            return label
    return None


_TITLE_STRIP_RE = re.compile(
    r"^\s*\[(?:" + "|".join(re.escape(p) for p in TITLE_STRIP_PREFIXES) + r")[^\]]*\]\s*"
) if TITLE_STRIP_PREFIXES else None


def _strip_title_prefix(title):
    if not title or not _TITLE_STRIP_RE:
        return title
    return _TITLE_STRIP_RE.sub("", title)


# ── Flow work-item state ─────────────────────────────────────────────────
def _flow_display_path(path):
    try:
        p = Path(path).expanduser().resolve(strict=False)
        home = Path.home().resolve(strict=False)
        rel = p.relative_to(home)
        return "~/" + str(rel)
    except (OSError, RuntimeError, ValueError):
        return str(path)


def _flow_slug(value, fallback="item", max_len=48):
    s = re.sub(r"[^A-Za-z0-9._-]+", "-", str(value or "").strip()).strip("-._")
    if not s:
        s = fallback
    return s[:max_len]


def _flow_field_key(label):
    s = re.sub(r"[^a-z0-9]+", "_", str(label or "").strip().lower()).strip("_")
    aliases = {
        "target": "target_date",
        "date": "target_date",
        "due": "target_date",
        "due_date": "target_date",
        "color": "color_seed",
    }
    return aliases.get(s, s)


def _flow_node_id(kind, repo_path=None, object_id=None):
    kind = (kind or "").strip().lower()
    if kind == "repo":
        repo = resolve_repo_path(repo_path)
        return f"repo:{repo}"
    if kind == "object":
        oid = _flow_slug(object_id, fallback="object", max_len=96)
        return f"object:{oid}"
    raise ValueError("kind must be repo or object")


def _flow_state_path(kind, repo_path=None, object_id=None):
    kind = (kind or "").strip().lower()
    if kind == "repo":
        repo = resolve_repo_path(repo_path)
        leaf = _flow_slug(Path(repo).name, fallback="repo", max_len=44)
        digest = hashlib.sha1(repo.encode("utf-8")).hexdigest()[:12]
        return FLOW_STATE_DIR / "repos" / f"{leaf}-{digest}.md"
    if kind == "object":
        oid = _flow_slug(object_id, fallback="object", max_len=96)
        return FLOW_STATE_DIR / "objects" / f"{oid}.md"
    raise ValueError("kind must be repo or object")


def _flow_parse_fields(content):
    fields = {k: "" for k in _FLOW_FIELD_LABELS}
    fields["status"] = "Active"
    fields["color_seed"] = "auto"
    in_fields = False
    for line in str(content or "").splitlines():
        if re.match(r"^##\s+Flow fields\s*$", line.strip(), re.IGNORECASE):
            in_fields = True
            continue
        if in_fields and re.match(r"^##\s+", line):
            break
        if not in_fields:
            continue
        if not line.strip().startswith("|"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) < 2:
            continue
        if re.fullmatch(r":?-{3,}:?", cells[0] or ""):
            continue
        key = _flow_field_key(cells[0])
        if key in fields and cells[0].lower() != "field":
            fields[key] = cells[1]
    return fields


def _flow_managed_block(name, body):
    return (
        f"<!-- ccc:auto:start {name} -->\n"
        f"{str(body or '').rstrip()}\n"
        f"<!-- ccc:auto:end {name} -->"
    )


def _flow_replace_managed_block(content, name, body):
    block = _flow_managed_block(name, body)
    pattern = re.compile(
        r"<!--\s*ccc:auto:start\s+" + re.escape(name) + r"\s*-->"
        r"[\s\S]*?"
        r"<!--\s*ccc:auto:end\s+" + re.escape(name) + r"\s*-->",
        re.IGNORECASE,
    )
    if pattern.search(content or ""):
        return pattern.sub(block, content, count=1)
    return str(content or "").rstrip() + "\n\n" + block + "\n"


def _flow_table_cell(value):
    s = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    s = s.replace("|", "\\|")
    return s or "-"


def _flow_item_done(item):
    if bool(item.get("done")):
        return True
    status = str(item.get("status") or "").strip().lower()
    return status in {"done", "completed", "complete", "archived", "verified", "closed"}


def _flow_current_work_block(items):
    rows = [
        "## Current work",
        "",
        "| Item | Status | Session | Updated | Notes |",
        "|---|---|---|---|---|",
    ]
    clean = [it for it in (items or []) if isinstance(it, dict) and (it.get("title") or it.get("item"))]
    if not clean:
        rows.append("| No visible child work yet. | - | - | - | - |")
    for it in clean:
        rows.append(
            "| "
            + " | ".join([
                _flow_table_cell(it.get("title") or it.get("item")),
                _flow_table_cell(it.get("status")),
                _flow_table_cell(it.get("session") or it.get("session_id")),
                _flow_table_cell(it.get("updated")),
                _flow_table_cell(it.get("notes")),
            ])
            + " |"
        )
    return "\n".join(rows)


def _flow_open_items_block(items):
    lines = ["## Open items", ""]
    open_items = [it for it in (items or []) if isinstance(it, dict) and not _flow_item_done(it)]
    if not open_items:
        lines.append("- None detected yet.")
    for it in open_items:
        title = _flow_table_cell(it.get("title") or it.get("item"))
        status = _flow_table_cell(it.get("status"))
        lines.append(f"- {title}" + (f" ({status})" if status != "-" else ""))
    return "\n".join(lines)


def _flow_completed_block(items):
    lines = ["## Completed", ""]
    done_items = [it for it in (items or []) if isinstance(it, dict) and _flow_item_done(it)]
    if not done_items:
        lines.append("- None detected yet.")
    for it in done_items:
        title = _flow_table_cell(it.get("title") or it.get("item"))
        status = _flow_table_cell(it.get("status"))
        lines.append(f"- {title}" + (f" ({status})" if status != "-" else ""))
    return "\n".join(lines)


def _flow_template(kind, title, repo_path=None, object_id=None):
    title = (str(title or "").strip()
             or (Path(str(repo_path)).name if repo_path else "")
             or str(object_id or "").strip()
             or "Flow work item")
    fields = [
        "| Field | Value |",
        "|---|---|",
        "| Status | Active |",
        "| Goal |  |",
        "| Target date |  |",
        "| ETA |  |",
        "| Owner |  |",
        "| Color seed | auto |",
    ]
    meta = []
    if kind == "repo" and repo_path:
        meta.append(f"Repo path: `{repo_path}`")
    if kind == "object" and object_id:
        meta.append(f"Object id: `{object_id}`")
    now = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S %Z")
    parts = [
        f"# {title}",
        "",
        "## Flow fields",
        "",
        "\n".join(fields),
        "",
    ]
    if meta:
        parts.extend(["## Identity", "", "\n".join(meta), ""])
    parts.extend([
        "## Summary",
        "",
        "Write the current state here.",
        "",
        _flow_managed_block("status-table", _flow_current_work_block([])),
        "",
        _flow_managed_block("open-items", _flow_open_items_block([])),
        "",
        _flow_managed_block("completed", _flow_completed_block([])),
        "",
        "## Manual notes",
        "",
        f"Created by CCC Flow on {now}.",
        "",
    ])
    return "\n".join(parts)


def _flow_read_index():
    try:
        data = json.loads(FLOW_INDEX_FILE.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        data = {}
    nodes = data.get("nodes") if isinstance(data, dict) else None
    return nodes if isinstance(nodes, dict) else {}


def _flow_write_index(nodes):
    FLOW_STATE_DIR.mkdir(parents=True, exist_ok=True)
    tmp = FLOW_INDEX_FILE.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps({"schema": 1, "nodes": nodes}, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(tmp, FLOW_INDEX_FILE)


def _flow_index_upsert(entry):
    with _FLOW_INDEX_LOCK:
        nodes = _flow_read_index()
        nodes[entry["node_id"]] = {
            "kind": entry.get("kind") or "",
            "repo_path": entry.get("repo_path") or "",
            "object_id": entry.get("object_id") or "",
            "title": entry.get("title") or "",
            "path": entry.get("path") or "",
            "updated_at": time.time(),
        }
        _flow_write_index(nodes)


def _flow_response_for_path(entry, path):
    try:
        content = path.read_text(encoding="utf-8", errors="replace")
        mtime = path.stat().st_mtime
    except OSError as exc:
        return {"ok": False, "error": str(exc)}, 500
    fields = _flow_parse_fields(content)
    return {
        "ok": True,
        "kind": entry.get("kind") or "",
        "node_id": entry["node_id"],
        "title": entry.get("title") or "",
        "repo_path": entry.get("repo_path") or "",
        "object_id": entry.get("object_id") or "",
        "path": str(path),
        "state_path": _flow_display_path(path),
        "content": content,
        "mtime": mtime,
        "fields": fields,
    }, 200


def _flow_entry_from_payload(payload):
    payload = payload or {}
    kind = str(payload.get("kind") or "").strip().lower()
    repo_path = str(payload.get("repo_path") or "").strip()
    object_id = str(payload.get("object_id") or "").strip()
    title = str(payload.get("title") or "").strip()
    node_id = _flow_node_id(kind, repo_path=repo_path, object_id=object_id)
    if kind == "repo":
        repo_path = resolve_repo_path(repo_path)
        if not title:
            title = Path(repo_path).name
    elif kind == "object":
        object_id = _flow_slug(object_id, fallback="object", max_len=96)
        if not title:
            title = object_id
    path = _flow_state_path(kind, repo_path=repo_path, object_id=object_id)
    return {
        "kind": kind,
        "node_id": node_id,
        "repo_path": repo_path,
        "object_id": object_id,
        "title": title,
        "path": str(path),
    }, path


def _flow_load_node_payload(payload, create=False):
    try:
        entry, path = _flow_entry_from_payload(payload)
    except (RepoContextError, ValueError) as exc:
        status = exc.status if isinstance(exc, RepoContextError) else 400
        return {"ok": False, "error": str(exc)}, status
    if not _path_is_within(path, FLOW_STATE_DIR):
        return {"ok": False, "error": "invalid flow state path"}, 403
    if not path.exists():
        if not create:
            return {"ok": False, "error": "not found", "path": str(path)}, 404
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            content = _flow_template(
                entry["kind"],
                entry.get("title"),
                repo_path=entry.get("repo_path"),
                object_id=entry.get("object_id"),
            )
            tmp = path.with_suffix(path.suffix + ".tmp")
            tmp.write_text(content, encoding="utf-8")
            os.replace(tmp, path)
        except OSError as exc:
            return {"ok": False, "error": f"could not create flow file: {exc}"}, 500
    _flow_index_upsert(entry)
    return _flow_response_for_path(entry, path)


def _flow_save_node_payload(payload):
    try:
        entry, path = _flow_entry_from_payload(payload)
    except (RepoContextError, ValueError) as exc:
        status = exc.status if isinstance(exc, RepoContextError) else 400
        return {"ok": False, "error": str(exc)}, status
    if not _path_is_within(path, FLOW_STATE_DIR):
        return {"ok": False, "error": "invalid flow state path"}, 403
    content = payload.get("content")
    if not isinstance(content, str):
        return {"ok": False, "error": "content must be a string"}, 400
    if len(content.encode("utf-8", errors="replace")) > 1024 * 1024:
        return {"ok": False, "error": "content too large"}, 413
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists() and not payload.get("overwrite"):
            current_mtime = path.stat().st_mtime
            expected = payload.get("mtime")
            if expected is not None:
                try:
                    expected_f = float(expected)
                except (TypeError, ValueError):
                    expected_f = 0.0
                if expected_f and abs(current_mtime - expected_f) > 0.001:
                    return {
                        "ok": False,
                        "error": "flow file changed on disk",
                        "mtime": current_mtime,
                    }, 409
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(content, encoding="utf-8")
        os.replace(tmp, path)
    except OSError as exc:
        return {"ok": False, "error": str(exc)}, 500
    _flow_index_upsert(entry)
    return _flow_response_for_path(entry, path)


def _flow_refresh_node_payload(payload):
    result, status = _flow_load_node_payload(payload, create=True)
    if not result.get("ok"):
        return result, status
    content = result.get("content") or ""
    items = payload.get("items") or []
    if not isinstance(items, list):
        items = []
    content = _flow_replace_managed_block(content, "status-table", _flow_current_work_block(items))
    content = _flow_replace_managed_block(content, "open-items", _flow_open_items_block(items))
    content = _flow_replace_managed_block(content, "completed", _flow_completed_block(items))
    save_payload = dict(payload)
    save_payload["content"] = content
    save_payload["mtime"] = result.get("mtime")
    save_payload["overwrite"] = True
    refreshed, refresh_status = _flow_save_node_payload(save_payload)
    if refreshed.get("ok"):
        refreshed["derived"] = {
            "active_session_count": len([it for it in items if isinstance(it, dict) and not _flow_item_done(it)]),
            "completed_count": len([it for it in items if isinstance(it, dict) and _flow_item_done(it)]),
            "open_item_count": len([it for it in items if isinstance(it, dict) and not _flow_item_done(it)]),
        }
    return refreshed, refresh_status


def _flow_index_payload():
    entries = []
    with _FLOW_INDEX_LOCK:
        nodes = _flow_read_index()
    for node_id, entry in sorted(nodes.items()):
        if not isinstance(entry, dict):
            continue
        path = Path(entry.get("path") or "")
        if not path.is_file() or not _path_is_within(path, FLOW_STATE_DIR):
            continue
        try:
            content = path.read_text(encoding="utf-8", errors="replace")
            mtime = path.stat().st_mtime
        except OSError:
            continue
        entries.append({
            "node_id": node_id,
            "kind": entry.get("kind") or "",
            "repo_path": entry.get("repo_path") or "",
            "object_id": entry.get("object_id") or "",
            "title": entry.get("title") or "",
            "path": str(path),
            "state_path": _flow_display_path(path),
            "mtime": mtime,
            "fields": _flow_parse_fields(content),
        })
    return {"ok": True, "entries": entries, "count": len(entries)}

# Sidecar state (written by hooks)
SIDECAR_STATE_DIR = Path.home() / ".claude" / "command-center" / "live-state"
HOOK_SCRIPTS_DIR = Path.home() / ".claude" / "command-center" / "hooks"
HOOK_MARKER = "command-center/hooks/"
CCC_HOOK_SCRIPT_NAMES = (
    "pre-tool-use.py", "post-tool-use.py", "notification.py", "stop.py",
    "pre-compact.py", "post-compact.py",
)
# Legacy marker (pre-rename) — kept so ensure_hooks_installed can detect old
# entries in ~/.claude/settings.json and rewrite them to the new path.
HOOK_MARKER_LEGACY = "log-viewer/hooks/"


def _hook_python_executable():
    """Absolute Python executable for Claude Code hook commands."""
    system_python = "/usr/bin/python3"
    if sys.platform == "darwin" and os.access(system_python, os.X_OK):
        return system_python
    exe = sys.executable or ""
    if exe and not os.path.isabs(exe):
        exe = shutil.which(exe) or exe
    if not exe:
        exe = shutil.which("python3") or shutil.which("python") or "python3"
    return exe


def _hook_script_command(script_path):
    return f"{shlex.quote(_hook_python_executable())} {shlex.quote(str(script_path))}"


def _ccc_hook_command(script_name):
    return _hook_script_command(HOOK_SCRIPTS_DIR / script_name)


def _normalize_ccc_hook_command(command):
    """Return a PATH-independent command for CCC hook script entries."""
    if not isinstance(command, str):
        return command, False
    rewritten = command.replace(HOOK_MARKER_LEGACY, HOOK_MARKER)
    for script_name in CCC_HOOK_SCRIPT_NAMES:
        if script_name in rewritten and HOOK_MARKER in rewritten:
            normalized = _ccc_hook_command(script_name)
            return normalized, normalized != command
    return rewritten, rewritten != command

# Spawned headless Claude sessions
_spawned_sessions = []  # [{pid, name, log, proc}]
_CLAUDE_PREWARM_LOCK = threading.Lock()
_CLAUDE_PREWARMS = {}
_CLAUDE_PREWARM_TTL_S = 120
_CLAUDE_PREWARM_MAX = 4

# Ring buffer of recent session kill/retire events, surfaced to the UI so the
# user knows CCC killed a spawn (and why). Capped at _KILL_EVENTS_MAX; old
# entries fall off the left. Polled via /api/sessions/live-activity.
_KILL_EVENTS_MAX = 20
_KILL_EVENTS = collections.deque(maxlen=_KILL_EVENTS_MAX)
_KILL_EVENTS_LOCK = threading.Lock()


def _record_kill_event(entry, *, reason, caller, alive, age_s=None):
    """Append a kill event to the ring buffer for UI surfacing."""
    try:
        sid = (entry or {}).get("session_id") or (entry or {}).get("resumed_sid") or ""
        name = (entry or {}).get("name") or ""
        pid = (entry or {}).get("pid")
        ev = {
            "id": str(uuid.uuid4()),
            "ts": round(time.time(), 3),
            "pid": pid,
            "session_id": str(sid),
            "name": str(name),
            "reason": str(reason or "unspecified"),
            "caller": str(caller or ""),
            "alive": bool(alive),
            "age_s": round(age_s, 1) if age_s is not None else None,
            "cwd": str((entry or {}).get("cwd") or ""),
        }
        with _KILL_EVENTS_LOCK:
            _KILL_EVENTS.append(ev)
    except Exception:
        pass


def _drain_new_kill_events(last_seen_id=""):
    """Return kill events newer than last_seen_id (for frontend polling)."""
    with _KILL_EVENTS_LOCK:
        out = []
        for ev in _KILL_EVENTS:
            if ev["id"] == last_seen_id:
                out = []  # found the cursor; start fresh after this point
                continue
            out.append(ev)
        return list(out)


# ── Interrupt event emission ──────────────────────────────────────────────
# Unified helper for detecting and emitting [Request interrupted by user]
# events. Both detection sites (transcript-scan in _extract_tail_meta and
# SSE stream in _stream_spawn_deltas_log) call this helper instead of
# inlining the dedup + sink logic. The helper owns:
#   - _INTERRUPT_EVENTS_ENABLED gate (default-off, opt-in in main())
#   - _SEEN_INTERRUPTS dedup (thread-safe, standardized key: sid:uuid)
#   - 48h freshness cutoff on ALL sinks (toast + ledger + activity.log)
#   - The three sinks: _log_activity, _resume_ledger_append, _record_kill_event
# When disabled, the helper returns WITHOUT modifying _SEEN_INTERRUPTS —
# marking-seen-while-disabled would silently swallow the later real emission
# when the dashboard eventually enables.
_INTERRUPT_FRESHNESS_CUTOFF_S = 48 * 3600


def _emit_interrupt_event(sid, uuid_str, *, source, agent_name="", event_ts=None):
    """Emit an interrupt event (activity log + ledger + kill-event toast).

    Called from both the transcript-scan path (_extract_tail_meta) and the
    SSE stream path (_stream_spawn_deltas_log). Deduped by sid:uuid across
    processes via the durable ledger seed at startup. Events older than 48h
    are marked seen but not emitted to any sink (prevents upgrade-day
    backfill flood when the schema bump forces a full cold reparse).
    """
    if not _INTERRUPT_EVENTS_ENABLED:
        return
    if not sid or not uuid_str:
        return
    # Internal prewarm reservations get SIGTERM'd on expiry/eviction while a
    # turn is technically in flight (they're idle, but Claude still writes
    # "[Request interrupted by user]" to their own transcript). That is
    # routine prewarm-pool churn, not a user-facing stuck session — surfacing
    # it as a "Request interrupt … session is now stuck" toast just confuses
    # whoever's looking at the dashboard when a background repo warm-up
    # cycles. The placeholder name is always "prewarm-<cwd-basename>" (see
    # static/app.js's prewarm request) or agent_name "ccc-prewarm" pre-claim.
    _name_check = str(agent_name or "").strip().lower()
    if _name_check == "ccc-prewarm" or _name_check.startswith("prewarm-"):
        return
    dedup_key = f"{sid}:{uuid_str}"
    with _SEEN_INTERRUPTS_LOCK:
        if dedup_key in _SEEN_INTERRUPTS:
            return
        _SEEN_INTERRUPTS.add(dedup_key)
    # Freshness cutoff: skip all sinks for events older than 48h.
    # The interrupt is already marked seen (above) so we don't re-check
    # it on every cache hit. This prevents the upgrade-day backfill burst
    # when the schema bump forces a cold reparse of years of transcripts.
    if event_ts is not None and (time.time() - event_ts) > _INTERRUPT_FRESHNESS_CUTOFF_S:
        return
    try:
        _log_activity(
            "interrupt", "INTERRUPT",
            f"sid={sid} — Request interrupt",
        )
        _resume_ledger_append(
            "interrupt", sid=sid,
            reason="request_interrupted",
            source=source,
            uuid=uuid_str,
            agent_name=agent_name,
        )
        _record_kill_event(
            {"name": agent_name, "session_id": sid},
            reason="request_interrupted",
            caller=source,
            alive=False,
        )
        with _RECENT_INTERRUPT_LOCK:
            _RECENT_INTERRUPT_BY_SID[sid] = event_ts if event_ts is not None else time.time()
    except Exception:
        pass


def _session_recently_interrupted(sid):
    """True if `sid` had an interrupt event within _RECENT_INTERRUPT_WINDOW_S.

    Drives the "Interrupted" badge on the session row — a visual confirmation
    that a request_interrupted event actually reached the transcript, distinct
    from an interrupt-ask that's still pending or was dismissed.
    """
    if not sid:
        return False
    with _RECENT_INTERRUPT_LOCK:
        ts = _RECENT_INTERRUPT_BY_SID.get(sid)
    return bool(ts and (time.time() - ts) < _RECENT_INTERRUPT_WINDOW_S)


def _seed_seen_interrupts_from_ledger():
    """Seed _SEEN_INTERRUPTS from the resume ledger at startup.

    Reads both the current ledger file and the rotation backup in full,
    extracting every sid:uuid pair from lines where event == "interrupt".
    This makes dedup at-most-once across restarts: the in-memory set is
    repopulated from the durable record on every boot.

    Must be called in main() before any background thread (reaper, archive
    refresher) starts parsing transcripts — those threads would fire unseeded.
    """
    for fpath in (_RESUME_LEDGER_BACKUP, _RESUME_LEDGER_FILE):
        try:
            if not fpath.is_file():
                continue
            with fpath.open("r") as f:
                for line in f:
                    # Prefilter: skip lines that can't contain an interrupt
                    # event. Coupled to json.dumps default separators (which
                    # produce '"event": "interrupt"' with a space after the
                    # colon) — if the format ever switches to compact
                    # separators ('"event":"interrupt"'), update this check
                    # to match both styles.
                    if '"event": "interrupt"' not in line:
                        continue
                    try:
                        rec = json.loads(line)
                    except (json.JSONDecodeError, ValueError):
                        continue
                    if rec.get("event") != "interrupt":
                        continue
                    sid = rec.get("sid") or ""
                    uuid_str = rec.get("uuid") or ""
                    if sid and uuid_str:
                        _SEEN_INTERRUPTS.add(f"{sid}:{uuid_str}")
        except OSError:
            continue


def _emit_interrupts_from_meta(meta, path_stem):
    """Emit interrupt events from a cached meta's "interrupted" field.

    Called on cache hits in _extract_tail_meta — the parser already ran on
    this file and stored the interrupt data in meta. Without this, an
    interrupt whose transcript was cached by a non-emitting process (archive
    worker) would never be emitted by the dashboard, because the cache hit
    skips the parse loop.
    """
    interrupted = meta.get("interrupted") if isinstance(meta, dict) else None
    if not interrupted:
        return
    for entry in interrupted:
        if not isinstance(entry, dict):
            continue
        uuid_str = entry.get("uuid") or ""
        event_ts = entry.get("ts")
        if uuid_str:
            _emit_interrupt_event(
                path_stem, uuid_str,
                source="transcript-scan",
                agent_name=meta.get("agent_name") or meta.get("custom_title") or "",
                event_ts=event_ts,
            )


# ── CCC-initiated interrupt approvals ─────────────────────────────────────
# CCC must never interrupt/kill a session that could be mid-turn on its own.
# Any automatic path that wants to (Codex compaction/silent-turn recovery,
# the idle reaper hitting a session with an active tool child) files an ask
# here instead. The UI surfaces pending asks with Approve/Dismiss; only an
# approved ask executes the interrupt. Fully-idle reaping (no active tool
# child) stays automatic — nothing in-flight is lost there.
#
# File-backed because the asker and the resolver live in different processes:
# the worker runs the Codex recovery pump, the dashboard serves the resolve
# endpoint. Mutations flock() the file so the two can't lose each other's
# writes.
_INTERRUPT_ASKS_FILE = COMMAND_CENTER_STATE_DIR / "interrupt-asks.json"
_INTERRUPT_ASKS_LOCK = threading.Lock()
_INTERRUPT_ASK_PENDING_TTL_S = 24 * 3600     # unanswered asks expire
_INTERRUPT_ASK_DISMISS_SNOOZE_S = 6 * 3600   # dismissed → don't re-ask for 6h
_INTERRUPT_ASK_RESOLVED_KEEP_S = 48 * 3600   # prune resolved entries after 48h


def _interrupt_asks_mutate(fn):
    """Load → fn(asks) → save, atomically across threads AND processes.

    `fn` receives the pruned list and returns (asks, result); the list is
    written back with an atomic replace while an flock on the file is held.
    """
    with _INTERRUPT_ASKS_LOCK:
        COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
        lock_path = _INTERRUPT_ASKS_FILE.with_suffix(".lock")
        with open(lock_path, "w") as lf:
            fcntl.flock(lf, fcntl.LOCK_EX)
            try:
                asks = _interrupt_asks_read_unlocked()
                asks, result = fn(asks)
                tmp = _INTERRUPT_ASKS_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps({"asks": asks}, indent=1))
                os.replace(tmp, _INTERRUPT_ASKS_FILE)
            finally:
                fcntl.flock(lf, fcntl.LOCK_UN)
    return result


def _interrupt_asks_read_unlocked(now=None):
    """Read + prune the ask list. Callers hold the flock (or accept a
    read-only, possibly-momentarily-stale view for polling)."""
    now = time.time() if now is None else now
    try:
        raw = json.loads(_INTERRUPT_ASKS_FILE.read_text())
    except (OSError, json.JSONDecodeError):
        return []
    asks = raw.get("asks") if isinstance(raw, dict) else None
    if not isinstance(asks, list):
        return []
    kept = []
    for a in asks:
        if not isinstance(a, dict):
            continue
        status = a.get("status") or "pending"
        created = float(a.get("created_at") or 0)
        resolved = float(a.get("resolved_at") or 0)
        if status == "pending" and now - created > _INTERRUPT_ASK_PENDING_TTL_S:
            continue
        if status != "pending" and resolved and now - resolved > _INTERRUPT_ASK_RESOLVED_KEEP_S:
            continue
        kept.append(a)
    return kept


def _file_interrupt_ask(sid, source, reason, action, name=""):
    """File (or refresh) an approval ask for a CCC-initiated interrupt.

    Dedup key is (sid, source). Returns the authoritative entry:
      * an existing pending/approved entry wins (no duplicate asks);
      * a dismissed entry inside the snooze window is returned as-is so the
        caller can back off instead of nagging;
      * anything else (no entry, expired, executed, stale dismissal) files a
        fresh pending ask.
    """
    sid = str(sid or "").strip()
    if not sid:
        return None

    def mutate(asks):
        now = time.time()
        for a in asks:
            if a.get("sid") != sid or a.get("source") != source:
                continue
            status = a.get("status") or "pending"
            if status in ("pending", "approved"):
                return asks, a
            if status == "dismissed" and now - float(a.get("resolved_at") or 0) \
                    < _INTERRUPT_ASK_DISMISS_SNOOZE_S:
                return asks, a
        entry = {
            "id": str(uuid.uuid4()),
            "sid": sid,
            "name": str(name or ""),
            "source": str(source or ""),
            "reason": str(reason or ""),
            "action": action if isinstance(action, dict) else {},
            "status": "pending",
            "created_at": round(time.time(), 3),
        }
        # Replace any stale entry for the same (sid, source) so the list
        # holds at most one row per asker per session.
        asks = [a for a in asks
                if not (a.get("sid") == sid and a.get("source") == source)]
        asks.append(entry)
        _log_activity(
            "interrupt-ask", "ASK",
            f"sid={sid} source={source} — {reason}",
        )
        return asks, entry

    try:
        return _interrupt_asks_mutate(mutate)
    except OSError:
        return None


def _mark_interrupt_ask(ask_id, status, note=""):
    def mutate(asks):
        hit = None
        for a in asks:
            if a.get("id") == ask_id:
                a["status"] = status
                a["resolved_at"] = round(time.time(), 3)
                if note:
                    a["note"] = str(note)
                hit = a
                break
        return asks, hit
    try:
        return _interrupt_asks_mutate(mutate)
    except OSError:
        return None


def _pending_interrupt_asks():
    """Pending asks for the live-activity poll (read-only, lock-free)."""
    return [a for a in _interrupt_asks_read_unlocked()
            if (a.get("status") or "pending") == "pending"]


def _resolve_interrupt_ask(ask_id, decision):
    """Approve or dismiss an ask from the UI.

    Dismiss just marks the entry (askers snooze on it). Approve executes the
    stored action when this process can (sigterm), or marks the entry
    `approved` for the owning process to consume (codex-interrupt — the
    recovery pump in the worker picks it up on its next tick).
    """
    ask_id = str(ask_id or "").strip()
    if not ask_id:
        return {"ok": False, "error": "missing ask id"}
    if decision not in ("approve", "dismiss"):
        return {"ok": False, "error": "decision must be approve or dismiss"}

    if decision == "dismiss":
        hit = _mark_interrupt_ask(ask_id, "dismissed")
        if hit is None:
            return {"ok": False, "error": "ask not found"}
        _log_activity("interrupt-ask", "DISMISS",
                      f"sid={hit.get('sid')} source={hit.get('source')}")
        return {"ok": True, "status": "dismissed"}

    hit = _mark_interrupt_ask(ask_id, "approved")
    if hit is None:
        return {"ok": False, "error": "ask not found"}
    sid = hit.get("sid") or ""
    action = hit.get("action") if isinstance(hit.get("action"), dict) else {}
    kind = action.get("kind") or ""
    _log_activity("interrupt-ask", "APPROVE",
                  f"sid={sid} source={hit.get('source')} kind={kind}")
    if kind == "sigterm":
        pid = action.get("pid")
        try:
            pid = int(pid)
        except (TypeError, ValueError):
            _mark_interrupt_ask(ask_id, "executed", note="invalid pid")
            return {"ok": False, "error": "stored pid is invalid"}
        if not _pid_is_engine_process(pid, "claude"):
            _mark_interrupt_ask(ask_id, "executed", note="process already gone")
            return {"ok": True, "status": "executed",
                    "note": "process already gone"}
        # The ask's idle check only ran once, when it was filed — this dialog
        # can sit unresolved for hours. Re-check right before the kill so a
        # click on a since-gone-busy process doesn't tear down a live turn.
        # ps-based (not the in-memory spawn entry), so it works even when the
        # spawn is owned by the worker process rather than this one.
        if _spawn_entry_active_tool_child({"pid": pid}):
            _mark_interrupt_ask(
                ask_id, "deferred",
                note="process started a tool call since this ask was filed; not killed")
            return {"ok": True, "status": "deferred", "pid": pid,
                    "note": "session is busy now — not killed. Re-open the dialog once it's idle."}
        try:
            os.kill(pid, signal.SIGTERM)
        except (OSError, ProcessLookupError) as e:
            _mark_interrupt_ask(ask_id, "executed", note=f"kill failed: {e}")
            return {"ok": False, "error": f"kill failed: {e}"}
        _resume_ledger_append(
            "kill", sid=sid, pid=pid, source="interrupt_ask_approved",
            reason=hit.get("reason") or "",
        )
        _mark_interrupt_ask(ask_id, "executed")
        return {"ok": True, "status": "executed", "pid": pid}
    if kind == "sigterm-steer":
        text = action.get("text") or ""
        target_sid = action.get("session_id") or sid
        if not text or not target_sid:
            _mark_interrupt_ask(ask_id, "executed", note="missing text or session_id")
            return {"ok": False, "error": "stored action is incomplete"}
        result = _inject_text_into_session(target_sid, text, mode="steer", source="annotate-queue-approved")
        note = "executed" if result.get("ok") else f"steer failed: {result.get('error') or 'unknown'}"
        _mark_interrupt_ask(ask_id, "executed", note=note)
        return {"ok": bool(result.get("ok")), "status": "executed", "inject": result}
    # codex-interrupt (and any future owner-executed kind): leave `approved`;
    # the asker consumes it on its next tick and marks it executed.
    return {"ok": True, "status": "approved",
            "note": "queued — the owning process executes it shortly"}


# Ring buffer of prewarm lifecycle events (spawned, claimed, expired), surfaced
# to the UI so the user can see when CCC is pre-warming a session ahead of time
# and when the reservation is claimed or expires unused.
_PREWARM_EVENTS_MAX = 20
_PREWARM_EVENTS = collections.deque(maxlen=_PREWARM_EVENTS_MAX)
_PREWARM_EVENTS_LOCK = threading.Lock()


def _record_prewarm_event(kind, prewarm_id, entry):
    """Append a prewarm lifecycle event to the ring buffer for UI surfacing."""
    try:
        ev = {
            "id": str(uuid.uuid4()),
            "ts": round(time.time(), 3),
            "kind": str(kind or ""),
            "prewarm_id": str(prewarm_id or "")[:8],
            "pid": (entry or {}).get("pid"),
            "name": str((entry or {}).get("name") or ""),
            "cwd": str((entry or {}).get("cwd") or ""),
        }
        with _PREWARM_EVENTS_LOCK:
            _PREWARM_EVENTS.append(ev)
    except Exception:
        pass


def _drain_new_prewarm_events(last_seen_id=""):
    """Return prewarm events newer than last_seen_id (for frontend polling)."""
    with _PREWARM_EVENTS_LOCK:
        out = []
        for ev in _PREWARM_EVENTS:
            if ev["id"] == last_seen_id:
                out = []
                continue
            out.append(ev)
        return list(out)


