# ---------------------------------------------------------------------------
# ccc doctor / GET /api/engines/doctor (W3-3): per-engine health for every
# spawnable engine, not just the 5 covered by onboarding. Reuses the same
# bin resolvers as _engines_installed() and the same auth probes as
# _get_onboarding_status() rather than re-implementing detection — this is
# a fusion view, not a new probe.
# ---------------------------------------------------------------------------

def _doctor_auth_present(engine, onboarding_clis):
    """(bool_or_None, source) -- None means "no probe implemented", not
    "not logged in". Never guess a false negative for an engine this repo
    has no real auth signal for."""
    cli_info = onboarding_clis.get(engine)
    if cli_info is not None:
        return bool(cli_info.get("logged_in")), "cli-login-check"
    if engine == "opencode":
        try:
            return bool(_opencode_configured_providers()), "opencode-auth-json"
        except Exception:
            return None, "check-failed"
    return None, "no-probe-implemented"


def _launchd_print_job_pid(label, timeout=3):
    """PID launchd currently owns for `label` via `launchctl print`, or None."""
    if platform.system() != "Darwin":
        return None
    try:
        target = f"gui/{os.getuid()}/{label}"
        proc = subprocess.run(
            ["launchctl", "print", target],
            capture_output=True, text=True, timeout=timeout,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if proc.returncode != 0:
        return None
    m = re.search(r"\bpid\s*=\s*(\d+)\b", proc.stdout or "", re.IGNORECASE)
    return int(m.group(1)) if m else None


def _doctor_is_server_py_command(cmd):
    try:
        argv = shlex.split(cmd or "")
    except ValueError:
        argv = str(cmd or "").split()
    if len(argv) < 2:
        return False
    exe = os.path.basename(argv[0]).lower()
    if "python" not in exe:
        return False
    return any(os.path.basename(arg) == "server.py" for arg in argv[1:])


def _doctor_server_process_rows():
    """Every python `server.py` process visible to ps, with process start time."""
    rows = []
    out = _sys_run([_SYS_PS, "-axo", "pid=,lstart=,command="], timeout=5)
    for line in out.splitlines():
        parts = line.strip().split(None, 6)
        if len(parts) < 7:
            continue
        try:
            pid = int(parts[0])
        except ValueError:
            continue
        cmd = parts[6]
        if not _doctor_is_server_py_command(cmd):
            continue
        rows.append({
            "pid": pid,
            "started_at": " ".join(parts[1:6]),
            "cmd": cmd,
        })
    return rows


def _doctor_process_cwds(pids):
    return _sys_cwds(pids)


def _doctor_listening_ports(pids):
    if not pids:
        return {}
    out = _sys_run([
        _SYS_LSOF,
        "-nP",
        "-a",
        "-iTCP",
        "-sTCP:LISTEN",
        "-FpPn",
        "-p",
        ",".join(str(int(pid)) for pid in pids),
    ], timeout=5)
    ports = {}
    cur = None
    for line in out.splitlines():
        if line.startswith("p"):
            try:
                cur = int(line[1:])
            except ValueError:
                cur = None
        elif line.startswith("n") and cur is not None:
            m = re.search(r":(\d+)(?:\s|\(|$)", line[1:])
            if not m:
                continue
            ports.setdefault(cur, set()).add(int(m.group(1)))
    return {pid: sorted(vals) for pid, vals in ports.items()}


def _doctor_registry_by_pid(repo_path=None):
    try:
        entries = _read_registry_pruned()
    except Exception:
        entries = []
    repo_path_norm = os.path.normpath(str(repo_path or "")) if repo_path else ""
    by_pid = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        if repo_path_norm:
            install_path = os.path.normpath(str(entry.get("install_path") or ""))
            if install_path != repo_path_norm:
                continue
        try:
            by_pid[int(entry.get("pid"))] = entry
        except (TypeError, ValueError):
            continue
    return by_pid


def _doctor_instance_fix_line(kill_pids):
    restart = (
        "launchctl kickstart -k "
        f"gui/$(id -u)/{_CCC_DASHBOARD_LAUNCHD_LABEL}"
    )
    pids = [str(int(pid)) for pid in kill_pids]
    return f"kill {' '.join(pids)} && {restart}" if pids else restart


def build_doctor_instances():
    """Read-only inventory of CCC dashboard server.py instances for this repo."""
    repo_path = os.path.normpath(str(CCC_ROOT))
    process_rows = _doctor_server_process_rows()
    pids = [row["pid"] for row in process_rows]
    cwds = _doctor_process_cwds(pids)
    ports_by_pid = _doctor_listening_ports(pids)
    registry_by_pid = _doctor_registry_by_pid(repo_path)
    launchd_pid = _launchd_print_job_pid(_CCC_DASHBOARD_LAUNCHD_LABEL)

    instances = []
    for row in process_rows:
        if not _doctor_is_server_py_command(row.get("cmd") or ""):
            continue
        pid = row["pid"]
        cwd = cwds.get(pid)
        if os.path.normpath(str(cwd or "")) != repo_path:
            continue
        reg = registry_by_pid.get(pid) or {}
        ports = list(ports_by_pid.get(pid) or [])
        reg_port = reg.get("port")
        try:
            reg_port = int(reg_port)
        except (TypeError, ValueError):
            reg_port = None
        port = reg_port if reg_port is not None else (ports[0] if ports else None)
        instances.append({
            "pid": pid,
            "port": port,
            "ports": ports,
            "started_at": reg.get("started_at") or row.get("started_at") or "",
            "process_started_at": row.get("started_at") or "",
            "cwd": cwd,
            "cmd": row.get("cmd") or "",
            "launchd_owned": bool(launchd_pid is not None and pid == launchd_pid),
            "registered": pid in registry_by_pid,
            "registry": {
                "port": reg_port,
                "install_path": reg.get("install_path") or None,
                "started_at": reg.get("started_at") or None,
            },
        })
    instances.sort(key=lambda item: item["pid"])

    warnings = []
    if len(instances) > 1:
        warnings.append("more than one CCC server.py process for this repo")
    non_launchd_listeners = [
        item for item in instances
        if item.get("ports") and item.get("pid") != launchd_pid
    ]
    if non_launchd_listeners:
        warnings.append("one or more listeners are not launchd-owned")
    elif launchd_pid is not None and instances and launchd_pid not in {item["pid"] for item in instances}:
        warnings.append("the launchd-owned pid is not a server.py process for this repo")

    kill_pids = []
    if warnings:
        kill_pids = [
            item["pid"] for item in instances
            if launchd_pid is None or item["pid"] != launchd_pid
        ]

    return {
        "ok": True,
        "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "repo_path": repo_path,
        "launchd_label": _CCC_DASHBOARD_LAUNCHD_LABEL,
        "launchd_pid": launchd_pid,
        "status": "warn" if warnings else "ok",
        "warning": "; ".join(warnings),
        "fix": _doctor_instance_fix_line(kill_pids) if warnings else None,
        "instances": instances,
    }


def build_ccc_doctor():
    """Per-engine: CLI present, auth present (where checkable), BYOK profile
    present, a dry-run smoke check, and dashboard instance diagnostics.
    Read-only -- never spawns a model subprocess or spends a token; the
    engine "smoke" step only confirms the CLI binary resolves, so it is safe
    to poll on every ``ccc doctor`` invocation.
    """
    installed = {row["engine"]: row for row in _engines_installed().get("engines", [])}
    onboarding_clis = _get_onboarding_status().get("clis", {})
    try:
        byok_profiles = byok_list_profiles()
    except Exception:
        byok_profiles = []
    engines = {}
    for engine in _ORCHESTRATION_SPAWN_ENGINES:
        row = installed.get(engine) or {}
        cli_present = bool(row.get("installed"))
        auth_present, auth_source = _doctor_auth_present(engine, onboarding_clis)
        byok_ready = engine in BYOK_DIRECT_ENV_ENGINES
        byok_profile_present = byok_ready and bool(byok_profiles)
        engines[engine] = {
            "cli_present": cli_present,
            "cli_bin": row.get("detail") or None,
            "auth_present": auth_present,
            "auth_source": auth_source,
            "byok_ready": byok_ready,
            "byok_profile_present": byok_profile_present,
            "smoke_dry_run": {
                "ok": cli_present,
                "note": (
                    "dry-run only: confirms the CLI binary resolves; no "
                    "subprocess is launched and no tokens are spent"
                ),
            },
        }
    return {
        "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "engines": engines,
        # W6-1: GitHub GraphQL points are a 5,000/hr budget shared across
        # every tool on this account, and CCC's issue/PR panels spend it.
        # Cached, and the read itself is free (a rateLimit-only query does
        # not count against the limit -- measured), so doctor stays cheap.
        "github_quota": read_graphql_quota(),
        "server_instances": build_doctor_instances(),
    }


_ONBOARDING_LOGIN_LOCK = threading.Lock()
_ONBOARDING_LOGIN_SESSIONS = {}
_ONBOARDING_LOGIN_MAX_BUFFER_CHARS = 200_000
_ONBOARDING_LOGIN_RETAIN_SECONDS = 10 * 60
_ONBOARDING_LOGIN_URL_RE = re.compile(r"https?://[^\s<>'\")\]]+")
_ONBOARDING_LOGIN_CODE_RE = re.compile(r"\b[A-Z0-9]{4}(?:-[A-Z0-9]{4}){1,5}\b")


def _onboarding_login_timeout_seconds():
    try:
        value = int(os.environ.get("CCC_ONBOARDING_LOGIN_TIMEOUT_SECONDS", "900"))
    except ValueError:
        value = 900
    return max(60, min(value, 60 * 60))


def _onboarding_login_command(engine):
    """Resolve the CLI auth command used by inline onboarding login."""
    key = str(engine or "").strip().lower()
    specs = {
        "claude": (_resolve_claude_bin, ["auth", "login"]),
        "codex": (_resolve_codex_bin, ["login"]),
        "cursor": (_resolve_cursor_bin, ["login"]),
        "antigravity": (_resolve_antigravity_bin, ["login"]),
        "kimi": (_resolve_kimi_bin, ["login"]),
    }
    spec = specs.get(key)
    if not spec:
        return {"ok": False, "error": f"Unknown engine: {engine}"}
    resolver, extra_args = spec
    info = resolver()
    if not info.get("available"):
        return {
            "ok": False,
            "engine": key,
            "code": info.get("code") or f"{key}_unavailable",
            "error": info.get("reason") or f"{key} CLI not found",
        }
    argv = [info["bin"], *extra_args]
    return {
        "ok": True,
        "engine": key,
        "argv": argv,
        "command": shlex.join(argv),
    }


def _onboarding_login_output_hints(text):
    """Extract user-actionable auth URLs and device codes from CLI output."""
    seen_urls = set()
    urls = []
    for match in _ONBOARDING_LOGIN_URL_RE.findall(str(text or "")):
        clean = match.rstrip(".,;:")
        if clean and clean not in seen_urls:
            seen_urls.add(clean)
            urls.append(clean)
    seen_codes = set()
    codes = []
    for match in _ONBOARDING_LOGIN_CODE_RE.findall(str(text or "")):
        if match not in seen_codes:
            seen_codes.add(match)
            codes.append(match)
    return {"urls": urls[:5], "codes": codes[:5]}


def _append_onboarding_login_output(session_id, chunk):
    if not chunk:
        return
    with _ONBOARDING_LOGIN_LOCK:
        session = _ONBOARDING_LOGIN_SESSIONS.get(session_id)
        if not session:
            return
        text = session.get("output", "") + chunk
        offset = session.get("offset", 0) + len(chunk)
        base_offset = session.get("base_offset", 0)
        if len(text) > _ONBOARDING_LOGIN_MAX_BUFFER_CHARS:
            trim = len(text) - _ONBOARDING_LOGIN_MAX_BUFFER_CHARS
            text = text[trim:]
            base_offset += trim
        session["output"] = text
        session["offset"] = offset
        session["base_offset"] = base_offset
        session["last_activity"] = time.time()


def _onboarding_login_snapshot(session, offset=0):
    base_offset = int(session.get("base_offset") or 0)
    end_offset = int(session.get("offset") or 0)
    output = session.get("output") or ""
    try:
        requested = int(offset or 0)
    except (TypeError, ValueError):
        requested = 0
    start = max(0, min(len(output), requested - base_offset))
    visible = output[start:]
    exit_code = session.get("exit_code")
    running = bool(session.get("running"))
    if running and session.get("proc") is not None and session["proc"].poll() is not None:
        running = False
        exit_code = session["proc"].returncode
    return {
        "ok": True,
        "session_id": session.get("id"),
        "engine": session.get("engine"),
        "command": session.get("command"),
        "running": running,
        "exit_code": exit_code,
        "cancelled": bool(session.get("cancelled")),
        "timed_out": bool(session.get("timed_out")),
        "output": visible,
        "offset": end_offset,
        "base_offset": base_offset,
        "hints": _onboarding_login_output_hints(output),
        "started_at": session.get("started_at"),
        "ended_at": session.get("ended_at"),
    }


def _terminate_onboarding_login_process(session, force=False):
    proc = session.get("proc")
    if not proc or proc.poll() is not None:
        return
    try:
        pgid = os.getpgid(proc.pid)
    except OSError:
        pgid = None
    try:
        if pgid:
            os.killpg(pgid, signal.SIGKILL if force else signal.SIGTERM)
        elif force:
            proc.kill()
        else:
            proc.terminate()
    except (ProcessLookupError, PermissionError, OSError):
        pass


def _close_onboarding_login_fd(session):
    fd = session.get("master_fd")
    if fd is None:
        return
    session["master_fd"] = None
    try:
        os.close(fd)
    except OSError:
        pass


def _cleanup_onboarding_login_sessions():
    now = time.time()
    timeout = _onboarding_login_timeout_seconds()
    to_timeout = []
    to_delete = []
    with _ONBOARDING_LOGIN_LOCK:
        for sid, session in list(_ONBOARDING_LOGIN_SESSIONS.items()):
            proc = session.get("proc")
            running = bool(session.get("running"))
            if running and proc is not None and proc.poll() is not None:
                session["running"] = False
                session["exit_code"] = proc.returncode
                session["ended_at"] = now
                running = False
            if running and now - float(session.get("last_activity") or session.get("started_at") or now) > timeout:
                session["timed_out"] = True
                session["running"] = False
                session["ended_at"] = now
                session["exit_code"] = -1
                to_timeout.append(session)
            elif not running and now - float(session.get("ended_at") or now) > _ONBOARDING_LOGIN_RETAIN_SECONDS:
                to_delete.append(sid)
        for sid in to_delete:
            _ONBOARDING_LOGIN_SESSIONS.pop(sid, None)
    for session in to_timeout:
        _terminate_onboarding_login_process(session)
        _close_onboarding_login_fd(session)


def _onboarding_login_reader(session_id, master_fd, proc):
    try:
        while True:
            if proc.poll() is not None:
                # Drain any final bytes the child wrote before exiting.
                try:
                    while True:
                        data = os.read(master_fd, 4096)
                        if not data:
                            break
                        _append_onboarding_login_output(
                            session_id,
                            data.decode("utf-8", errors="replace"),
                        )
                except BlockingIOError:
                    pass
                except OSError:
                    pass
                break
            try:
                readable, _, _ = select.select([master_fd], [], [], 0.2)
            except (OSError, ValueError):
                break
            if not readable:
                continue
            try:
                data = os.read(master_fd, 4096)
            except BlockingIOError:
                continue
            except OSError:
                break
            if not data:
                break
            _append_onboarding_login_output(session_id, data.decode("utf-8", errors="replace"))
    finally:
        try:
            exit_code = proc.wait(timeout=1)
        except subprocess.TimeoutExpired:
            exit_code = proc.poll()
        with _ONBOARDING_LOGIN_LOCK:
            session = _ONBOARDING_LOGIN_SESSIONS.get(session_id)
            if session:
                session["running"] = False
                session["exit_code"] = exit_code
                session["ended_at"] = time.time()
        try:
            os.close(master_fd)
        except OSError:
            pass


def _start_onboarding_login_session(engine):
    """Start a short-lived PTY-backed login process for the onboarding modal."""
    _cleanup_onboarding_login_sessions()
    command = _onboarding_login_command(engine)
    if not command.get("ok"):
        return command
    key = command["engine"]
    with _ONBOARDING_LOGIN_LOCK:
        for session in _ONBOARDING_LOGIN_SESSIONS.values():
            if session.get("engine") == key and session.get("running"):
                snap = _onboarding_login_snapshot(session)
                snap["already_running"] = True
                return snap

    import pty
    try:
        master_fd, slave_fd = pty.openpty()
    except OSError as e:
        return {"ok": False, "engine": key, "error": f"openpty failed: {e}"}
    try:
        flags = fcntl.fcntl(master_fd, fcntl.F_GETFL)
        fcntl.fcntl(master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    except OSError:
        pass
    try:
        proc = subprocess.Popen(
            command["argv"],
            stdin=slave_fd,
            stdout=slave_fd,
            stderr=slave_fd,
            cwd=str(Path.home()),
            close_fds=True,
            start_new_session=True,
        )
    except (FileNotFoundError, OSError, ValueError) as e:
        try:
            os.close(master_fd)
            os.close(slave_fd)
        except OSError:
            pass
        return {"ok": False, "engine": key, "error": f"login command failed to start: {e}"}
    try:
        os.close(slave_fd)
    except OSError:
        pass

    session_id = "login-" + uuid.uuid4().hex
    now = time.time()
    session = {
        "id": session_id,
        "engine": key,
        "command": command["command"],
        "argv": command["argv"],
        "proc": proc,
        "master_fd": master_fd,
        "running": True,
        "exit_code": None,
        "cancelled": False,
        "timed_out": False,
        "output": "",
        "offset": 0,
        "base_offset": 0,
        "started_at": now,
        "last_activity": now,
        "ended_at": None,
    }
    with _ONBOARDING_LOGIN_LOCK:
        _ONBOARDING_LOGIN_SESSIONS[session_id] = session
    thread = threading.Thread(
        target=_onboarding_login_reader,
        args=(session_id, master_fd, proc),
        daemon=True,
        name=f"onboarding-login-{key}",
    )
    thread.start()
    return _onboarding_login_snapshot(session)


def _onboarding_login_status(session_id, offset=0):
    _cleanup_onboarding_login_sessions()
    with _ONBOARDING_LOGIN_LOCK:
        session = _ONBOARDING_LOGIN_SESSIONS.get(str(session_id or ""))
        if not session:
            return {"ok": False, "error": "login session not found"}
        return _onboarding_login_snapshot(session, offset=offset)


def _send_onboarding_login_input(session_id, text):
    with _ONBOARDING_LOGIN_LOCK:
        session = _ONBOARDING_LOGIN_SESSIONS.get(str(session_id or ""))
        if not session:
            return {"ok": False, "error": "login session not found"}
        if not session.get("running"):
            return {"ok": False, "error": "login session is not running"}
        fd = session.get("master_fd")
        if fd is None:
            return {"ok": False, "error": "login session input is closed"}
        session["last_activity"] = time.time()
    try:
        os.write(fd, str(text or "").encode("utf-8"))
    except OSError as e:
        return {"ok": False, "error": str(e)}
    return {"ok": True}


def _cancel_onboarding_login_session(session_id):
    with _ONBOARDING_LOGIN_LOCK:
        session = _ONBOARDING_LOGIN_SESSIONS.get(str(session_id or ""))
        if not session:
            return {"ok": False, "error": "login session not found"}
        session["cancelled"] = True
        session["running"] = False
        session["ended_at"] = time.time()
    _terminate_onboarding_login_process(session)
    deadline = time.time() + 2
    proc = session.get("proc")
    while proc is not None and proc.poll() is None and time.time() < deadline:
        time.sleep(0.05)
    if proc is not None and proc.poll() is None:
        _terminate_onboarding_login_process(session, force=True)
    with _ONBOARDING_LOGIN_LOCK:
        if proc is not None:
            session["exit_code"] = proc.poll()
        snap = _onboarding_login_snapshot(session)
    _close_onboarding_login_fd(session)
    return snap


def _cancel_all_onboarding_login_sessions():
    with _ONBOARDING_LOGIN_LOCK:
        ids = list(_ONBOARDING_LOGIN_SESSIONS.keys())
    for sid in ids:
        _cancel_onboarding_login_session(sid)


def _launch_login_terminal(engine):
    """Launch a terminal window and run the login command for the specified engine."""
    import subprocess
    if platform.system() != "Darwin":
        _log_macos_only("onboardingLoginTerminal")
        return {"ok": False, "inline_login": True, "error": "opening a visible terminal is macOS-only"}

    command_info = _onboarding_login_command(engine)
    if not command_info.get("ok"):
        return command_info
    command = command_info["command"]
        
    # AppleScript string needs the command embedded; escape backslashes and double quotes
    cmd_lit = command.replace("\\", "\\\\").replace('"', '\\"')
    target = _preferred_terminal_app()
    
    if target == "iTerm2":
        script = f'''
        tell application "iTerm2"
          activate
          set newWin to (create window with default profile)
          tell current session of newWin
            write text "{cmd_lit}"
          end tell
        end tell
        return "ok"
        '''
    else:
        script = f'''
        tell application "Terminal"
          activate
          do script "{cmd_lit}"
        end tell
        return "ok"
        '''
        
    try:
        # Launch terminal in background
        subprocess.Popen(["osascript", "-e", script])
        return {"ok": True, "terminal_app": target, "command": command}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _launch_install_terminal(engine):
    """Launch a terminal window and run the install command for the specified engine."""
    import subprocess
    if platform.system() != "Darwin":
        _log_macos_only("onboardingInstallTerminal")
        return {"ok": False, "error": "opening a visible terminal is macOS-only"}

    status = _get_onboarding_status()
    cli = status.get("clis", {}).get(engine)
    if not cli or not cli.get("install_instruction"):
        return {"ok": False, "error": f"no install instruction available for engine: {engine}"}

    command = cli["install_instruction"]
    cmd_lit = command.replace("\\", "\\\\").replace('"', '\\"')
    target = _preferred_terminal_app()

    if target == "iTerm2":
        script = f'''
        tell application "iTerm2"
          activate
          set newWin to (create window with default profile)
          tell current session of newWin
            write text "{cmd_lit}"
          end tell
        end tell
        return "ok"
        '''
    else:
        script = f'''
        tell application "Terminal"
          activate
          do script "{cmd_lit}"
        end tell
        return "ok"
        '''

    try:
        subprocess.Popen(["osascript", "-e", script])
        return {"ok": True, "terminal_app": target, "command": command}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _reset_onboarding():
    """Reset onboarding state by deleting onboarding.json."""
    onboarding_file = COMMAND_CENTER_STATE_DIR / "onboarding.json"
    if onboarding_file.is_file():
        try:
            onboarding_file.unlink()
        except Exception:
            pass


def _complete_onboarding():
    """Mark onboarding as completed by writing to onboarding.json in state dir."""
    import json
    from datetime import datetime, timezone
    COMMAND_CENTER_STATE_DIR.mkdir(parents=True, exist_ok=True)
    onboarding_file = COMMAND_CENTER_STATE_DIR / "onboarding.json"
    data = {
        "completed": True,
        "completed_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    }
    with open(onboarding_file, "w", encoding="utf-8") as f:
        json.dump(data, f)



def migrate_state_dir():
    """One-time rename: ~/.claude/log-viewer/ → ~/.claude/command-center/.

    Pre-rename users have data at the old path. We rename it on first launch
    of the renamed binary so they don't lose session-names, archives, etc.
    Idempotent — does nothing if the new path already exists or the old one
    doesn't.
    """
    old = Path.home() / ".claude" / "log-viewer"
    new = COMMAND_CENTER_STATE_DIR
    if new.exists() or not old.exists():
        return
    try:
        old.rename(new)
        print(f"  [migrate] Renamed {old} -> {new}")
    except OSError as e:
        print(f"  [migrate] Could not rename state dir ({e}). Continuing with {new}.")


def ensure_hooks_installed():
    """Ensure our PostToolUse and Stop hooks are registered in ~/.claude/settings.json.

    Also copies the hook scripts from this repo's hooks/ into
    ~/.claude/command-center/hooks/ so ~/.claude/settings.json can reference
    them from a stable location independent of where this repo is checked out.
    Migrates legacy `log-viewer/hooks/` references to the new path in-place.
    """
    # Copy hook scripts into the well-known install location, keeping them
    # in sync with whatever version is in this repo.
    import shutil
    repo_hooks = CCC_ROOT / "hooks"
    HOOK_SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
    for name in CCC_HOOK_SCRIPT_NAMES:
        src = repo_hooks / name
        if not src.exists():
            continue
        dst = HOOK_SCRIPTS_DIR / name
        try:
            if not dst.exists() or dst.read_bytes() != src.read_bytes():
                shutil.copy2(src, dst)
                print(f"  [hooks] Synced {name} -> {dst}")
        except OSError as e:
            print(f"  [hooks] Could not copy {name}: {e}")

    settings_path = Path.home() / ".claude" / "settings.json"
    try:
        if settings_path.exists():
            settings = json.loads(settings_path.read_text())
        else:
            settings = {}
    except (OSError, json.JSONDecodeError) as e:
        print(f"  [hooks] Could not read settings.json: {e}")
        return

    hooks = settings.setdefault("hooks", {})

    # Rewrite CCC-owned hook entries to use an absolute Python executable. Claude
    # Code hook environments can run with a minimal PATH, where bare `python3`
    # exits 127 before our script even starts.
    rewrote_hooks = False
    for kind in ("PreToolUse", "PostToolUse", "Notification", "Stop", "PreCompact", "PostCompact"):
        for entry in hooks.get(kind, []) or []:
            for h in entry.get("hooks", []) or []:
                cmd = h.get("command", "")
                normalized, changed = _normalize_ccc_hook_command(cmd)
                if changed:
                    h["command"] = normalized
                    rewrote_hooks = True

    # PreToolUse hook — writes an in-flight marker so the dashboard can show
    # "running X for Ns" while a long tool is still executing, and blocks on a
    # relayed AskUserQuestion (needs the long `timeout` below to wait out the
    # user's answer).
    pre_tool_hooks = hooks.setdefault("PreToolUse", [])
    has_pre_tool = any(
        "pre-tool-use.py" in h.get("command", "") and HOOK_MARKER in h.get("command", "")
        for entry in pre_tool_hooks
        for h in entry.get("hooks", [])
    )
    if not has_pre_tool:
        pre_tool_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("pre-tool-use.py"),
                "timeout": PRETOOLUSE_HOOK_TIMEOUT,
            }]
        })
        print("  [hooks] Installed PreToolUse hook")
    else:
        # Migrate older installs: ensure our pre-tool-use hook carries the long
        # timeout so AskUserQuestion relay can block until answered.
        for entry in pre_tool_hooks:
            for h in entry.get("hooks", []) or []:
                cmd = h.get("command", "")
                if ("pre-tool-use.py" in cmd and HOOK_MARKER in cmd
                        and h.get("timeout") != PRETOOLUSE_HOOK_TIMEOUT):
                    h["timeout"] = PRETOOLUSE_HOOK_TIMEOUT
                    rewrote_hooks = True
                    print("  [hooks] Set PreToolUse hook timeout for question relay")

    # PostToolUse hook
    post_tool_hooks = hooks.setdefault("PostToolUse", [])
    has_post_tool = any(
        "post-tool-use.py" in h.get("command", "") and HOOK_MARKER in h.get("command", "")
        for entry in post_tool_hooks
        for h in entry.get("hooks", [])
    )
    if not has_post_tool:
        post_tool_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("post-tool-use.py")
            }]
        })
        print("  [hooks] Installed PostToolUse hook")

    # Notification hook — fires when Claude Code asks for permission (or
    # otherwise wants the user's attention). Drives a precise "Needs
    # approval" badge on the kanban card, replacing the brittle
    # pending_tool/age heuristic the UI used to rely on.
    notification_hooks = hooks.setdefault("Notification", [])
    has_notification = any(
        "notification.py" in h.get("command", "") and HOOK_MARKER in h.get("command", "")
        for entry in notification_hooks
        for h in entry.get("hooks", [])
    )
    if not has_notification:
        notification_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("notification.py")
            }]
        })
        print("  [hooks] Installed Notification hook")

    # Stop hook
    stop_hooks = hooks.setdefault("Stop", [])
    has_stop = any(
        HOOK_MARKER in h.get("command", "")
        for entry in stop_hooks
        for h in entry.get("hooks", [])
    )
    if not has_stop:
        stop_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("stop.py")
            }]
        })
        print("  [hooks] Installed Stop hook")

    # PreCompact / PostCompact hooks — mark a session as mid-/compact so the
    # dashboard can show a "Compacting…" badge instead of a stale tool pill.
    # No long timeout needed: unlike PreToolUse (which blocks on a relayed
    # AskUserQuestion answer), these just write/clear a marker file and return.
    pre_compact_hooks = hooks.setdefault("PreCompact", [])
    has_pre_compact = any(
        "pre-compact.py" in h.get("command", "") and HOOK_MARKER in h.get("command", "")
        for entry in pre_compact_hooks
        for h in entry.get("hooks", [])
    )
    if not has_pre_compact:
        pre_compact_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("pre-compact.py")
            }]
        })
        print("  [hooks] Installed PreCompact hook")

    post_compact_hooks = hooks.setdefault("PostCompact", [])
    has_post_compact = any(
        "post-compact.py" in h.get("command", "") and HOOK_MARKER in h.get("command", "")
        for entry in post_compact_hooks
        for h in entry.get("hooks", [])
    )
    if not has_post_compact:
        post_compact_hooks.append({
            "matcher": "",
            "hooks": [{
                "type": "command",
                "command": _ccc_hook_command("post-compact.py")
            }]
        })
        print("  [hooks] Installed PostCompact hook")

    if (not has_pre_tool or not has_post_tool or not has_notification
            or not has_stop or not has_pre_compact or not has_post_compact
            or rewrote_hooks):
        tmp_path = settings_path.with_suffix(".tmp")
        try:
            tmp_path.write_text(json.dumps(settings, indent=4) + "\n")
            tmp_path.replace(settings_path)
            if rewrote_hooks:
                print("  [hooks] Normalized Claude Code hook commands in settings.json")
            print("  [hooks] settings.json updated")
        except OSError as e:
            print(f"  [hooks] Failed to write settings.json: {e}")
            tmp_path.unlink(missing_ok=True)


_adopt_ccc_module("fleet")
_adopt_ccc_module("fleet_reco")

_adopt_ccc_module("fleet_jobs")

def main():
    import socketserver
    class ThreadedHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
        allow_reuse_address = True
        daemon_threads = True
    # Parse CLI overrides for this server instance. Env var PORT and the
    # module-level default still apply when the flags are absent.
    port = PORT
    bind_host_arg = None
    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--port" and i + 1 < len(sys.argv):
            try:
                port = int(sys.argv[i + 1])
            except (TypeError, ValueError):
                print(f"Invalid --port value: {sys.argv[i + 1]}", file=sys.stderr)
                raise SystemExit(2)
            i += 1
        elif arg == "--host" and i + 1 < len(sys.argv):
            bind_host_arg = sys.argv[i + 1]
            i += 1
        i += 1
    if not 1 <= port <= 65535:
        print(f"Invalid --port value: {port} (must be 1-65535)", file=sys.stderr)
        raise SystemExit(2)
    _raise_open_file_limit()
    migrate_state_dir()
    _install_python_stack_dump_handler()
    # Keep spawn stats across a dashboard restart -- otherwise restarting
    # mid-investigation throws away the evidence you restarted to look at.
    _spawn_timeline_load()
    # Build the unified session graph from all edge sources. Lightweight
    # (reads 4 files + 1 sqlite query) and makes family-tree queries O(1)
    # for the rest of this process's lifetime.
    try:
        _session_graph.load()
        _session_graph_build_from_all_sources()
        stats = _session_graph.stats()
        print(f"  [session-graph] loaded {stats['edges']} edges across {stats['parents']} parents")
    except Exception as e:
        print(f"  [session-graph] build failed: {e}")
    _start_session_graph_codex_refresh()
    # Diagnostic: mark every server start in the resume ledger so a burst of
    # cold_resume events right after this line implicates restart-EOF as the
    # cause of warm processes dying.
    _resume_ledger_append("server_start", pid=os.getpid())
    ensure_hooks_installed()
    _schedule_claude_spawn_capability_probe()
    install_orchestration_skill()
    worker_health = _control_plane_request("health")
    worker_capabilities = set(
        ((worker_health.get("worker") or {}).get("capabilities") or [])
    )
    worker_owns_engines = (
        worker_health.get("ok")
        and "engine-execution-v1" in worker_capabilities
    )
    # Seed /api/health's worker_compat cache from the RPC we already made
    # above (no extra socket round-trip) so the pill has a real value from
    # the first poll, not just after the first hourly Maintenance tick.
    _set_worker_compat_cache(_worker_compat_snapshot(worker_health))
    if worker_owns_engines:
        print(
            "  [control-plane] worker owns engine processes "
            f"(pid {((worker_health.get('worker') or {}).get('pid'))})"
        )
    else:
        _reap_orphaned_claude_prewarms()
        _reattach_spawned_orphans()
        if worker_health.get("ok"):
            print(
                "  [control-plane] worker is from an older build; "
                "using compatible dashboard execution until it restarts"
            )
    if worker_owns_engines:
        _reattach_spawned_orphans(skip_engines=("claude", "codex", "kimi"))
        drain = worker_health.get("drain") or {}
        if (
            drain.get("enabled")
            and str(drain.get("reason") or "").startswith(
                ("dashboard-restart:", "worker-restart:")
            )
        ):
            # "worker-restart:" drains are normally lifted by the restart
            # handler itself once the worker is healthy; this catches the
            # ones it leaked (dashboard died mid-restart), which otherwise
            # defer every queued submit forever.
            resumed = _control_plane_request("drain.set", {
                "enabled": False,
                "reason": "dashboard online",
            })
            print(
                "  [control-plane] restart handoff resumed "
                f"({int(resumed.get('replayed') or 0)} queued action(s))"
            )
    threading.Thread(
        target=_claude_desktop_visibility_backfill_once,
        daemon=True,
        name="ccc-claude-desktop-backfill",
    ).start()
    if _codex_sidebar_backfill_enabled():
        threading.Thread(
            target=_codex_sidebar_visibility_backfill_once,
            daemon=True,
            name="ccc-codex-sidebar-backfill",
        ).start()
    threading.Thread(
        target=_cursor_sidebar_visibility_backfill_once,
        daemon=True,
        name="ccc-cursor-sidebar-backfill",
    ).start()
    # Token Optimizer quality is advisory UI metadata. Hydrate it in the
    # background; every request only reads the published in-memory map.
    _start_token_optimizer_quality_index_refresher()
    # WatchTower's ticket list is GitHub-backed and its cache is in-process,
    # so it is cold at exactly the moment the dashboard boot burst hits it.
    # Measured on a restart: four concurrent /api/queue/* + /api/watchtower/*
    # requests each fired their own `gh` round-trip and took 6-9s, and because
    # they hold the GIL between subprocess waits they dragged /api/sessions to
    # 11s alongside them. Warm it once, off the request path, before the
    # browser asks. Failure is fine -- the endpoints still fetch on demand.
    threading.Thread(
        target=lambda: _wt_list_items_display_cached(max_age=0),
        name="ccc-wt-items-prewarm", daemon=True,
    ).start()
    _load_conv_meta_cache()
    # Seed _SEEN_INTERRUPTS from the resume ledger BEFORE any background
    # thread starts parsing transcripts. The seed makes dedup at-most-once
    # across restarts. Must run before the reaper/archive refresher threads
    # — those parse transcripts and would fire unseeded.
    _seed_seen_interrupts_from_ledger()
    # Enable interrupt event emission only in the real dashboard server,
    # not in ephemeral verification instances (CCC_EPHEMERAL=1 bypasses
    # the duplicate-repo check and would emit into the shared ledger).
    if not os.environ.get("CCC_EPHEMERAL"):
        global _INTERRUPT_EVENTS_ENABLED
        _INTERRUPT_EVENTS_ENABLED = True
    _load_cwd_relocation_cache()
    _load_session_cwd_overrides()
    _load_stats_file_cache()
    try:
        _SCRATCH_DIR.mkdir(parents=True, exist_ok=True)
    except OSError:
        # Best-effort — if we can't make the dir, the `claude -p` callers
        # below will still work; their throwaways will just land in the
        # parent dir's slug, same as before this fix.
        pass
    _gc_scratch_jsonls()
    # SECURITY: bind to 127.0.0.1 by default. The whole trust model is
    # "implicit because it's local"; binding to all interfaces (the old
    # `("", PORT)`) exposed every endpoint — including subprocess-spawning
    # ones — to anyone on the same LAN. Escape hatch for power users:
    # CCC_BIND_HOST=0.0.0.0 (with an explicit warning printed below). The
    # final value is resolved across env vars, the persisted network.json,
    # and (when trust_tailnet is on) the live Tailscale node — see
    # `_resolve_runtime_network`.
    bind_host, resolved_origins, network_info = _resolve_runtime_network(port, bind_host_arg)
    ALLOWED_ORIGINS[:] = resolved_origins  # in-place: _check_same_origin reads the global list
    global RUNTIME_NETWORK_INFO, BIND_HOST
    RUNTIME_NETWORK_INFO = network_info
    BIND_HOST = bind_host
    server = ThreadedHTTPServer((bind_host, port), CommandCenterHandler)
    if bind_host not in ("127.0.0.1", "localhost", "::1"):
        print(f"⚠️  WARNING: binding to {bind_host} — server is reachable from the network.")
        print(f"   This server has no auth. Anyone who can reach this port can run")
        print(f"   subprocesses on your machine. Unset CCC_BIND_HOST to revert to localhost.")
    if ALLOWED_ORIGINS:
        print(f"⚠️  Same-origin allowlist extended: {', '.join(ALLOWED_ORIGINS)}")
    if network_info["trust_tailnet"] and not network_info["tailnet"]["available"]:
        print("   trust_tailnet is on but `tailscale` CLI is not on PATH — install it or unset to silence.")
    if _wt_messaging_enabled() and not _wt_cli_available():
        print("⚠️  CCC_MESSAGING_BACKEND=wt is set but `wt` is not on PATH — headless delivery falls back to native `claude --resume`. Install WatchTower or unset to silence.")
    _check_duplicate_repo_instance()
    write_port_file(bind_host, port=port)
    _register_self(port, bind_host)
    # CCC as a Claude Code peer (slice 3): bind our own socket and publish a
    # registry row real Claude sessions can dial, so a receiver has somewhere
    # to reply and report_to children can use SendMessage instead of curl.
    # Dashboard-process-only (the worker never calls this) and gated behind
    # the same CCC_MESSAGING_BACKEND=uds opt-in as the rest of the peer
    # transport -- a no-op on every install that hasn't flipped that flag.
    if os.environ.get("CCC_WORKER_PROCESS") != "1":
        _ccc_peer_server_start()
    # SIGTERM (systemd / `kill <pid>`) needs explicit cleanup; SIGINT (Ctrl+C)
    # raises KeyboardInterrupt below and is handled there. Both paths remove
    # this server's registry entry so peers don't see a stale ghost.
    def _on_sigterm(signum, frame):
        try:
            _unregister_self()
        except Exception:
            pass
        try:
            _ccc_peer_server_stop()
        except Exception:
            pass
        sys.exit(0)
    signal.signal(signal.SIGTERM, _on_sigterm)
    display_host = "localhost" if bind_host in ("127.0.0.1", "::1") else bind_host
    print(f"Command Center running at http://{display_host}:{port}")
    print(f"  State dir:     {COMMAND_CENTER_STATE_DIR}")
    print(f"  Projects dir:  {PROJECTS_ROOT}")
    print(f"  Press Ctrl+C to stop")
    # Cache warming is opt-in. On machines with a large ~/.claude/projects tree,
    # the old always-on warmup could compete with the first foreground request
    # and hold the Python GIL long enough to make the whole app feel stuck.
    if _env_truthy("CCC_WARM_CACHE_ON_STARTUP"):
        threading.Thread(target=_warm_cache, daemon=True).start()
    # Idle-session reaper: sweeps every 30 min, SIGTERMs `claude` processes
    # whose JSONL has been quiet for >24h. Catches abandoned-but-not-archived
    # sessions and forgotten cron agents that the archive-time kill misses.
    threading.Thread(target=_idle_reaper_loop, daemon=True).start()
    # Next.js and Claude/Agy detached background scanner
    threading.Thread(target=_system_processes_scanner_loop, daemon=True, name="ccc-system-processes-scanner").start()
    # Chuck iMessage monitor: polls chat.db every 2 minutes, injects new
    # messages from +17035592946 into the CHUCK session via inject-input.
    threading.Thread(target=_chuck_imessage_poller, daemon=True).start()
    # Keep installed harnesses and Anthropic's exact model catalog current.
    # The first pass runs immediately in the daemon; failures are recorded for
    # Settings and never delay server startup or request handling.
    threading.Thread(
        target=_engine_maintenance_loop,
        daemon=True,
        name="ccc-engine-maintenance",
    ).start()
    # Anonymous opt-in telemetry — defaults OFF. The loop self-gates on
    # CCC_TELEMETRY_DISABLED and the per-user opt-in JSON; starting the
    # thread here is unconditional but no bytes leave the host unless the
    # user clicks "Enable" on the dashboard bar. See _telemetry_loop docs.
    threading.Thread(target=_telemetry_loop, daemon=True, name="ccc-telemetry").start()
    _start_plan_usage_poller()
    threading.Thread(
        target=run_presence_sampler,
        args=(_PRODUCTIVITY_STORE,),
        daemon=True,
        name="ccc-productivity-presence",
    ).start()
    # Anonymous open beacon — fires at most ONCE PER UTC DAY while running.
    # NOT opt-in, but carries no install_id and no identity (3 fields:
    # schema, version, platform). The CCC_TELEMETRY_DISABLED env var kills
    # it; that single switch is the user's guarantee that nothing leaves
    # the host. See docs/telemetry.md#anonymous-open-beacon.
    threading.Thread(target=_telemetry_open_beacon_loop, daemon=True, name="ccc-telemetry-open").start()
    # Perf-event breach-pattern self-filer — checks the last 24h of
    # archive_load/conv_open beacons every CCC_PERF_TICKET_CHECK_INTERVAL_S
    # (default 900s) and self-files a WatchTower CCC bug ticket on a real
    # regression pattern, deduped same-day / while a ticket is still open.
    # Off for ephemeral test/CI processes and via an explicit opt-out.
    if not os.environ.get("CCC_EPHEMERAL") and not os.environ.get("CCC_PERF_TICKETS_DISABLED"):
        threading.Thread(target=perf_ticket_loop, daemon=True, name="ccc-perf-ticket").start()
    # Decision Inbox: hourly stalled-work scan + token governor
    # (ccc_server/decision_inbox.py). Off for ephemeral test/CI processes
    # and via CCC_DECISION_INBOX_DISABLED=1; the config file's `enabled`
    # flag is re-read every interval.
    if not os.environ.get("CCC_EPHEMERAL") and not os.environ.get("CCC_DECISION_INBOX_DISABLED"):
        threading.Thread(target=decision_inbox_loop, daemon=True, name="ccc-decision-inbox").start()
    # Recover in-progress group-chat coordinations and start background watcher.
    _start_coordination_watcher()
    _start_resume_queue_watcher()
    # GH #71 (mechanism 5) — always-on reaper for stale Claude headless agents
    # whose session has been taken over by a live terminal. Runs regardless of
    # any open dashboard so the ~500MB stale process doesn't linger.
    _ensure_headless_staleness_watcher_started()
    # CCC-863: unattended usage/rate-limit auto-resume ("continue" is sent
    # the moment a stopped session's quota resets, no manual button).
    _start_usage_limit_watcher()
    # Pre-warm the throughput caches so the first /throughput page load is
    # instant (hits in-memory caches instead of re-parsing transcripts).
    def _prewarm_throughput():
        _throughput_payload("all_7_days")
        _throughput_week_rankings()
    if _should_prewarm_throughput_on_startup():
        threading.Thread(target=_prewarm_throughput, daemon=True, name="ccc-throughput-prewarm").start()
    # Self-serve-loop health check: periodic self-probe + SIGUSR2 stack dump
    # on repeated misses. See `_self_health_check_loop` docstring for the
    # 2026-08-28 sleep/wake silent-hang incident this instruments for.
    # Skipped for ephemeral verification instances (CCC_EPHEMERAL=1) -- same
    # gate as _INTERRUPT_EVENTS_ENABLED above -- since those are short-lived
    # and this is 5-minute-cadence diagnostic noise for them, not signal.
    if not os.environ.get("CCC_EPHEMERAL"):
        threading.Thread(
            target=_self_health_check_loop,
            args=(port,),
            daemon=True,
            name="ccc-self-health-check",
        ).start()
    print()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
        try:
            _unregister_self()
        except Exception:
            pass
        try:
            _ccc_peer_server_stop()
        except Exception:
            pass
        server.server_close()


# ── Chuck iMessage Poller ─────────────────────────────────────────────────────
_CHUCK_PHONE = "+17035592946"
_CHUCK_SESSION_ID = "b1216dcf-99b2-48bf-85af-cb0ecea4f1ca"
_CHUCK_LAST_SEEN_FILE = Path("/tmp/chuck-loop-last-seen.txt")
_IMESSAGE_DB = Path.home() / "Library" / "Messages" / "chat.db"
_CHUCK_POLL_INTERVAL = 120  # seconds
_APPLE_EPOCH_OFFSET = 978307200  # seconds between Unix epoch and Apple epoch (2001-01-01)


def _chuck_read_last_seen() -> int:
    try:
        return int(_CHUCK_LAST_SEEN_FILE.read_text().strip())
    except Exception:
        return int(time.time()) - 3600


def _chuck_write_last_seen(ts: int) -> None:
    try:
        _CHUCK_LAST_SEEN_FILE.write_text(str(ts))
    except Exception:
        pass


def _chuck_fetch_new_messages(since_unix: int):
    """Return list of (unix_ts, is_from_me, text) tuples newer than since_unix."""
    if not _IMESSAGE_DB.exists():
        return []
    apple_ns = (since_unix - _APPLE_EPOCH_OFFSET) * 1_000_000_000
    try:
        conn = sqlite3.connect(str(_IMESSAGE_DB), check_same_thread=False, timeout=5)
        cur = conn.cursor()
        cur.execute(
            """
            SELECT m.date / 1000000000 + ? AS unix_ts,
                   m.is_from_me,
                   m.text
            FROM message m
            JOIN handle h ON m.handle_id = h.rowid
            WHERE h.id = ?
              AND m.date > ?
              AND m.text IS NOT NULL
            ORDER BY m.date ASC
            """,
            (_APPLE_EPOCH_OFFSET, _CHUCK_PHONE, apple_ns),
        )
        rows = cur.fetchall()
        conn.close()
        return rows
    except Exception:
        return []


def _chuck_inject(text: str) -> None:
    """Inject text into the CHUCK session via the local CCC inject-input API."""
    try:
        payload = json.dumps({"session_id": _CHUCK_SESSION_ID, "text": text}).encode()
        req = urllib.request.Request(
            f"http://127.0.0.1:{PORT}/api/inject-input",
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        urllib.request.urlopen(req, timeout=10)
    except Exception:
        pass


def _chuck_is_quiet_hours() -> bool:
    """Return True between 10pm and 7am US/Eastern."""
    try:
        import subprocess as _sp
        result = _sp.run(
            ["python3", "-c",
             "from datetime import datetime; import zoneinfo; "
             "h=datetime.now(zoneinfo.ZoneInfo('America/New_York')).hour; "
             "print('1' if h>=22 or h<7 else '0')"],
            capture_output=True, text=True, timeout=5,
        )
        return result.stdout.strip() == "1"
    except Exception:
        return False


def _chuck_imessage_poller() -> None:
    """Background daemon thread: poll chat.db, inject new Chuck messages into CHUCK session."""
    # Stagger startup so the server is fully bound before first inject attempt.
    time.sleep(15)
    while True:
        try:
            if not _chuck_is_quiet_hours():
                last_seen = _chuck_read_last_seen()
                rows = _chuck_fetch_new_messages(last_seen)
                if rows:
                    chuck_msgs = [(ts, txt) for ts, is_from_me, txt in rows if not is_from_me]
                    if chuck_msgs:
                        lines = []
                        for ts, txt in chuck_msgs:
                            dt = datetime.fromtimestamp(ts).strftime("%H:%M")
                            lines.append(f"[{dt}] CHUCK: {txt}")
                        inject_text = (
                            "[chuck-loop] New message(s) from Chuck:\n\n"
                            + "\n".join(lines)
                            + "\n\nReview and decide how to proceed per the loop rules."
                        )
                        _chuck_inject(inject_text)
                    # Bump last-seen to the newest message timestamp regardless of direction.
                    newest_ts = max(ts for ts, _, _ in rows)
                    _chuck_write_last_seen(newest_ts + 1)
        except Exception:
            pass
        time.sleep(_CHUCK_POLL_INTERVAL)


