    if len(sys.argv) >= 2 and sys.argv[1] == "--archive-refresh-worker":
        if len(sys.argv) != 4:
            print(
                "usage: server.py --archive-refresh-worker OPTIONS OUTPUT",
                file=sys.stderr,
            )
            raise SystemExit(2)
        raise SystemExit(_archive_refresh_worker_main(sys.argv[2], sys.argv[3]))
    main()
